import * as GaussianSplats3D from '@mkkellogg/gaussian-splats-3d';
import { GaussianAbstractComponent, GaussianSplatConfig, LoaderStatus } from './gaussian-abstract-component';

/**
 * GaussianSplats3D 库的 Gaussian Splatting 组件实现
 * 封装 @mkkellogg/gaussian-splats-3d 库
 */
export class GaussianSplats3DComponent extends GaussianAbstractComponent<typeof GaussianSplats3D.DropInViewer> {
  private viewerOptions: any;
  private globalScene: any;

  constructor(viewerOptions?: any, globalScene?: any) {
    super();

    this.globalScene = globalScene;

    // 保存viewer配置
    this.viewerOptions = {
      dynamicScene: true,
      progressiveLoad: true,
      sphericalHarmonicsDegree: 2,
      sharedMemoryForWorkers: false,
      freeIntermediateSplatData: true,
      sceneRevealMode: GaussianSplats3D.SceneRevealMode.Instant,
      useBuiltInControls: false,
      selfDrivenMode: false,
      ...viewerOptions,
    };

    // 创建 DropInViewer
    this.viewer = new GaussianSplats3D.DropInViewer({
      ...this.viewerOptions,
    });
  }

  /**
   * 添加场景
   * @param url 场景文件URL
   * @param config 配置参数
   * @param id 可选的唯一标识符
   * @returns Promise<string> 返回场景ID
   */
  async addScene(url: string, config?: Partial<GaussianSplatConfig>): Promise<GaussianSplats3D.Viewer> {
    if (!this.viewer) {
      throw new Error('Viewer not initialized. Please call setScene() first.');
    }

    try {
      // 准备场景配置
      const sceneOptions: any = {
        progressiveLoad: true,
        showLoadingUI: config?.showLoadingUI ?? false,
      };

      // 设置位置
      if (config?.position) {
        sceneOptions.position = config.position;
      }

      // 设置旋转
      if (config?.rotation) {
        sceneOptions.rotation = config.rotation;
      }

      // 设置缩放
      if (config?.scale) {
        sceneOptions.scale = config.scale;
      }

      // 设置进度回调
      if (config?.onProgress) {
        sceneOptions.onProgress = (progress: number, progressLabel: string, loaderStatus: LoaderStatus) => {
          config.onProgress?.(progress / 100, loaderStatus);
        };
      }

      // 加载场景
      await this.viewer.addSplatScene(url, sceneOptions);

      // 设置渲染顺序
      if (config?.renderOrder !== undefined) {
        this.viewer.renderOrder = config.renderOrder;

        // 备选方案：通过调整Z轴位置控制深度
        if (config.renderOrder < 0) {
          this.viewer.position.z += config.renderOrder * 0.01;
        }
      } else {
        this.viewer.renderOrder = 0;
      }

      // 调用渲染回调
      config?.renderCallback?.();
      this.globalScene.add(this.viewer);

      return this.viewer;
    } catch (error) {
      console.error('Failed to add GaussianSplats3D scene:', error);
      throw error;
    }
  }

  /**
   * 重写dispose方法，清理viewer
   */
  dispose(): void {
    if (this.viewer) {
      if (Array.isArray(this.viewer)) {
        this.viewer.forEach((v) => v?.dispose());
      } else {
        this.viewer.dispose();
      }
      this.viewer = null;
    }
    super.dispose();
  }
}
