import * as THREE from 'three';
import { BaseCharacter } from './base-character';
import { PhysicsWorldManager } from './physics-world-manager';
import { CharacterModelInfo, CharacterState } from '@/types';
import { PathFinding } from './path-finding.ts';

/**
 * NPC类 - 非玩家角色
 * 可以随机移动，受重力和碰撞影响，支持动画播放，支持A*寻路
 */
export class NPC extends BaseCharacter {
  // NPC特有属性
  private movementPattern: 'idle' | 'wander' | 'patrol' | 'pathfinding' = 'wander';
  private wanderRadius = 5; // 漫游半径
  private wanderSpeed = 0.5; // 漫游速度倍数
  private currentDirection = new THREE.Vector3();
  private movementTimer = 0;
  private movementInterval = 3; // 每3秒改变一次方向
  private idleTimer = 0;
  private idleChance = 0.3; // 30%概率进入idle状态
  private isIdle = false;
  private patrolPoints: THREE.Vector3[] = [];
  private currentPatrolIndex = 0;
  private rigidBodyHandle?: number; // 物理刚体句柄

  // 寻路相关
  private pathfinding?: PathFinding; // 寻路系统
  private currentPath: THREE.Vector3[] = []; // 当前路径
  private currentPathIndex = 0; // 当前路径点索引
  private pathReachThreshold = 0.5; // 到达路径点的阈值（米）

  constructor(
    id: string,
    modelConfig: CharacterModelInfo,
    scene: THREE.Scene,
    physicsWorldManager: PhysicsWorldManager,
    spawnPoint: THREE.Vector3,
    capsuleRadius = 0.35,
    capsuleHeight = 1.0,
    capsuleBottomOffset = 0.85,
  ) {
    super(id, modelConfig, scene, physicsWorldManager, spawnPoint, capsuleRadius, capsuleHeight, capsuleBottomOffset);

    // NPC使用较慢的速度
    this.walkVelocity = 1.5;
    this.runVelocity = 3.0;

    // 禁用悬崖检测 - NPC使用动态刚体,会自然下落,不需要悬崖保护
    this.cliffDetectionEnabled = false;

    // 初始化随机方向
    this.randomizeDirection();
  }

  /**
   * 设置刚体句柄
   */
  public setRigidBodyHandle(handle: number): void {
    this.rigidBodyHandle = handle;
  }

  /**
   * 设置移动模式
   */
  public setMovementPattern(pattern: 'idle' | 'wander' | 'patrol' | 'pathfinding'): void {
    this.movementPattern = pattern;
    console.log(`🤖 NPC ${this.id}: 移动模式设置为 ${pattern}`);
  }

  /**
   * 设置漫游参数
   */
  public setWanderParams(radius: number, speed: number): void {
    this.wanderRadius = radius;
    this.wanderSpeed = speed;
  }

  /**
   * 设置巡逻点
   */
  public setPatrolPoints(points: THREE.Vector3[]): void {
    this.patrolPoints = points;
    this.currentPatrolIndex = 0;
  }

  /**
   * 设置寻路系统
   */
  public setPathfinding(pathfinding: PathFinding): void {
    this.pathfinding = pathfinding;
    console.log(`🗺️ NPC ${this.id}: 寻路系统已设置`);
  }

  /**
   * 设置寻路目标
   * @param target 目标位置
   */
  public setPathTarget(target: THREE.Vector3): void {
    if (!this.pathfinding) {
      console.warn(`⚠️ NPC ${this.id}: 未设置寻路系统`);
      return;
    }

    if (!this.model) {
      console.warn(`⚠️ NPC ${this.id}: 模型未加载`);
      return;
    }

    this.movementPattern = 'pathfinding';

    // 计算路径
    const path = this.pathfinding.findPath(this.model.position, target);

    if (path.length > 0) {
      this.currentPath = path;
      this.currentPathIndex = 0;
      console.log(`🗺️ NPC ${this.id}: 找到路径，共 ${path.length} 个点`);
    } else {
      console.warn(`⚠️ NPC ${this.id}: 未找到到目标的路径`);
      this.currentPath = [];
    }
  }

  /**
   * 清除当前路径
   */
  public clearPath(): void {
    this.currentPath = [];
    this.currentPathIndex = 0;
    console.log(`🗑️ NPC ${this.id}: 路径已清除`);
  }

  /**
   * 获取当前路径
   */
  public getCurrentPath(): THREE.Vector3[] {
    return this.currentPath;
  }

  /**
   * 随机化移动方向
   */
  private randomizeDirection(): void {
    // 随机角度（0-360度）
    const angle = Math.random() * Math.PI * 2;

    // 设置新的移动方向
    this.currentDirection.set(Math.sin(angle), 0, Math.cos(angle));
    this.currentDirection.normalize();

    // 随机决定是否进入idle状态
    if (Math.random() < this.idleChance) {
      this.isIdle = true;
      this.idleTimer = Math.random() * 2 + 1; // 1-3秒的idle时间
    } else {
      this.isIdle = false;
    }
  }

  /**
   * 更新漫游移动
   */
  private updateWanderMovement(delta: number): {
    moveX: number;
    moveZ: number;
    hasMovement: boolean;
  } {
    this.movementTimer += delta;

    // 如果在idle状态
    if (this.isIdle) {
      this.idleTimer -= delta;
      if (this.idleTimer <= 0) {
        this.isIdle = false;
        this.randomizeDirection();
      }
      return { moveX: 0, moveZ: 0, hasMovement: false };
    }

    // 定期改变方向
    if (this.movementTimer >= this.movementInterval) {
      this.movementTimer = 0;
      this.randomizeDirection();
    }

    // 检查是否超出漫游范围
    if (this.model) {
      const distanceFromSpawn = this.model.position.distanceTo(this.spawnPoint);
      if (distanceFromSpawn > this.wanderRadius) {
        // 超出范围，调整方向朝向出生点
        const directionToSpawn = new THREE.Vector3().subVectors(this.spawnPoint, this.model.position).normalize();
        this.currentDirection.copy(directionToSpawn);
      }
    }

    // 计算移动速度(米/秒)
    const velocity = this.walkVelocity * this.wanderSpeed;
    const moveX = this.currentDirection.x * velocity;
    const moveZ = this.currentDirection.z * velocity;

    return { moveX, moveZ, hasMovement: true };
  }

  /**
   * 更新巡逻移动
   */
  private updatePatrolMovement(delta: number): {
    moveX: number;
    moveZ: number;
    hasMovement: boolean;
  } {
    if (this.patrolPoints.length === 0 || !this.model) {
      return { moveX: 0, moveZ: 0, hasMovement: false };
    }

    const currentTarget = this.patrolPoints[this.currentPatrolIndex];
    const distanceToTarget = this.model.position.distanceTo(currentTarget);

    // 到达巡逻点，切换到下一个
    if (distanceToTarget < 0.5) {
      this.currentPatrolIndex = (this.currentPatrolIndex + 1) % this.patrolPoints.length;

      // 有机会在巡逻点idle
      if (Math.random() < this.idleChance) {
        this.isIdle = true;
        this.idleTimer = Math.random() * 2 + 1;
        return { moveX: 0, moveZ: 0, hasMovement: false };
      }
    }

    // 如果在idle状态
    if (this.isIdle) {
      this.idleTimer -= delta;
      if (this.idleTimer <= 0) {
        this.isIdle = false;
      }
      return { moveX: 0, moveZ: 0, hasMovement: false };
    }

    // 计算朝向目标的方向
    this.currentDirection.subVectors(currentTarget, this.model.position);
    this.currentDirection.y = 0;
    this.currentDirection.normalize();

    // 计算移动速度(米/秒)
    const velocity = this.walkVelocity * this.wanderSpeed;
    const moveX = this.currentDirection.x * velocity;
    const moveZ = this.currentDirection.z * velocity;

    return { moveX, moveZ, hasMovement: true };
  }

  /**
   * 更新寻路移动
   */
  private updatePathfindingMovement(_delta: number): {
    moveX: number;
    moveZ: number;
    hasMovement: boolean;
  } {
    // 没有路径或模型未加载
    if (this.currentPath.length === 0 || !this.model) {
      return { moveX: 0, moveZ: 0, hasMovement: false };
    }

    // 已经到达路径末端
    if (this.currentPathIndex >= this.currentPath.length) {
      console.log(`✅ NPC ${this.id}: 已到达目标`);
      this.currentPath = [];
      this.currentPathIndex = 0;
      return { moveX: 0, moveZ: 0, hasMovement: false };
    }

    const currentWaypoint = this.currentPath[this.currentPathIndex];
    const distanceToWaypoint = new THREE.Vector2(
      this.model.position.x - currentWaypoint.x,
      this.model.position.z - currentWaypoint.z,
    ).length();

    // 到达当前路径点，前往下一个
    if (distanceToWaypoint < this.pathReachThreshold) {
      this.currentPathIndex++;

      // 检查是否到达最后一个点
      if (this.currentPathIndex >= this.currentPath.length) {
        console.log(`🎯 NPC ${this.id}: 到达路径终点`);
        return { moveX: 0, moveZ: 0, hasMovement: false };
      }

      // 输出进度
      console.log(`🚶 NPC ${this.id}: 到达路径点 ${this.currentPathIndex}/${this.currentPath.length}`);
    }

    // 计算朝向当前路径点的方向
    const nextWaypoint = this.currentPath[this.currentPathIndex];
    this.currentDirection.subVectors(nextWaypoint, this.model.position);
    this.currentDirection.y = 0;
    this.currentDirection.normalize();

    // 计算移动速度(米/秒)
    const velocity = this.walkVelocity * this.wanderSpeed;
    const moveX = this.currentDirection.x * velocity;
    const moveZ = this.currentDirection.z * velocity;

    return { moveX, moveZ, hasMovement: true };
  }

  /**
   * 更新NPC（主循环）
   */
  public update(delta: number): void {
    if (!this.model || !this.physicsWorldManager || this.rigidBodyHandle === undefined) {
      return;
    }

    // 从物理引擎获取当前位置
    const physicsPosition = this.physicsWorldManager.getRigidBodyPosition(this.rigidBodyHandle);
    if (!physicsPosition) {
      console.warn(`⚠️ NPC ${this.id}: 无法获取物理位置`);
      return;
    }

    // 获取当前速度用于调试
    // const currentVelocity = this.physicsWorldManager.getRigidBodyVelocity(this.rigidBodyHandle);

    // 更新模型位置（调整胶囊体中心到模型底部的偏移）
    const { capsuleBottomOffset } = this;
    if (this.modelConfig.transform?.position) {
      this.model.position.set(
        physicsPosition.x + this.modelConfig.transform.position.x,
        physicsPosition.y - capsuleBottomOffset + this.modelConfig.transform.position.y,
        physicsPosition.z + this.modelConfig.transform.position.z,
      );
    } else {
      this.model.position.set(physicsPosition.x, physicsPosition.y - capsuleBottomOffset, physicsPosition.z);
    }

    let moveX = 0;
    let moveZ = 0;
    let hasMovement = false;

    // 根据移动模式更新移动
    switch (this.movementPattern) {
      case 'idle':
        hasMovement = false;
        break;
      case 'wander': {
        const wanderResult = this.updateWanderMovement(delta);
        moveX = wanderResult.moveX;
        moveZ = wanderResult.moveZ;
        hasMovement = wanderResult.hasMovement;
        break;
      }
      case 'patrol': {
        const patrolResult = this.updatePatrolMovement(delta);
        moveX = patrolResult.moveX;
        moveZ = patrolResult.moveZ;
        hasMovement = patrolResult.hasMovement;
        break;
      }
      case 'pathfinding': {
        const pathfindingResult = this.updatePathfindingMovement(delta);
        moveX = pathfindingResult.moveX;
        moveZ = pathfindingResult.moveZ;
        hasMovement = pathfindingResult.hasMovement;
        break;
      }
    }

    // 应用悬崖检测
    const cliffResult = this.applyCliffDetection(moveX, moveZ);
    moveX = cliffResult.moveX;
    moveZ = cliffResult.moveZ;

    // 如果有移动,更新角色朝向和速度
    if (hasMovement && (Math.abs(moveX) > 0.001 || Math.abs(moveZ) > 0.001)) {
      const moveAngle = Math.atan2(this.currentDirection.x, this.currentDirection.z);
      this.rotateQuarternion.setFromAxisAngle(this.rotateAngle, moveAngle);

      // 结合基础旋转
      const combinedRotation = new THREE.Quaternion();
      combinedRotation.multiplyQuaternions(this.rotateQuarternion, this.baseRotation);
      this.model.quaternion.copy(combinedRotation);

      // 设置水平移动速度(moveX和moveZ现在是速度值,单位:米/秒)
      this.physicsWorldManager.setRigidBodyHorizontalVelocity(this.rigidBodyHandle, moveX, moveZ);
    } else {
      // 停止水平移动,但保持垂直速度(重力影响)
      this.physicsWorldManager.setRigidBodyHorizontalVelocity(this.rigidBodyHandle, 0, 0);
    }

    // 构建角色状态（简化版，因为不使用角色控制器）
    const characterState: CharacterState = {
      isGrounded: true, // 简化处理
      hasMovementInput: hasMovement,
      forwardInput: hasMovement ? 1 : 0,
      strafeInput: 0,
      jumpPressed: false,
      isJumping: false,
    };

    // 更新动画
    this.updateCharacterStateAndAnimation(delta, characterState);
  }

  /**
   * 使NPC跳跃
   */
  public jump(): void {
    if (this.physicsWorldManager && this.rigidBodyHandle !== undefined) {
      // 施加向上的力
      this.physicsWorldManager.applyForceToRigidBody(this.rigidBodyHandle, new THREE.Vector3(0, 5, 0));
    }
  }

  /**
   * 设置位置（重写父类方法）
   */
  public setPosition(position: THREE.Vector3): void {
    if (this.model && this.physicsWorldManager && this.rigidBodyHandle !== undefined) {
      // 更新模型位置
      this.model.position.copy(position);

      // 同步物理位置
      const physicsPosition = new THREE.Vector3(
        position.x,
        position.y + (this.capsuleHeight / 2 + this.capsuleRadius),
        position.z,
      );
      this.physicsWorldManager.setRigidBodyPosition(this.rigidBodyHandle, physicsPosition);
    }
  }

  /**
   * 销毁NPC（重写父类方法）
   */
  public dispose(): void {
    // 先移除物理刚体
    if (this.physicsWorldManager && this.rigidBodyHandle !== undefined) {
      this.physicsWorldManager.removeRigidBodyByHandle(this.rigidBodyHandle);
    }

    // 调用父类的dispose
    super.dispose();
  }

  /**
   * 设置NPC朝向某个位置
   */
  public lookAt(position: THREE.Vector3): void {
    if (!this.model) return;

    const direction = new THREE.Vector3().subVectors(position, this.model.position).normalize();

    const angle = Math.atan2(direction.x, direction.z);
    this.rotateQuarternion.setFromAxisAngle(this.rotateAngle, angle);

    const combinedRotation = new THREE.Quaternion();
    combinedRotation.multiplyQuaternions(this.rotateQuarternion, this.baseRotation);
    this.model.quaternion.copy(combinedRotation);
  }

  /**
   * 移动到指定位置（设置朝向）
   */
  public moveTo(position: THREE.Vector3): void {
    this.movementPattern = 'wander';

    if (this.model) {
      this.currentDirection.subVectors(position, this.model.position);
      this.currentDirection.y = 0;
      this.currentDirection.normalize();
    }
  }

  /**
   * 停止移动
   */
  public stopMovement(): void {
    this.movementPattern = 'idle';
    this.isIdle = true;
  }

  /**
   * 恢复移动
   */
  public resumeMovement(): void {
    this.movementPattern = 'wander';
    this.isIdle = false;
  }
}
