import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import RAPIER from '@dimforge/rapier3d-compat';
import { BaseCharacter } from './base-character';
import { PhysicsWorldManager } from './physics-world-manager';
import { CharacterState } from '@/types';
import { isMobile } from '@/utils';
import { CapsuleManager } from './capsule-manager';
import { CharacterCameraManager } from './character-camera-manager';

export const W = 'keyw';
export const A = 'keya';
export const S = 'keys';
export const D = 'keyd';
export const Q = 'keyq';
export const E = 'keye';
export const SHIFT = 'shiftleft';
export const SPACE = 'space';
export const DIRECTIONS = [W, A, S, D];

/**
 * Character 类 - 玩家控制的角色
 */
export class Character extends BaseCharacter {
  // 状态管理
  public toggleRun = true;
  private hadInputLastFrame = false;

  // 速度渐变相关
  private movementStartTime = 0; // 开始移动的时间
  private isAccelerating = false; // 是否正在加速
  private readonly ACCELERATION_DURATION = 1000; // 加速持续时间2秒（毫秒）
  private readonly START_VELOCITY = 2; // 起始速度
  private readonly TARGET_VELOCITY = 5; // 目标速度
  private currentMovementVelocity = 2; // 当前移动速度

  // 触摸控制相关
  private joystickInput?: { x: number; y: number; distance: number; edgeRatio: number };
  private touchDelta?: { x: number; y: number };

  // 控制器引用
  private orbitControl: OrbitControls;
  private camera: THREE.Camera;
  private isMobile = false;
  private capsuleManager: CapsuleManager;
  private cameraManager: CharacterCameraManager;

  // OrbitControls距离调整相关（仅用于adjustCameraDistance方法）
  private offset = 0;

  constructor(
    id: string,
    modelConfig: any,
    scene: THREE.Scene,
    physicsWorldManager: PhysicsWorldManager,
    spawnPoint: THREE.Vector3,
    orbitControls: OrbitControls,
    camera: THREE.Camera,
    capsuleRadius = 0.35,
    capsuleHeight = 1.0,
    capsuleBottomOffset = 0.85,
    targetHeight = 1.65, // 新增：目标角色高度参数
  ) {
    super(id, modelConfig, scene, physicsWorldManager, spawnPoint, capsuleRadius, capsuleHeight, capsuleBottomOffset);
    this.orbitControl = orbitControls;
    this.camera = camera;
    this.isMobile = isMobile();

    // 创建胶囊体管理器
    this.capsuleManager = new CapsuleManager(targetHeight);

    // 创建摄像机管理器
    this.cameraManager = new CharacterCameraManager(camera, orbitControls, this.capsuleManager, this.isMobile);
  }

  /**
   * 切换跑步模式
   */
  public switchRunToggle(): void {
    this.toggleRun = !this.toggleRun;
  }

  /**
   * 设置摄像机旋转速度
   */
  public updateCameraRotationSpeed(speed: number): void {
    this.cameraManager.updateCameraRotationSpeed(speed);
  }

  /**
   * 设置弹簧臂碰撞检测对象
   */
  public setSpringArmCollisionObjects(objects: THREE.Object3D[]): void {
    this.cameraManager.setSpringArmCollisionObjects(objects);
  }

  /**
   * 添加弹簧臂碰撞检测对象
   */
  public addSpringArmCollisionObject(object: THREE.Object3D): void {
    this.cameraManager.addSpringArmCollisionObject(object);
  }

  /**
   * 移除弹簧臂碰撞检测对象
   */
  public removeSpringArmCollisionObject(object: THREE.Object3D): void {
    this.cameraManager.removeSpringArmCollisionObject(object);
  }

  /**
   * 启用/禁用弹簧臂
   */
  public setSpringArmEnabled(enabled: boolean): void {
    this.cameraManager.setSpringArmEnabled(enabled);
  }

  /**
   * 获取弹簧臂是否启用
   */
  public isSpringArmEnabled(): boolean {
    return this.cameraManager.isSpringArmEnabled();
  }

  /**
   * 启用/禁用弹簧臂碰撞检测
   */
  public setSpringArmCollisionEnabled(enabled: boolean): void {
    this.cameraManager.setSpringArmCollisionEnabled(enabled);
  }

  /**
   * 设置弹簧臂使用 Rapier 物理世界（与角色使用相同的碰撞体）
   */
  public setSpringArmRapierWorld(world: RAPIER.World | null): void {
    this.cameraManager.setSpringArmRapierWorld(world);
  }

  /**
   * 设置弹簧臂排除的角色碰撞体
   */
  public setSpringArmCharacterCollider(collider: RAPIER.Collider | null): void {
    this.cameraManager.setSpringArmCharacterCollider(collider);
  }

  /**
   * 获取摄像机管理器（用于高级配置）
   */
  public getCameraManager(): CharacterCameraManager {
    return this.cameraManager;
  }

  /**
   * 更新摇杆输入
   */
  public updateJoystick(data: { x: number; y: number; distance: number; edgeRatio: number }): void {
    this.joystickInput = data;
  }

  /**
   * 更新触摸增量
   */
  public updateTouchDelta(delta: { x: number; y: number }): void {
    this.touchDelta = delta;
  }

  /**
   * 主更新方法 - 处理角色的运动和动画
   */
  public update(delta: number, keysPressed: Record<string, boolean>, isOrbitControlActive = false): void {
    if (!this.model) {
      return;
    }

    // 1. 初始化和摄像机同步
    this.initializeFrameData(isOrbitControlActive);

    // 2. 处理摄像机旋转（触摸和键盘）
    this.updateCameraRotation(delta, keysPressed, isOrbitControlActive);

    // 3. 处理移动输入
    const { forwardInput, strafeInput } = this.processMovementInput(keysPressed, isOrbitControlActive);

    // 4. 处理跳跃输入
    this.processJumpInput(keysPressed);

    // 5. 检查是否有任何输入
    const hasInput = this.checkHasInput(forwardInput, strafeInput, keysPressed);

    // 6. 更新角色状态和动画
    this.updateCharacterAnimation(delta, hasInput, forwardInput, strafeInput, keysPressed);

    // 7. 计算和执行移动
    const { moveX, moveZ } = this.calculateMovement(hasInput, forwardInput, strafeInput, delta);

    // 8. 执行物理移动和摄像机跟随
    this.executeMovementAndCameraFollow(moveX, moveZ, delta, hasInput, isOrbitControlActive);

    // 9. 最终处理
    this.finalizeFrame(hasInput, isOrbitControlActive);
  }

  /**
   * 初始化帧数据和摄像机同步
   */
  private initializeFrameData(isOrbitControlActive: boolean): void {
    // 如果 OrbitControls 刚刚被使用过，同步摄像机状态
    if (isOrbitControlActive && this.model) {
      this.cameraManager.saveCameraPosition(this.model.position);

      // 同步摄像机yaw角度
      const offset = new THREE.Vector3();
      offset.subVectors(this.camera.position, this.model.position);
      const yaw = Math.atan2(-offset.x, -offset.z);
      this.cameraManager.setCameraYaw(yaw);
    }
  }

  /**
   * 更新摄像机旋转（处理触摸和键盘输入）
   */
  private updateCameraRotation(
    delta: number,
    keysPressed: Record<string, boolean>,
    isOrbitControlActive: boolean,
  ): void {
    this.cameraManager.updateCameraRotation(delta, this.touchDelta, keysPressed, isOrbitControlActive);
  }

  /**
   * 处理移动输入（摇杆和键盘）
   */
  private processMovementInput(
    keysPressed: Record<string, boolean>,
    isOrbitControlActive: boolean,
  ): {
    forwardInput: number;
    strafeInput: number;
  } {
    let forwardInput = 0;
    let strafeInput = 0;

    // 处理摇杆输入
    if (this.joystickInput) {
      // 摇杆控制：前后移动
      forwardInput = this.joystickInput.y; // 摇杆向上为正，向下为负

      // 如果 OrbitControls 激活，摇杆的 x 值用于左右移动
      // 否则，x 值置为 0（因为使用 deltax 控制摄像机旋转）
      if (isOrbitControlActive) {
        strafeInput = -this.joystickInput.x;
      } else {
        strafeInput = 0;
      }
    }

    // 处理键盘输入
    // W/S键控制前后移动
    if (keysPressed[W]) forwardInput += 1;
    if (keysPressed[S]) forwardInput -= 1;

    // A/D键的行为取决于 OrbitControls 是否激活
    if (isOrbitControlActive) {
      // OrbitControls 激活时：A/D 键用于左右移动（strafe）
      if (keysPressed[A]) strafeInput += 1; // A键向左
      if (keysPressed[D]) strafeInput -= 1; // D键向右
    }
    // 注意：当 OrbitControls 未激活时，A/D 键用于摄像机旋转，已在 processKeyboardRotation 中处理

    return { forwardInput, strafeInput };
  }

  /**
   * 处理跳跃输入
   */
  private processJumpInput(keysPressed: Record<string, boolean>): void {
    // 跳跃控制（空格键）
    if (keysPressed[SPACE] && this.physicsWorldManager) {
      this.physicsWorldManager.jumpCharacter();
    }
  }

  /**
   * 检查是否有任何输入
   */
  private checkHasInput(forwardInput: number, strafeInput: number, keysPressed: Record<string, boolean>): boolean {
    return (
      Math.abs(forwardInput) > 0 ||
      Math.abs(strafeInput) > 0 ||
      keysPressed[A] ||
      keysPressed[D] ||
      keysPressed[W] ||
      keysPressed[S]
    );
  }

  /**
   * 更新角色状态和动画（Character特定实现）
   */
  private updateCharacterAnimation(
    delta: number,
    hasInput: boolean,
    forwardInput: number,
    strafeInput: number,
    keysPressed: Record<string, boolean>,
  ): void {
    // 构建角色状态对象
    const characterState: CharacterState = {
      isGrounded: this.physicsWorldManager?.isCharacterGrounded() ?? true,
      hasMovementInput: hasInput,
      forwardInput,
      strafeInput,
      jumpPressed: keysPressed[SPACE] || false,
      isJumping: (this.physicsWorldManager?.getCharacterVerticalVelocity() ?? 0) > 0,
    };

    // 使用动画管理器根据状态更新动画（传入当前移动速度）
    if (this.animationManager?.isReady()) {
      this.animationManager.updateAnimationByState(characterState, this.currentMovementVelocity);
      this.animationManager.update(delta);
    } else if (this.animationManager && !this.animationManager.isReady()) {
      // 动画管理器存在但未准备好，只更新mixer
      this.animationManager.update(delta);
    }
  }

  /**
   * 计算移动向量和速度
   */
  private calculateMovement(
    hasInput: boolean,
    forwardInput: number,
    strafeInput: number,
    delta: number,
  ): {
    moveX: number;
    moveZ: number;
  } {
    const moveX = 0;
    const moveZ = 0;

    if (!hasInput) {
      // 停止移动时重置加速状态
      this.isAccelerating = false;
      this.currentMovementVelocity = this.START_VELOCITY;
      return { moveX, moveZ };
    }

    // 检测是否刚开始移动（从静止到移动的瞬间）
    if (!this.hadInputLastFrame) {
      this.syncCameraStateOnMovementStart();
      // 开始新的加速过程
      this.movementStartTime = performance.now();
      this.isAccelerating = true;
      this.currentMovementVelocity = this.START_VELOCITY;
    }

    // 根据移动方向调整目标摄像机距离
    this.adjustTargetCameraDistance(forwardInput);

    // 计算移动方向和角度
    const { moveAngle, velocity } = this.calculateMovementDirection(forwardInput, strafeInput);

    // 设置角色朝向（结合基础旋转和移动方向）
    this.rotateQuarternion.setFromAxisAngle(this.rotateAngle, moveAngle);
    // 将移动旋转与基础旋转结合（注意顺序：先移动旋转，再基础旋转）
    const combinedRotation = new THREE.Quaternion();
    combinedRotation.multiplyQuaternions(this.rotateQuarternion, this.baseRotation);
    this.model!.quaternion.copy(combinedRotation);

    // 计算初始水平移动量
    const initialMoveX = this.walkDirection.x * velocity * delta;
    const initialMoveZ = this.walkDirection.z * velocity * delta;

    // 应用悬崖检测
    const cliffResult = this.applyCliffDetection(initialMoveX, initialMoveZ);

    if (cliffResult.wasBlocked) {
      // 移动被完全阻止，可以在这里添加反馈（如音效、UI提示等）
      console.log(`🎮 角色 ${this.id}: 移动被悬崖检测阻止`);
    }

    return {
      moveX: cliffResult.moveX,
      moveZ: cliffResult.moveZ,
    };
  }

  /**
   * 同步摄像机状态（在开始移动时）
   */
  private syncCameraStateOnMovementStart(): void {
    if (!this.model) return;
    this.cameraManager.saveCameraPosition(this.model.position);

    // 同步 cameraYaw 为摄像机的实际角度，避免跳变
    const offset = new THREE.Vector3();
    offset.subVectors(this.camera.position, this.model.position);
    const yaw = Math.atan2(-offset.x, -offset.z);
    this.cameraManager.setCameraYaw(yaw);
  }

  /**
   * 根据移动方向调整目标摄像机距离
   */
  private adjustTargetCameraDistance(forwardInput: number): void {
    this.cameraManager.adjustTargetCameraDistance(forwardInput);
  }

  /**
   * 计算移动方向和速度
   */
  private calculateMovementDirection(
    forwardInput: number,
    strafeInput: number,
  ): {
    moveAngle: number;
    velocity: number;
  } {
    // 获取摄像机yaw角度
    const cameraYaw = this.cameraManager.getCameraYaw();

    // 计算输入角度（相对于摄像机）
    const inputAngle = Math.atan2(strafeInput, forwardInput);

    // 计算最终移动方向角度（摄像机yaw + 输入角度）
    const moveAngle = cameraYaw + inputAngle;

    // 计算移动方向向量
    this.walkDirection.set(Math.sin(moveAngle), 0, Math.cos(moveAngle));
    this.walkDirection.normalize();

    // 计算移动速度 - 使用渐变速度
    let velocity = this.currentMovementVelocity;

    // 如果正在加速，更新速度
    if (this.isAccelerating) {
      const elapsedTime = performance.now() - this.movementStartTime;

      if (elapsedTime >= this.ACCELERATION_DURATION) {
        // 加速完成，固定在目标速度
        this.isAccelerating = false;
        this.currentMovementVelocity = this.TARGET_VELOCITY;
        velocity = this.TARGET_VELOCITY;
        console.log('✅ 加速完成，速度达到:', velocity);
      } else {
        // 线性插值计算当前速度
        const progress = elapsedTime / this.ACCELERATION_DURATION; // 0 到 1
        this.currentMovementVelocity = this.START_VELOCITY + (this.TARGET_VELOCITY - this.START_VELOCITY) * progress;
        velocity = this.currentMovementVelocity;
        // 每隔一段时间输出一次速度，避免日志过多
        if (Math.random() < 0.05) {
          console.log(`⚡ 加速中: ${velocity.toFixed(2)} (进度: ${(progress * 100).toFixed(1)}%)`);
        }
      }
    }

    // 应用移动速度因子（基于摄像机旋转速度）
    const hasJoystickInput = this.joystickInput !== undefined;
    const speedFactor = this.cameraManager.calculateMovementSpeedFactor(hasJoystickInput);
    velocity *= speedFactor;

    // 向后移动时速度降低
    if (forwardInput < 0) {
      velocity = velocity * 0.7;
    }

    // 只有当没有任何移动输入时，速度才为0
    if (forwardInput === 0 && strafeInput === 0) {
      velocity = 0;
    }

    return { moveAngle, velocity };
  }

  /**
   * 执行物理移动和摄像机跟随
   */
  private executeMovementAndCameraFollow(
    moveX: number,
    moveZ: number,
    delta: number,
    hasInput: boolean,
    isOrbitControlActive: boolean,
  ): void {
    // 始终更新物理（重力需要持续作用）
    if (this.physicsWorldManager && this.model) {
      this.executeRapierPhysicsMovement(moveX, moveZ, delta, hasInput, isOrbitControlActive);
    } else if (hasInput) {
      // 回退到 Octree 碰撞检测（只在有输入时执行）
      this.executeOctreeMovement(moveX, moveZ, isOrbitControlActive);
    }
  }

  /**
   * 执行基于Rapier物理引擎的移动
   */
  private executeRapierPhysicsMovement(
    moveX: number,
    moveZ: number,
    delta: number,
    hasInput: boolean,
    isOrbitControlActive: boolean,
  ): void {
    // 记录移动前的位置，用于计算实际移动量（包括Y轴）
    const previousX = this.model!.position.x;
    const previousY = this.model!.position.y;
    const previousZ = this.model!.position.z;

    // 使用 Rapier 物理系统进行移动和碰撞检测（包括重力）
    const movement = new THREE.Vector3(moveX, 0, moveZ);
    const newPosition = this.physicsWorldManager!.moveCharacter(movement, delta);

    // 调整模型位置：胶囊体的位置是中心点，需要将模型脚部对齐到胶囊体底部
    const { capsuleBottomOffset } = this;

    if (this.modelConfig.transform?.position) {
      this.model!.position.set(
        newPosition.x + this.modelConfig.transform.position.x,
        newPosition.y - capsuleBottomOffset + this.modelConfig.transform.position.y,
        newPosition.z + this.modelConfig.transform.position.z,
      );
    }

    // 计算人物实际移动量（考虑碰撞后的修正，包括垂直移动）
    const actualMove = {
      x: this.model!.position.x - previousX,
      y: this.model!.position.y - previousY,
      z: this.model!.position.z - previousZ,
    };

    // 处理摄像机跟随
    this.cameraManager.handleCameraFollowing(this.model!.position, actualMove, hasInput, isOrbitControlActive, delta);
  }

  /**
   * 执行基于Octree的碰撞检测移动
   */
  private executeOctreeMovement(moveX: number, moveZ: number, isOrbitControlActive: boolean): void {
    if (this.worldOctree && this.playerCollider) {
      this.playerCollider.start.set(
        this.model!.position.x + moveX,
        this.model!.position.y + 0.35,
        this.model!.position.z + moveZ,
      );
      this.playerCollider.end.set(
        this.model!.position.x + moveX,
        this.model!.position.y + 1.0,
        this.model!.position.z + moveZ,
      );

      const result = this.worldOctree.capsuleIntersect(this.playerCollider);

      if (result) {
        this.playerCollider.translate(result.normal.multiplyScalar(result.depth));
        this.model!.position.x = this.playerCollider.start.x;
        this.model!.position.z = this.playerCollider.start.z;
      } else {
        this.model!.position.x += moveX;
        this.model!.position.z += moveZ;
      }
    } else {
      // 没有碰撞检测，直接移动
      this.model!.position.x += moveX;
      this.model!.position.z += moveZ;
    }

    // 处理摄像机跟随（不包含Y轴移动）
    const actualMove = { x: moveX, y: 0, z: moveZ };
    this.cameraManager.handleCameraFollowing(this.model!.position, actualMove, true, isOrbitControlActive);
  }

  /**
   * 最终处理（调整摄像机距离和记录状态）
   */
  private finalizeFrame(hasInput: boolean, isOrbitControlActive: boolean): void {
    // 调整摄像机距离以支持更大角度向上看（只在OrbitControls激活时）
    if (isOrbitControlActive) {
      this.adjustCameraDistanceForLookUp();
    }

    // 记录本帧是否有输入，用于下一帧判断
    this.hadInputLastFrame = hasInput;
    this.touchDelta = { x: 0, y: 0 };
  }

  /**
   * 调整摄像机距离以支持更大角度向上看（OrbitControls模式特定逻辑）
   * 注意：此方法保留了原有的业务逻辑，与CharacterCameraManager中的通用逻辑不同
   */
  private adjustCameraDistanceForLookUp(): void {
    if (!this.orbitControl) return;

    // 获取摄像机参数（根据当前角色高度动态计算）
    const cameraParams = this.capsuleManager.getCameraParams();

    // 获取当前摄像机的极角（垂直角度）
    const polarAngle = this.orbitControl.getPolarAngle();

    // 定义临界角度：当角度大于此值时认为接近地面
    const groundThreshold = Math.PI / 2; // 90度，水平角度
    const maxAngle = Math.PI / 2 + 0.8; // 最大允许角度

    let targetDistance: number;
    // 判断是否接近地面
    if (polarAngle <= groundThreshold) {
      // 离开地面时，恢复摇臂长度为标准距离
      targetDistance = cameraParams.distance + this.offset;
    } else {
      // 超过临界角度后，根据角度差值平滑过渡
      const angleDiff = polarAngle - groundThreshold; // 超出临界角度的部分
      const maxAngleDiff = maxAngle - groundThreshold; // 最大角度差

      // 计算过渡因子（0到1之间）
      const transitionFactor = Math.min(1, angleDiff / maxAngleDiff);

      // 从标准距离平滑过渡到最小距离（标准距离的一半）
      const minDistance = cameraParams.distance * 0.5;
      const maxDistance = cameraParams.distance + this.offset;
      targetDistance = maxDistance - (maxDistance - minDistance) * transitionFactor;
    }

    // 获取当前距离
    const currentDistance = this.orbitControl.getDistance();

    // 如果目标距离小于当前距离，需要立即调整
    if (targetDistance < currentDistance) {
      // 计算摄像机到目标点的方向向量
      const direction = new THREE.Vector3();
      direction.subVectors(this.camera.position, this.orbitControl.target).normalize();

      // 设置新的摄像机位置
      this.camera.position.copy(this.orbitControl.target).add(direction.multiplyScalar(targetDistance));

      // 更新OrbitControls的距离限制
      this.orbitControl.minDistance = Math.min(targetDistance, this.orbitControl.minDistance || 1);
      this.orbitControl.maxDistance = targetDistance;
    } else {
      // 如果目标距离大于等于当前距离，只更新最大距离限制
      this.orbitControl.maxDistance = targetDistance;

      // 平滑调整到目标距离（如果当前距离小于目标距离）
      if (currentDistance < targetDistance) {
        const direction = new THREE.Vector3();
        direction.subVectors(this.camera.position, this.orbitControl.target).normalize();

        // 使用插值平滑过渡到目标距离
        const newDistance = THREE.MathUtils.lerp(currentDistance, targetDistance, 0.05);
        this.camera.position.copy(this.orbitControl.target).add(direction.multiplyScalar(newDistance));
      }
    }

    // 更新OrbitControls
    this.orbitControl.update();
  }
}
