import * as THREE from 'three';
import { GsplatModifier, PackedSplats, SplatFileType, SplatMesh } from '@sparkjsdev/spark';
import { GaussianAbstractComponent, GaussianSplatConfig, LoaderStatus } from './gaussian-abstract-component';
import { sleep } from '@/utils';

const CHUNK_THRESHOLD = 262144; // 256KB threshold
const BYTES_PER_SPLAT = 32; // Each splat is 32 bytes

interface LoadProgressivelyOptions {
  url: string;
  container: SplatMesh;
  headers?: Record<string, string>;
  onLoad?: (receivedBytes: number) => void;
  onProgress?: (receivedBytes: number, totalBytes: number) => void;
}
interface LoadMeshConfig {
  position?: number[];
  rotation?: number[];
  scale?: number[];
  renderOrder?: number;
  onProgress?: (receivedBytes: number, totalBytes: number, loaderStatus: LoaderStatus) => void;
  renderCallback?: () => void;
  showLoadingUI?: boolean;
  // Spark 特有配置
  sparkOptions?: any;
  sphericalHarmonicsDegree?: number;
}
/**
 * Spark 库的 Gaussian Splatting 组件实现
 * 封装 @sparkjsdev/spark 库
 */
export class SparkComponent extends GaussianAbstractComponent<SplatMesh> {
  private viewerOptions: {
    fileBytes?: Uint8Array | ArrayBuffer;
    // Override file type
    fileType?: SplatFileType;
    // Use PackedSplats object as source
    packedSplats?: PackedSplats;
    // Reserve space for at least this many splats for construction
    maxSplats?: number;
    // Constructor callback to create splats
    constructSplats?: (splats: PackedSplats) => Promise<void> | void;
    // Callback for when mesh initialization is complete
    onLoad?: (mesh: SplatMesh) => Promise<void> | void;
    // Toggle controls whether SplatEdits have an effect, default true
    editable?: boolean;
    // Frame callback to update mesh. Call mesh.updateVersion() if we need to re-generate
    onFrame?: ({ mesh, time, deltaTime }: { mesh: SplatMesh; time: number; deltaTime: number }) => void;
    // Object-space and world-space splat modifiers to apply
    objectModifier?: GsplatModifier;
    worldModifier?: GsplatModifier;
  };
  private packedSplats: PackedSplats | PackedSplats[] | null = null;
  private globalScene: any;
  constructor(viewerOptions?: any, globalScene?: any) {
    super();
    this.viewerOptions = viewerOptions;
    this.globalScene = globalScene;
  }
  /**
   * 添加场景
   * @param url 场景文件URL
   * @param config 配置参数
   * @param id 可选的唯一标识符
   * @returns Promise<string> 返回场景ID
   */
  async addScene(url: string, config?: Partial<GaussianSplatConfig>): Promise<SplatMesh | SplatMesh[]> {
    try {
      if (config?.mortonConfig) {
        const response = await fetch(config?.mortonConfig);
        const mortonConfig = await response.json();

        this.viewer = [];
        this.packedSplats = [];
        const totalSize = mortonConfig?.tiles?.reduce((acc, tile) => acc + tile[2], 0) || 0;
        let currentDownloadSize = 0;

        // 如果提供了 mortonCenter，则根据距离排序 tiles
        let tiles = mortonConfig?.tiles || [];
        if (config?.mortonCenter) {
          const { x: centerX, y, z } = config.mortonCenter;
          const centerY = -y;
          const centerZ = -z;

          // 为每个 tile 计算中心点和距离
          const tilesWithDistance = tiles.map((tile) => {
            // tile[4] 是最小值 [minX, minY, minZ]
            // tile[5] 是最大值 [maxX, maxY, maxZ]
            const min = tile[4];
            const max = tile[5];

            // 计算 tile 的中心点
            const centerX_tile = (min[0] + max[0]) / 2;
            const centerY_tile = (min[1] + max[1]) / 2;
            const centerZ_tile = (min[2] + max[2]) / 2;

            // 计算中心点到 mortonCenter 的欧几里得距离
            const dx = centerX_tile - centerX;
            const dy = centerY_tile - centerY;
            const dz = centerZ_tile - centerZ;
            const distance = Math.sqrt(dx * dx + dy * dy + dz * dz);

            // 判断 tile 的范围是否包含 mortonCenter
            const containsCenter =
              centerX >= min[0] &&
              centerX <= max[0] &&
              centerY >= min[1] &&
              centerY <= max[1] &&
              centerZ >= min[2] &&
              centerZ <= max[2];

            return {
              tile,
              center: [centerX_tile, centerY_tile, centerZ_tile],
              minBound: tile[4],
              maxBound: tile[5],
              distance,
              containsCenter,
            };
          });

          // 两级排序：
          // 1. 包含 mortonCenter 的 tile 排在前面
          // 2. 按距离从近到远排序
          tilesWithDistance.sort((a, b) => {
            // 第一级排序：包含中心点的优先
            if (a.containsCenter && !b.containsCenter) return -1;
            if (!a.containsCenter && b.containsCenter) return 1;

            // 第二级排序：按距离从近到远
            return a.distance - b.distance;
          });

          // 提取排序后的 tiles
          tiles = tilesWithDistance.map((item) => item.tile);
        }
        // 并发加载 tiles，最多同时 3 个请求
        const maxConcurrent = 4;
        let completedCount = 0;

        const loadTile = async (tile: any, index: number): Promise<void> =>
          new Promise(async (resolve, reject) => {
            try {
              // Create SplatMesh with explicit fileType and fileBytes
              const splatMeshConfig = {
                position: config?.position,
                rotation: config?.rotation,
                scale: config?.scale,
                showLoadingUI: config?.showLoadingUI,
              };

              const { packedSplats, splatMesh } = await this.loadSplatMesh(
                {
                  url,
                  headers: {
                    Range: `bytes=${tile?.[1]}-${tile?.[1] + tile[2] - 1}`,
                    'cache-control': 'max-age=172800',
                  },
                },
                {
                  ...splatMeshConfig,
                  onProgress: (receivedBytes: number, totalBytes: number, loaderStatus: LoaderStatus) => {
                    if (loaderStatus === LoaderStatus.Done) {
                      currentDownloadSize += receivedBytes;
                      config?.onProgress?.(
                        Math.round((currentDownloadSize / totalSize) * 100) / 100,
                        LoaderStatus.Downloading,
                      );
                      resolve();
                    }
                  },
                },
              );

              (this.viewer as SplatMesh[])?.push(splatMesh);
              (this.packedSplats as PackedSplats[])?.push(packedSplats!);
              this.globalScene?.add(splatMesh);

              completedCount++;
            } catch (error) {
              reject(error);
            }
          });
        // 使用并发控制加载 tiles，每个任务间隔 200ms
        const loadTasks: Promise<void>[] = [];

        for (let i = 0; i < tiles.length; i++) {
          const tile = tiles[i];

          // 创建一个包含延迟的任务
          const task = (async () => {
            // 如果不是第一个任务，先等待 200ms
            if (i > 0) {
              await sleep(200);
            }
            // 执行 loadTile
            await loadTile(tile, i);
          })();

          loadTasks.push(task);
        }

        // 等待所有任务（包括 loadTile 和延迟）完成
        await Promise.all(loadTasks);

        config?.onProgress?.(1, LoaderStatus.Done);
      } else {
        // 直接加载splat大文件
        const { packedSplats, splatMesh } = await this.loadSplatMesh(
          { url },
          {
            ...config,
            onProgress: (receivedBytes: number, totalBytes?: number, loaderStatus?: LoaderStatus) => {
              const progress = receivedBytes / totalBytes!;
              config?.onProgress?.(progress, LoaderStatus.Downloading);
              if (loaderStatus === LoaderStatus.Done) {
                config?.onProgress?.(1, LoaderStatus.Done);
              }
            },
          },
        );
        this.viewer = splatMesh;
        this.packedSplats = packedSplats || null;
        this.globalScene?.add(splatMesh);
      }

      // 调用渲染回调
      config?.renderCallback?.();
      return this.viewer;
    } catch (error) {
      console.error('Failed to add Spark scene:', error);
      throw error;
    }
  }

  /**
   * 重写dispose方法，清理viewer
   */
  dispose(): void {
    // 处理 viewer
    if (this.viewer) {
      if (Array.isArray(this.viewer)) {
        this.viewer.forEach((v) => v?.dispose());
      } else {
        this.viewer.dispose();
      }
      this.viewer = null;
    }

    // 处理 packedSplats
    if (this.packedSplats) {
      if (Array.isArray(this.packedSplats)) {
        this.packedSplats.forEach((ps) => ps?.dispose());
      } else {
        this.packedSplats.dispose();
      }
      this.packedSplats = null;
    }

    super.dispose();
  }

  private async loadSplatMesh(
    option: {
      url?: string;
      headers?: Record<string, string>;
      fileBytes?: Uint8Array | ArrayBuffer;
      fileType?: SplatFileType;
    },
    config?: Partial<LoadMeshConfig>,
  ): Promise<{ splatMesh: SplatMesh; packedSplats?: PackedSplats }> {
    // 创建 SplatMesh
    const splatMesh = new SplatMesh({
      ...this.viewerOptions,
    });

    // 设置位置
    if (config?.position) {
      splatMesh.position.set(config.position[0], config.position[1], config.position[2]);
    }

    // 设置旋转（在默认旋转基础上）
    if (config?.rotation) {
      splatMesh.quaternion.set(config.rotation[0], config.rotation[1], config.rotation[2], config.rotation[3]);
    }

    // 设置缩放
    if (config?.scale) {
      splatMesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);
    }

    // 设置渲染顺序
    if (config?.renderOrder !== undefined) {
      splatMesh.renderOrder = config.renderOrder;
    }
    // 如果传入的是url，则使用渐进式加载
    if (option.url) {
      const loadOption: LoadProgressivelyOptions = { url: option.url, container: splatMesh };
      option.headers && (loadOption.headers = option.headers);
      this.loadProgressively({
        ...loadOption,
        onLoad: (receivedBytes: number) => {
          config?.onProgress?.(receivedBytes, receivedBytes, LoaderStatus.Done);
        },
        onProgress: (receivedBytes: number, totalBytes: number) => {
          config?.onProgress?.(receivedBytes, totalBytes, LoaderStatus.Downloading);
        },
      });
    } else {
      // 如果传入的是fileBytes，则直接加载
      splatMesh.packedSplats = new PackedSplats({
        fileBytes: option.fileBytes,
        fileType: option.fileType,
      });
      await splatMesh.packedSplats.initialized;
    }
    return {
      // packedSplats,
      splatMesh,
    };
  }

  private async loadProgressively(option: LoadProgressivelyOptions) {
    const response = await fetch(option.url, { headers: option.headers || {} });
    if (!response.ok) {
      throw new Error(`Failed to fetch: ${response.statusText}`);
    }
    const reader = response.body?.getReader();

    let receivedBytes = 0;
    let chunks: Uint8Array[] = [];
    let accumulatedBytes = 0;
    if (!reader) return;

    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        // Process remaining data (if any)
        if (chunks.length > 0 && accumulatedBytes > 0) {
          const remainingData = new Uint8Array(accumulatedBytes);
          let offset = 0;
          for (const chunk of chunks) {
            remainingData.set(chunk, offset);
            offset += chunk.length;
          }

          // Ensure remaining data is aligned to 32 bytes
          const alignedLength = Math.floor(remainingData.length / BYTES_PER_SPLAT) * BYTES_PER_SPLAT;
          if (alignedLength > 0) {
            const alignedData = remainingData.slice(0, alignedLength);
            await this.processChunk(alignedData, true, option.container);
          }
        }
        option?.onLoad?.(receivedBytes);

        break;
      }
      receivedBytes += value.length;
      chunks.push(value);
      accumulatedBytes += value.length;

      // Process when accumulated data exceeds CHUNK_THRESHOLD
      if (accumulatedBytes > CHUNK_THRESHOLD) {
        // Combine all chunks into one array
        const combinedData = new Uint8Array(accumulatedBytes);
        let offset = 0;
        for (const chunk of chunks) {
          combinedData.set(chunk, offset);
          offset += chunk.length;
        }

        // Calculate aligned bytes (must be multiple of BYTES_PER_SPLAT)
        const numSplatsAvailable = Math.floor(accumulatedBytes / BYTES_PER_SPLAT);
        const alignedBytes = numSplatsAvailable * BYTES_PER_SPLAT;

        // Process the aligned data (use slice to create a copy, not a view)
        const dataToProcess = combinedData.slice(0, alignedBytes);

        await this.processChunk(dataToProcess, true, option.container);

        // Keep remaining unprocessed data for next iteration
        const remainingBytes = accumulatedBytes - alignedBytes;
        if (remainingBytes > 0) {
          const remainingData = combinedData.slice(alignedBytes);
          chunks = [remainingData];
          accumulatedBytes = remainingBytes;
        } else {
          chunks = [];
          accumulatedBytes = 0;
        }

        option?.onProgress?.(receivedBytes, Number(response.headers.get('content-length')) || 0);
      }
    }
  }
  private async processChunk(data: Uint8Array, isFinal: boolean, splatMesh: SplatMesh) {
    try {
      const BYTES_PER_SPLAT = 32;
      const numSplats = Math.floor(data.length / BYTES_PER_SPLAT);

      if (numSplats === 0) return;

      // Create new PackedSplats from chunk data
      const packedSplats = new PackedSplats({
        fileBytes: data,
        fileType: SplatFileType.SPLAT,
      });

      // Wait for PackedSplats to initialize
      await packedSplats.initialized;

      // Add the new splats to existing SplatMesh
      if (splatMesh.packedSplats) {
        // Append new splats to existing PackedSplats
        splatMesh.packedSplats.appendPackedArray(packedSplats.packedArray!, true);
      } else {
        // First chunk - set the PackedSplats directly
        splatMesh.packedSplats = packedSplats;
      }
    } catch (e) {
      console.error('❌ Error processing chunk:', e);
    }
  }
}
