import { ref, Ref } from 'vue';

export class EventManager {
  public keysPressed: Ref<Record<string, boolean>> = ref({});
  public joystickInput: Ref<{ x: number; y: number; distance: number }> = ref({ x: 0, y: 0, distance: 0 });
  public touchDelta: Ref<{ x: number; y: number }> = ref({ x: 0, y: 0 });
  public isJoystickRunning: Ref<boolean> = ref(false);
  public cameraRotation: Ref<number> = ref(0);
  public isMousePressed: Ref<boolean> = ref(false); // 添加鼠标按下状态跟踪
  // 事件发射器
  private eventListeners: Map<string, Function[]> = new Map();

  private keyDownHandler?: (event: KeyboardEvent) => void;
  private keyUpHandler?: (event: KeyboardEvent) => void;
  private resizeHandler?: () => void;
  private mouseDownHandler?: (event: MouseEvent) => void;
  private mouseUpHandler?: (event: MouseEvent) => void;
  private touchStartHandler?: (event: TouchEvent) => void;
  private touchMoveHandler?: (event: TouchEvent) => void;
  private touchEndHandler?: (event: TouchEvent) => void;

  constructor() {
    this.setupEventListeners();
  }

  public on(event: string, callback: Function) {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, []);
    }
    this.eventListeners.get(event)!.push(callback);
  }

  public off(event: string, callback: Function) {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      const index = listeners.indexOf(callback);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    }
  }

  // 摇杆相关方法
  public updateJoystickInput(data: { x: number; y: number; distance: number }) {
    if (data) {
      this.joystickInput.value = data;
    }
  }

  public updateTouchDelta(delta: { x: number; y: number }) {
    if (delta) {
      this.touchDelta.value = delta;
    }
  }

  public updateCameraRotation(rotation: number) {
    this.cameraRotation.value = rotation;
  }

  public toggleJoystickRun(isRunning: boolean) {
    this.isJoystickRunning.value = isRunning;
  }

  // 工具方法
  public hasAnyInput(): boolean {
    const hasJoystickInput = this.joystickInput.value?.distance > 0;
    const hasKeyboardInput =
      this.keysPressed.value.keyw ||
      this.keysPressed.value.keya ||
      this.keysPressed.value.keys ||
      this.keysPressed.value.keyd;
    const hasMouseInput = this.isMousePressed.value; // 添加鼠标状态检查

    return hasJoystickInput || hasKeyboardInput || hasMouseInput;
  }

  public isInJoystickArea(x: number, y: number): boolean {
    const screenWidth = window.innerWidth;
    const screenHeight = window.innerHeight;

    const isLeftHalf = x < screenWidth / 2;
    const isBottomHalf = y > screenHeight / 2;

    return isLeftHalf && isBottomHalf;
  }

  public reset() {
    this.keysPressed.value = {};
    this.joystickInput.value = { x: 0, y: 0, distance: 0 };
    this.touchDelta.value = { x: 0, y: 0 };
    this.isJoystickRunning.value = false;
    this.cameraRotation.value = 0;
    this.isMousePressed.value = false; // 重置鼠标状态
  }

  public dispose() {
    if (this.keyDownHandler) document.removeEventListener('keydown', this.keyDownHandler);
    if (this.keyUpHandler) document.removeEventListener('keyup', this.keyUpHandler);
    if (this.resizeHandler) window.removeEventListener('resize', this.resizeHandler);
    if (this.mouseDownHandler) document.removeEventListener('mousedown', this.mouseDownHandler);
    if (this.mouseUpHandler) document.removeEventListener('mouseup', this.mouseUpHandler);
    if (this.touchStartHandler) document.removeEventListener('touchstart', this.touchStartHandler);
    if (this.touchMoveHandler) document.removeEventListener('touchmove', this.touchMoveHandler);
    if (this.touchEndHandler) document.removeEventListener('touchend', this.touchEndHandler);

    this.eventListeners.clear();
  }

  private setupEventListeners() {
    this.keyDownHandler = this.handleKeyDown.bind(this);
    this.keyUpHandler = this.handleKeyUp.bind(this);
    this.resizeHandler = this.handleResize.bind(this);
    this.mouseDownHandler = this.handleMouseDown.bind(this);
    this.mouseUpHandler = this.handleMouseUp.bind(this);
    this.touchStartHandler = this.handleTouchStart.bind(this);
    this.touchMoveHandler = this.handleTouchMove.bind(this);
    this.touchEndHandler = this.handleTouchEnd.bind(this);

    document.addEventListener('keydown', this.keyDownHandler);
    document.addEventListener('keyup', this.keyUpHandler);
    window.addEventListener('resize', this.resizeHandler);
    document.addEventListener('mousedown', this.mouseDownHandler);
    document.addEventListener('mouseup', this.mouseUpHandler);
    document.addEventListener('touchstart', this.touchStartHandler, { passive: false });
    document.addEventListener('touchmove', this.touchMoveHandler, { passive: false });
    document.addEventListener('touchend', this.touchEndHandler, { passive: false });
  }
  private emit(event: string, data?: any) {
    const listeners = this.eventListeners.get(event);
    if (listeners) {
      listeners.forEach((callback) => callback(data));
    }
  }

  private handleKeyDown(event: KeyboardEvent) {
    const key = event.code.toLowerCase();
    this.keysPressed.value[key] = true;

    // 触发自定义事件
    this.emit('keydown', { key, event });
  }

  private handleKeyUp(event: KeyboardEvent) {
    const key = event.code.toLowerCase();
    this.keysPressed.value[key] = false;

    // 触发自定义事件
    this.emit('keyup', { key, event });
  }

  private handleResize() {
    this.emit('resize');
  }

  private handleMouseDown(event: MouseEvent) {
    this.isMousePressed.value = true; // 设置鼠标按下状态
    this.emit('mousedown', event);
  }

  private handleMouseUp(event: MouseEvent) {
    this.isMousePressed.value = false; // 重置鼠标按下状态
    this.emit('mouseup', event);
  }

  private handleTouchStart(event: TouchEvent) {
    this.emit('touchstart', event);
  }

  private handleTouchMove(event: TouchEvent) {
    this.emit('touchmove', event);
  }

  private handleTouchEnd(event: TouchEvent) {
    this.emit('touchend', event);
  }
}
