import * as THREE from 'three';
import RAPIER from '@dimforge/rapier3d-compat';
import { TerrainManager, type UnrealTerrainConfig, type TerrainOptions } from './terrain-manager';

export interface RigidBodyInfo {
  rigidBody: RAPIER.RigidBody;
  collider: RAPIER.Collider;
  mesh?: THREE.Mesh;
  originalGeometry?: THREE.BufferGeometry; // 存储原始几何体用于调试可视化
}

export class PhysicsWorldManager {
  private world: RAPIER.World | null = null;
  private isInitialized = false;
  private rigidBodies: Map<string, RigidBodyInfo> = new Map();
  private characterController: RAPIER.KinematicCharacterController | null = null;
  private characterRigidBody: RAPIER.RigidBody | null = null;
  private characterCollider: RAPIER.Collider | null = null;
  private characterVelocity: THREE.Vector3 = new THREE.Vector3(0, 0, 0);
  private gravity = -9.81;
  private terrainManager: TerrainManager;
  private characterCapsuleRadius = 0.35;
  private characterCapsuleHeight = 1.0;
  private terrainMesh: THREE.Mesh | null = null;

  constructor() {
    this.terrainManager = new TerrainManager();
  }

  public async init() {
    try {
      // 初始化Rapier
      await RAPIER.init();

      // 创建物理世界，设置重力
      const gravity = new RAPIER.Vector3(0.0, -9.81, 0.0);
      this.world = new RAPIER.World(gravity);

      this.isInitialized = true;
      console.log('Rapier物理世界初始化成功');
    } catch (error) {
      console.error('Rapier初始化失败:', error);
    }
  }

  /**
   * 等待物理世界初始化完成
   */
  public async waitForInitialization(): Promise<void> {
    while (!this.isInitialized) {
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  }

  /**
   * 获取物理世界实例
   */
  public getWorld(): RAPIER.World | null {
    return this.world;
  }

  /**
   * 创建地面碰撞体
   */
  public createGround(size = 20, position: THREE.Vector3 = new THREE.Vector3(0, 0, 0)): string {
    if (!this.world) return '';

    const groundId = 'ground';

    // 创建静态刚体
    const rigidBodyDesc = RAPIER.RigidBodyDesc.fixed().setTranslation(position.x, position.y, position.z);
    const rigidBody = this.world.createRigidBody(rigidBodyDesc);

    // 创建立方体碰撞器（地面）
    const colliderDesc = RAPIER.ColliderDesc.cuboid(size / 2, 0.1, size / 2);
    const collider = this.world.createCollider(colliderDesc, rigidBody);

    this.rigidBodies.set(groundId, {
      rigidBody,
      collider,
    });

    console.log(`地面碰撞体创建成功: ${groundId}`);
    return groundId;
  }

  /**
   * 创建角色控制器
   */
  public createCharacterController(
    position: THREE.Vector3 = new THREE.Vector3(0, 1, 0),
    radius = 0.35,
    height = 1.0,
  ): void {
    if (!this.world) return;

    // 如果已存在角色控制器，先移除
    if (this.characterController || this.characterRigidBody) {
      this.removeCharacterController();
    }

    // 存储胶囊体参数
    this.characterCapsuleRadius = radius;
    this.characterCapsuleHeight = height;

    // 创建角色刚体（动态）
    const rigidBodyDesc = RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(
      position.x,
      position.y,
      position.z,
    );
    this.characterRigidBody = this.world.createRigidBody(rigidBodyDesc);

    // 创建胶囊碰撞器
    const colliderDesc = RAPIER.ColliderDesc.capsule(height / 2, radius);

    // 设置碰撞组，确保与地形正确交互
    colliderDesc.setCollisionGroups(0x00010001); // 组1，与组1碰撞
    colliderDesc.setSolverGroups(0x00010001); // 求解器组设置

    this.characterCollider = this.world.createCollider(colliderDesc, this.characterRigidBody);

    // 创建角色控制器
    this.characterController = this.world.createCharacterController(0.01);

    // 启用自动台阶功能 - 参数：(maxStepHeight, minWidth, includeVerticalWalls)
    this.characterController.enableAutostep(0.3, 0.1, true);

    // 启用贴地功能 - 参数：snapDistance
    this.characterController.enableSnapToGround(0.2);

    // 设置滑动角度（防止在陡峭表面上滑动）
    this.characterController.setSlideEnabled(true);

    console.log('🎮 角色控制器创建成功:');
    console.log(`   位置: (${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)})`);
    console.log(`   胶囊体: 半径=${radius}m, 高度=${height}m`);
    console.log(`   自动台阶: 最大高度=0.3m, 最小宽度=0.1m`);
    console.log(`   贴地距离: 0.2m`);
  }

  /**
   * 创建立方体碰撞体
   */
  public createBox(
    id: string,
    size: THREE.Vector3,
    position: THREE.Vector3,
    isStatic = true,
    mesh?: THREE.Mesh,
  ): string {
    if (!this.world) return '';

    // 创建刚体
    const rigidBodyDesc = isStatic ? RAPIER.RigidBodyDesc.fixed() : RAPIER.RigidBodyDesc.dynamic();

    rigidBodyDesc.setTranslation(position.x, position.y, position.z);
    const rigidBody = this.world.createRigidBody(rigidBodyDesc);

    // 创建立方体碰撞器
    const colliderDesc = RAPIER.ColliderDesc.cuboid(size.x / 2, size.y / 2, size.z / 2);
    const collider = this.world.createCollider(colliderDesc, rigidBody);

    this.rigidBodies.set(id, {
      rigidBody,
      collider,
      mesh,
    });

    // console.log(`立方体碰撞体创建成功: ${id}`);
    return id;
  }

  /**
   * 创建球体碰撞体
   */
  public createSphere(id: string, radius: number, position: THREE.Vector3, isStatic = true, mesh?: THREE.Mesh): string {
    if (!this.world) return '';

    // 创建刚体
    const rigidBodyDesc = isStatic ? RAPIER.RigidBodyDesc.fixed() : RAPIER.RigidBodyDesc.dynamic();

    rigidBodyDesc.setTranslation(position.x, position.y, position.z);
    const rigidBody = this.world.createRigidBody(rigidBodyDesc);

    // 创建球体碰撞器
    const colliderDesc = RAPIER.ColliderDesc.ball(radius);
    const collider = this.world.createCollider(colliderDesc, rigidBody);

    this.rigidBodies.set(id, {
      rigidBody,
      collider,
      mesh,
    });

    console.log(`球体碰撞体创建成功: ${id}`);
    return id;
  }

  /**
   * 从GLB模型创建碰撞体（使用三角网格）
   */
  public createMeshColliderFromGLB(
    id: string,
    gltfScene: THREE.Group,
    position: THREE.Vector3 = new THREE.Vector3(0, 0, 0),
    rotation: THREE.Euler = new THREE.Euler(0, 0, 0),
    scale: THREE.Vector3 = new THREE.Vector3(1, 1, 1),
    isStatic = true,
  ): string {
    if (!this.world) return '';

    // 收集所有网格的几何体
    const vertices: number[] = [];
    const indices: number[] = [];
    let vertexOffset = 0;

    gltfScene.traverse((child) => {
      if (child instanceof THREE.Mesh && child.geometry) {
        const { geometry } = child;

        // 确保几何体有位置属性
        if (!geometry.attributes.position) return;

        // 获取世界矩阵
        child.updateMatrixWorld(true);
        const worldMatrix = child.matrixWorld.clone();

        // 应用缩放、旋转和位置变换
        const scaleMatrix = new THREE.Matrix4().makeScale(scale.x, scale.y, scale.z);
        const rotationMatrix = new THREE.Matrix4().makeRotationFromEuler(rotation);
        const translationMatrix = new THREE.Matrix4().makeTranslation(position.x, position.y, position.z);

        const transformMatrix = new THREE.Matrix4()
          .multiplyMatrices(translationMatrix, rotationMatrix)
          .multiply(scaleMatrix)
          .multiply(worldMatrix);

        // 获取顶点数据
        const positionAttribute = geometry.attributes.position;
        const vertex = new THREE.Vector3();

        for (let i = 0; i < positionAttribute.count; i++) {
          vertex.fromBufferAttribute(positionAttribute, i);
          vertex.applyMatrix4(transformMatrix);
          vertices.push(vertex.x, vertex.y, vertex.z);
        }

        // 获取索引数据
        if (geometry.index) {
          const indexArray = geometry.index.array;
          for (let i = 0; i < indexArray.length; i++) {
            indices.push(indexArray[i] + vertexOffset);
          }
        } else {
          // 如果没有索引，创建顺序索引
          for (let i = 0; i < positionAttribute.count; i++) {
            indices.push(i + vertexOffset);
          }
        }

        vertexOffset += positionAttribute.count;
      }
    });

    if (vertices.length === 0 || indices.length === 0) {
      console.warn(`GLB模型 ${id} 没有找到有效的几何体数据`);
      return '';
    }

    // 创建刚体
    const rigidBodyDesc = isStatic ? RAPIER.RigidBodyDesc.fixed() : RAPIER.RigidBodyDesc.dynamic();

    rigidBodyDesc.setTranslation(0, 0, 0); // 位置已经在顶点变换中处理
    const rigidBody = this.world.createRigidBody(rigidBodyDesc);

    // 创建三角网格碰撞器
    const colliderDesc = RAPIER.ColliderDesc.trimesh(new Float32Array(vertices), new Uint32Array(indices));
    const collider = this.world.createCollider(colliderDesc, rigidBody);

    // 创建合并后的几何体用于调试可视化
    const mergedGeometry = new THREE.BufferGeometry();
    mergedGeometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
    mergedGeometry.setIndex(indices);
    mergedGeometry.computeVertexNormals();

    this.rigidBodies.set(id, {
      rigidBody,
      collider,
      originalGeometry: mergedGeometry,
    });

    console.log(`GLB模型碰撞体创建成功: ${id}, 顶点数: ${vertices.length / 3}, 三角形数: ${indices.length / 3}`);
    return id;
  }

  /**
   * 移动角色（带重力支持）
   */
  public moveCharacter(movement: THREE.Vector3, deltaTime = 0.016): THREE.Vector3 {
    if (!this.world || !this.characterController || !this.characterRigidBody || !this.characterCollider) {
      return new THREE.Vector3();
    }

    // 获取当前位置
    const currentPos = this.characterRigidBody.translation();

    // 应用重力到垂直速度
    if (!this.isCharacterGrounded()) {
      this.characterVelocity.y += this.gravity * deltaTime;
    } else {
      // 在地面上时，重置垂直速度（但允许小的向下速度以保持贴地）
      if (this.characterVelocity.y < 0) {
        this.characterVelocity.y = 0;
      }
    }

    // 限制下降速度（终端速度）
    const maxFallSpeed = -20;
    if (this.characterVelocity.y < maxFallSpeed) {
      this.characterVelocity.y = maxFallSpeed;
    }

    // 组合水平移动和垂直速度
    const totalMovement = new RAPIER.Vector3(movement.x, this.characterVelocity.y * deltaTime, movement.z);

    // 使用角色控制器计算移动
    this.characterController.computeColliderMovement(this.characterCollider, totalMovement);

    // 获取修正后的移动向量
    const correctedMovement = this.characterController.computedMovement();

    // 检查垂直碰撞
    if (Math.abs(correctedMovement.y) < Math.abs(totalMovement.y)) {
      // 发生了垂直碰撞，重置垂直速度
      if (totalMovement.y < 0 && correctedMovement.y >= 0) {
        // 撞到地面，重置下降速度
        this.characterVelocity.y = 0;
      } else if (totalMovement.y > 0 && correctedMovement.y <= 0) {
        // 撞到天花板，重置上升速度
        this.characterVelocity.y = 0;
      }
    }

    // 应用移动
    const newPos = {
      x: currentPos.x + correctedMovement.x,
      y: currentPos.y + correctedMovement.y,
      z: currentPos.z + correctedMovement.z,
    };

    this.characterRigidBody.setNextKinematicTranslation(newPos);

    return new THREE.Vector3(newPos.x, newPos.y, newPos.z);
  }

  /**
   * 获取角色位置
   */
  public getCharacterPosition(): THREE.Vector3 {
    if (!this.characterRigidBody) {
      return new THREE.Vector3();
    }

    const pos = this.characterRigidBody.translation();
    return new THREE.Vector3(pos.x, pos.y, pos.z);
  }

  /**
   * 设置角色位置
   */
  public setCharacterPosition(position: THREE.Vector3): void {
    if (!this.characterRigidBody) return;

    this.characterRigidBody.setTranslation({ x: position.x, y: position.y, z: position.z }, true);
  }

  /**
   * 获取角色胶囊体半径
   */
  public getCharacterCapsuleRadius(): number {
    return this.characterCapsuleRadius;
  }

  /**
   * 获取角色胶囊体高度
   */
  public getCharacterCapsuleHeight(): number {
    return this.characterCapsuleHeight;
  }

  /**
   * 检查角色是否在地面上
   */
  public isCharacterGrounded(): boolean {
    if (!this.characterController) return false;
    return this.characterController.computedGrounded();
  }

  /**
   * 让角色跳跃
   */
  public jumpCharacter(jumpForce = 4.0): boolean {
    if (!this.isCharacterGrounded()) {
      return false; // 只能在地面上跳跃
    }

    this.characterVelocity.y = jumpForce;
    return true;
  }

  /**
   * 获取角色垂直速度
   */
  public getCharacterVerticalVelocity(): number {
    return this.characterVelocity.y;
  }

  /**
   * 重置角色物理状态
   */
  public resetCharacterPhysics(): void {
    this.characterVelocity.set(0, 0, 0);
  }

  /**
   * 移除角色控制器
   */
  public removeCharacterController(): void {
    if (!this.world) return;

    // 移除角色控制器
    if (this.characterController) {
      this.world.removeCharacterController(this.characterController);
      this.characterController = null;
    }

    // 移除角色碰撞器
    if (this.characterCollider) {
      this.world.removeCollider(this.characterCollider, true);
      this.characterCollider = null;
    }

    // 移除角色刚体
    if (this.characterRigidBody) {
      this.world.removeRigidBody(this.characterRigidBody);
      this.characterRigidBody = null;
    }

    console.log('🗑️ 角色控制器已移除');
  }

  /**
   * 更新物理世界
   */
  public update(_deltaTime: number): void {
    if (!this.world) return;

    // 步进物理模拟
    this.world.step();

    // 同步动态物体的位置到Three.js网格
    this.rigidBodies.forEach((info, _id) => {
      if (info.mesh && !info.rigidBody.isFixed()) {
        const position = info.rigidBody.translation();
        const rotation = info.rigidBody.rotation();

        info.mesh.position.set(position.x, position.y, position.z);
        info.mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      }
    });
  }

  /**
   * 移除碰撞体
   */
  public removeRigidBody(id: string): void {
    const info = this.rigidBodies.get(id);
    if (info && this.world) {
      this.world.removeCollider(info.collider, true);
      this.world.removeRigidBody(info.rigidBody);
      this.rigidBodies.delete(id);
      // console.log(`碰撞体已移除: ${id}`);
    }
  }

  /**
   * 获取碰撞体信息
   */
  public getRigidBodyInfo(id: string): RigidBodyInfo | undefined {
    return this.rigidBodies.get(id);
  }

  /**
   * 获取所有碰撞体ID
   */
  public getAllRigidBodyIds(): string[] {
    return Array.from(this.rigidBodies.keys());
  }

  /**
   * 创建静态胶囊体刚体（用于NPC）
   * @param position 位置
   * @param radius 胶囊体半径
   * @param height 胶囊体高度
   * @returns 刚体句柄（ID）
   */
  public createStaticRigidBody(position: THREE.Vector3, radius: number, height: number): number {
    if (!this.world) {
      throw new Error('物理世界未初始化');
    }

    // 创建静态刚体
    const rigidBodyDesc = RAPIER.RigidBodyDesc.fixed().setTranslation(position.x, position.y, position.z);
    const rigidBody = this.world.createRigidBody(rigidBodyDesc);

    // 创建胶囊体碰撞器
    const colliderDesc = RAPIER.ColliderDesc.capsule(height / 2, radius);
    const collider = this.world.createCollider(colliderDesc, rigidBody);

    // 生成唯一ID
    const rigidBodyId = `static_${rigidBody.handle}`;

    this.rigidBodies.set(rigidBodyId, {
      rigidBody,
      collider,
    });

    console.log(
      `静态刚体创建成功: ${rigidBodyId} at (${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)})`,
    );
    return rigidBody.handle;
  }

  /**
   * 创建动态刚体（受重力影响）
   * @param position 位置
   * @param radius 胶囊体半径
   * @param height 胶囊体高度
   * @returns 刚体句柄
   */
  public createDynamicRigidBody(position: THREE.Vector3, radius: number, height: number): number {
    if (!this.world) {
      throw new Error('物理世界未初始化');
    }

    // 创建动态刚体（受重力影响）
    const rigidBodyDesc = RAPIER.RigidBodyDesc.dynamic()
      .setTranslation(position.x, position.y, position.z)
      .setLinearDamping(0.5) // 线性阻尼，减缓移动
      .setAngularDamping(1.0) // 角度阻尼，防止旋转
      .lockRotations(); // 锁定旋转，防止倒下

    const rigidBody = this.world.createRigidBody(rigidBodyDesc);

    // 创建胶囊体碰撞器
    const colliderDesc = RAPIER.ColliderDesc.capsule(height / 2, radius)
      .setFriction(0.5) // 摩擦力
      .setRestitution(0.0); // 弹性（0 = 完全非弹性）

    const collider = this.world.createCollider(colliderDesc, rigidBody);

    // 生成唯一ID
    const rigidBodyId = `dynamic_${rigidBody.handle}`;

    this.rigidBodies.set(rigidBodyId, {
      rigidBody,
      collider,
    });

    console.log(
      `动态刚体创建成功: ${rigidBodyId} at (${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)})`,
    );
    return rigidBody.handle;
  }

  /**
   * 通过句柄移除刚体
   * @param handle 刚体句柄
   */
  public removeRigidBodyByHandle(handle: number): void {
    // 尝试两种ID格式
    const staticId = `static_${handle}`;
    const dynamicId = `dynamic_${handle}`;

    if (this.rigidBodies.has(staticId)) {
      this.removeRigidBody(staticId);
    } else if (this.rigidBodies.has(dynamicId)) {
      this.removeRigidBody(dynamicId);
    } else {
      console.warn(`⚠️ 刚体不存在: handle ${handle}`);
    }
  }

  /**
   * 设置刚体位置
   * @param handle 刚体句柄
   * @param position 新位置
   */
  public setRigidBodyPosition(handle: number, position: THREE.Vector3): void {
    // 尝试两种ID格式
    const staticId = `static_${handle}`;
    const dynamicId = `dynamic_${handle}`;

    const info = this.rigidBodies.get(staticId) || this.rigidBodies.get(dynamicId);

    if (info && this.world) {
      info.rigidBody.setTranslation({ x: position.x, y: position.y, z: position.z }, true);
      console.log(
        `刚体位置更新: handle ${handle} -> (${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)})`,
      );
    } else {
      console.warn(`⚠️ 刚体不存在: handle ${handle}`);
    }
  }

  /**
   * 获取刚体位置
   * @param handle 刚体句柄
   * @returns 刚体位置，如果不存在则返回null
   */
  public getRigidBodyPosition(handle: number): THREE.Vector3 | null {
    const staticId = `static_${handle}`;
    const dynamicId = `dynamic_${handle}`;

    const info = this.rigidBodies.get(staticId) || this.rigidBodies.get(dynamicId);

    if (info) {
      const translation = info.rigidBody.translation();
      return new THREE.Vector3(translation.x, translation.y, translation.z);
    }

    return null;
  }

  /**
   * 对刚体施加力
   * @param handle 刚体句柄
   * @param force 力向量
   */
  public applyForceToRigidBody(handle: number, force: THREE.Vector3): void {
    const dynamicId = `dynamic_${handle}`;
    const info = this.rigidBodies.get(dynamicId);

    if (info?.rigidBody.isDynamic()) {
      info.rigidBody.applyImpulse({ x: force.x, y: force.y, z: force.z }, true);
    } else {
      console.warn(`⚠️ 动态刚体不存在或不是动态类型: handle ${handle}`);
    }
  }

  /**
   * 设置刚体速度
   * @param handle 刚体句柄
   * @param velocity 速度向量
   */
  public setRigidBodyVelocity(handle: number, velocity: THREE.Vector3): void {
    const dynamicId = `dynamic_${handle}`;
    const info = this.rigidBodies.get(dynamicId);

    if (info?.rigidBody.isDynamic()) {
      info.rigidBody.setLinvel({ x: velocity.x, y: velocity.y, z: velocity.z }, true);
    } else {
      console.warn(`⚠️ 动态刚体不存在或不是动态类型: handle ${handle}`);
    }
  }

  /**
   * 获取刚体速度
   * @param handle 刚体句柄
   * @returns 速度向量，如果不存在则返回null
   */
  public getRigidBodyVelocity(handle: number): THREE.Vector3 | null {
    const dynamicId = `dynamic_${handle}`;
    const info = this.rigidBodies.get(dynamicId);

    if (info?.rigidBody.isDynamic()) {
      const linvel = info.rigidBody.linvel();
      return new THREE.Vector3(linvel.x, linvel.y, linvel.z);
    }

    return null;
  }

  /**
   * 设置刚体水平速度（保持垂直速度不变）
   * @param handle 刚体句柄
   * @param velocityX X方向速度
   * @param velocityZ Z方向速度
   */
  public setRigidBodyHorizontalVelocity(handle: number, velocityX: number, velocityZ: number): void {
    const dynamicId = `dynamic_${handle}`;
    const info = this.rigidBodies.get(dynamicId);

    if (info?.rigidBody.isDynamic()) {
      const currentLinvel = info.rigidBody.linvel();
      info.rigidBody.setLinvel({ x: velocityX, y: currentLinvel.y, z: velocityZ }, true);
    } else {
      console.warn(`⚠️ 动态刚体不存在或不是动态类型: handle ${handle}`);
    }
  }

  /**
   * 射线检测
   */
  public raycast(origin: THREE.Vector3, direction: THREE.Vector3, maxDistance = 100) {
    if (!this.world) return null;

    const ray = new RAPIER.Ray(
      { x: origin.x, y: origin.y, z: origin.z },
      { x: direction.x, y: direction.y, z: direction.z },
    );

    return this.world.castRay(ray, maxDistance, true);
  }

  /**
   * 悬崖检测配置
   */
  private cliffDetectionConfig = {
    enabled: true,
    checkDistance: 1.2, // 前瞻距离（米）
    maxFallDistance: 3.0, // 允许的最大掉落高度（米）
    checkPoints: 3, // 检测点数量
    safetyMargin: 0.3, // 安全边距（米）
    rayOriginHeight: 0.5, // 射线起始高度（米）
  };

  /**
   * 检查角色前方是否有悬崖
   * @param currentPosition 当前位置
   * @param moveDirection 移动方向（已归一化）
   * @param checkDistance 检测距离（可选，默认使用配置值）
   * @returns true表示检测到悬崖，false表示安全
   */
  public checkCliffAhead(
    currentPosition: THREE.Vector3,
    moveDirection: THREE.Vector3,
    checkDistance?: number,
  ): boolean {
    if (!this.world || !this.cliffDetectionConfig.enabled) {
      return false;
    }

    const actualCheckDistance = checkDistance || this.cliffDetectionConfig.checkDistance;
    const { maxFallDistance, rayOriginHeight, safetyMargin } = this.cliffDetectionConfig;

    // 确保移动方向已归一化
    const normalizedDirection = moveDirection.clone().normalize();

    // 定义多个检测点（正前方、左前方、右前方）
    const checkOffsets = [
      { x: 0, z: 1 }, // 正前方
      { x: -safetyMargin, z: 1 }, // 左前方
      { x: safetyMargin, z: 1 }, // 右前方
    ];

    // 检查每个点
    for (const offset of checkOffsets) {
      // 计算检测点的世界坐标
      const checkPoint = currentPosition.clone();

      // 应用移动方向和偏移
      const forwardOffset = normalizedDirection.clone().multiplyScalar(actualCheckDistance * offset.z);
      const rightVector = new THREE.Vector3(-normalizedDirection.z, 0, normalizedDirection.x); // 右向量
      const sideOffset = rightVector.multiplyScalar(offset.x);

      checkPoint.add(forwardOffset).add(sideOffset);
      checkPoint.y += rayOriginHeight; // 设置射线起始高度

      // 向下投射射线
      const rayOrigin = checkPoint;
      const rayDirection = new THREE.Vector3(0, -1, 0); // 向下

      const hit = this.raycast(rayOrigin, rayDirection, maxFallDistance);

      if (!hit) {
        // 没有检测到地面，说明是悬崖
        // console.log(`🚫 检测到悬崖 - 位置: (${checkPoint.x.toFixed(2)}, ${checkPoint.y.toFixed(2)}, ${checkPoint.z.toFixed(2)})`);
        return true;
      }

      // 检查掉落距离是否过大
      const fallDistance = hit.toi; // Time of Impact = 碰撞距离
      if (fallDistance > maxFallDistance * 0.8) {
        // 80%阈值作为预警
        console.log(`⚠️ 检测到较大掉落 - 距离: ${fallDistance.toFixed(2)}m`);
        return true;
      }
    }

    return false; // 所有检测点都安全
  }

  /**
   * 检查指定位置是否有地面支撑
   * @param position 要检查的位置
   * @param radius 检测半径（可选）
   * @returns 地面支撑信息
   */
  public checkGroundSupport(
    position: THREE.Vector3,
    radius?: number,
  ): {
    hasSupport: boolean;
    distance?: number;
    normal?: THREE.Vector3;
  } {
    if (!this.world) {
      return { hasSupport: false };
    }

    const checkRadius = radius || this.characterCapsuleRadius;
    const maxCheckDistance = 2.0; // 最大检测距离

    // 在角色周围多个点进行检测
    const checkPoints = [
      { x: 0, z: 0 }, // 中心
      { x: checkRadius * 0.7, z: 0 }, // 右侧
      { x: -checkRadius * 0.7, z: 0 }, // 左侧
      { x: 0, z: checkRadius * 0.7 }, // 前方
      { x: 0, z: -checkRadius * 0.7 }, // 后方
    ];

    let supportCount = 0;
    let minDistance = Infinity;
    const avgNormal = new THREE.Vector3();

    for (const point of checkPoints) {
      const rayOrigin = new THREE.Vector3(
        position.x + point.x,
        position.y + 0.5, // 稍微抬高起始点
        position.z + point.z,
      );

      const hit = this.raycast(rayOrigin, new THREE.Vector3(0, -1, 0), maxCheckDistance);

      if (hit) {
        supportCount++;
        minDistance = Math.min(minDistance, hit.toi);

        // 累积法向量（如果可用）
        if (hit.normal) {
          avgNormal.add(new THREE.Vector3(hit.normal.x, hit.normal.y, hit.normal.z));
        }
      }
    }

    // 如果大部分检测点都有支撑，认为是安全的
    const hasSupport = supportCount >= checkPoints.length * 0.6; // 60%的点有支撑就认为安全

    if (hasSupport && avgNormal.length() > 0) {
      avgNormal.normalize();
    }

    return {
      hasSupport,
      distance: minDistance !== Infinity ? minDistance : undefined,
      normal: hasSupport && avgNormal.length() > 0 ? avgNormal : undefined,
    };
  }

  /**
   * 寻找安全的移动方向（沿着边缘滑动）
   * @param currentPosition 当前位置
   * @param intendedDirection 原本想要的移动方向
   * @returns 安全的移动方向，如果没有找到则返回null
   */
  public findSafeMovementDirection(
    currentPosition: THREE.Vector3,
    intendedDirection: THREE.Vector3,
  ): THREE.Vector3 | null {
    if (!this.world) return null;

    const testAngles = [-30, -15, 15, 30, -45, 45, -60, 60]; // 测试角度（度）

    for (const angle of testAngles) {
      // 将角度转换为弧度
      const radians = (angle * Math.PI) / 180;

      // 旋转原始方向
      const testDirection = intendedDirection.clone();
      const cos = Math.cos(radians);
      const sin = Math.sin(radians);

      const newX = testDirection.x * cos - testDirection.z * sin;
      const newZ = testDirection.x * sin + testDirection.z * cos;

      testDirection.set(newX, 0, newZ).normalize();

      // 检查这个方向是否安全
      if (!this.checkCliffAhead(currentPosition, testDirection)) {
        console.log(`✅ 找到安全方向 - 角度偏移: ${angle}°`);
        return testDirection;
      }
    }

    console.log(`❌ 未找到安全的移动方向`);
    return null; // 没有找到安全方向
  }

  /**
   * 设置悬崖检测配置
   */
  public setCliffDetectionConfig(config: Partial<typeof this.cliffDetectionConfig>): void {
    this.cliffDetectionConfig = { ...this.cliffDetectionConfig, ...config };
    console.log('🔧 悬崖检测配置已更新:', this.cliffDetectionConfig);
  }

  /**
   * 获取悬崖检测配置
   */
  public getCliffDetectionConfig() {
    return { ...this.cliffDetectionConfig };
  }

  /**
   * 从高度图加载地形
   * @param heightMapUrl - R16 高度图文件路径
   * @param unrealConfig - 虚幻引擎地形配置
   * @param options - 地形创建选项
   * @returns 地形物理体信息
   */
  public async loadTerrain(heightMapUrl: string, unrealConfig: UnrealTerrainConfig, options: TerrainOptions = {}) {
    if (!this.world) {
      console.error('物理世界未初始化，无法创建地形');
      return null;
    }

    try {
      console.log('🏔️ 开始加载地形物理体...');

      // 使用 TerrainManager 创建地形
      const terrainPhysics = await this.terrainManager.createTerrainFromHeightMap(
        this.world,
        heightMapUrl,
        unrealConfig,
        {
          friction: 0.8,
          restitution: 0.1,
          debug: true,
          ...options,
        },
      );

      // 将地形物理体添加到管理系统中
      const terrainId = `terrain_${Date.now()}`;
      this.rigidBodies.set(terrainId, {
        rigidBody: terrainPhysics.rigidBody,
        collider: terrainPhysics.collider,
        originalGeometry: terrainPhysics.visualGeometry, // 存储可视化几何体
      });

      console.log('✅ 地形物理体已添加到物理世界');
      console.log(`   地形ID: ${terrainId}`);
      console.log(`   尺寸: ${terrainPhysics.info.width.toFixed(1)}m × ${terrainPhysics.info.height.toFixed(1)}m`);
      console.log(
        `   高度范围: ${terrainPhysics.info.minHeight.toFixed(2)}m ~ ${terrainPhysics.info.maxHeight.toFixed(2)}m`,
      );

      return terrainPhysics;
    } catch (error) {
      console.error('❌ 地形创建失败:', error);
      return null;
    }
  }

  public getCharacterCollider() {
    return this.characterCollider;
  }

  /**
   * 获取地形网格（用于弹簧臂碰撞检测）
   */
  public getTerrainMesh(): THREE.Mesh | null {
    return this.terrainMesh;
  }

  /**
   * 加载默认平面地形
   * @param scene THREE.js场景对象
   * @param _options 地形选项
   */
  public async loadDefaultTerrain(
    scene: THREE.Scene,
    _options: {
      debug?: boolean;
    } = {},
  ): Promise<void> {
    if (!this.world) {
      console.error('物理世界未初始化，无法创建默认地形');
      return;
    }

    try {
      console.log('🏔️ 创建默认平面地形...');

      // 创建一个大的平面几何体作为默认地形
      const planeSize = 1000; // 平面大小 200x200
      const planeGeometry = new THREE.PlaneGeometry(planeSize, planeSize);

      // 创建平面网格
      const planeMesh = new THREE.Mesh(planeGeometry);

      // 将平面旋转90度使其水平放置，并设置位置为y=0
      planeMesh.rotation.x = -Math.PI / 2;
      planeMesh.position.set(0, -0.9, 0);
      planeMesh.receiveShadow = true;
      planeMesh.userData.isCollider = true;
      planeMesh.userData.isStatic = true;

      // 保存地形网格引用
      this.terrainMesh = planeMesh;

      // 添加到场景
      scene.add(planeMesh);

      // 在物理世界中创建对应的地面碰撞体
      this.createGround(planeSize, new THREE.Vector3(0, 0, 0));

      console.log(`✅ 默认平面地形创建成功: ${planeSize}x${planeSize}，位置: (0, 0, 0)`);
    } catch (error) {
      console.error('❌ 默认地形创建失败:', error);
      throw error;
    }
  }

  /**
   * 清理资源
   */
  public dispose(): void {
    if (this.world) {
      // 清理所有刚体
      this.rigidBodies.forEach((info) => {
        this.world!.removeCollider(info.collider, true);
        this.world!.removeRigidBody(info.rigidBody);
      });
      this.rigidBodies.clear();

      // 清理角色控制器
      if (this.characterController) {
        this.world.removeCharacterController(this.characterController);
        this.characterController = null;
      }

      // 释放世界
      this.world.free();
      this.world = null;
    }

    this.characterRigidBody = null;
    this.characterCollider = null;
    this.isInitialized = false;

    // 清理地形管理器
    if (this.terrainManager) {
      this.terrainManager.dispose();
    }

    console.log('PhysicsWorldManager已清理');
  }
}
