import * as THREE from 'three';
import { Octree } from 'three/examples/jsm/math/Octree.js';
import { Capsule } from 'three/examples/jsm/math/Capsule.js';
import { PhysicsWorldManager } from './physics-world-manager';
import { AnimationManager } from './animation-manager';
import { CharacterModelInfo, CharacterState } from '@/types';

/**
 * BaseCharacter 基类 - 所有角色和NPC的基础类
 * 提供基本的移动、物理、动画等功能
 */
export abstract class BaseCharacter {
  // 基本属性
  public readonly id: string;
  protected model?: THREE.Group;
  protected animationManager?: AnimationManager;
  protected modelConfig: CharacterModelInfo;
  protected scene: THREE.Scene;

  // 运动相关
  protected walkDirection = new THREE.Vector3();
  protected rotateAngle = new THREE.Vector3(0, 1, 0);
  protected rotateQuarternion: THREE.Quaternion = new THREE.Quaternion();
  protected baseRotation: THREE.Quaternion = new THREE.Quaternion();

  // 碰撞检测
  protected worldOctree: Octree | null = null;
  protected playerCollider: Capsule | null = null;
  protected physicsWorldManager: PhysicsWorldManager | null = null;

  // 悬崖检测配置
  protected cliffDetectionEnabled = true;
  protected cliffBehaviorMode: 'block' | 'slide' | 'slow' = 'slide';

  // 物理参数
  protected spawnPoint: THREE.Vector3;
  protected capsuleRadius: number;
  protected capsuleHeight: number;
  protected capsuleBottomOffset: number; // 胶囊体中心到底部的距离

  // 速度配置
  protected fadeDuration = 0.2;
  protected runVelocity = 5;
  protected walkVelocity = 2;

  constructor(
    id: string,
    modelConfig: CharacterModelInfo,
    scene: THREE.Scene,
    physicsWorldManager: PhysicsWorldManager,
    spawnPoint: THREE.Vector3,
    capsuleRadius = 0.35,
    capsuleHeight = 1.0,
    capsuleBottomOffset = 0.85,
  ) {
    this.id = id;
    this.modelConfig = modelConfig;
    this.scene = scene;
    this.physicsWorldManager = physicsWorldManager;
    this.spawnPoint = spawnPoint;
    this.capsuleRadius = capsuleRadius;
    this.capsuleHeight = capsuleHeight;
    this.capsuleBottomOffset = capsuleBottomOffset;
  }

  /**
   * 获取角色ID
   */
  public getId(): string {
    return this.id;
  }

  /**
   * 获取模型配置
   */
  public getModelConfig(): CharacterModelInfo {
    return this.modelConfig;
  }

  /**
   * 获取动画管理器
   */
  public getAnimationManager(): AnimationManager | undefined {
    return this.animationManager;
  }

  /**
   * 获取模型对象
   */
  public getModel(): THREE.Group | undefined {
    return this.model;
  }

  /**
   * 设置模型对象
   */
  public setModel(model: THREE.Group): void {
    this.model = model;
  }

  /**
   * 设置动画管理器
   */
  public setAnimationManager(animationManager: AnimationManager): void {
    this.animationManager = animationManager;
  }

  /**
   * 获取胶囊体半径
   */
  public getCapsuleRadius(): number {
    return this.capsuleRadius;
  }

  /**
   * 获取胶囊体高度
   */
  public getCapsuleHeight(): number {
    return this.capsuleHeight;
  }

  /**
   * 获取胶囊体底部偏移
   */
  public getCapsuleBottomOffset(): number {
    return this.capsuleBottomOffset;
  }

  /**
   * 获取当前位置
   */
  public getPosition(): THREE.Vector3 {
    return this.model?.position.clone() || this.spawnPoint.clone();
  }

  /**
   * 获取出生点位置
   */
  public getSpawnPoint(): THREE.Vector3 {
    return this.spawnPoint.clone();
  }

  /**
   * 设置位置
   */
  public setPosition(position: THREE.Vector3): void {
    if (this.model) {
      this.model.position.copy(position);

      // 同步物理位置
      if (this.physicsWorldManager) {
        const physicsPosition = new THREE.Vector3(
          position.x,
          position.y + (this.capsuleHeight / 2 + this.capsuleRadius),
          position.z,
        );
        this.physicsWorldManager.setCharacterPosition(physicsPosition);
      }
    }
  }

  /**
   * 获取当前旋转
   */
  public getRotation(): THREE.Euler {
    return this.model?.rotation.clone() || new THREE.Euler();
  }

  /**
   * 设置旋转
   */
  public setRotation(rotation: THREE.Euler): void {
    if (this.model) {
      this.model.rotation.copy(rotation);
      this.baseRotation.setFromEuler(rotation);
    }
  }

  /**
   * 设置基础旋转
   */
  public setBaseRotation(rotation: THREE.Euler): void {
    this.baseRotation.setFromEuler(rotation);
    if (this.model) {
      this.model.rotation.copy(rotation);
    }
  }

  /**
   * 获取模型缩放
   */
  public getScale(): THREE.Vector3 {
    return this.model?.scale.clone() || new THREE.Vector3(1, 1, 1);
  }

  /**
   * 设置模型缩放
   */
  public setScale(scale: number | THREE.Vector3): void {
    if (this.model) {
      if (typeof scale === 'number') {
        this.model.scale.setScalar(scale);
      } else {
        this.model.scale.copy(scale);
      }
    }
  }

  /**
   * 设置可见性
   */
  public setVisible(visible: boolean): void {
    if (this.model) {
      this.model.visible = visible;
    }
  }

  /**
   * 获取可见性
   */
  public isVisible(): boolean {
    return this.model?.visible ?? false;
  }

  /**
   * 设置世界八叉树碰撞检测
   */
  public setWorldOctree(octree: Octree, collider: Capsule): void {
    this.worldOctree = octree;
    this.playerCollider = collider;
    console.log(`🎮 角色 ${this.id}: Octree 碰撞检测已设置`);
  }

  /**
   * 设置悬崖检测配置
   */
  public setCliffDetection(enabled: boolean, behaviorMode: 'block' | 'slide' | 'slow' = 'slide'): void {
    this.cliffDetectionEnabled = enabled;
    this.cliffBehaviorMode = behaviorMode;
    console.log(`🎮 角色 ${this.id}: 悬崖检测设置: ${enabled ? '启用' : '禁用'}, 模式: ${behaviorMode}`);
  }

  /**
   * 获取悬崖检测状态
   */
  public getCliffDetectionStatus(): { enabled: boolean; mode: string } {
    return {
      enabled: this.cliffDetectionEnabled,
      mode: this.cliffBehaviorMode,
    };
  }

  /**
   * 播放动画
   */
  public playAnimation(animationName: string, _loop = true): void {
    if (this.animationManager?.isReady()) {
      this.animationManager.playAnimation(animationName);
    }
  }

  /**
   * 停止动画
   */
  public stopAnimation(): void {
    if (this.animationManager?.isReady()) {
      this.animationManager.stopAllAnimations();
    }
  }

  /**
   * 获取当前播放的动画名称
   */
  public getCurrentAnimation(): string {
    return this.animationManager?.getCurrentAnimation() || '';
  }

  /**
   * 执行基于Rapier物理引擎的移动
   */
  protected executePhysicsMovement(moveX: number, moveZ: number, delta: number): THREE.Vector3 {
    if (!this.model || !this.physicsWorldManager) {
      return this.model?.position.clone() || new THREE.Vector3();
    }

    // 使用 Rapier 物理系统进行移动和碰撞检测（包括重力）
    const movement = new THREE.Vector3(moveX, 0, moveZ);
    const newPosition = this.physicsWorldManager.moveCharacter(movement, delta);

    // 调整模型位置：胶囊体的位置是中心点，需要将模型脚部对齐到胶囊体底部
    const { capsuleBottomOffset } = this;

    if (this.modelConfig.transform?.position) {
      this.model.position.set(
        newPosition.x + this.modelConfig.transform.position.x,
        newPosition.y - capsuleBottomOffset + this.modelConfig.transform.position.y,
        newPosition.z + this.modelConfig.transform.position.z,
      );
    } else {
      this.model.position.set(newPosition.x, newPosition.y - capsuleBottomOffset, newPosition.z);
    }

    return this.model.position.clone();
  }

  /**
   * 检测移动方向是否会导致掉落悬崖
   */
  protected checkCliffDetection(moveDirection: THREE.Vector3): {
    isCliff: boolean;
    safeDirection?: THREE.Vector3;
    reason?: string;
  } {
    if (!this.cliffDetectionEnabled || !this.physicsWorldManager || !this.model) {
      return { isCliff: false };
    }

    const currentPosition = this.model.position.clone();
    const hasCliff = this.physicsWorldManager.checkCliffAhead(currentPosition, moveDirection);

    if (!hasCliff) {
      return { isCliff: false };
    }

    switch (this.cliffBehaviorMode) {
      case 'block':
        return {
          isCliff: true,
          reason: 'blocked',
        };

      case 'slide':
        const safeDirection = this.physicsWorldManager.findSafeMovementDirection(currentPosition, moveDirection);
        return {
          isCliff: true,
          safeDirection: safeDirection || undefined,
          reason: safeDirection ? 'redirected' : 'blocked',
        };

      case 'slow':
        const slowDirection = moveDirection.clone().multiplyScalar(0.3);
        return {
          isCliff: true,
          safeDirection: slowDirection,
          reason: 'slowed',
        };

      default:
        return { isCliff: false };
    }
  }

  /**
   * 应用悬崖检测结果到移动向量
   */
  protected applyCliffDetection(
    moveX: number,
    moveZ: number,
  ): {
    moveX: number;
    moveZ: number;
    wasBlocked: boolean;
  } {
    if (Math.abs(moveX) < 0.001 && Math.abs(moveZ) < 0.001) {
      return { moveX, moveZ, wasBlocked: false };
    }

    const moveDirection = new THREE.Vector3(moveX, 0, moveZ).normalize();
    const detection = this.checkCliffDetection(moveDirection);

    if (!detection.isCliff) {
      return { moveX, moveZ, wasBlocked: false };
    }

    if (!detection.safeDirection) {
      return { moveX: 0, moveZ: 0, wasBlocked: true };
    }

    const originalMagnitude = Math.sqrt(moveX * moveX + moveZ * moveZ);
    const correctedMoveX = detection.safeDirection.x * originalMagnitude;
    const correctedMoveZ = detection.safeDirection.z * originalMagnitude;

    return {
      moveX: correctedMoveX,
      moveZ: correctedMoveZ,
      wasBlocked: false,
    };
  }

  /**
   * 更新角色状态和动画
   */
  protected updateCharacterStateAndAnimation(delta: number, state: CharacterState): void {
    if (this.animationManager?.isReady()) {
      this.animationManager.updateAnimationByState(state);
      this.animationManager.update(delta);
    } else if (this.animationManager && !this.animationManager.isReady()) {
      this.animationManager.update(delta);
    }
  }

  /**
   * 主更新方法 - 子类需要实现
   */
  public abstract update(delta: number, ...args: any[]): void;

  /**
   * 销毁角色
   */
  public dispose(): void {
    if (this.animationManager) {
      this.animationManager.dispose();
      this.animationManager = undefined;
    }

    if (this.model) {
      this.scene.remove(this.model);

      this.model.traverse((child) => {
        if (child instanceof THREE.Mesh) {
          if (child.geometry) {
            child.geometry.dispose();
          }
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((material) => material.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });

      this.model = undefined;
    }

    console.log(`🎮 角色 ${this.id} 已销毁`);
  }
}
