import * as THREE from 'three';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { AnimationStateMachine, AnimationState, AnimationContext } from './animation-state-machine';
import { AnimationConfig, CharacterState, ModelAnimationConfig } from '@/types';

const DEFAULT_ANIMATIONS: AnimationConfig[] = [
  { name: 'Idle', fileName: 'Idle.fbx' },
  { name: 'Walking', fileName: 'Walking.fbx' },
  { name: 'Running', fileName: 'Running.fbx' },
  { name: 'Falling', fileName: 'Falling.fbx' },
  { name: 'Jumping', fileName: 'Jumping.fbx' },
];
export class AnimationManager {
  private mixer?: THREE.AnimationMixer;
  private animationsMap: Map<string, THREE.AnimationAction> = new Map();
  private fadeDuration = 0.2;
  private stateMachine: AnimationStateMachine;
  private isInitialized = false; // 添加初始化状态标志
  private animationConfig?: ModelAnimationConfig; // 动画配置

  // 动画播放速率相关
  private characterHeight = 1.65; // 角色高度（米）
  private runVelocity = 5; // 跑步速度（米/秒）
  private walkVelocity = 2; // 走路速度（米/秒）// 上次计算的播放速率
  private animationPlaybackRates: Map<string, number> = new Map(); // 每个动画的播放速率
  private animationSpeedScale = 1.0; // 动画速度比例

  // 默认动画配置

  private currentAction = '';

  constructor(
    model: THREE.Group,
    fadeDuration = 0.2,
    characterHeight = 1.65,
    runVelocity = 5,
    walkVelocity = 2,
    animationConfig?: ModelAnimationConfig,
    animationSpeedScale = 1.0,
  ) {
    this.mixer = new THREE.AnimationMixer(model);
    this.fadeDuration = fadeDuration;
    this.animationConfig = animationConfig;
    this.characterHeight = characterHeight;
    this.runVelocity = runVelocity;
    this.walkVelocity = walkVelocity;
    this.animationSpeedScale = animationSpeedScale;
    this.stateMachine = new AnimationStateMachine();

    // 设置状态机回调
    this.stateMachine.onStateChange((_from, to) => {
      this.playAnimationByState(to);
    });

    // 确保状态机初始状态为 IDLE
    this.stateMachine.transitionTo(AnimationState.IDLE);
  }

  /**
   * 初始化动画系统
   */
  async init(): Promise<void> {
    console.log('🎭 初始化动画管理器...');
    console.log('🎭 Mixer状态:', this.mixer ? '已创建' : '未创建');
    console.log('🎭 动画配置:', this.animationConfig ? '已配置' : '使用默认配置');
    console.log('🎭 已加载动画数量:', this.animationsMap.size);

    // 如果已经通过loadGLBAnimations加载了动画，跳过额外加载
    if (this.animationsMap.size > 0) {
      console.log('✅ 检测到已加载的GLB内置动画，跳过外部动画加载');
    } else if (this.animationConfig) {
      // 检查是否是内置动画配置（basePath为空或undefined）
      if (!this.animationConfig.basePath || this.animationConfig.basePath.trim() === '') {
        console.log('📋 检测到内置动画配置（basePath为空），等待GLB动画加载');
        // 不执行任何操作，等待loadGLBAnimations被调用
        if (this.animationConfig?.isFromQuery) {
          await this.loadAnimationsFromConfig(this.animationConfig);
        }
      } else {
        // 使用模型特定的动画配置（外部文件）
        await this.loadAnimationsFromConfig(this.animationConfig);
      }
    } else {
      // 使用默认动画配置（从外部文件加载）
      console.warn('⚠️ 没有动画配置且没有内置动画，尝试从默认路径加载');
      await this.loadAnimations();
    }

    // 播放默认动画
    if (this.animationsMap.size > 0) {
      // 计算所有动画的播放速率
      this.calculateAllAnimationPlaybackRates();

      // 确保状态机也同步到 IDLE 状态
      this.stateMachine.transitionTo(AnimationState.IDLE);

      this.isInitialized = true; // 标记为已初始化
      // 直接播放 Idle 动画
      this.playAnimation('Idle');
      console.log('✅ 动画管理器初始化完成，开始播放 Idle 动画');
    } else {
      console.warn('⚠️ 动画管理器初始化完成，但没有可用动画');
    }
  }

  /**
   * 更新动画系统
   */
  update(delta: number): void {
    this.mixer?.update(delta);
  }

  /**
   * 播放指定动画
   */
  playAnimation(animationName: string): boolean {
    if (this.currentAction === animationName) {
      return true; // 已经在播放该动画
    }

    let toPlay = this.animationsMap.get(animationName);
    const current = this.animationsMap.get(this.currentAction);

    // 如果找不到精确匹配，尝试查找相似的动画名称
    if (!toPlay) {
      const availableAnimations = Array.from(this.animationsMap.keys());
      const lowerCaseTarget = animationName.toLowerCase();

      // 尝试不区分大小写的匹配
      const similarAnimation = availableAnimations.find((name) => name.toLowerCase() === lowerCaseTarget);

      if (similarAnimation) {
        console.log(`🔄 找到相似动画: "${animationName}" -> "${similarAnimation}"`);
        toPlay = this.animationsMap.get(similarAnimation);
      } else {
        // 尝试部分匹配（例如 "Walking" 匹配 "walk"）
        const partialMatch = availableAnimations.find(
          (name) => name.toLowerCase().includes(lowerCaseTarget) || lowerCaseTarget.includes(name.toLowerCase()),
        );

        if (partialMatch) {
          console.log(`🔄 找到部分匹配动画: "${animationName}" -> "${partialMatch}"`);
          toPlay = this.animationsMap.get(partialMatch);
        }
      }
    }

    if (current && toPlay) {
      current.fadeOut(this.fadeDuration);
      toPlay.reset().fadeIn(this.fadeDuration).play();

      // 应用播放速率
      const playbackRate = this.animationPlaybackRates.get(animationName) || 1.0;
      toPlay.setEffectiveTimeScale(playbackRate);

      this.currentAction = animationName;
      return true;
    }
    if (toPlay && !current) {
      // 初始化时没有当前动画，直接播放
      console.log(`✅ 初始动画播放: ${animationName}`);
      toPlay.reset().play();
      this.currentAction = animationName;

      // 确保动画权重正确设置
      toPlay.setEffectiveWeight(1.0);

      // 应用播放速率
      const playbackRate = this.animationPlaybackRates.get(animationName) || 1.0;
      toPlay.setEffectiveTimeScale(playbackRate);

      console.log(
        `🎭 动画 "${animationName}" 权重设置为: ${toPlay.getEffectiveWeight()}, 播放速率: ${playbackRate.toFixed(3)}`,
      );

      return true;
    }

    console.warn(`⚠️ 动画切换失败: 找不到动画 "${animationName}"`);
    console.log(`   可用动画: [${Array.from(this.animationsMap.keys()).join(', ')}]`);

    // 尝试使用任何可用的动画作为后备
    if (!toPlay && this.animationsMap.size > 0) {
      const firstAvailableAnimation = this.animationsMap.values().next().value;
      const firstName = this.animationsMap.keys().next().value;
      if (firstAvailableAnimation) {
        console.log(`🔄 使用第一个可用动画作为替代: ${firstName}`);
        if (current) current.fadeOut(this.fadeDuration);
        firstAvailableAnimation.reset().fadeIn(this.fadeDuration).play();

        // 应用播放速率
        const playbackRate = this.animationPlaybackRates.get(animationName) || 1.0;
        firstAvailableAnimation.setEffectiveTimeScale(playbackRate);

        this.currentAction = firstName; // 记录实际播放的动画名称
        return true;
      }
    }
    return false;
  }

  /**
   * 检查动画管理器是否已初始化
   */
  isReady(): boolean {
    return this.isInitialized && this.animationsMap.size > 0;
  }

  /**
   * 获取当前播放的动画名称
   */
  getCurrentAnimation(): string {
    return this.stateMachine.getCurrentState().toString();
  }

  /**
   * 获取当前播放的动画动作
   */
  getCurrentAction(): THREE.AnimationAction | null {
    if (!this.currentAction) {
      return null;
    }
    return this.animationsMap.get(this.currentAction) || null;
  }

  /**
   * 获取所有可用的动画名称
   */
  getAvailableAnimations(): string[] {
    return Array.from(this.animationsMap.keys());
  }

  /**
   * 检查指定动画是否存在
   */
  hasAnimation(animationName: string): boolean {
    return this.animationsMap.has(animationName);
  }

  /**
   * 设置动画淡入淡出时间
   */
  setFadeDuration(duration: number): void {
    this.fadeDuration = duration;
  }

  /**
   * 根据角色状态更新并播放合适的动画（使用状态机）
   */
  updateAnimationByState(state: CharacterState, currentVelocity?: number): string {
    // 如果动画管理器还没有初始化完成，返回默认状态
    if (!this.isInitialized || this.animationsMap.size === 0) {
      // 只在第一次输出警告，避免日志噪音
      if (Math.random() < 0.01) {
        // 大约1%的概率输出
        console.log('🎭 动画管理器未初始化完成，跳过状态更新');
      }
      return 'Idle';
    }

    // 将CharacterState转换为AnimationContext
    const context: Partial<AnimationContext> = {
      isGrounded: state.isGrounded,
      hasMovementInput: state.hasMovementInput,
      forwardInput: state.forwardInput,
      strafeInput: state.strafeInput,
      jumpPressed: state.jumpPressed || false,
      isJumping: state.isJumping || false,
      currentVelocity, // 传入当前速度
    };

    // 更新状态机上下文
    this.stateMachine.updateContext(context);

    // 更新状态机（会自动处理状态转移）
    const currentState = this.stateMachine.update(0.016); // 假设60fps

    return currentState.toString();
  }

  /**
   * 获取当前应该使用的移动速度类型
   */
  getCurrentSpeedType(): 'running' | 'walking' | 'idle' {
    const currentState = this.stateMachine.getCurrentState();
    switch (currentState) {
      case AnimationState.WALKING:
        return 'walking';
      case AnimationState.RUNNING:
        return 'running';
      case AnimationState.FALLING: // 下落时也可以有水平移动
        return 'running';
      case AnimationState.JUMPING: // 跳跃时保持移动能力
        return 'running';
      default:
        return 'idle';
    }
  }

  /**
   * 停止所有动画
   */
  stopAllAnimations(): void {
    if (this.mixer) {
      this.mixer.stopAllAction();
    }
  }

  /**
   * 销毁动画管理器
   */
  dispose(): void {
    this.stopAllAnimations();
    this.animationsMap.clear();
    this.mixer = undefined;
    console.log('🗑️ 动画管理器已销毁');
  }

  /**
   * 调试动画状态
   */
  debugAnimationState(): void {
    if (!this.mixer) {
      console.log('🎭 调试: 动画混合器不存在');
      return;
    }

    const currentState = this.stateMachine.getCurrentState();
    console.log('🎭 动画状态调试:');
    console.log(`   当前状态: ${currentState}`);
    console.log(`   可用动画: [${Array.from(this.animationsMap.keys()).join(', ')}]`);

    // 状态机调试信息
    const debugInfo = this.stateMachine.getDebugInfo();
    console.log('🎭 状态机调试信息:', debugInfo);

    this.animationsMap.forEach((action, name) => {
      console.log(
        `   ${name}: enabled=${action.enabled}, weight=${action.weight.toFixed(3)}, time=${action.time.toFixed(3)}`,
      );
    });
  }

  /**
   * 获取状态机调试信息
   */
  getStateMachineDebugInfo(): any {
    return this.stateMachine.getDebugInfo();
  }

  /**
   * 更新角色参数并重新计算播放速率
   * @param characterHeight 角色高度（米）
   * @param runVelocity 跑步速度（米/秒）
   * @param walkVelocity 走路速度（米/秒）
   */
  updateCharacterParameters(characterHeight: number, runVelocity: number, walkVelocity: number): void {
    this.characterHeight = characterHeight;
    this.runVelocity = runVelocity;
    this.walkVelocity = walkVelocity;

    // 重新计算所有动画的播放速率
    if (this.isInitialized) {
      this.calculateAllAnimationPlaybackRates();

      // 如果当前有播放的动画，更新其播放速率
      const currentAction = this.getCurrentAction();
      if (currentAction && this.currentAction) {
        const playbackRate = this.animationPlaybackRates.get(this.currentAction) || 1.0;
        currentAction.setEffectiveTimeScale(playbackRate);
      }
    }
  }

  /**
   * 从GLB模型加载内置动画
   * @param gltf GLB模型数据
   * @param animationMapping 可选的动画名称映射配置（从配置文件中读取）
   */
  loadGLBAnimations(gltf: any, animationMapping?: Record<string, string>): void {
    if (!this.mixer) return;

    console.log(`🎭 开始加载GLB内置动画，共 ${gltf.animations.length} 个:`);

    // 如果提供了配置中的映射，使用配置映射
    if (animationMapping) {
      console.log(`📋 使用配置文件中的动画映射:`, animationMapping);

      // 创建一个反向映射：GLB动画名 -> 标准名称
      const reverseMapping: Record<string, string> = {};
      for (const [standardName, glbName] of Object.entries(animationMapping)) {
        reverseMapping[glbName] = standardName;
      }

      gltf.animations.forEach((clip: THREE.AnimationClip) => {
        const action = this.mixer!.clipAction(clip);
        const originalName = clip.name;

        // 查找该GLB动画应该映射到哪个标准名称
        const mappedName = reverseMapping[originalName];

        if (mappedName) {
          console.log(`✅ GLB动画 "${originalName}" 映射为 "${mappedName}" (配置映射)`);
          this.animationsMap.set(mappedName, action);

          // 同时保存原始名称的引用
          if (mappedName !== originalName) {
            this.animationsMap.set(originalName, action);
          }
        } else {
          console.log(`⚠️ GLB动画 "${originalName}" 未在配置中映射，保持原名称`);
          this.animationsMap.set(originalName, action);
        }
      });
    } else {
      // 使用默认的自动映射逻辑
      console.log(`🔄 使用默认自动映射逻辑`);

      const animationNameMap: Record<string, string> = {
        // 常见的动画名称变体
        idle: 'Idle',
        Idle: 'Idle',
        IDLE: 'Idle',
        walk: 'Walking',
        Walk: 'Walking',
        walking: 'Walking',
        Walking: 'Walking',
        WALK: 'Walking',
        run: 'Running',
        Run: 'Running',
        running: 'Running',
        Running: 'Running',
        RUN: 'Running',
        jump: 'Jumping',
        Jump: 'Jumping',
        jumping: 'Jumping',
        Jumping: 'Jumping',
        JUMP: 'Jumping',
        fall: 'Falling',
        Fall: 'Falling',
        falling: 'Falling',
        Falling: 'Falling',
        FALL: 'Falling',
      };

      gltf.animations.forEach((clip: THREE.AnimationClip, index: number) => {
        const action = this.mixer!.clipAction(clip);
        const originalName = clip.name;

        // 尝试映射到标准名称
        let mappedName = animationNameMap[originalName];

        // 如果没有映射，尝试通过索引映射
        if (!mappedName) {
          const indexMap = ['Idle', 'Walking', 'Running', 'Jumping', 'Falling'];
          if (index < indexMap.length) {
            mappedName = indexMap[index];
            console.log(`🔄 GLB动画 "${originalName}" (索引${index}) 映射为 "${mappedName}"`);
          } else {
            mappedName = originalName; // 保持原名称
            console.log(`⚠️ GLB动画 "${originalName}" 无法映射，保持原名称`);
          }
        } else {
          console.log(`✅ GLB动画 "${originalName}" 映射为 "${mappedName}"`);
        }

        // 存储映射后的动画
        this.animationsMap.set(mappedName, action);

        // 如果映射后的名称与原名称不同，也保存原名称的引用
        if (mappedName !== originalName) {
          this.animationsMap.set(originalName, action);
        }
      });
    }

    console.log(`✅ GLB动画加载完成，可用动画: [${Array.from(this.animationsMap.keys()).join(', ')}]`);
  }

  /**
   * 添加自定义动画配置并加载
   */
  async addCustomAnimations(animations: AnimationConfig[]): Promise<void> {
    await this.loadAnimations(animations);
  }

  /**
   * 从模型配置加载动画文件（支持URL和本地路径）
   */
  private async loadAnimationsFromConfig(config: ModelAnimationConfig): Promise<void> {
    const fbxLoader = new FBXLoader();
    // 导入GLTFLoader用于加载GLB动画文件
    const { GLTFLoader } = await import('three/examples/jsm/loaders/GLTFLoader.js');
    const gltfLoader = new GLTFLoader();
    let loadedCount = 0;

    console.log(`🎭 开始从配置加载动画文件...`);
    console.log(`🎭 基础路径: ${config.basePath}`);

    // 遍历动画配置
    for (const [animationName, item] of Object.entries(config.animations)) {
      try {
        const fileName = typeof item === 'object' ? item?.url : item;
        const isGLB = fileName.toLowerCase().endsWith('.glb');

        // 判断是否为URL（包含http或https）
        const isUrl = fileName.startsWith('http://') || fileName.startsWith('https://');

        let filePath: string;
        const idx = typeof item === 'object' ? item?.animationIdx : 0;
        if (isUrl) {
          filePath = fileName; // 直接使用URL
          console.log(`🌐 加载动画: ${animationName} 从URL: ${filePath}`);
        } else {
          filePath = `./${config.basePath}${fileName}`;
          console.log(`📁 加载动画: ${animationName} 从本地: ${filePath}`);
        }

        let animationClip: THREE.AnimationClip | null = null;

        if (isGLB) {
          // 加载GLB动画文件
          const gltf = await gltfLoader.loadAsync(filePath);
          if (gltf.animations && gltf.animations.length > 0) {
            animationClip = gltf.animations[idx]; // 根据索引取动画剪辑
            console.log(`✅ GLB动画文件加载成功: ${animationName} (原名: ${animationClip.name})`);
          } else {
            console.warn(`⚠️ GLB动画文件中没有找到动画剪辑: ${filePath}`);
            continue;
          }
        } else {
          // 加载FBX动画文件
          const animationFBX = await fbxLoader.loadAsync(filePath);
          if (animationFBX.animations && animationFBX.animations.length > 0) {
            animationClip = animationFBX.animations[0]; // 取第一个动画剪辑
            console.log(`✅ FBX动画文件加载成功: ${animationName} (原名: ${animationClip.name})`);
          } else {
            console.warn(`⚠️ FBX动画文件中没有找到动画剪辑: ${filePath}`);
            continue;
          }
        }

        if (animationClip) {
          const originalName = animationClip.name;

          // 创建一个新的动画剪辑，使用配置中的名称
          const renamedClip = animationClip.clone();
          renamedClip.name = animationName;

          // 创建动画动作并添加到映射中
          const action = this.mixer!.clipAction(renamedClip);

          // 设置动画循环模式
          action.setLoop(THREE.LoopRepeat, Infinity);
          action.clampWhenFinished = false;

          // 使用配置中的名称作为键
          this.animationsMap.set(animationName, action);
          loadedCount += 1;

          console.log(
            `✅ 动画加载成功: ${animationName} (原名: ${originalName}, 时长: ${renamedClip.duration.toFixed(2)}s)`,
          );
        }
      } catch (error) {
        console.error(`❌ 动画加载失败: ${item}`, error);
        // 继续加载其他动画，不中断整个流程
      }
    }

    console.log(`🎭 配置动画加载完成，共加载 ${loadedCount}/${Object.keys(config.animations).length} 个动画`);
    console.log(`🎭 最终动画映射:`, Array.from(this.animationsMap.keys()));

    // 如果没有加载到任何动画，创建一个默认的空动画
    if (loadedCount === 0) {
      console.log('🎭 创建默认空动画...');
      this.createDefaultAnimations();
    }
  }
  /**
   * 计算模型的腿长（基于人体比例）
   * @param modelHeight 模型高度（米）
   * @returns 腿长（米）
   */
  private calculateLegLength(modelHeight: number): number {
    // 根据人体工程学，腿长约为身高的53%
    return modelHeight * 0.53;
  }

  /**
   * 计算步长（基于腿长和移动类型）
   * @param legLength 腿长（米）
   * @param movementType 移动类型：'walking' | 'running'
   * @returns 步长（米）
   */
  private calculateStrideLength(legLength: number, movementType: 'walking' | 'running' = 'walking'): number {
    const strideMultiplier = movementType === 'running' ? 1.2 : 0.8;
    return legLength * strideMultiplier;
  }

  /**
   * 计算动画播放速率以匹配实际移动速度
   * @param movementType 移动类型：'walking' | 'running'
   * @param actualVelocity 实际移动速度（米/秒）
   * @param animationDuration 动画时长（秒）
   * @param stepsPerCycle 一个动画周期内的步数，默认2步（左右脚各一步）
   * @returns 动画播放速率倍数
   */
  private calculateAnimationPlaybackRate(
    movementType: 'walking' | 'running',
    actualVelocity: number,
    animationDuration: number,
    stepsPerCycle = 2,
  ): number {
    if (actualVelocity <= 0 || animationDuration <= 0) {
      return 1.0; // 默认播放速率
    }

    // 计算腿长和步长
    const legLength = this.calculateLegLength(this.characterHeight);
    const strideLength = this.calculateStrideLength(legLength, movementType);

    // 计算一个动画周期应该覆盖的距离（步数 × 步长）
    const distancePerCycle = stepsPerCycle * strideLength;

    // 计算在当前速度下，走完一个动画周期需要的时间
    const timeNeededForCycle = distancePerCycle / actualVelocity;

    // 计算播放速率：原始动画时长 / 实际需要的时长
    const playbackRate = animationDuration / timeNeededForCycle;

    // 限制播放速率在合理范围内（0.5x - 3.0x）
    const clampedRate = Math.max(0.5, Math.min(3.0, playbackRate)) * 0.8;

    return clampedRate;
  }

  /**
   * 计算并缓存所有动画的播放速率
   */
  private calculateAllAnimationPlaybackRates(): void {
    this.animationsMap.forEach((action, animationName) => {
      const clip = action.getClip();
      if (!clip) return;

      let playbackRate = 1.0; // 默认播放速率

      // 根据动画类型计算播放速率
      if (animationName === 'Running') {
        playbackRate = this.calculateAnimationPlaybackRate('running', this.runVelocity, clip.duration, 2);
        playbackRate *= this.animationSpeedScale;
      } else if (animationName === 'Walking') {
        playbackRate = this.calculateAnimationPlaybackRate('walking', this.walkVelocity, clip.duration, 2);
        playbackRate *= this.animationSpeedScale;
      }

      this.animationPlaybackRates.set(animationName, playbackRate);
      console.log(`🎭 动画 "${animationName}" 播放速率: ${playbackRate.toFixed(3)}`);
    });
  }
  /**
   * 加载动画文件（默认方式，适用于自带动画的模型）
   */
  private async loadAnimations(animations: AnimationConfig[] = DEFAULT_ANIMATIONS): Promise<void> {
    const fbxLoader = new FBXLoader();
    let loadedCount = 0;

    console.log(`🎭 开始加载 ${animations.length} 个动画文件...`);

    for (const animConfig of animations) {
      try {
        const filePath = `./models/character/anim/${animConfig.fileName}`;
        console.log(`📁 加载动画: ${animConfig.name} 从 ${filePath}`);

        const animationFBX = await fbxLoader.loadAsync(filePath);

        if (animationFBX.animations && animationFBX.animations.length > 0) {
          // 取第一个动画剪辑
          const animationClip = animationFBX.animations[0];
          const originalName = animationClip.name;

          // 创建一个新的动画剪辑，使用配置中的名称
          const renamedClip = animationClip.clone();
          renamedClip.name = animConfig.name;

          // 创建动画动作并添加到映射中
          const action = this.mixer!.clipAction(renamedClip);

          // 设置动画循环模式
          action.setLoop(animConfig.loop || THREE.LoopRepeat, Infinity);
          action.clampWhenFinished = animConfig.clampWhenFinished || false;

          // 使用配置中的名称作为键
          this.animationsMap.set(animConfig.name, action);
          loadedCount += 1;

          console.log(
            `✅ 动画加载成功: ${animConfig.name} (原名: ${originalName}, 时长: ${renamedClip.duration.toFixed(2)}s)`,
          );
        } else {
          console.warn(`⚠️ 动画文件中没有找到动画剪辑: ${filePath}`);
        }
      } catch (error) {
        console.error(`❌ 动画加载失败: ${animConfig.fileName}`, error);
        // 继续加载其他动画，不中断整个流程
      }
    }

    console.log(`🎭 外部动画加载完成，共加载 ${loadedCount}/${animations.length} 个动画`);
    console.log(`🎭 最终动画映射:`, Array.from(this.animationsMap.keys()));

    // 如果没有加载到任何动画，创建一个默认的空动画
    if (loadedCount === 0) {
      console.log('🎭 创建默认空动画...');
      this.createDefaultAnimations();
    }
  }

  /**
   * 创建默认动画（当无法加载外部动画时使用）
   */
  private createDefaultAnimations(): void {
    // 创建一个简单的待机动画（无动作）
    const idleClip = new THREE.AnimationClip('Idle', 1, []);
    const idleAction = this.mixer!.clipAction(idleClip);
    this.animationsMap.set('Idle', idleAction);

    // 创建简单的跑步动画（复制待机动画）
    const runningClip = new THREE.AnimationClip('Running', 1, []);
    const runningAction = this.mixer!.clipAction(runningClip);
    this.animationsMap.set('Running', runningAction);

    // 创建简单的下落动画
    const fallingClip = new THREE.AnimationClip('Falling', 1, []);
    const fallingAction = this.mixer!.clipAction(fallingClip);
    this.animationsMap.set('Falling', fallingAction);

    console.log('✅ 默认动画创建完成');
  }

  /**
   * 播放指定动画（内部方法，由状态机调用）
   */
  private playAnimationByState(animationState: AnimationState): boolean {
    const animationName = animationState.toString();
    return this.playAnimation(animationName);
  }
}
