import * as THREE from 'three';
import { PhysicsWorldManager } from './physics-world-manager';

export interface DebugConfig {
  showColliders: boolean;
  showCharacterController: boolean;
  showPerformanceStats: boolean;
  showPhysicsInfo: boolean;
  wireframeMode: boolean;
  showTerrain: boolean;
  showCliffDetection: boolean; // 新增：显示悬崖检测射线
}

export interface PerformanceStats {
  fps: number;
  frameTime: number;
  physicsTime: number;
  renderTime: number;
  memoryUsage: number;
}

export class DebugManager {
  // Debug配置
  public config: DebugConfig = {
    showColliders: false,
    showCharacterController: false,
    showPerformanceStats: false,
    showPhysicsInfo: false,
    wireframeMode: false,
    showTerrain: false,
    showCliffDetection: false, // 新增：显示悬崖检测射线
  };
  private scene: THREE.Scene;
  private physicsWorldManager: PhysicsWorldManager | null = null;
  private debugGroup: THREE.Group;
  private colliderMeshes: Map<string, THREE.Mesh> = new Map();
  private characterControllerMesh: THREE.Mesh | null = null;

  private terrainMeshes: Map<string, THREE.Mesh> = new Map();

  // 悬崖检测可视化
  private cliffDetectionGroup: THREE.Group | null = null;
  private cliffRayHelpers: THREE.ArrowHelper[] = [];
  private cliffDetectionLines: THREE.Line[] = [];

  // 性能统计
  private performanceStats: PerformanceStats = {
    fps: 0,
    frameTime: 0,
    physicsTime: 0,
    renderTime: 0,
    memoryUsage: 0,
  };

  private frameCount = 0;
  private lastTime = performance.now();
  private fpsUpdateInterval = 1000; // 1秒更新一次FPS

  // 材质
  private colliderMaterials = {
    static: new THREE.MeshBasicMaterial({
      color: 0x00ff00,
      wireframe: true,
      transparent: true,
      opacity: 0.5,
    }),
    dynamic: new THREE.MeshBasicMaterial({
      color: 0xff0000,
      wireframe: true,
      transparent: true,
      opacity: 0.5,
    }),
    character: new THREE.MeshBasicMaterial({
      color: 0x0000ff,
      wireframe: true,
      transparent: true,
      opacity: 0.7,
    }),
    terrain: new THREE.MeshBasicMaterial({
      color: 0xffaa00,
      wireframe: true,
      transparent: true,
      opacity: 0.3,
    }),
    // 悬崖检测材质
    cliffRaySafe: new THREE.MeshBasicMaterial({
      color: 0x00ff00, // 绿色：安全
    }),
    cliffRayDanger: new THREE.MeshBasicMaterial({
      color: 0xff0000, // 红色：危险
    }),
    cliffRayWarning: new THREE.MeshBasicMaterial({
      color: 0xffaa00, // 橙色：警告
    }),
  };

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    this.debugGroup = new THREE.Group();
    this.debugGroup.name = 'DebugGroup';
    this.scene.add(this.debugGroup);
  }

  public setPhysicsWorldManager(physicsManager: PhysicsWorldManager) {
    this.physicsWorldManager = physicsManager;
  }

  /**
   * 更新debug信息
   */
  public update(deltaTime: number): void {
    this.updatePerformanceStats(deltaTime);

    if (this.config.showColliders) {
      this.updateColliderVisualization();
    }

    if (this.config.showCharacterController) {
      this.updateCharacterControllerVisualization();
    }

    if (this.config.showTerrain) {
      this.updateTerrainVisualization();
    }

    if (this.config.showCliffDetection) {
      this.updateCliffDetectionVisualization();
    }
  }

  /**
   * 设置碰撞体可视化状态
   */
  public setColliderVisualization(enabled: boolean): void {
    this.config.showColliders = enabled;

    if (enabled) {
      this.createColliderVisualization();
    } else {
      this.clearColliderVisualization();
    }

    console.log(`碰撞体可视化: ${enabled ? '开启' : '关闭'}`);
  }

  /**
   * 切换碰撞体可视化
   */
  public toggleColliderVisualization(): void {
    this.setColliderVisualization(!this.config.showColliders);
  }

  /**
   * 设置角色控制器可视化状态
   */
  public setCharacterControllerVisualization(enabled: boolean): void {
    this.config.showCharacterController = enabled;

    if (enabled) {
      this.createCharacterControllerVisualization();
    } else {
      this.clearCharacterControllerVisualization();
    }

    console.log(`角色控制器可视化: ${enabled ? '开启' : '关闭'}`);
  }

  /**
   * 刷新角色控制器可视化（当胶囊体参数改变时调用）
   */
  public refreshCharacterControllerVisualization(): void {
    if (this.config.showCharacterController) {
      this.createCharacterControllerVisualization();
      console.log('🔄 角色控制器可视化已刷新');
    }
  }

  /**
   * 切换角色控制器可视化
   */
  public toggleCharacterControllerVisualization(): void {
    this.setCharacterControllerVisualization(!this.config.showCharacterController);
  }

  /**
   * 设置线框模式状态
   */
  public setWireframeMode(enabled: boolean): void {
    this.config.wireframeMode = enabled;

    // 只对非调试组中的对象应用线框模式
    this.scene.traverse((object) => {
      if (
        object instanceof THREE.Mesh &&
        object.material &&
        !this.debugGroup.children.includes(object) && // 排除调试可视化对象
        object.parent !== this.debugGroup
      ) {
        if (Array.isArray(object.material)) {
          object.material.forEach((material) => {
            if (material instanceof THREE.MeshStandardMaterial || material instanceof THREE.MeshBasicMaterial) {
              material.wireframe = enabled;
            }
          });
        } else if (
          object.material instanceof THREE.MeshStandardMaterial ||
          object.material instanceof THREE.MeshBasicMaterial
        ) {
          object.material.wireframe = enabled;
        }
      }
    });

    console.log(`线框模式: ${enabled ? '开启' : '关闭'}`);
  }

  /**
   * 切换线框模式
   */
  public toggleWireframeMode(): void {
    this.setWireframeMode(!this.config.wireframeMode);
  }

  /**
   * 设置地形可视化状态
   */
  public setTerrainVisualization(enabled: boolean): void {
    this.config.showTerrain = enabled;

    if (enabled) {
      this.createTerrainVisualization();
    } else {
      this.clearTerrainVisualization();
    }

    console.log(`地形可视化: ${enabled ? '开启' : '关闭'}`);
  }

  /**
   * 切换地形可视化
   */
  public toggleTerrainVisualization(): void {
    this.setTerrainVisualization(!this.config.showTerrain);
  }

  /**
   * 获取性能统计信息
   */
  public getPerformanceStats(): PerformanceStats {
    return { ...this.performanceStats };
  }

  /**
   * 获取物理世界信息
   */
  public getPhysicsInfo(): any {
    if (!this.physicsWorldManager) return null;

    const world = this.physicsWorldManager.getWorld();
    if (!world) return null;

    return {
      rigidBodyCount: this.physicsWorldManager.getAllRigidBodyIds().length,
      characterPosition: this.physicsWorldManager.getCharacterPosition(),
      isCharacterGrounded: this.physicsWorldManager.isCharacterGrounded(),
      characterVerticalVelocity: this.physicsWorldManager.getCharacterVerticalVelocity(),
      worldGravity: world.gravity,
    };
  }

  /**
   * 创建碰撞体可视化（只显示场景碰撞体，不包括角色控制器）
   */
  private createColliderVisualization(): void {
    if (!this.physicsWorldManager) return;

    this.clearColliderVisualization();

    const rigidBodyIds = this.physicsWorldManager.getAllRigidBodyIds();

    rigidBodyIds.forEach((id) => {
      // 跳过角色控制器的碰撞体（通常没有特定ID，但我们可以通过类型判断）
      if (id === 'character' || id.includes('character')) return;

      const info = this.physicsWorldManager!.getRigidBodyInfo(id);
      if (!info) return;

      const position = info.rigidBody.translation();
      const rotation = info.rigidBody.rotation();
      const isStatic = info.rigidBody.isFixed();

      // 调试信息
      console.log(`碰撞体 ${id}: 类型=${info.collider.shape.type}, 静态=${isStatic}`);

      // 根据碰撞器类型创建可视化网格
      let geometry: THREE.BufferGeometry;
      const colliderShape = info.collider.shape;

      if (colliderShape.type === 0) {
        // Ball
        const { radius } = colliderShape as any;
        geometry = new THREE.SphereGeometry(radius, 16, 12);
      } else if (colliderShape.type === 1) {
        // Cuboid
        const { halfExtents } = colliderShape as any;
        geometry = new THREE.BoxGeometry(halfExtents.x * 2, halfExtents.y * 2, halfExtents.z * 2);
      } else if (colliderShape.type === 2) {
        // Capsule
        // 如果是胶囊体，很可能是角色控制器，跳过
        if (!isStatic) return;

        const { radius } = colliderShape as any;
        const { halfHeight } = colliderShape as any;
        geometry = new THREE.CapsuleGeometry(radius, halfHeight * 2, 8, 16);
      } else {
        // 对于三角网格类型，使用存储的原始几何体
        if (info.originalGeometry) {
          geometry = info.originalGeometry.clone();
        } else {
          // 如果没有原始几何体，使用默认边界框
          console.warn(`碰撞体 ${id} 没有原始几何体数据，使用默认边界框`);
          geometry = new THREE.BoxGeometry(2, 2, 2);
        }
      }

      // 场景碰撞体统一使用绿色
      const material = new THREE.MeshBasicMaterial({
        color: 0x00ff00,
        wireframe: true,
        transparent: true,
        opacity: 0.6,
      });

      const mesh = new THREE.Mesh(geometry, material);

      mesh.position.set(position.x, position.y, position.z);
      mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      mesh.name = `Collider_${id}`;

      this.colliderMeshes.set(id, mesh);
      this.debugGroup.add(mesh);
    });
  }

  /**
   * 更新碰撞体可视化
   */
  private updateColliderVisualization(): void {
    if (!this.physicsWorldManager) return;

    this.colliderMeshes.forEach((mesh, id) => {
      const info = this.physicsWorldManager!.getRigidBodyInfo(id);
      if (info) {
        const position = info.rigidBody.translation();
        const rotation = info.rigidBody.rotation();

        mesh.position.set(position.x, position.y, position.z);
        mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      }
    });
  }

  /**
   * 清除碰撞体可视化
   */
  private clearColliderVisualization(): void {
    this.colliderMeshes.forEach((mesh) => {
      this.debugGroup.remove(mesh);
    });
    this.colliderMeshes.clear();
  }

  /**
   * 创建角色控制器可视化
   */
  private createCharacterControllerVisualization(): void {
    if (!this.physicsWorldManager) return;

    this.clearCharacterControllerVisualization();

    // 从物理世界管理器获取实际的胶囊体参数
    const capsuleRadius = this.physicsWorldManager.getCharacterCapsuleRadius();
    const capsuleHeight = this.physicsWorldManager.getCharacterCapsuleHeight();

    // 创建胶囊形状表示角色控制器（使用实际参数）
    const geometry = new THREE.CapsuleGeometry(capsuleRadius, capsuleHeight, 8, 16);
    this.characterControllerMesh = new THREE.Mesh(geometry, this.colliderMaterials.character);
    this.characterControllerMesh.name = 'CharacterController';

    this.debugGroup.add(this.characterControllerMesh);

    console.log(`🎨 角色控制器可视化已创建 - 半径: ${capsuleRadius}m, 高度: ${capsuleHeight}m`);
  }

  /**
   * 更新角色控制器可视化
   */
  private updateCharacterControllerVisualization(): void {
    if (!this.characterControllerMesh || !this.physicsWorldManager) return;

    const position = this.physicsWorldManager.getCharacterPosition();
    this.characterControllerMesh.position.copy(position);
  }

  /**
   * 清除角色控制器可视化
   */
  private clearCharacterControllerVisualization(): void {
    if (this.characterControllerMesh) {
      this.debugGroup.remove(this.characterControllerMesh);
      this.characterControllerMesh = null;
    }
  }

  /**
   * 创建地形可视化（只显示地形碰撞体）
   */
  private createTerrainVisualization(): void {
    if (!this.physicsWorldManager) return;

    this.clearTerrainVisualization();

    const rigidBodyIds = this.physicsWorldManager.getAllRigidBodyIds();

    rigidBodyIds.forEach((id) => {
      // 只显示地形相关的碰撞体
      if (!id.includes('terrain')) return;

      const info = this.physicsWorldManager!.getRigidBodyInfo(id);
      if (!info) return;

      const position = info.rigidBody.translation();
      const rotation = info.rigidBody.rotation();

      console.log(
        `地形碰撞体 ${id}: 位置=(${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)})`,
      );

      // 使用存储的原始几何体创建地形可视化
      let geometry: THREE.BufferGeometry;

      if (info.originalGeometry) {
        geometry = info.originalGeometry.clone();
        console.log(`使用地形原始几何体，顶点数: ${geometry.attributes.position.count}`);
      } else {
        // 如果没有原始几何体，创建一个平面表示地形
        console.warn(`地形 ${id} 没有原始几何体数据，使用默认平面`);
        geometry = new THREE.PlaneGeometry(100, 100, 50, 50);
        geometry.rotateX(-Math.PI / 2); // 水平放置
      }

      // 使用橙色线框材质表示地形
      const mesh = new THREE.Mesh(geometry, this.colliderMaterials.terrain);

      // 🔧 修复：地形可视化需要与物理碰撞体完全对齐
      // 物理碰撞体有位置和旋转变换，可视化也必须应用相同的变换
      if (info.originalGeometry) {
        // 地形几何体是在局部坐标系中创建的，需要应用刚体的变换
        mesh.position.set(position.x, position.y, position.z);
        mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
        console.log(
          `🔧 地形可视化应用刚体变换: 位置=(${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)}), 旋转=(${rotation.x.toFixed(3)}, ${rotation.y.toFixed(3)}, ${rotation.z.toFixed(3)}, ${rotation.w.toFixed(3)})`,
        );
      } else {
        // 默认平面需要应用刚体变换
        mesh.position.set(position.x, position.y, position.z);
        mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
        console.log(
          `使用默认平面，应用刚体变换: 位置=(${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)})`,
        );
      }

      mesh.name = `TerrainDebug_${id}`;

      this.terrainMeshes.set(id, mesh);
      this.debugGroup.add(mesh);
    });

    if (this.terrainMeshes.size === 0) {
      console.warn('未找到地形碰撞体进行可视化');
    } else {
      console.log(`创建了 ${this.terrainMeshes.size} 个地形可视化网格`);
    }
  }

  /**
   * 更新地形可视化
   */
  private updateTerrainVisualization(): void {
    if (!this.physicsWorldManager) return;

    this.terrainMeshes.forEach((mesh, id) => {
      const info = this.physicsWorldManager!.getRigidBodyInfo(id);
      if (info) {
        const position = info.rigidBody.translation();
        const rotation = info.rigidBody.rotation();

        mesh.position.set(position.x, position.y, position.z);
        mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      }
    });
  }

  /**
   * 清除地形可视化
   */
  private clearTerrainVisualization(): void {
    this.terrainMeshes.forEach((mesh) => {
      this.debugGroup.remove(mesh);
    });
    this.terrainMeshes.clear();
  }

  /**
   * 更新性能统计
   */
  private updatePerformanceStats(deltaTime: number): void {
    this.frameCount++;
    const currentTime = performance.now();

    // 更新帧时间
    this.performanceStats.frameTime = deltaTime * 1000; // 转换为毫秒

    // 每秒更新一次FPS
    if (currentTime - this.lastTime >= this.fpsUpdateInterval) {
      this.performanceStats.fps = Math.round((this.frameCount * 1000) / (currentTime - this.lastTime));
      this.frameCount = 0;
      this.lastTime = currentTime;

      // 更新内存使用情况（如果可用）
      if ((performance as any).memory) {
        this.performanceStats.memoryUsage = (performance as any).memory.usedJSHeapSize / 1024 / 1024; // MB
      }
    }
  }

  /**
   * 打印debug信息到控制台
   */
  public logDebugInfo(): void {
    console.group('🔧 Debug Information');

    console.log('📊 Performance Stats:', this.getPerformanceStats());
    console.log('🌍 Physics Info:', this.getPhysicsInfo());
    console.log('⚙️ Debug Config:', this.config);

    if (this.physicsWorldManager) {
      console.log('📦 Rigid Bodies:', this.physicsWorldManager.getAllRigidBodyIds());
    }

    console.groupEnd();
  }

  /**
   * 清理资源
   */
  public dispose(): void {
    this.clearColliderVisualization();
    this.clearCharacterControllerVisualization();
    this.clearTerrainVisualization();
    this.clearCliffDetectionVisualization();

    this.scene.remove(this.debugGroup);

    // 清理材质
    Object.values(this.colliderMaterials).forEach((material) => {
      material.dispose();
    });

    console.log('DebugManager已清理');
  }

  /**
   * 设置悬崖检测可视化状态
   */
  public setCliffDetectionVisualization(enabled: boolean): void {
    this.config.showCliffDetection = enabled;

    if (enabled) {
      this.createCliffDetectionVisualization();
    } else {
      this.clearCliffDetectionVisualization();
    }

    console.log(`悬崖检测可视化: ${enabled ? '开启' : '关闭'}`);
  }

  /**
   * 切换悬崖检测可视化
   */
  public toggleCliffDetectionVisualization(): void {
    this.setCliffDetectionVisualization(!this.config.showCliffDetection);
  }

  /**
   * 创建悬崖检测可视化
   */
  private createCliffDetectionVisualization(): void {
    if (!this.cliffDetectionGroup) {
      this.cliffDetectionGroup = new THREE.Group();
      this.cliffDetectionGroup.name = 'CliffDetectionGroup';
      this.debugGroup.add(this.cliffDetectionGroup);
    }
  }

  /**
   * 更新悬崖检测可视化
   */
  private updateCliffDetectionVisualization(): void {
    if (!this.physicsWorldManager || !this.cliffDetectionGroup) return;

    // 清除之前的可视化
    this.clearCliffDetectionRays();

    // 获取角色位置（这里需要从外部传入，或者通过其他方式获取）
    const characterPosition = this.physicsWorldManager.getCharacterPosition();
    if (!characterPosition) return;

    // 获取悬崖检测配置
    const config = this.physicsWorldManager.getCliffDetectionConfig();

    // 定义检测方向（8个方向）
    const directions = [
      { x: 0, z: 1, name: 'Forward' }, // 前
      { x: 1, z: 1, name: 'ForwardRight' }, // 右前
      { x: 1, z: 0, name: 'Right' }, // 右
      { x: 1, z: -1, name: 'BackRight' }, // 右后
      { x: 0, z: -1, name: 'Back' }, // 后
      { x: -1, z: -1, name: 'BackLeft' }, // 左后
      { x: -1, z: 0, name: 'Left' }, // 左
      { x: -1, z: 1, name: 'ForwardLeft' }, // 左前
    ];

    directions.forEach((dir, index) => {
      const direction = new THREE.Vector3(dir.x, 0, dir.z).normalize();

      // 检查这个方向是否有悬崖
      const hasCliff = this.physicsWorldManager!.checkCliffAhead(characterPosition, direction, config.checkDistance);

      // 创建射线可视化
      this.createCliffDetectionRay(
        characterPosition,
        direction,
        config.checkDistance,
        config.maxFallDistance,
        hasCliff,
        index,
      );
    });
  }

  /**
   * 创建单个悬崖检测射线可视化
   */
  private createCliffDetectionRay(
    origin: THREE.Vector3,
    direction: THREE.Vector3,
    checkDistance: number,
    maxFallDistance: number,
    hasCliff: boolean,
    index: number,
  ): void {
    if (!this.cliffDetectionGroup) return;

    // 计算检测点位置
    const checkPoint = origin.clone().add(direction.clone().multiplyScalar(checkDistance));
    checkPoint.y += 0.5; // 射线起始高度

    // 创建水平射线（显示检测方向）
    const horizontalGeometry = new THREE.BufferGeometry().setFromPoints([
      origin.clone().add(new THREE.Vector3(0, 0.5, 0)),
      checkPoint,
    ]);

    const horizontalMaterial = new THREE.LineBasicMaterial({
      color: hasCliff ? 0xff0000 : 0x00ff00, // 红色：危险，绿色：安全
      linewidth: 2,
    });

    const horizontalLine = new THREE.Line(horizontalGeometry, horizontalMaterial);
    horizontalLine.name = `CliffRayHorizontal_${index}`;
    this.cliffDetectionGroup.add(horizontalLine);
    this.cliffDetectionLines.push(horizontalLine);

    // 创建垂直射线（显示掉落检测）
    const verticalStart = checkPoint;
    const verticalEnd = checkPoint.clone().add(new THREE.Vector3(0, -maxFallDistance, 0));

    const verticalGeometry = new THREE.BufferGeometry().setFromPoints([verticalStart, verticalEnd]);

    const verticalMaterial = new THREE.LineBasicMaterial({
      color: hasCliff ? 0xff4444 : 0x44ff44, // 浅红色：危险，浅绿色：安全
      linewidth: 1,
      transparent: true,
      opacity: 0.6,
    });

    const verticalLine = new THREE.Line(verticalGeometry, verticalMaterial);
    verticalLine.name = `CliffRayVertical_${index}`;
    this.cliffDetectionGroup.add(verticalLine);
    this.cliffDetectionLines.push(verticalLine);

    // 在检测点添加小球标记
    const sphereGeometry = new THREE.SphereGeometry(0.05, 8, 6);
    const sphereMaterial = new THREE.MeshBasicMaterial({
      color: hasCliff ? 0xff0000 : 0x00ff00,
      transparent: true,
      opacity: 0.8,
    });

    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.copy(checkPoint);
    sphere.name = `CliffDetectionPoint_${index}`;
    this.cliffDetectionGroup.add(sphere);
  }

  /**
   * 清除悬崖检测射线
   */
  private clearCliffDetectionRays(): void {
    this.cliffDetectionLines.forEach((line) => {
      if (this.cliffDetectionGroup) {
        this.cliffDetectionGroup.remove(line);
      }
      line.geometry.dispose();
      (line.material as THREE.Material).dispose();
    });
    this.cliffDetectionLines = [];

    // 清除箭头助手
    this.cliffRayHelpers.forEach((helper) => {
      if (this.cliffDetectionGroup) {
        this.cliffDetectionGroup.remove(helper);
      }
      helper.dispose();
    });
    this.cliffRayHelpers = [];

    // 清除所有检测点球体
    if (this.cliffDetectionGroup) {
      const objectsToRemove = this.cliffDetectionGroup.children.filter((child) =>
        child.name.startsWith('CliffDetectionPoint_'),
      );
      objectsToRemove.forEach((obj) => {
        this.cliffDetectionGroup!.remove(obj);
        if (obj instanceof THREE.Mesh) {
          obj.geometry.dispose();
          (obj.material as THREE.Material).dispose();
        }
      });
    }
  }

  /**
   * 清除悬崖检测可视化
   */
  private clearCliffDetectionVisualization(): void {
    this.clearCliffDetectionRays();

    if (this.cliffDetectionGroup) {
      this.debugGroup.remove(this.cliffDetectionGroup);
      this.cliffDetectionGroup = null;
    }
  }
}
