import { ref, Ref } from 'vue';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { ORBIT_CONTROLS_CONFIG } from './constant/character';

export class OrbitControlManager {
  public isActive: Ref<boolean> = ref(false);
  public isManuallyActivated: Ref<boolean> = ref(false);
  public touchId: Ref<number | null> = ref(null);
  public hasTouchReleased: Ref<boolean> = ref(false);

  private orbitControls: OrbitControls | null = null;
  private onStateChangeCallback?: (isActive: boolean, isManual: boolean) => void;

  constructor(onStateChange?: (isActive: boolean, isManual: boolean) => void) {
    this.onStateChangeCallback = onStateChange;
  }

  /**
   * 创建并初始化 OrbitControls
   */
  public createOrbitControls(camera: THREE.Camera, domElement: HTMLElement, initialDistance?: number): OrbitControls {
    this.orbitControls = new OrbitControls(camera, domElement);

    // 设置默认配置
    this.orbitControls.enableDamping = true;
    this.orbitControls.enablePan = false;
    this.orbitControls.maxPolarAngle = ORBIT_CONTROLS_CONFIG.MAX_POLAR_ANGLE;

    // 如果提供了初始距离，设置距离限制
    if (initialDistance !== undefined) {
      this.orbitControls.minDistance = Math.max(
        ORBIT_CONTROLS_CONFIG.ABSOLUTE_MIN_DISTANCE,
        initialDistance * ORBIT_CONTROLS_CONFIG.MIN_DISTANCE_RATIO,
      );
      this.orbitControls.maxDistance = initialDistance * ORBIT_CONTROLS_CONFIG.MAX_DISTANCE_RATIO;
      console.log(
        `🎮 OrbitControls 距离限制设置: min=${this.orbitControls.minDistance.toFixed(2)}, max=${this.orbitControls.maxDistance.toFixed(2)}`,
      );
    }

    this.orbitControls.update();

    console.log('🎮 OrbitControls 已创建并初始化');
    return this.orbitControls;
  }

  /**
   * 获取 OrbitControls 实例
   */
  public getOrbitControls(): OrbitControls | null {
    return this.orbitControls;
  }

  /**
   * 设置状态变化回调函数
   */
  public setStateChangeCallback(callback: (isActive: boolean, isManual: boolean) => void): void {
    this.onStateChangeCallback = callback;
  }

  public setOrbitControls(controls: OrbitControls) {
    this.orbitControls = controls;
  }

  public activate(isManual = false, touchId?: number) {
    if (!this.isActive.value) {
      this.isActive.value = true;
      this.isManuallyActivated.value = isManual;

      if (touchId !== undefined) {
        this.touchId.value = touchId;
      }

      this.hasTouchReleased.value = false;

      if (this.orbitControls) {
        this.orbitControls.enabled = true;
      }

      this.onStateChangeCallback?.(true, isManual);
      console.log(`OrbitControls 激活 (${isManual ? '手动' : '自动'})`);
      // console.log(' this.orbitControls.enabled', this.orbitControls?.enabled);
    }
  }

  public deactivate() {
    if (this.isActive.value) {
      this.isActive.value = false;
      this.isManuallyActivated.value = false;
      this.touchId.value = null;
      this.hasTouchReleased.value = false;

      this.onStateChangeCallback?.(false, false);
      // console.log('OrbitControls 停用');
    }
  }

  public toggle() {
    if (this.isActive.value) {
      this.deactivate();
    } else {
      this.activate(true); // 手动切换
    }
  }

  public handleMouseDown(event: MouseEvent, isInJoystickArea: (x: number, y: number) => boolean) {
    const isInJoystick = isInJoystickArea(event.clientX, event.clientY);

    if (!isInJoystick && !this.isActive.value) {
      this.activate(false); // 鼠标激活不是手动激活
    }
  }

  public handleMouseUp(_event: MouseEvent) {
    // 鼠标释放时，如果是自动激活的，标记为可以停用
    if (this.isActive.value && !this.isManuallyActivated.value) {
      this.hasTouchReleased.value = true;
      console.log('🖱️ 鼠标释放，标记为可停用状态');
    }
  }

  public checkKeyboardActivation(keysPressed: Record<string, boolean>) {
    // 获取当前按下的方向键
    const activeKeys = Object.keys(keysPressed).filter((key) => keysPressed[key]);
    const directionKeys = activeKeys.filter((key) => ['keyw', 'keya', 'keys', 'keyd'].includes(key));

    // 如果同时按下两个或更多方向键，激活双手模式
    // if (directionKeys.length >= 2 && !this.isActive.value) {
    //   this.activate(false); // 自动激活双手模式
    // } else
    if (directionKeys.length === 0 && this.isActive.value && !this.isManuallyActivated.value) {
      // 如果没有方向键按下且是自动激活的，准备切换回单手模式
      this.hasTouchReleased.value = true;
    }
  }

  public handleTouchStart(event: TouchEvent, isInJoystickArea: (x: number, y: number) => boolean) {
    const touchCount = event.touches.length;

    if (touchCount === 1) {
      const touch = event.touches[0];
      const isInJoystick = isInJoystickArea(touch.clientX, touch.clientY);

      if (!isInJoystick && !this.isActive.value) {
        this.activate(false, touch.identifier);
      }
    } else if (touchCount === 2) {
      // 双指触摸，激活OrbitControls
      if (!this.isActive.value) {
        this.activate(false);
      }

      // 更新触摸ID为最新的触摸点
      const latestTouch = event.touches[touchCount - 1];
      this.touchId.value = latestTouch.identifier;
    }
  }

  public handleTouchMove(event: TouchEvent) {
    const touchCount = event.touches.length;

    if (touchCount === 1 && this.isActive.value && !this.isManuallyActivated.value) {
      // 单指移动时，检查是否是OrbitControls的触摸点
      const touch = event.touches[0];
      if (this.touchId.value !== null && touch.identifier !== this.touchId.value) {
        // 如果当前触摸点不是OrbitControls的触摸点，停用OrbitControls
        this.deactivate();
      }
    }
  }

  public handleTouchEnd(event: TouchEvent, hasAnyInput: () => boolean) {
    const touchCount = event.touches.length;

    if (touchCount === 0) {
      // 所有触摸点都释放了
      this.hasTouchReleased.value = true;

      // 如果没有任何输入且不是手动激活，则停用OrbitControls
      if (!hasAnyInput() && !this.isManuallyActivated.value) {
        this.deactivate();
      }
    } else if (this.touchId.value !== null) {
      // 检查OrbitControls的触摸点是否还存在
      const stillExists = Array.from(event.touches).some((touch) => touch.identifier === this.touchId.value);

      if (!stillExists) {
        this.hasTouchReleased.value = true;

        if (!hasAnyInput() && !this.isManuallyActivated.value) {
          this.deactivate();
        }
      }
    }
  }

  public checkAutoDeactivation(hasAnyInput: () => boolean) {
    // 检查是否应该自动停用OrbitControls
    // 只有在以下条件都满足时才停用：
    // 1. OrbitControls当前是激活状态
    // 2. 不是手动激活的（是自动激活的）
    // 3. 触摸已释放（对于触摸输入）
    // 4. 没有任何输入（包括键盘、摇杆、鼠标）
    if (this.isActive.value && !this.isManuallyActivated.value && this.hasTouchReleased.value && !hasAnyInput()) {
      console.log('🔄 自动停用OrbitControls - 所有输入都已释放');
      this.deactivate();
    }
  }

  public setAutoRotate(enabled: boolean) {
    if (this.orbitControls) {
      this.orbitControls.autoRotate = enabled;
      console.log(`OrbitControls autoRotate 设置为: ${enabled}`);
    }
  }

  public dispose() {
    this.orbitControls = null;
    this.onStateChangeCallback = undefined;
  }
}
