import { SplatMesh } from '@sparkjsdev/spark';
import * as THREE from 'three';

export enum LoaderStatus {
  Downloading = 0,
  Processing = 1,
  Done = 2,
}

/**
 * 统一的配置接口
 */
export interface GaussianSplatConfig {
  url: string;
  mortonConfig?: string;
  mortonCenter?: THREE.Vector3;
  viewer: any;
  position?: number[];
  rotation?: number[];
  scale?: number[];
  renderOrder?: number;
  onProgress?: (progress: number, loaderStatus: LoaderStatus) => void;
  renderCallback?: () => void;
  showLoadingUI?: boolean;
  // Spark 特有配置
  sparkOptions?: any;
  // GaussianSplats3D 特有配置
  gaussianSplats3DOption?: any;
  sphericalHarmonicsDegree?: number;
}

/**
 * 统一的加载结果接口
 */
export interface LoadResult {
  mesh: any; // 可以是 SplatMesh 或 DropInViewer
  dispose: () => void;
}

/**
 * Gaussian Splatting 组件基类
 * 抹平 @sparkjsdev/spark 和 @mkkellogg/gaussian-splats-3d 的接口差异
 */
export abstract class GaussianAbstractComponent<T> {
  public viewer: T | T[] | null = null; // 存储viewer实例
  protected scene: THREE.Scene | null = null;
  protected loadedMeshes: Map<string, LoadResult> = new Map();

  constructor() {}

  /**
   * 设置场景
   */
  setScene(scene: THREE.Scene): void {
    this.scene = scene;
  }

  /**
   * 移除场景
   * @param sceneId 场景ID
   */
  removeScene(sceneId: string): void {
    const result = this.loadedMeshes.get(sceneId);
    if (result) {
      if (this.scene) {
        this.scene.remove(result.mesh);
      }
      result.dispose();
      this.loadedMeshes.delete(sceneId);
    }
  }

  /**
   * 获取已加载的场景
   * @param sceneId 场景ID
   */
  getScene(sceneId: string): LoadResult | undefined {
    return this.loadedMeshes.get(sceneId);
  }

  /**
   * 获取所有已加载的场景ID
   */
  getAllSceneIds(): string[] {
    return Array.from(this.loadedMeshes.keys());
  }

  /**
   * 清理所有资源
   */
  dispose(): void {
    this.loadedMeshes.forEach((result) => {
      if (this.scene) {
        this.scene.remove(result.mesh);
      }
      result.dispose();
    });
    this.loadedMeshes.clear();
    this.scene = null;
  }

  /**
   * 更新场景位置
   */
  updatePosition(sceneId: string, position: number[]): void {
    const result = this.loadedMeshes.get(sceneId);
    if (result?.mesh) {
      result.mesh.position.set(position[0], position[1], position[2]);
    }
  }

  /**
   * 更新场景旋转
   */
  updateRotation(sceneId: string, rotation: number[]): void {
    const result = this.loadedMeshes.get(sceneId);
    if (result?.mesh) {
      result.mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
    }
  }

  /**
   * 更新场景缩放
   */
  updateScale(sceneId: string, scale: number[]): void {
    const result = this.loadedMeshes.get(sceneId);
    if (result?.mesh) {
      result.mesh.scale.set(scale[0], scale[1], scale[2]);
    }
  }
  /**
   * 添加场景 - 子类需要实现具体逻辑
   * @param url 场景文件URL
   * @param config 配置参数
   * @param id 可选的唯一标识符
   * @returns Promise<string> 返回场景ID
   */
  abstract addScene(url: string, config?: Partial<GaussianSplatConfig>, id?: string): Promise<any>;
}
