import * as THREE from 'three';
import { SplatConfig } from '../../../types';
import { PhysicsWorldManager } from './physics-world-manager';
import { GaussianSplatStrategyManager } from './strategies/gaussian-splat-strategy-manager';
import { GaussianSplatLoadStrategy } from './strategies/gaussian-splat-load-strategy';

interface GaussianSplatScene {
  id: string;
  config: SplatConfig;
  isLoaded: boolean;
  strategy?: GaussianSplatLoadStrategy; // 关联的策略
}

interface GaussianSplatsOptions {
  scene: THREE.Scene;
  camera?: THREE.Camera;
  renderer?: THREE.WebGLRenderer;
  physicsWorldManager?: PhysicsWorldManager;
  onProgress?: (progress: number) => void;
  onSceneLoaded?: (sceneId: string) => void;
  onSceneDisposed?: (sceneId: string) => void;
}

export class GaussianSplattingManager {
  private readonly scene: THREE.Scene;
  // private camera?: THREE.Camera;
  // private renderer?: THREE.WebGLRenderer;
  private physicsWorldManager?: PhysicsWorldManager;
  private splatScenes: Map<string, GaussianSplatScene> = new Map();
  private readonly onProgress?: (progress: number) => void;
  private readonly onSceneLoaded?: (sceneId: string) => void;
  private readonly onSceneDisposed?: (sceneId: string) => void;
  private strategyManager: GaussianSplatStrategyManager; // 策略管理器

  constructor(options: GaussianSplatsOptions) {
    this.scene = options.scene;
    // this.camera = options.camera;
    // this.renderer = options.renderer;
    this.physicsWorldManager = options.physicsWorldManager;
    this.onProgress = options.onProgress;
    this.onSceneLoaded = options.onSceneLoaded;
    this.onSceneDisposed = options.onSceneDisposed;
    // 初始化策略管理器，传递 PhysicsWorldManager
    this.strategyManager = new GaussianSplatStrategyManager(this.scene, this.physicsWorldManager);
  }

  setEnablePreloadNearest(enable: boolean): void {
    this.strategyManager.setEnablePreloadNearest(enable);
  }

  /**
   * 加载高斯泼溅场景
   * @param sceneId 场景唯一标识
   * @param config 场景配置
   * @returns Promise<void>
   */
  async loadSplatScene(sceneId: string, config: SplatConfig): Promise<void> {
    console.log(`开始加载高斯泼溅场景: ${sceneId}`, config);

    // 如果场景已存在，先卸载
    if (this.splatScenes.has(sceneId)) {
      await this.disposeSplatScene(sceneId);
    }

    try {
      // 判断使用哪种加载策略
      await this.loadWithStrategy(sceneId, config);

      console.log(`高斯泼溅场景加载完成: ${sceneId}`);
      this.onSceneLoaded?.(sceneId);
    } catch (error) {
      console.error(`加载高斯泼溅场景失败: ${sceneId}`, error);
      throw error;
    }
  }

  /**
   * 卸载指定的高斯泼溅场景
   * @param sceneId 场景ID
   */
  async disposeSplatScene(sceneId: string): Promise<void> {
    const splatScene = this.splatScenes.get(sceneId);
    if (!splatScene) {
      console.warn(`场景 ${sceneId} 不存在，无法卸载`);
      return;
    }

    try {
      console.log(`开始卸载高斯泼溅场景: ${sceneId}`);

      // 如果使用了策略，通过策略清理
      if (splatScene.strategy) {
        splatScene.strategy.dispose();
      }

      // 从管理器中移除
      this.splatScenes.delete(sceneId);

      console.log(`高斯泼溅场景卸载完成: ${sceneId}`);
      this.onSceneDisposed?.(sceneId);
    } catch (error) {
      console.error(`卸载高斯泼溅场景失败: ${sceneId}`, error);
      throw error;
    }
  }

  /**
   * 批量卸载场景，保留指定的场景
   * @param sceneIdsToKeep 需要保留的场景ID数组
   */
  async disposeScenesExcept(sceneIdsToKeep: string[]): Promise<void> {
    console.log('开始批量卸载场景，保留:', sceneIdsToKeep);

    const keepSet = new Set(sceneIdsToKeep);
    const scenesToDispose: string[] = [];

    // 找出需要卸载的场景
    this.splatScenes.forEach((_scene, sceneId) => {
      if (!keepSet.has(sceneId)) {
        scenesToDispose.push(sceneId);
      }
    });

    // 批量卸载
    for (const sceneId of scenesToDispose) {
      await this.disposeSplatScene(sceneId);
    }

    console.log(`批量卸载完成，剩余场景数量: ${this.splatScenes.size}`);
  }

  /**
   * 卸载所有场景
   */
  async disposeAllScenes(): Promise<void> {
    console.log('开始卸载所有高斯泼溅场景');

    const sceneIds = Array.from(this.splatScenes.keys());
    for (const sceneId of sceneIds) {
      await this.disposeSplatScene(sceneId);
    }

    console.log('所有高斯泼溅场景已卸载');
  }

  /**
   * 获取指定场景
   * @param sceneId 场景ID
   * @returns 场景对象或undefined
   */
  getSplatScene(sceneId: string): GaussianSplatScene | undefined {
    return this.splatScenes.get(sceneId);
  }

  /**
   * 获取所有已加载的场景ID
   * @returns 场景ID数组
   */
  getLoadedSceneIds(): string[] {
    return Array.from(this.splatScenes.keys());
  }

  /**
   * 检查场景是否已加载
   * @param sceneId 场景ID
   * @returns 是否已加载
   */
  isSceneLoaded(sceneId: string): boolean {
    const scene = this.splatScenes.get(sceneId);
    return scene?.isLoaded || false;
  }

  /**
   * 获取场景统计信息
   * @returns 统计信息
   */
  getStats() {
    return {
      totalScenes: this.splatScenes.size,
      loadedScenes: Array.from(this.splatScenes.values()).filter((scene) => scene.isLoaded).length,
      sceneIds: this.getLoadedSceneIds(),
    };
  }

  /**
   * 更新策略（每帧调用）
   * @param deltaTime 时间增量
   */
  update(): void {
    this.strategyManager.update();
  }

  /**
   * 获取策略管理器
   */
  getStrategyManager(): GaussianSplatStrategyManager {
    return this.strategyManager;
  }

  /**
   * 清理管理器资源
   */
  dispose(): void {
    console.log('开始清理GaussianSplatsManager');
    this.disposeAllScenes();
    this.strategyManager.dispose();
    this.splatScenes.clear();
  }

  /**
   * 使用策略模式加载场景
   * @param sceneId 场景ID
   * @param config 场景配置
   */
  private async loadWithStrategy(sceneId: string, config: SplatConfig): Promise<void> {
    console.log('使用策略模式加载场景');

    // 使用策略管理器加载
    const strategy = await this.strategyManager.createStrategy(config);

    if (!strategy) {
      throw new Error('Failed to create strategy');
    }

    // 创建场景记录
    const splatScene: GaussianSplatScene = {
      id: sceneId,
      config,
      isLoaded: true,
      strategy, // 保存策略引用
    };

    this.splatScenes.set(sceneId, splatScene);
    await strategy.load();
  }
}
