import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { PhysicsWorldManager } from './physics-world-manager';
import { convertRotationToRadians } from '../../../utils';
import { Collision } from '@/types';

/**
 * 网格管理器 - 负责加载和管理场景中的3D模型
 */
export class CollisionManager {
  private scene: THREE.Scene;
  private physicsWorldManager: PhysicsWorldManager;
  private collisionMeshes: THREE.Object3D[] = [];

  constructor(scene: THREE.Scene, physicsWorldManager: PhysicsWorldManager) {
    this.scene = scene;
    this.physicsWorldManager = physicsWorldManager;
    console.log('🏗️ CollisionManager 初始化完成');
  }

  /**
   * 获取所有碰撞网格（用于弹簧臂碰撞检测）
   */
  public getCollisionMeshes(): THREE.Object3D[] {
    return this.collisionMeshes;
  }

  /**
   * 从URL加载场景网格模型
   * @param collision
   */
  public async loadSceneCollisionFromUrl(collision: Collision): Promise<void> {
    try {
      console.log('🏗️ 开始加载场景碰撞模型:', collision.url);

      const loader = new GLTFLoader();
      const sceneGltf = await loader.loadAsync(collision.url);
      const sceneModel = sceneGltf.scene;
      const rotation = convertRotationToRadians(collision.transform.rotation);
      // 设置场景模型的位置、旋转和缩放
      sceneModel.position.set(
        collision.transform.position[0],
        collision.transform.position[1],
        collision.transform.position[2],
      );
      sceneModel.rotation.set(rotation[0], rotation[1], rotation[2]);
      sceneModel.scale.set(collision.transform.scale[0], collision.transform.scale[1], collision.transform.scale[2]);
      // 遍历场景模型，设置材质和阴影
      // sceneModel.traverse((object: any) => {
      //   if (object.isMesh) {
      //     object.castShadow = true;
      //     object.receiveShadow = true;
      //
      //     // 如果材质存在，可以调整一些属性
      //     if (object.material) {
      //       // 确保材质支持阴影
      //       object.material.needsUpdate = true;
      //
      //       // 设置透明度 - 如果没有设置则默认完全透明
      //       const opacity = collision.opacity !== undefined && collision.opacity !== null ? collision.opacity : 0.2;
      //
      //       // 启用透明度
      //       object.material.transparent = true;
      //       object.material.opacity = opacity;
      //
      //       // 如果是数组材质（多材质），需要遍历设置
      //       if (Array.isArray(object.material)) {
      //         object.material.forEach((mat: any) => {
      //           mat.transparent = true;
      //           mat.opacity = opacity;
      //           mat.needsUpdate = true;
      //         });
      //       }
      //     }
      //   }
      // });

      // 将场景模型添加到场景中
      // this.scene.add(sceneModel);

      // 收集碰撞网格（用于弹簧臂检测）
      let meshCount = 0;
      sceneModel.traverse((child) => {
        if (child instanceof THREE.Mesh) {
          child.userData.isCollider = true;
          this.collisionMeshes.push(child);
          meshCount++;
        }
      });
      console.log(`🎯 CollisionManager: 收集了 ${meshCount} 个碰撞网格`);

      // 从GLB模型创建碰撞体
      this.physicsWorldManager.createMeshColliderFromGLB(
        'scene_collision',
        sceneModel,
        new THREE.Vector3(
          collision.transform.position[0],
          collision.transform.position[1],
          collision.transform.position[2],
        ), // 位置
        new THREE.Euler(rotation[0], rotation[1], rotation[2]), // 旋转
        new THREE.Vector3(collision.transform.scale[0], collision.transform.scale[1], collision.transform.scale[2]), // 缩放
        true, // 静态碰撞体
      );

      console.log('✅ 场景网格模型加载完成');
      console.log(`   位置: (${collision.transform.position.join(', ')})`);
      console.log(`   旋转: (${collision.transform.rotation.join(', ')})`);
      console.log(`   缩放: (${collision.transform.scale.join(', ')})`);
    } catch (error) {
      console.error('❌ 场景网格模型加载失败:', error);
      throw error;
    }
  }

  /**
   * 加载场景网格模型（原有方法，保持向后兼容）
   * @param loader - GLTF加载器
   */
  public async loadSceneMesh(loader: GLTFLoader): Promise<void> {
    try {
      console.log('🏗️ 开始加载场景碰撞模型: acg_street_700k.glb');
      const sceneGltf = await loader.loadAsync('./acg_street_700k.glb');
      const sceneModel = sceneGltf.scene;

      // 设置场景模型的位置、旋转和缩放
      sceneModel.position.set(0, 0, 0);
      sceneModel.rotation.set(0, 0, 0);
      sceneModel.scale.set(1, 1, 1);

      // 遍历场景模型，设置材质和阴影
      sceneModel.traverse((object: any) => {
        if (object.isMesh) {
          object.castShadow = true;
          object.receiveShadow = true;

          // 如果材质存在，可以调整一些属性
          if (object.material) {
            // 确保材质支持阴影
            object.material.needsUpdate = true;
          }
        }
      });

      // 将场景模型添加到场景中
      this.scene.add(sceneModel);

      // 收集碰撞网格（用于弹簧臂检测）
      let meshCount = 0;
      sceneModel.traverse((child) => {
        if (child instanceof THREE.Mesh) {
          child.userData.isCollider = true;
          this.collisionMeshes.push(child);
          meshCount++;
        }
      });
      console.log(`🎯 CollisionManager: 收集了 ${meshCount} 个碰撞网格`);

      // 从GLB模型创建碰撞体
      this.physicsWorldManager.createMeshColliderFromGLB(
        'scene_collision',
        sceneModel,
        new THREE.Vector3(0, 0, 0), // 位置
        new THREE.Euler(0, 0, 0), // 旋转
        new THREE.Vector3(1, 1, 1), // 缩放
        true, // 静态碰撞体
      );

      console.log('✅ 场景碰撞模型加载完成');
    } catch (sceneError) {
      console.error('❌ 场景碰撞模型加载失败:', sceneError);
      // 如果场景模型加载失败，继续添加测试碰撞体
      this.addTestColliders();
    }
  }
  /**
   * 清理资源
   */
  public dispose(): void {
    console.log('🏗️ CollisionManager 资源已清理');
  }
  /**
   * 添加测试碰撞体（当场景模型加载失败时的备用方案）
   */
  private addTestColliders(): void {
    console.log('🧪 添加测试碰撞体作为备用方案');

    // 添加一些基本的测试碰撞体
    this.physicsWorldManager.createBox('test_ground', new THREE.Vector3(50, 1, 50), new THREE.Vector3(0, -1, 0), true);

    this.physicsWorldManager.createBox('test_wall1', new THREE.Vector3(1, 5, 20), new THREE.Vector3(10, 2.5, 0), true);

    this.physicsWorldManager.createBox('test_wall2', new THREE.Vector3(20, 5, 1), new THREE.Vector3(0, 2.5, 10), true);

    console.log('✅ 测试碰撞体添加完成');
  }
}
