import { ref, Ref } from 'vue';

export class FullscreenManager {
  public isFullscreen: Ref<boolean> = ref(false);

  private onChangeCallback?: (isFullscreen: boolean) => void;

  constructor(onChangeCallback?: (isFullscreen: boolean) => void) {
    this.onChangeCallback = onChangeCallback;
    this.setupEventListeners();
  }

  public async toggle(): Promise<void> {
    try {
      if (!this.isFullscreen.value) {
        await this.enter();
      } else {
        await this.exit();
      }
    } catch (error) {
      console.warn('全屏操作失败:', error);
      throw error;
    }
  }

  public async enter(): Promise<void> {
    if (this.isFullscreen.value) return;

    const element = document.documentElement;

    if (element.requestFullscreen) {
      await element.requestFullscreen();
    } else if ((element as any).webkitRequestFullscreen) {
      await (element as any).webkitRequestFullscreen();
    } else if ((element as any).mozRequestFullScreen) {
      await (element as any).mozRequestFullScreen();
    } else if ((element as any).msRequestFullscreen) {
      await (element as any).msRequestFullscreen();
    } else {
      throw new Error('浏览器不支持全屏功能');
    }
  }

  public async exit(): Promise<void> {
    if (!this.isFullscreen.value) return;

    if (document.exitFullscreen) {
      await document.exitFullscreen();
    } else if ((document as any).webkitExitFullscreen) {
      await (document as any).webkitExitFullscreen();
    } else if ((document as any).mozCancelFullScreen) {
      await (document as any).mozCancelFullScreen();
    } else if ((document as any).msExitFullscreen) {
      await (document as any).msExitFullscreen();
    } else {
      throw new Error('浏览器不支持退出全屏功能');
    }
  }

  public dispose() {
    document.removeEventListener('fullscreenchange', this.handleFullscreenChange);
    document.removeEventListener('webkitfullscreenchange', this.handleFullscreenChange);
    document.removeEventListener('mozfullscreenchange', this.handleFullscreenChange);
    document.removeEventListener('MSFullscreenChange', this.handleFullscreenChange);
    this.onChangeCallback = undefined;
  }
  private setupEventListeners() {
    document.addEventListener('fullscreenchange', this.handleFullscreenChange);
    document.addEventListener('webkitfullscreenchange', this.handleFullscreenChange);
    document.addEventListener('mozfullscreenchange', this.handleFullscreenChange);
    document.addEventListener('MSFullscreenChange', this.handleFullscreenChange);
  }

  private handleFullscreenChange = () => {
    const isCurrentlyFullscreen = !!(
      document.fullscreenElement ||
      (document as any).webkitFullscreenElement ||
      (document as any).mozFullScreenElement ||
      (document as any).msFullscreenElement
    );

    this.isFullscreen.value = isCurrentlyFullscreen;
    this.onChangeCallback?.(isCurrentlyFullscreen);
  };
}
