import * as THREE from 'three';
import RAPIER from '@dimforge/rapier3d-compat';

/**
 * 虚幻引擎地形配置接口
 */
export interface UnrealTerrainConfig {
  transform: {
    locationCM: [number, number, number]; // 地形位置 [x, y, z] (厘米)
    rotation: [number, number, number]; // 地形旋转 [x, y, z] (弧度)
    scale: [number, number, number]; // 地形缩放 [x, y, z]
  };
  resolution: {
    totalVertices: [number, number]; // [width, height] 总顶点数
    componentVertices: [number, number]; // [width, height] 组件顶点数
    componentSections: [number, number]; // [x, y] 分段数
  };
}

/**
 * 地形物理体创建选项
 */
export interface TerrainOptions {
  friction?: number;
  restitution?: number;
  debug?: boolean;
}

/**
 * 地形物理体信息
 */
export interface TerrainPhysicsInfo {
  rigidBody: RAPIER.RigidBody;
  collider: RAPIER.Collider;
  visualGeometry: THREE.BufferGeometry; // 用于可视化的几何体
  info: {
    width: number;
    height: number;
    minHeight: number;
    maxHeight: number;
    resolution: { x: number; y: number };
    position: { x: number; y: number; z: number };
    unrealConfig: UnrealTerrainConfig;
    vertexCount: number;
    r16Data: {
      width: number;
      height: number;
      totalPixels: number;
    };
  };
}

/**
 * R16 数据对象
 */
interface R16Data {
  dataView: DataView;
  width: number;
  height: number;
  totalPixels: number;
  byteLength: number;
}

/**
 * 地形管理器类
 * 负责从 R16 高度图创建地形物理碰撞体
 */
export class TerrainManager {
  // R16 格式常量
  private readonly R16_MIN_VALUE = 0;
  private readonly R16_MAX_VALUE = 65535;
  private readonly BYTES_PER_PIXEL = 2; // 16 位 = 2 字节

  // 虚幻引擎高度范围常量
  private readonly UE_MIN_HEIGHT = -256;
  private readonly UE_MAX_HEIGHT = 255.992;

  constructor() {
    console.log('🏔️ TerrainManager 初始化完成');
  }

  /**
   * 加载地形（高级接口）
   * @param world - Rapier 物理世界
   * @param heightMapUrl - 高度图URL
   * @param debugManager - 调试管理器（可选）
   * @returns 地形物理体信息
   */
  public async loadTerrain(
    world: RAPIER.World,
    heightMapUrl = '/terrain/heightmap.r16',
    debugManager?: any,
  ): Promise<TerrainPhysicsInfo | null> {
    try {
      console.log('🏔️ 开始加载高度图地形...');
      console.log('📍 地形URL:', heightMapUrl);

      const unrealConfig = {
        transform: {
          locationCM: [-11615.0, -12670.0, 100],
          rotation: [0, 0, 0],
          scale: [30, 30, 100],
        },
        resolution: {
          totalVertices: [714, 807],
          componentVertices: [32, 32],
          componentSections: [1, 1],
        },
      };

      console.log('⚙️ 地形配置:', unrealConfig);

      const terrainPhysics = await this.createTerrainFromHeightMap(world, heightMapUrl, unrealConfig, {
        friction: 0.8,
        restitution: 0.1,
        debug: true,
      });

      if (terrainPhysics) {
        console.log('✅ 高度图地形加载成功！');
        console.log(
          `📏 地形尺寸: ${terrainPhysics.info.width.toFixed(1)}m × ${terrainPhysics.info.height.toFixed(1)}m`,
        );
        console.log(
          `📊 高度范围: ${terrainPhysics.info.minHeight.toFixed(2)}m ~ ${terrainPhysics.info.maxHeight.toFixed(2)}m`,
        );
        console.log(
          `🎯 地形位置: (${terrainPhysics.info.position.x.toFixed(2)}, ${terrainPhysics.info.position.y.toFixed(2)}, ${terrainPhysics.info.position.z.toFixed(2)})`,
        );
        console.log(`🔢 顶点数量: ${terrainPhysics.info.vertexCount}`);
        console.log(`📐 分辨率: ${terrainPhysics.info.resolution.x} × ${terrainPhysics.info.resolution.y}`);

        // 自动启用地形碰撞可视化
        if (debugManager) {
          console.log('🎨 自动启用地形碰撞可视化...');
          debugManager.setTerrainVisualization(true);
        }

        return terrainPhysics;
      }
      console.warn('⚠️ 地形物理体创建返回空值');
      return null;
    } catch (terrainError) {
      console.error('❌ 高度图地形加载失败:', terrainError);
      console.error('🔍 错误详情:', {
        message: terrainError instanceof Error ? terrainError.message : '未知错误',
        stack: terrainError instanceof Error ? terrainError.stack : undefined,
      });
      return null;
    }
  }

  /**
   * 从高度图创建地形物理体
   * @param world - Rapier 物理世界
   * @param heightMapUrl - R16 高度图文件路径
   * @param unrealConfig - 虚幻引擎地形配置
   * @param options - 创建选项
   * @returns 地形物理体信息
   */
  public async createTerrainFromHeightMap(
    world: RAPIER.World,
    heightMapUrl: string,
    unrealConfig: UnrealTerrainConfig,
    options: TerrainOptions = {},
  ): Promise<TerrainPhysicsInfo> {
    console.log('🏔️ 开始创建地形物理体...');
    console.log('📋 虚幻引擎配置:', unrealConfig);

    try {
      // 1. 加载 R16 数据
      const r16Data = await this.loadR16Data(heightMapUrl, unrealConfig);

      // 2. 计算地形参数
      const config = this.calculateTerrainConfig(unrealConfig, options);

      // 3. 创建高度数据数组
      const heights = await this.createHeightDataFromR16(r16Data, config);

      // 4. 创建 Rapier heightfield 碰撞体
      const { rigidBody, collider } = this.createHeightfieldCollider(world, heights, config);

      // 5. 创建可视化几何体
      const visualGeometry = this.createVisualizationGeometry(heights, config);

      console.log('✅ 地形物理体创建完成');

      return {
        rigidBody,
        collider,
        visualGeometry,
        info: {
          width: config.actualWidth,
          height: config.actualHeight,
          minHeight: config.minHeight,
          maxHeight: config.maxHeight,
          resolution: { x: config.resolutionX, y: config.resolutionY },
          position: config.position,
          unrealConfig,
          vertexCount: heights.length,
          r16Data: {
            width: r16Data.width,
            height: r16Data.height,
            totalPixels: r16Data.totalPixels,
          },
        },
      };
    } catch (error) {
      console.error('❌ 地形物理体创建失败:', error);
      throw error;
    }
  }

  /**
   * 加载 R16 二进制数据
   * @param url - R16 文件路径
   * @param unrealConfig - 虚幻引擎地形配置
   * @returns R16 数据对象
   */
  private async loadR16Data(url: string, unrealConfig: UnrealTerrainConfig): Promise<R16Data> {
    try {
      console.log(`🔄 开始加载 R16 高度图: ${url}`);

      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const arrayBuffer = await response.arrayBuffer();
      const dataView = new DataView(arrayBuffer);

      // 使用虚幻引擎配置提供的准确尺寸
      const width = unrealConfig.resolution.totalVertices[0];
      const height = unrealConfig.resolution.totalVertices[1];

      console.log(`📐 使用虚幻引擎配置尺寸: ${width} x ${height}`);

      // 验证文件大小是否匹配
      const expectedSize = width * height * this.BYTES_PER_PIXEL;
      if (arrayBuffer.byteLength !== expectedSize) {
        console.warn(`⚠️ 文件大小不匹配! 期望: ${expectedSize} 字节, 实际: ${arrayBuffer.byteLength} 字节`);
      }

      const totalPixels = width * height;

      const r16Data: R16Data = {
        dataView,
        width,
        height,
        totalPixels,
        byteLength: arrayBuffer.byteLength,
      };

      console.log(`✅ R16 高度图加载成功:`);
      console.log(`   文件大小: ${(arrayBuffer.byteLength / 1024).toFixed(2)} KB`);
      console.log(`   图像尺寸: ${width} x ${height}`);
      console.log(`   总像素数: ${totalPixels}`);

      return r16Data;
    } catch (error) {
      console.error(`❌ R16 高度图加载失败: ${url}`, error);
      throw error;
    }
  }

  /**
   * 计算地形配置参数
   * @param unrealConfig - 虚幻引擎配置
   * @param options - 创建选项
   * @returns 地形配置
   */
  private calculateTerrainConfig(unrealConfig: UnrealTerrainConfig, options: TerrainOptions) {
    const { transform, resolution } = unrealConfig;

    // 根据虚幻引擎规则计算实际尺寸
    const componentResX = resolution.componentVertices[0];
    const componentResY = resolution.componentVertices[1];
    const totalVerticesX = resolution.totalVertices[0];
    const totalVerticesY = resolution.totalVertices[1];

    // 获取缩放参数
    const xScale = transform.scale[0];
    const yScale = transform.scale[1];
    const zScale = transform.scale[2];

    // 计算实际组件数
    const actualComponentsX = totalVerticesX / componentResX;
    const actualComponentsY = totalVerticesY / componentResY;

    // 计算实际尺寸（米）- 参考代码的计算方式
    const actualWidth = (actualComponentsX * componentResX * xScale) / 100;
    const actualHeight = (actualComponentsY * componentResY * yScale) / 100;

    console.log('rapier r16', totalVerticesX, totalVerticesY, xScale, yScale, zScale);

    // 虚幻引擎高度计算
    const minHeightMeters = (this.UE_MIN_HEIGHT * zScale) / 100;
    const maxHeightMeters = (this.UE_MAX_HEIGHT * zScale) / 100;
    const heightRange = maxHeightMeters - minHeightMeters;

    // 位置计算（厘米转米）
    const { locationCM } = transform;
    const locationM = [
      locationCM[0] / 100, // X
      locationCM[1] / 100, // Y
      locationCM[2] / 100, // Z
    ];

    // 参考代码的坐标系转换方式
    // 虚幻引擎使用左上角作为原点，Rapier 使用中心点
    const terrainCenterX = locationM[0] + actualWidth / 2; // 虚幻X -> Rapier X
    const terrainCenterY = locationM[2]; // 虚幻Z -> Rapier Y (高度)
    const terrainCenterZ = locationM[1] + actualHeight / 2; // 虚幻Y -> Rapier Z

    // 使用合适的分辨率（可以根据需要调整）
    const resolutionX = Math.min(totalVerticesX, 200);
    const resolutionY = Math.min(totalVerticesY, 200);

    const config = {
      resolutionX,
      resolutionY,
      actualWidth,
      actualHeight,
      minHeight: minHeightMeters,
      maxHeight: maxHeightMeters,
      heightRange,
      position: {
        x: terrainCenterX,
        y: terrainCenterY,
        z: terrainCenterZ,
      },
      friction: options.friction || 0.8,
      restitution: options.restitution || 0.1,
      debug: options.debug || false,
    };

    console.log(`🏔️ 虚幻引擎地形参数计算完成:`);
    console.log(`   原始顶点数: ${totalVerticesX} × ${totalVerticesY}`);
    console.log(`   使用分辨率: ${resolutionX} × ${resolutionY}`);
    console.log(`   实际尺寸: ${actualWidth.toFixed(1)}m × ${actualHeight.toFixed(1)}m`);
    console.log(`   高度范围: ${minHeightMeters.toFixed(2)}m ~ ${maxHeightMeters.toFixed(2)}m`);
    console.log(`   虚幻位置: [${locationCM[0]}, ${locationCM[1]}, ${locationCM[2]}] cm`);
    console.log(
      `   转换后中心: (${terrainCenterX.toFixed(2)}, ${terrainCenterY.toFixed(2)}, ${terrainCenterZ.toFixed(2)}) m`,
    );
    console.log(`   缩放比例: [${xScale}, ${yScale}, ${zScale}]`);

    return config;
  }

  /**
   * 从 R16 数据创建高度数据数组
   * @param r16Data - R16 数据对象
   * @param config - 地形配置
   * @returns 高度数据数组
   */
  private async createHeightDataFromR16(r16Data: R16Data, config: any): Promise<Float32Array> {
    return new Promise((resolve, reject) => {
      try {
        console.log(`🏔️ 开始从 R16 数据创建高度数组...`);
        console.log(`📊 配置参数:`, {
          resolutionX: config.resolutionX,
          resolutionY: config.resolutionY,
          minHeight: config.minHeight,
          maxHeight: config.maxHeight,
        });

        const { resolutionX } = config;
        const { resolutionY } = config;
        const totalPoints = resolutionX * resolutionY;

        console.log(`📊 高度数组信息:`);
        console.log(`   分辨率: ${resolutionX} x ${resolutionY}`);
        console.log(`   总点数: ${totalPoints}`);

        // 计算采样比例
        const sampleScaleX = (r16Data.width - 1) / (resolutionX - 1);
        const sampleScaleY = (r16Data.height - 1) / (resolutionY - 1);

        console.log(`📊 采样比例: X=${sampleScaleX.toFixed(3)}, Y=${sampleScaleY.toFixed(3)}`);

        // 创建高度数据数组
        const heights = new Float32Array(totalPoints);

        // 统计高度值用于调试
        let minHeightFound = Infinity;
        let maxHeightFound = -Infinity;
        let totalHeight = 0;

        // 生成高度数据
        for (let y = 0; y < resolutionY; y++) {
          for (let x = 0; x < resolutionX; x++) {
            // 计算在 R16 数据中的采样位置
            const sampleX = Math.round(x * sampleScaleX);
            const sampleY = Math.round(y * sampleScaleY);

            // 确保采样位置在有效范围内
            const clampedX = Math.min(sampleX, r16Data.width - 1);
            const clampedY = Math.min(sampleY, r16Data.height - 1);

            // 计算在 R16 数据中的字节偏移
            const offset = (clampedY * r16Data.width + clampedX) * this.BYTES_PER_PIXEL;

            // 读取 16 位高度值（小端序）
            const rawHeight = r16Data.dataView.getUint16(offset, true);

            // 归一化高度值 (0-65535 -> 0-1)
            const normalizedHeight = rawHeight / this.R16_MAX_VALUE;

            // 计算实际高度
            const actualHeight = config.minHeight + normalizedHeight * (config.maxHeight - config.minHeight);

            // 存储高度值（注意：Rapier 使用行优先存储，需要垂直翻转）
            const flippedY = resolutionY - 1 - y;
            const index = flippedY * resolutionX + x;
            heights[index] = actualHeight;

            // 统计信息
            minHeightFound = Math.min(minHeightFound, actualHeight);
            maxHeightFound = Math.max(maxHeightFound, actualHeight);
            totalHeight += actualHeight;

            // 调试：打印前几个点的信息
            if (index < 5) {
              console.log(
                `🔍 点 ${index}: 网格(${x},${y}) -> 采样(${clampedX},${clampedY}) -> 原始值${rawHeight} -> 高度${actualHeight.toFixed(2)}m`,
              );
            }
          }
        }

        // 输出统计信息
        const avgHeight = totalHeight / totalPoints;
        console.log(`📊 高度统计:`);
        console.log(`   最小高度: ${minHeightFound.toFixed(2)}m`);
        console.log(`   最大高度: ${maxHeightFound.toFixed(2)}m`);
        console.log(`   平均高度: ${avgHeight.toFixed(2)}m`);
        console.log(`   高度范围: ${(maxHeightFound - minHeightFound).toFixed(2)}m`);

        console.log('✅ R16 高度数据数组创建完成');
        resolve(heights);
      } catch (error) {
        console.error('❌ 创建 R16 高度数据数组失败:', error);
        reject(error);
      }
    });
  }

  /**
   * 创建 Rapier heightfield 碰撞体
   * @param world - Rapier 物理世界
   * @param heights - 高度数据数组
   * @param config - 配置参数
   * @returns 物理体对象
   */
  private createHeightfieldCollider(world: RAPIER.World, heights: Float32Array, config: any) {
    try {
      console.log(`🔧 开始创建 Rapier heightfield 碰撞体...`);
      console.log(`   高度数据长度: ${heights.length}`);
      console.log(`   分辨率: ${config.resolutionX} × ${config.resolutionY}`);
      console.log(`   实际尺寸: ${config.actualWidth.toFixed(2)}m × ${config.actualHeight.toFixed(2)}m`);

      // 创建 heightfield 碰撞体描述
      // Rapier heightfield 参数：(nrows, ncols, heights, scale)
      // nrows = Z方向的段数 = resolutionY - 1 (深度方向)
      // ncols = X方向的段数 = resolutionX - 1 (宽度方向)
      // 高度数据按行优先顺序存储：heights[row * ncols + col]
      // scale: heightfield 的总尺寸，原点在中心

      // 验证高度数据
      let minHeight = Infinity;
      let maxHeight = -Infinity;
      for (let i = 0; i < heights.length; i++) {
        minHeight = Math.min(minHeight, heights[i]);
        maxHeight = Math.max(maxHeight, heights[i]);
      }

      // 创建 heightfield 碰撞体描述（参考代码的参数顺序）
      const colliderDesc = RAPIER.ColliderDesc.heightfield(
        config.resolutionY - 1, // nrows (行数)
        config.resolutionX - 1, // ncols (列数)
        heights, // 高度数据
        { x: config.actualHeight, y: 1.0, z: config.actualWidth }, // 缩放
      );

      console.log(`🔧 Heightfield 参数详情:`);
      console.log(`   分辨率: ${config.resolutionX} × ${config.resolutionY} 顶点`);
      console.log(`   段数: ${config.resolutionX - 1} × ${config.resolutionY - 1} 段`);
      console.log(`   缩放: {x: ${config.actualHeight.toFixed(2)}, y: 1.0, z: ${config.actualWidth.toFixed(2)}}`);
      console.log(`   实际高度范围: [${minHeight.toFixed(2)}, ${maxHeight.toFixed(2)}]m`);
      console.log(`   配置高度范围: [${config.minHeight.toFixed(2)}, ${config.maxHeight.toFixed(2)}]m`);

      // 设置物理属性
      colliderDesc.setFriction(config.friction);
      colliderDesc.setRestitution(config.restitution);

      // 设置碰撞组和过滤器，确保与角色控制器正确交互
      colliderDesc.setCollisionGroups(0x00010001); // 组1，与组1碰撞
      colliderDesc.setSolverGroups(0x00010001); // 求解器组设置

      // 创建静态刚体（绕 Y 轴旋转 90 度以匹配坐标系）
      const rotation = this.eulerToQuaternion(0, Math.PI * 0.5, 0);
      const rigidBodyDesc = RAPIER.RigidBodyDesc.fixed()
        .setTranslation(config.position.x, config.position.y, config.position.z)
        .setRotation(rotation);

      const rigidBody = world.createRigidBody(rigidBodyDesc);
      const collider = world.createCollider(colliderDesc, rigidBody);

      console.log(`✅ Rapier heightfield 碰撞体创建完成:`);
      console.log(`   刚体句柄: ${rigidBody.handle}`);
      console.log(`   碰撞体句柄: ${collider.handle}`);
      console.log(
        `   刚体位置: (${config.position.x.toFixed(2)}, ${config.position.y.toFixed(2)}, ${config.position.z.toFixed(2)})`,
      );
      console.log(`   heightfield尺寸: ${config.actualWidth.toFixed(1)}m × ${config.actualHeight.toFixed(1)}m`);
      console.log(`   段数: ${config.resolutionX - 1} × ${config.resolutionY - 1}`);
      console.log(
        `   局部坐标范围: X[${(-config.actualWidth / 2).toFixed(1)}, ${(config.actualWidth / 2).toFixed(1)}], Z[${(-config.actualHeight / 2).toFixed(1)}, ${(config.actualHeight / 2).toFixed(1)}]`,
      );

      return { rigidBody, collider };
    } catch (error) {
      console.error('❌ 创建 Rapier heightfield 碰撞体失败:', error);
      throw error;
    }
  }

  /**
   * 创建地形可视化几何体
   * @param heights - 高度数据数组
   * @param config - 地形配置
   * @returns Three.js 几何体
   */
  private createVisualizationGeometry(heights: Float32Array, config: any): THREE.BufferGeometry {
    console.log('🎨 创建地形可视化几何体...');

    const { resolutionX } = config;
    const { resolutionY } = config;
    const { actualWidth } = config;
    const { actualHeight } = config;

    console.log(`📐 几何体参数:`);
    console.log(`   分辨率: ${resolutionX} × ${resolutionY}`);
    console.log(`   实际尺寸: ${actualWidth.toFixed(2)}m × ${actualHeight.toFixed(2)}m`);
    console.log(`   高度数据长度: ${heights.length}`);
    console.log(
      `   刚体位置: (${config.position.x.toFixed(2)}, ${config.position.y.toFixed(2)}, ${config.position.z.toFixed(2)})`,
    );

    // 创建顶点数组
    const vertices: number[] = [];
    const indices: number[] = [];

    // 生成顶点 - 创建局部坐标系中的几何体，与物理碰撞体对齐
    // 几何体使用局部坐标，变换将在 DebugManager 中通过刚体变换应用
    for (let y = 0; y < resolutionY; y++) {
      for (let x = 0; x < resolutionX; x++) {
        // 计算局部坐标（相对于 heightfield 中心）
        const localX = (x / (resolutionX - 1) - 0.5) * actualWidth;
        const localZ = (y / (resolutionY - 1) - 0.5) * actualHeight;

        // 使用与物理碰撞体相同的高度数据索引（考虑垂直翻转）
        const flippedY = resolutionY - 1 - y;
        const localY = heights[flippedY * resolutionX + x];

        // 应用与物理碰撞体相同的旋转变换（绕 Y 轴旋转 90 度）
        // 旋转前：localX, localY, localZ
        // 旋转后：-localZ, localY, localX
        const rotatedX = -localZ;
        const rotatedY = localY;
        const rotatedZ = localX;

        // 存储局部坐标（不加世界位置偏移）
        vertices.push(rotatedX, rotatedY, rotatedZ);

        // 调试前几个顶点
        if (y * resolutionX + x < 5) {
          console.log(
            `🔍 顶点 ${y * resolutionX + x}: 网格(${x},${y}) -> 翻转Y(${flippedY}) -> 局部(${localX.toFixed(2)}, ${localY.toFixed(2)}, ${localZ.toFixed(2)}) -> 旋转后局部(${rotatedX.toFixed(2)}, ${rotatedY.toFixed(2)}, ${rotatedZ.toFixed(2)})`,
          );
        }
      }
    }

    // 生成三角形索引
    for (let y = 0; y < resolutionY - 1; y++) {
      for (let x = 0; x < resolutionX - 1; x++) {
        const topLeft = y * resolutionX + x;
        const topRight = y * resolutionX + (x + 1);
        const bottomLeft = (y + 1) * resolutionX + x;
        const bottomRight = (y + 1) * resolutionX + (x + 1);

        // 第一个三角形
        indices.push(topLeft, bottomLeft, topRight);
        // 第二个三角形
        indices.push(topRight, bottomLeft, bottomRight);
      }
    }

    // 创建几何体
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();

    // 添加一些调试标记点
    if (config.debug) {
      console.log(`🎯 地形调试信息:`);
      console.log(
        `   中心点高度: ${heights[Math.floor(resolutionY / 2) * resolutionX + Math.floor(resolutionX / 2)].toFixed(2)}m`,
      );
      console.log(`   四个角的高度:`);
      console.log(`     左上角: ${heights[0].toFixed(2)}m`);
      console.log(`     右上角: ${heights[resolutionX - 1].toFixed(2)}m`);
      console.log(`     左下角: ${heights[(resolutionY - 1) * resolutionX].toFixed(2)}m`);
      console.log(`     右下角: ${heights[(resolutionY - 1) * resolutionX + resolutionX - 1].toFixed(2)}m`);
    }

    // 计算实际的坐标范围（世界坐标）
    const minX = config.position.x - actualWidth / 2;
    const maxX = config.position.x + actualWidth / 2;
    const minZ = config.position.z - actualHeight / 2;
    const maxZ = config.position.z + actualHeight / 2;

    console.log(`✅ 地形可视化几何体创建完成:`);
    console.log(`   顶点数: ${vertices.length / 3}`);
    console.log(`   三角形数: ${indices.length / 3}`);
    console.log(
      `   局部坐标范围: X[${(-actualWidth / 2).toFixed(1)}, ${(actualWidth / 2).toFixed(1)}], Z[${(-actualHeight / 2).toFixed(1)}, ${(actualHeight / 2).toFixed(1)}]`,
    );
    console.log(`   几何体类型: 局部坐标系（需要通过刚体变换应用到世界坐标）`);
    console.log(
      `   刚体位置: (${config.position.x.toFixed(2)}, ${config.position.y.toFixed(2)}, ${config.position.z.toFixed(2)})`,
    );

    return geometry;
  }

  /**
   * 欧拉角转四元数
   * @param x - X 轴旋转角度（弧度）
   * @param y - Y 轴旋转角度（弧度）
   * @param z - Z 轴旋转角度（弧度）
   * @returns 四元数
   */
  private eulerToQuaternion(x: number, y: number, z: number) {
    const c1 = Math.cos(x / 2);
    const c2 = Math.cos(y / 2);
    const c3 = Math.cos(z / 2);
    const s1 = Math.sin(x / 2);
    const s2 = Math.sin(y / 2);
    const s3 = Math.sin(z / 2);

    return {
      x: s1 * c2 * c3 + c1 * s2 * s3,
      y: c1 * s2 * c3 - s1 * c2 * s3,
      z: c1 * c2 * s3 + s1 * s2 * c3,
      w: c1 * c2 * c3 - s1 * s2 * s3,
    };
  }

  /**
   * 清理资源
   */
  public dispose(): void {
    console.log('🏔️ TerrainManager 资源已清理');
  }
}
