import * as THREE from 'three';
import { GaussianAbstractComponent } from '../components/gaussian-abstract-component';
import { SplatConfig } from '../../../../types';

/**
 * 高斯泼溅加载策略抽象基类
 */
export abstract class GaussianSplatLoadStrategy {
  protected scene: THREE.Scene;
  protected viewer: GaussianAbstractComponent<any> | null = null;
  protected config: SplatConfig;


  constructor(scene: THREE.Scene, config: SplatConfig) {
    this.scene = scene;
    this.config = config;
  }

  /**
   * 获取viewer实例
   */
  getViewer(): GaussianAbstractComponent<any> | null {
    return this.viewer;
  }


  /**
   * 加载场景
   * @param sceneId 场景ID
   * @returns Promise<void>
   */
  abstract load(): Promise<void>;

  /**
   * 卸载场景
   */
  abstract dispose(): void;

  /**
   * 更新策略（每帧调用）
   * @param deltaTime 时间增量
   */
  abstract update(): void;
}
