import * as THREE from 'three';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { PhysicsWorldManager } from './physics-world-manager';
import { AnimationManager } from './animation-manager';
import { LocalModelConfig, TARGET_CHARACTER_HEIGHT } from './constant';
import { CharacterModelInfo } from '@/types';
import { convertRotationToRadians } from '@/utils';
import { NPC } from './npc';
import { PathFinding } from './path-finding.ts';
import { calculateCapsuleParams } from './capsule-manager';

/**
 * NPC实例接口
 */
export interface NPCInstance {
  id: string;
  npc: NPC; // NPC类实例
  model: THREE.Group;
  animationManager: AnimationManager;
  position: THREE.Vector3;
  modelConfig: CharacterModelInfo;
  rigidBodyHandle: number; // Rapier动态刚体句柄
  isActive: boolean;
}

/**
 * NPC配置接口
 */
export interface NPCConfig {
  position: THREE.Vector3 | { x: number; y: number; z: number };
  modelId?: string; // 指定模型ID，如果不指定则随机选择
  scale?: number; // 自定义缩放，如果不指定则使用模型配置
  targetHeight?: number; // 目标高度（米），用于计算胶囊体参数
  animations?: {
    idle?: boolean;
    walking?: boolean;
    running?: boolean;
  };
}

/**
 * NPC管理器
 * 负责创建、管理和更新场景中的NPC
 */
export class NPCManager {
  private scene: THREE.Scene;
  private physicsWorldManager: PhysicsWorldManager;
  private npcs: Map<string, NPCInstance> = new Map();
  private npcCounter = 0;
  private dynamicModelConfigs: Map<string, CharacterModelInfo> = new Map();
  private pathfinding: PathFinding; // 寻路系统

  constructor(scene: THREE.Scene, physicsWorldManager: PhysicsWorldManager) {
    this.scene = scene;
    this.physicsWorldManager = physicsWorldManager;

    // 初始化寻路系统（创建一个较大的导航区域）
    const navigationBounds = new THREE.Box3(new THREE.Vector3(-100, -10, -100), new THREE.Vector3(100, 10, 100));
    this.pathfinding = new PathFinding(navigationBounds);

    console.log('🤖 NPCManager 初始化完成');
    console.log('🗺️ 寻路系统已初始化（导航区域: 200x200）');
  }

  /**
   * 添加动态模型配置
   * @param config 动态模型配置
   */
  public addDynamicModelConfig(config: CharacterModelInfo): void {
    this.dynamicModelConfigs.set(config.id, config);
    console.log(`🔧 NPCManager 添加动态模型配置: ${config.name} (${config.id})`);
  }

  /**
   * 获取所有可用的模型配置（本地 + 动态）
   */
  private getAllAvailableModels(): CharacterModelInfo[] {
    const allModels = [...LocalModelConfig.models];

    // 添加动态配置的模型
    this.dynamicModelConfigs.forEach((config) => {
      // 避免重复添加（如果动态配置的ID与本地配置冲突，优先使用动态配置）
      const existingIndex = allModels.findIndex((model) => model.id === config.id);
      if (existingIndex >= 0) {
        allModels[existingIndex] = config; // 替换为动态配置
      } else {
        allModels.push(config); // 添加新的动态配置
      }
    });

    return allModels;
  }

  /**
   * 随机选择一个角色模型
   */
  private getRandomModel(): CharacterModelInfo {
    const availableModels = this.getAllAvailableModels();
    const randomIndex = Math.floor(Math.random() * availableModels.length);
    return availableModels[randomIndex];
  }

  /**
   * 根据ID获取模型配置
   */
  private getModelById(modelId: string): CharacterModelInfo | null {
    const availableModels = this.getAllAvailableModels();
    return availableModels.find((model) => model.id === modelId) || null;
  }

  /**
   * 计算模型的自动缩放值
   */
  private calculateAutoScale(model: THREE.Group, targetHeight: number = TARGET_CHARACTER_HEIGHT): number {
    const originalScale = model.scale.clone();
    const originalPosition = model.position.clone();
    const originalRotation = model.rotation.clone();

    model.scale.set(1, 1, 1);
    model.position.set(0, 0, 0);
    model.rotation.set(0, 0, 0);
    model.updateMatrixWorld(true);

    const box = new THREE.Box3().setFromObject(model);
    const modelHeight = box.max.y - box.min.y;

    model.scale.copy(originalScale);
    model.position.copy(originalPosition);
    model.rotation.copy(originalRotation);
    model.updateMatrixWorld(true);

    if (modelHeight <= 0) {
      console.warn('⚠️ NPC模型高度计算异常，使用默认缩放值 1.0');
      return 1.0;
    }

    const scale = targetHeight / modelHeight;
    console.log(
      `📏 NPC自动缩放计算: 原始高度=${modelHeight.toFixed(3)}, 目标高度=${targetHeight.toFixed(3)}, 缩放值=${scale.toFixed(6)}`,
    );
    return scale;
  }

  /**
   * 加载NPC模型
   */
  private async loadNPCModel(modelConfig: CharacterModelInfo): Promise<{ model: THREE.Group; gltf?: any }> {
    const fileExtension = modelConfig.modelFilePath.toLowerCase().split('.').pop();
    console.log(`📁 加载NPC模型: ${modelConfig.name} (${modelConfig.modelFilePath}, 格式: ${fileExtension})`);

    let characterModel: THREE.Group;
    let gltfData: any = undefined;

    if (fileExtension === 'fbx') {
      const fbxLoader = new FBXLoader();
      characterModel = await fbxLoader.loadAsync(modelConfig.modelFilePath);
      console.log('✅ FBX NPC模型加载成功');
    } else if (fileExtension === 'glb') {
      const gltfLoader = new GLTFLoader();
      const gltf = await gltfLoader.loadAsync(modelConfig.modelFilePath);
      characterModel = gltf.scene;
      gltfData = gltf; // 保存gltf数据（包含动画）
      console.log(`✅ GLB NPC模型加载成功，包含 ${gltf.animations?.length || 0} 个内置动画`);
    } else {
      throw new Error(`不支持的NPC模型格式: ${fileExtension}`);
    }

    // 设置模型属性
    characterModel.traverse((object: any) => {
      if (object.isMesh) {
        object.castShadow = true;
        object.receiveShadow = true;

        // 优化材质
        if (object.material) {
          if (Array.isArray(object.material)) {
            object.material.forEach((material: any) => {
              this.optimizeMaterial(material);
            });
          } else {
            this.optimizeMaterial(object.material);
          }
        }
      }
    });

    return { model: characterModel, gltf: gltfData };
  }

  /**
   * 优化材质
   */
  private optimizeMaterial(material: any) {
    if (material.isMeshStandardMaterial || material.isMeshPhongMaterial) {
      material.needsUpdate = true;

      if (material.color) {
        const hsl = { h: 0, s: 0, l: 0 };
        material.color.getHSL(hsl);

        if (hsl.l < 0.3) {
          hsl.l = Math.max(0.3, hsl.l * 1.5);
          material.color.setHSL(hsl.h, hsl.s, hsl.l);
        }
      }

      if (material.isMeshStandardMaterial) {
        if (material.metalness > 0.8) {
          material.metalness = 0.3;
        }
        if (material.roughness < 0.3) {
          material.roughness = 0.5;
        }
      }
    }
  }

  /**
   * 创建NPC
   * @param config NPC配置
   * @returns NPC实例ID
   */
  public async createNPC(config: NPCConfig): Promise<string> {
    try {
      const npcId = `npc_${++this.npcCounter}`;
      console.log(`🤖 开始创建NPC: ${npcId}`);

      // 选择模型配置
      let modelConfig: CharacterModelInfo;
      if (config.modelId) {
        const specificModel = this.getModelById(config.modelId);
        if (!specificModel) {
          console.warn(`⚠️ 指定的模型ID不存在: ${config.modelId}，使用随机模型`);
          modelConfig = this.getRandomModel();
        } else {
          modelConfig = specificModel;
        }
      } else {
        modelConfig = this.getRandomModel();
      }

      console.log(`🎭 NPC选择模型: ${modelConfig.name} (${modelConfig.id})`);

      // 加载模型
      const { model, gltf } = await this.loadNPCModel(modelConfig);

      // 计算缩放
      let scale: number;
      if (config.scale !== undefined) {
        scale = config.scale;
      } else if (modelConfig.transform?.scale !== undefined) {
        scale = modelConfig.transform.scale;
      } else {
        scale = this.calculateAutoScale(model);
      }

      // 应用缩放
      model.scale.setScalar(scale);

      // 设置位置 - 处理普通对象或 THREE.Vector3
      let finalPosition: THREE.Vector3;
      if (config.position instanceof THREE.Vector3) {
        finalPosition = config.position.clone();
      } else {
        finalPosition = new THREE.Vector3(config.position.x, config.position.y, config.position.z);
      }

      if (modelConfig.transform?.position) {
        finalPosition.add(
          new THREE.Vector3(
            modelConfig.transform.position.x,
            modelConfig.transform.position.y,
            modelConfig.transform.position.z,
          ),
        );
      }
      model.position.copy(finalPosition);

      // 设置旋转（将角度转换为弧度）
      if (modelConfig.transform?.rotation) {
        const rotationRadians = convertRotationToRadians([
          modelConfig.transform.rotation.x,
          modelConfig.transform.rotation.y,
          modelConfig.transform.rotation.z,
        ]);
        model.rotation.set(rotationRadians[0], rotationRadians[1], rotationRadians[2]);
      }

      // 创建动画管理器
      const box = new THREE.Box3().setFromObject(model);
      const modelHeight = box.max.y - box.min.y;

      // NPC使用较慢的速度 (与NPC类中的速度保持一致)
      const npcRunVelocity = 3.0;
      const npcWalkVelocity = 1.5;
      const npcWanderSpeed = 0.5; // 漫游速度倍数

      // 计算NPC实际移动速度
      const actualWalkSpeed = npcWalkVelocity * npcWanderSpeed; // 1.5 * 0.5 = 0.75
      const actualRunSpeed = npcRunVelocity * npcWanderSpeed; // 3.0 * 0.5 = 1.5

      // 计算胶囊体参数
      const targetHeight = config.targetHeight || TARGET_CHARACTER_HEIGHT;
      const capsuleParams = calculateCapsuleParams(targetHeight);
      const { radius: capsuleRadius, height: capsuleHeight, bottomOffset: capsuleBottomOffset } = capsuleParams;

      console.log(
        `📏 NPC ${npcId} 胶囊体参数 (基于高度 ${targetHeight}m):`,
        `半径=${capsuleRadius}m, 高度=${capsuleHeight}m, 底部偏移=${capsuleBottomOffset}m`,
      );

      const animationManager = new AnimationManager(
        model,
        0.2, // fadeDuration
        modelHeight,
        actualRunSpeed, // 使用实际运动速度
        actualWalkSpeed, // 使用实际运动速度
        modelConfig.anim,
        modelConfig.animationSpeedScale || 1.0, // 动画速度比例
      );

      // 如果是GLB模型且有内置动画，先加载内置动画
      if (gltf?.animations && gltf.animations.length > 0) {
        console.log(`🎭 检测到GLB内置动画，加载 ${gltf.animations.length} 个动画`);

        // 如果配置中有动画映射（basePath为空但有animations），使用配置映射
        let animationMapping: Record<string, string> | undefined;
        if (modelConfig.anim?.animations) {
          // 转换animations为简单的字符串映射
          animationMapping = {};
          for (const [key, value] of Object.entries(modelConfig.anim.animations)) {
            animationMapping[key] = typeof value === 'string' ? value : value.url;
          }
        }
        animationManager.loadGLBAnimations(gltf, animationMapping);
      }

      // 初始化动画
      await animationManager.init();

      // 创建动态刚体（受重力和碰撞影响）
      // 胶囊体的位置是中心点
      const physicsPosition = new THREE.Vector3(
        finalPosition.x,
        finalPosition.y + (capsuleHeight / 2 + capsuleRadius), // y = 模型底部 + (胶囊体高度/2 + 胶囊体半径)
        finalPosition.z,
      );

      const rigidBodyHandle = this.physicsWorldManager.createDynamicRigidBody(
        physicsPosition,
        capsuleRadius,
        capsuleHeight,
      );

      console.log(
        `📦 NPC物理刚体创建: handle=${rigidBodyHandle}, 位置=(${physicsPosition.x.toFixed(2)}, ${physicsPosition.y.toFixed(2)}, ${physicsPosition.z.toFixed(2)})`,
      );

      // 创建NPC类实例
      const npc = new NPC(
        npcId,
        modelConfig,
        this.scene,
        this.physicsWorldManager,
        finalPosition,
        capsuleRadius,
        capsuleHeight,
        capsuleBottomOffset,
      );

      // 设置模型和动画管理器到NPC实例
      npc.setModel(model);
      npc.setAnimationManager(animationManager);

      // 设置刚体句柄到NPC实例
      npc.setRigidBodyHandle(rigidBodyHandle);

      // 应用模型的基础旋转
      if (modelConfig.transform?.rotation) {
        const rotationRadians = convertRotationToRadians([
          modelConfig.transform.rotation.x,
          modelConfig.transform.rotation.y,
          modelConfig.transform.rotation.z,
        ]);
        const baseRotation = new THREE.Euler(rotationRadians[0], rotationRadians[1], rotationRadians[2]);
        npc.setBaseRotation(baseRotation);
      }

      // 创建NPC实例记录
      const npcInstance: NPCInstance = {
        id: npcId,
        npc,
        model,
        animationManager,
        position: finalPosition,
        modelConfig,
        rigidBodyHandle,
        isActive: true,
      };

      // 添加到场景和管理器
      this.scene.add(model);
      this.npcs.set(npcId, npcInstance);

      // 设置默认动画和移动模式
      if (animationManager.isReady()) {
        animationManager.playAnimation('Idle');
      }

      // 设置NPC的寻路系统
      npc.setPathfinding(this.pathfinding);

      // 设置NPC为漫游模式
      npc.setMovementPattern('wander');

      console.log(`✅ NPC创建成功: ${npcId} (模型: ${modelConfig.name})`);
      console.log(
        `   位置: (${finalPosition.x.toFixed(2)}, ${finalPosition.y.toFixed(2)}, ${finalPosition.z.toFixed(2)})`,
      );
      console.log(`   缩放: ${scale.toFixed(6)}`);
      console.log(`   高度: ${modelHeight.toFixed(3)}m`);

      return npcId;
    } catch (error) {
      console.error('❌ NPC创建失败:', error);
      throw error;
    }
  }

  /**
   * 删除NPC
   * @param npcId NPC实例ID
   */
  public removeNPC(npcId: string): boolean {
    const npc = this.npcs.get(npcId);
    if (!npc) {
      console.warn(`⚠️ NPC不存在: ${npcId}`);
      return false;
    }

    try {
      // 销毁NPC实例（会自动清理物理、模型、动画等）
      npc.npc.dispose();

      // 从管理器中移除
      this.npcs.delete(npcId);

      console.log(`🗑️ NPC已删除: ${npcId}`);
      return true;
    } catch (error) {
      console.error(`❌ 删除NPC失败: ${npcId}`, error);
      return false;
    }
  }

  /**
   * 获取NPC实例
   * @param npcId NPC实例ID
   */
  public getNPC(npcId: string): NPCInstance | null {
    return this.npcs.get(npcId) || null;
  }

  /**
   * 获取所有NPC
   */
  public getAllNPCs(): NPCInstance[] {
    return Array.from(this.npcs.values());
  }

  /**
   * 获取NPC数量
   */
  public getNPCCount(): number {
    return this.npcs.size;
  }

  /**
   * 设置NPC动画
   * @param npcId NPC实例ID
   * @param animationName 动画名称
   */
  public setNPCAnimation(npcId: string, animationName: string): boolean {
    const npcInstance = this.npcs.get(npcId);
    if (!npcInstance) {
      console.warn(`⚠️ NPC不存在: ${npcId}`);
      return false;
    }

    npcInstance.npc.playAnimation(animationName);
    console.log(`🎭 NPC动画设置: ${npcId} -> ${animationName}`);
    return true;
  }

  /**
   * 设置NPC位置
   * @param npcId NPC实例ID
   * @param position 新位置
   */
  public setNPCPosition(npcId: string, position: THREE.Vector3): boolean {
    const npcInstance = this.npcs.get(npcId);
    if (!npcInstance) {
      console.warn(`⚠️ NPC不存在: ${npcId}`);
      return false;
    }

    npcInstance.npc.setPosition(position);
    npcInstance.position.copy(position);

    console.log(
      `📍 NPC位置更新: ${npcId} -> (${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)})`,
    );
    return true;
  }

  /**
   * 设置NPC激活状态
   * @param npcId NPC实例ID
   * @param active 是否激活
   */
  public setNPCActive(npcId: string, active: boolean): boolean {
    const npcInstance = this.npcs.get(npcId);
    if (!npcInstance) {
      console.warn(`⚠️ NPC不存在: ${npcId}`);
      return false;
    }

    npcInstance.isActive = active;
    npcInstance.npc.setVisible(active);

    console.log(`👁️ NPC激活状态: ${npcId} -> ${active ? '激活' : '隐藏'}`);
    return true;
  }

  /**
   * 更新所有NPC（在主循环中调用）
   * @param delta 时间增量
   */
  public update(delta: number): void {
    this.npcs.forEach((npcInstance) => {
      if (npcInstance.isActive) {
        // 调用NPC实例的update方法，会自动处理移动、重力、动画等
        npcInstance.npc.update(delta);
      }
    });
  }

  /**
   * 清理所有NPC
   */
  public dispose(): void {
    console.log('🗑️ 开始清理所有NPC...');

    const npcIds = Array.from(this.npcs.keys());
    npcIds.forEach((npcId) => {
      this.removeNPC(npcId);
    });

    this.npcs.clear();
    this.dynamicModelConfigs.clear();
    this.npcCounter = 0;

    console.log('✅ NPCManager 清理完成');
  }

  /**
   * 批量创建NPC
   * @param configs NPC配置数组
   * @returns 创建的NPC ID数组
   */
  public async createMultipleNPCs(configs: NPCConfig[]): Promise<string[]> {
    const npcIds: string[] = [];

    console.log(`🤖 开始批量创建${configs.length}个NPC...`);

    for (const config of configs) {
      try {
        const npcId = await this.createNPC(config);
        npcIds.push(npcId);
      } catch (error) {
        console.error('❌ 批量创建NPC时发生错误:', error);
      }
    }

    console.log(`✅ 批量创建NPC完成，成功创建${npcIds.length}/${configs.length}个`);
    return npcIds;
  }

  /**
   * 在指定区域随机创建NPC
   * @param center 区域中心点
   * @param radius 区域半径
   * @param count NPC数量
   * @param yPosition Y轴位置（可选，默认使用center的Y值）
   */
  public async createRandomNPCsInArea(
    center: THREE.Vector3 | { x: number; y: number; z: number },
    radius: number,
    count: number,
    yPosition?: number,
  ): Promise<string[]> {
    const configs: NPCConfig[] = [];

    // 处理 center 参数
    let centerPos: THREE.Vector3;
    if (center instanceof THREE.Vector3) {
      centerPos = center;
    } else {
      centerPos = new THREE.Vector3(center.x, center.y, center.z);
    }

    for (let i = 0; i < count; i++) {
      // 在圆形区域内随机生成位置
      const angle = Math.random() * Math.PI * 2;
      const distance = Math.random() * radius;

      const x = centerPos.x + Math.cos(angle) * distance;
      const z = centerPos.z + Math.sin(angle) * distance;
      const y = yPosition !== undefined ? yPosition : centerPos.y;

      configs.push({
        position: new THREE.Vector3(x, y, z),
      });
    }

    console.log(
      `🎲 在区域内随机创建${count}个NPC (中心: ${centerPos.x.toFixed(2)}, ${centerPos.y.toFixed(2)}, ${centerPos.z.toFixed(2)}, 半径: ${radius})`,
    );

    return await this.createMultipleNPCs(configs);
  }

  /**
   * 让NPC寻路到玩家位置
   * @param npcId NPC实例ID
   * @returns 是否成功设置寻路目标
   */
  public setNPCPathfindToPlayer(npcId: string): boolean {
    const npcInstance = this.npcs.get(npcId);
    if (!npcInstance) {
      console.warn(`⚠️ NPC不存在: ${npcId}`);
      return false;
    }

    // 获取玩家位置
    const playerPosition = this.physicsWorldManager.getCharacterPosition();
    if (!playerPosition) {
      console.warn('⚠️ 无法获取玩家位置');
      return false;
    }

    // 设置寻路目标
    const targetPos = new THREE.Vector3(playerPosition.x, playerPosition.y, playerPosition.z);
    npcInstance.npc.setPathTarget(targetPos);

    console.log(
      `🎯 NPC ${npcId} 开始寻路到玩家位置: (${playerPosition.x.toFixed(2)}, ${playerPosition.y.toFixed(2)}, ${playerPosition.z.toFixed(2)})`,
    );
    return true;
  }

  /**
   * 获取寻路系统实例（用于高级配置，如添加障碍物）
   */
  public getPathfinding(): PathFinding {
    return this.pathfinding;
  }
}
