export class ColorUtils {
  // 解析颜色整数
  static parseColorInt(colorInt: number) {
    return {
      r: (colorInt >> 24) & 0xff,
      g: (colorInt >> 16) & 0xff,
      b: (colorInt >> 8) & 0xff,
      a: colorInt & 0xff,
    };
  }

  // 转换为十六进制
  static toHex(colorInt: number) {
    const { r, g, b, a } = this.parseColorInt(colorInt);
    return `${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}${a.toString(16).padStart(2, '0')}`;
  }
}
