import { ProjectConfig, SplatConfig } from '../../../types';

/**
 * 配置管理器
 * 负责加载和管理项目配置
 */
export class ConfigManager {
  private config: ProjectConfig | null = null;
  private configUrl: string;

  constructor(configUrl: string) {
    this.configUrl = configUrl;
    console.log('⚙️ ConfigManager 初始化完成');
  }

  /**
   * 加载配置文件
   * @returns Promise<ProjectConfig>
   */
  public async loadConfig(): Promise<ProjectConfig> {
    try {
      console.log('🔄 开始加载项目配置...');
      console.log('📍 配置URL:', this.configUrl);

      const response = await fetch(this.configUrl);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const config: ProjectConfig = await response.json();
      this.config = config;

      console.log('✅ 项目配置加载成功:');
      console.log(`   项目名称: ${config.name}`);
      console.log(`   渲染器缩放: ${config.rendererScale}`);
      console.log(`   调试模式: ${config.debugger ? '开启' : '关闭'}`);
      console.log(`   米制缩放: ${config.meterScale}`);
      console.log(`   网格模型URL: ${config.collision?.url}`);
      console.log(`   地形URL: ${config.terrain?.url}`);
      console.log(
        `   角色初始位置: (${config.initial.player.position.x}, ${config.initial.player.position.y}, ${config.initial.player.position.z})`,
      );

      return config;
    } catch (error) {
      console.error('❌ 配置加载失败:', error);
      throw error;
    }
  }

  /**
   * 获取当前配置
   * @returns ProjectConfig | null
   */
  public getConfig(): ProjectConfig | null {
    return this.config;
  }

  /**
   * 获取高斯泼溅配置
   * @returns 高斯泼溅配置对象
   */
  public getGaussianSplattingConfig(): SplatConfig {
    return this.config!.gaussianSplatting;
  }

  /**
   * 获取地形配置
   * @returns 地形配置对象
   */
  public getTerrainConfig() {
    if (!this.config) {
      throw new Error('配置未加载，请先调用 loadConfig()');
    }

    const { terrain } = this.config;
    if (!terrain) return undefined;
    return {
      url: terrain.url,
      unrealConfig: {
        transform: {
          locationCM: terrain.transform.locationCM,
          rotation: terrain.transform.rotation,
          scale: terrain.transform.scale,
        },
        resolution: {
          totalVertices: terrain.resolution.totalVertices,
          componentVertices: terrain.resolution.componentVertices,
          componentSections: terrain.resolution.componentSections,
        },
      },
    };
  }

  /**
   * 获取网格模型配置
   * @returns 网格模型配置对象
   */
  public getCollisionConfig() {
    if (!this.config) {
      throw new Error('配置未加载，请先调用 loadConfig()');
    }
    return this.config.collision;
  }

  /**
   * 获取角色初始化配置
   * @returns 角色初始化配置
   */
  public getPlayerInitialConfig() {
    if (!this.config) {
      throw new Error('配置未加载，请先调用 loadConfig()');
    }

    const { player } = this.config.initial;
    return {
      position: {
        x: player.position.x,
        y: player.position.y,
        z: player.position.z,
      },
      rotation: {
        x: player.rotation.x,
        y: player.rotation.y,
        z: player.rotation.z,
      },
    };
  }

  /**
   * 获取摄像机初始化配置
   * @returns 摄像机初始化配置
   */
  public getCameraInitialConfig() {
    if (!this.config) {
      throw new Error('配置未加载，请先调用 loadConfig()');
    }

    // 摄像机位置设置已删除，将根据角色位置自动计算
    return {
      // 摄像机将自动跟随角色位置
    };
  }

  /**
   * 获取渲染器配置
   * @returns 渲染器配置
   */
  public getRendererConfig() {
    if (!this.config) {
      throw new Error('配置未加载，请先调用 loadConfig()');
    }

    return {
      scale: this.config.rendererScale,
      debugger: this.config.debugger,
      meterScale: this.config.meterScale,
    };
  }

  /**
   * 清理资源
   */
  public dispose(): void {
    this.config = null;
    console.log('⚙️ ConfigManager 资源已清理');
  }
}
