import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import * as GaussianSplats3D from '@mkkellogg/gaussian-splats-3d'; // 改为按需动态加载
import { CharacterManager } from './character-manager';
import { PhysicsWorldManager } from './physics-world-manager';
import { DebugManager } from './debug-manager';
import { CollisionManager } from './collision-manager';
import { TerrainManager } from './terrain-manager';
import { GaussianSplattingManager } from './gaussian-splatting-manager';
import { ConfigManager } from './config-manager';
import { NPCManager } from './npc-manager';
import { OrbitControlManager } from './orbit-control-manager';
import { degreesToRadians } from '../../../utils/index.ts';
import { SplatConfig, CharacterModelInfo, Transform, InteractionZone, DialogType } from '../../../types';
import { TARGET_CHARACTER_HEIGHT } from './constant';
import { StatsComponent } from './components/stats-component';
import { CapsuleManager } from './capsule-manager';

export class SceneManager {
  private stats: StatsComponent;
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera;
  private renderer: THREE.WebGLRenderer;
  private orbitControlManager: OrbitControlManager;
  private characterManager: CharacterManager | null = null;
  private clock: THREE.Clock;
  private animationId = 0;

  private keysPressed: Record<string, boolean> = {};
  private physicsWorldManager: PhysicsWorldManager;
  private debugManager: DebugManager;
  private collisionManager: CollisionManager | null = null;
  private terrainManager: TerrainManager;
  private gaussianSplattingManager: GaussianSplattingManager;
  private configManager: ConfigManager;
  private npcManager: NPCManager;

  // 人物出生变换配置（将从配置文件动态设置）
  private characterSpawnTransform: Transform = {
    position: { x: 0, y: 15, z: 0 },
    rotation: { x: 0, y: 0, z: 0 },
  };
  private characterTargetHeight = TARGET_CHARACTER_HEIGHT; // 目标角色高度
  private characterInfo?: CharacterModelInfo; // 动态角色信息
  // 交互区
  private isInitInteractionZone = false;
  private interactionZone: THREE.Mesh[] = [];
  private interactionBox: THREE.Box3[] = [];
  private modelSpotLight: THREE.SpotLight[] = [];
  private modelScene: THREE.Object3D[] = [];
  private interactionRef?: DialogType;
  private frameCount = 0;

  private firstGaussianSplatIsLoaded = false;

  constructor(
    private container: HTMLElement,
    configUrl: string,
    characterInfo?: CharacterModelInfo,
    interactionRef?: DialogType,
  ) {
    this.stats = new StatsComponent(container);
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera();
    this.renderer = new THREE.WebGLRenderer();
    this.orbitControlManager = new OrbitControlManager();
    this.clock = new THREE.Clock();
    this.physicsWorldManager = new PhysicsWorldManager();
    this.physicsWorldManager.init();
    this.debugManager = new DebugManager(this.scene);
    this.terrainManager = new TerrainManager();
    this.npcManager = new NPCManager(this.scene, this.physicsWorldManager);
    this.characterInfo = characterInfo; // 保存角色信息
    this.interactionRef = interactionRef;

    this.configManager = new ConfigManager(configUrl);

    this.gaussianSplattingManager = new GaussianSplattingManager({
      scene: this.scene,
      camera: this.camera,
      renderer: this.renderer,
      physicsWorldManager: this.physicsWorldManager,
      onProgress: (_progress: number) => {
        // console.log(`高斯点云加载进度: ${(progress * 100).toFixed(1)}%`);
      },
      onSceneLoaded: (sceneId: string) => {
        console.log(`高斯点云场景加载完成: ${sceneId}`);
      },
      onSceneDisposed: (sceneId: string) => {
        console.log(`高斯点云场景已卸载: ${sceneId}`);
      },
    });

    this.init();
  }

  public animate() {
    this.frameCount++;
    this.stats.begin();
    this.animationId = requestAnimationFrame(() => this.animate());

    const mixerUpdateDelta = this.clock.getDelta();

    // 更新物理世界
    this.physicsWorldManager.update(mixerUpdateDelta);

    // 更新debug管理器
    this.debugManager.update(mixerUpdateDelta);

    // 更新NPC管理器
    this.npcManager.update(mixerUpdateDelta);

    if (this.characterManager) {
      const isOrbitControlActive = this.orbitControlManager?.isActive?.value || false;
      this.characterManager.update(mixerUpdateDelta, this.getKeysPressed(), isOrbitControlActive);
    }
    if (this.frameCount % 2 == 0) this.gaussianSplattingManager.update();

    const orbitControls = this.orbitControlManager.getOrbitControls();
    if (orbitControls) {
      orbitControls.update();
    }
    this.renderer.render(this.scene, this.camera);

    this.stats.end();
    const character = this.characterManager?.getActiveCharacter();
    if (character) {
      // 检测玩家是否在交互区域内并更新对话框位置
      this.checkInteractionZone(character.getModel()!.position);
    }
  }

  public handleResize() {
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(window.innerWidth, window.innerHeight);
  }

  public updateJoystick(data: { x: number; y: number; distance: number; edgeRatio: number }) {
    if (this.characterManager) {
      this.characterManager.updateJoystick(data);
    }
  }

  public updateTouchDelta(delta: { x: number; y: number }) {
    if (this.characterManager) {
      this.characterManager.updateTouchDelta(delta);
    }
  }

  public updateCameraRotationSpeed(speed: number) {
    if (this.characterManager) {
      this.characterManager.updateCameraRotationSpeed(speed);
    }
  }

  public toggleRun(_isRunning: boolean) {
    if (this.characterManager) {
      this.characterManager.switchRunToggle();
    }
  }

  public setKeysPressed(keys: Record<string, boolean>) {
    this.keysPressed = keys;
  }

  public setJumpPressed(isPressed: boolean) {
    // 设置空格键状态来模拟跳跃，使用正确的键名
    this.keysPressed = { ...this.keysPressed, space: isPressed };
  }

  public getOrbitControls() {
    return this.orbitControlManager.getOrbitControls();
  }

  public getOrbitControlManager(): OrbitControlManager {
    return this.orbitControlManager;
  }

  public setOrbitControlManager(manager: OrbitControlManager) {
    this.orbitControlManager = manager;
  }

  public getCamera(): THREE.PerspectiveCamera {
    return this.camera;
  }

  public getCharacter() {
    return this.characterManager;
  }

  public getRenderer(): THREE.WebGLRenderer {
    return this.renderer;
  }

  public getPhysicsWorldManager(): PhysicsWorldManager {
    return this.physicsWorldManager;
  }

  public getDebugManager(): DebugManager {
    return this.debugManager;
  }

  public getGaussianSplattingManager(): GaussianSplattingManager {
    return this.gaussianSplattingManager;
  }

  public getConfigManager(): ConfigManager {
    return this.configManager;
  }

  public getNPCManager(): NPCManager {
    return this.npcManager;
  }

  public getCharacterSpawnTransform(): Transform {
    return { ...this.characterSpawnTransform };
  }

  public getCharacterSpawnPoint(): THREE.Vector3 {
    const pos = this.characterSpawnTransform.position!;
    return new THREE.Vector3(pos.x, pos.y, pos.z);
  }

  public getCharacterSpawnRotation(): THREE.Vector3 {
    const rot = this.characterSpawnTransform.rotation!;
    return new THREE.Vector3(rot.x, rot.y, rot.z);
  }

  /**
   * 获取当前角色信息
   */
  public getCharacterInfo(): CharacterModelInfo | null {
    return this.characterInfo || null;
  }

  /**
   * 切换角色模型
   * @param modelId 新模型的ID
   */
  public async switchCharacterModel(modelId: string): Promise<void> {
    if (!this.characterManager) {
      throw new Error('角色管理器未初始化');
    }

    try {
      console.log(`🔄 开始切换角色模型: ${modelId}`);

      // 保存当前角色状态
      const currentPosition = this.physicsWorldManager.getCharacterPosition();
      const currentKeys = { ...this.keysPressed };

      // 保存当前的动态配置
      const dynamicConfigs = this.characterManager.getDynamicModelConfigs();

      // 销毁当前角色
      this.characterManager.dispose();

      const orbitControls = this.orbitControlManager.getOrbitControls();
      if (!orbitControls) {
        throw new Error('OrbitControls 未初始化');
      }

      this.characterManager = new CharacterManager(
        this.scene,
        this.physicsWorldManager,
        new THREE.Vector3(currentPosition.x, currentPosition.y - 0.85, currentPosition.z), // 调整为模型位置
        orbitControls,
        this.camera,
        this.characterTargetHeight,
      );

      // 设置新模型的ID
      // this.characterManager.setModelId(modelId); // 移除这行，使用新的API

      // 恢复动态配置
      dynamicConfigs.forEach((config, _key) => {
        this.characterManager!.addDynamicModelConfig(config);
        this.npcManager.addDynamicModelConfig(config);
      });

      // 创建新角色（使用指定的模型ID）
      await this.characterManager.createCharacter({
        modelId,
        spawnPoint: new THREE.Vector3(currentPosition.x, currentPosition.y - 0.85, currentPosition.z),
        setAsActive: true,
      });

      // 恢复按键状态
      this.keysPressed = currentKeys;

      console.log(`✅ 角色模型切换成功: ${modelId}`);
    } catch (error) {
      console.error(`❌ 角色模型切换失败: ${modelId}`, error);
      throw error;
    }
  }

  public getCharacterTargetHeight(): number {
    return this.characterTargetHeight;
  }

  public dispose() {
    if (this.animationId) {
      cancelAnimationFrame(this.animationId);
    }

    // 清理各个管理器
    this.physicsWorldManager.dispose();
    this.debugManager.dispose();
    this.terrainManager.dispose();
    this.gaussianSplattingManager.dispose();
    this.configManager.dispose();
    this.npcManager.dispose();
    if (this.collisionManager) {
      this.collisionManager.dispose();
    }

    this.renderer.dispose();
    this.scene.clear();
  }

  private getKeysPressed(): Record<string, boolean> {
    return this.keysPressed;
  }

  private init() {
    // SCENE - 设置为黑色背景
    this.scene.background = new THREE.Color(0x000000);

    // CAMERA
    this.camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);

    // RENDERER
    this.renderer = new THREE.WebGLRenderer({ antialias: false });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(1.5);
    this.renderer.shadowMap.enabled = true;
    this.container.appendChild(this.renderer.domElement);

    // CONTROLS - 使用 OrbitControlManager 创建，并设置初始距离限制
    const capsuleManager = new CapsuleManager(this.characterTargetHeight);
    const cameraParams = capsuleManager.getCameraParams();
    this.orbitControlManager.createOrbitControls(this.camera, this.renderer.domElement, cameraParams.distance);

    // 设置 OrbitControls 的 target 为角色注视点
    const orbitControls = this.orbitControlManager.getOrbitControls();
    if (orbitControls) {
      orbitControls.update();
    }

    // LIGHTS
    this.setupLights();

    // 加载模型和场景
    this.loadScene();
  }

  private setupLights() {
    // 增强环境光 - 提高亮度和改为更自然的颜色
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);
    this.scene.add(ambientLight);

    // 主方向光 - 增强亮度
    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.2);
    directionalLight.position.set(-1, 1.75, 1);
    directionalLight.position.multiplyScalar(30);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    directionalLight.shadow.camera.left = -30;
    directionalLight.shadow.camera.right = 30;
    directionalLight.shadow.camera.top = 30;
    directionalLight.shadow.camera.bottom = -30;
    directionalLight.shadow.camera.far = 100;
    this.scene.add(directionalLight);

    // 添加补充光源 - 从另一个角度照亮角色
    const fillLight = new THREE.DirectionalLight(0xffffff, 0.6);
    fillLight.position.set(1, 1, -1);
    fillLight.position.multiplyScalar(20);
    this.scene.add(fillLight);

    // 添加背光 - 增强角色轮廓
    const backLight = new THREE.DirectionalLight(0xffffff, 0.4);
    backLight.position.set(0, 2, -1);
    backLight.position.multiplyScalar(15);
    this.scene.add(backLight);
  }

  private async loadScene() {
    try {
      console.log('🚀 开始加载所有模型和资源...');

      // 0. 加载配置文件
      await this.loadConfig();

      // 1. 设置摄像机初始位置
      this.setupInitialCamera();

      // 2. 加载高斯点云
      await this.loadGaussianSplatsStep();

      // 3. 加载场景碰撞模型
      await this.loadSceneCollision();

      // 4. 加载地形
      await this.loadTerrain();

      // 5. 加载角色模型
      await this.loadCharacter();

      // 6. 开启预加载最近的高斯点云, 需要在人物出现之后再开启
      this.gaussianSplattingManager.setEnablePreloadNearest(true);

      // 7. 设置弹簧臂碰撞
      this.setupSpringArmCollision();

      const config = this.configManager.getConfig();
      if (!this.isInitInteractionZone && config?.interactionZones?.length) {
        // 添加交互区域
        this.addInteractionZone(config.interactionZones);
      }
      console.log('✅ 所有模型和资源加载完成！');
    } catch (error) {
      console.error('❌ 模型加载失败:', error);
    }
  }

  /**
   * 步骤0: 加载配置文件并初始化相关设置
   */
  private async loadConfig(): Promise<void> {
    console.log('⚙️ 第0步: 加载项目配置...');
    await this.configManager.loadConfig();

    // 更新角色出生变换（位置和旋转）
    const playerConfig = this.configManager.getPlayerInitialConfig();
    this.characterSpawnTransform = {
      position: { x: playerConfig.position.x, y: playerConfig.position.y, z: playerConfig.position.z },
      rotation: { x: playerConfig.rotation.x, y: playerConfig.rotation.y, z: playerConfig.rotation.z },
    };
    console.log(
      `🎮 角色出生变换已更新: 位置(${this.characterSpawnTransform.position!.x}, ${this.characterSpawnTransform.position!.y}, ${this.characterSpawnTransform.position!.z}), 旋转(${this.characterSpawnTransform.rotation!.x}, ${this.characterSpawnTransform.rotation!.y}, ${this.characterSpawnTransform.rotation!.z})`,
    );

    // 更新渲染器设置
    const rendererConfig = this.configManager.getRendererConfig();
    this.renderer.setPixelRatio(rendererConfig.scale);
    console.log(`🖥️ 渲染器缩放已设置: ${rendererConfig.scale}`);

    // 等待物理世界初始化
    await this.physicsWorldManager.waitForInitialization();

    // 设置物理世界到debug管理器
    this.debugManager.setPhysicsWorldManager(this.physicsWorldManager);
  }

  /**
   * 步骤1: 根据角色出生点设置摄像机初始位置
   * 使用与 CharacterCameraManager.updateCameraTarget 相同的计算逻辑
   */
  private setupInitialCamera(): void {
    console.log('📷 第1步: 设置摄像机初始位置...');

    // 根据角色高度计算正确的摄像机参数
    const capsuleManager = new CapsuleManager(this.characterTargetHeight);
    const cameraParams = capsuleManager.getCameraParams();

    const spawnPos = this.characterSpawnTransform.position!;
    const spawnRot = this.characterSpawnTransform.rotation!;

    // 使用角色初始旋转的 Y 轴作为 cameraYaw
    // 旋转值通常是角度，需要转换为弧度
    const cameraYaw = THREE.MathUtils.degToRad(spawnRot.y);

    // 使用与 CharacterCameraManager.updateCameraTarget 相同的计算逻辑
    const initialCameraPosition = new THREE.Vector3(
      spawnPos.x - Math.sin(cameraYaw) * cameraParams.distance,
      spawnPos.y + cameraParams.height,
      spawnPos.z - Math.cos(cameraYaw) * cameraParams.distance,
    );

    this.camera.position.copy(initialCameraPosition);
    console.log(
      `📷 摄像机位置已更新: (${this.camera.position.x.toFixed(2)}, ${this.camera.position.y.toFixed(2)}, ${this.camera.position.z.toFixed(2)})`,
    );
    console.log(
      `📷 摄像机参数: height=${cameraParams.height}, distance=${cameraParams.distance}, lookAtOffset=${cameraParams.lookAtOffset}, yaw=${cameraYaw.toFixed(2)}rad`,
    );

    // 更新 OrbitControls 的 target 为角色注视点
    const lookAtTarget = new THREE.Vector3(spawnPos.x, spawnPos.y + cameraParams.lookAtOffset, spawnPos.z);
    const orbitControls = this.orbitControlManager.getOrbitControls();
    if (orbitControls) {
      orbitControls.target.copy(lookAtTarget);
      orbitControls.update();
    }
  }

  /**
   * 步骤2: 加载高斯点云, 在
   */
  private async loadGaussianSplatsStep(): Promise<void> {
    return new Promise(async (resolve) => {
      console.log('✨ 第2步: 加载高斯点云...');
      this.loadGaussianSplats({
        // onScenesProgress: (sceneUrl, progress) => {
        //   console.log(`📦 高斯点云加载进度: ${sceneUrl} - ${Math.round(progress * 100)}%`);
        // },
        onFirstSceneProgress: (sceneUrl, progress) => {
          if (progress >= 0.5 && !this.firstGaussianSplatIsLoaded) {
            this.firstGaussianSplatIsLoaded = true;
            resolve();
          }
        },
      });
    });
  }

  /**
   * 步骤3: 加载场景碰撞模型
   */
  private async loadSceneCollision(): Promise<void> {
    console.log('📦 第3步: 加载场景碰撞模型...');
    this.collisionManager = new CollisionManager(this.scene, this.physicsWorldManager);

    const collisionConfig = this.configManager.getCollisionConfig();
    if (collisionConfig) {
      await this.collisionManager.loadSceneCollisionFromUrl(collisionConfig);
    }
  }

  /**
   * 步骤4: 加载地形
   */
  private async loadTerrain(): Promise<void> {
    console.log('🏔️ 第4步: 加载地形...');
    const rendererConfig = this.configManager.getRendererConfig();
    const terrainConfig = this.configManager.getTerrainConfig();
    const collisionConfig = this.configManager.getCollisionConfig();

    if (terrainConfig) {
      const terrainPhysics = await this.physicsWorldManager.loadTerrain(terrainConfig.url, terrainConfig.unrealConfig, {
        friction: 0.8,
        restitution: 0.1,
        debug: rendererConfig.debugger,
      });

      // 自动启用地形碰撞可视化（如果启用调试模式）
      if (terrainPhysics && rendererConfig.debugger) {
        console.log('🎨 自动启用地形碰撞可视化...');
        this.debugManager.setTerrainVisualization(true);
      }
    } else if (!collisionConfig) {
      // 如果没有地形配置，也没有场景碰撞配置，创建默认平面地形
      console.log('🏔️ 未找到地形配置，也没配置场景碰撞，创建默认平面地形...');
      await this.physicsWorldManager.loadDefaultTerrain(this.scene, { debug: rendererConfig.debugger });

      if (rendererConfig.debugger) {
        console.log('🎨 自动启用默认地形碰撞可视化...');
        this.debugManager.setTerrainVisualization(true);
      }
    }
  }

  /**
   * 步骤5: 加载角色模型
   */
  private async loadCharacter(): Promise<void> {
    console.log('🎮 第5步: 加载角色模型...');

    const orbitControls = this.orbitControlManager.getOrbitControls();
    if (!orbitControls) {
      throw new Error('OrbitControls 未初始化');
    }

    // 确定角色出生变换：优先使用 characterInfo 中的变换，否则使用 configManager 解析的 player 变换
    let spawnTransform: Transform;
    if (this.characterInfo?.transform) {
      spawnTransform = {
        position: this.characterInfo.transform.position || this.characterSpawnTransform.position,
        rotation: this.characterInfo.transform.rotation || this.characterSpawnTransform.rotation,
      };
      console.log(
        `🎮 使用 characterInfo 中的变换: 位置(${spawnTransform.position!.x}, ${spawnTransform.position!.y}, ${spawnTransform.position!.z}), 旋转(${spawnTransform.rotation!.x}, ${spawnTransform.rotation!.y}, ${spawnTransform.rotation!.z})`,
      );
    } else {
      spawnTransform = this.characterSpawnTransform;
      console.log(
        `🎮 使用配置文件中的变换: 位置(${spawnTransform.position!.x}, ${spawnTransform.position!.y}, ${spawnTransform.position!.z}), 旋转(${spawnTransform.rotation!.x}, ${spawnTransform.rotation!.y}, ${spawnTransform.rotation!.z})`,
      );
    }

    const spawnPoint = new THREE.Vector3(
      spawnTransform.position!.x,
      spawnTransform.position!.y,
      spawnTransform.position!.z,
    );

    this.characterManager = new CharacterManager(
      this.scene,
      this.physicsWorldManager,
      spawnPoint,
      orbitControls,
      this.camera,
      this.characterTargetHeight,
    );

    // 如果有动态角色信息，使用它；否则使用默认模型
    if (this.characterInfo) {
      console.log('🎭 使用动态角色信息加载模型:', this.characterInfo.name);
      await this.loadDynamicCharacter(this.characterInfo);
    } else {
      console.log('🎭 使用默认角色模型');
      await this.characterManager.init();
    }

    // 应用角色初始旋转
    const activeCharacter = this.characterManager.getActiveCharacter();
    if (activeCharacter?.getModel()) {
      const spawnRot = spawnTransform.rotation!;

      // 角色系统主要使用 Y 轴旋转来控制朝向
      // 配置中的 Y 轴旋转值是角度，需要转换为弧度
      const yawRadians = THREE.MathUtils.degToRad(spawnRot.y);

      // 使用角色系统的旋转轴 (0, 1, 0) 创建旋转四元数
      const rotateAxis = new THREE.Vector3(0, 1, 0);
      const targetQuaternion = new THREE.Quaternion().setFromAxisAngle(rotateAxis, yawRadians);

      // 获取当前四元数并应用旋转
      const currentQuaternion = activeCharacter.getModel()!.quaternion.clone();
      const finalQuaternion = currentQuaternion.multiply(targetQuaternion);

      // 直接设置最终的四元数
      activeCharacter.getModel()!.quaternion.copy(finalQuaternion);

      console.log(`🎮 角色初始旋转已应用: Y轴旋转 ${spawnRot.y}° (${yawRadians.toFixed(3)} 弧度)`);
    }
  }

  /**
   * 步骤5: 设置弹簧臂碰撞对象
   */
  private async loadDynamicCharacter(characterInfo: CharacterModelInfo): Promise<void> {
    if (!this.characterManager) {
      throw new Error('角色管理器未初始化');
    }

    try {
      console.log(`🎭 开始加载动态角色: ${characterInfo.name}`);
      console.log(`📦 模型URL: ${characterInfo.modelFilePath}`);

      // 从URL提取文件名
      const modelUrl = characterInfo.modelFilePath;
      const fileName = modelUrl.split('/').pop() || 'dynamic_model.glb';
      const dynamicModelId = `dynamic_${characterInfo.name}`;

      console.log(`📁 提取的文件名: ${fileName}, 动态模型ID: ${dynamicModelId}`);

      // 设置模型ID（动态模型）
      // this.characterManager.setModelId(dynamicModelId); // 移除这行，新的API不需要

      // 创建动态模型配置
      const dynamicModelConfig: CharacterModelInfo = {
        describe: '自定义角色',
        imagePath: '',
        modelTexture: characterInfo.modelTexture,
        id: dynamicModelId,
        name: characterInfo.name,
        modelFilePath: modelUrl, // 添加这个字段以保持一致性
        transform: characterInfo.transform || {
          position: { x: 0, y: 0, z: 0 },
          rotation: { x: 0, y: 0, z: 0 },
        },
        anim: characterInfo.anim,
        targetHeight: characterInfo.targetHeight,
      };

      // 将动态配置添加到角色管理器和NPC管理器
      this.characterManager.addDynamicModelConfig(dynamicModelConfig);
      this.npcManager.addDynamicModelConfig(dynamicModelConfig);

      // 创建角色（使用动态模型ID）
      await this.characterManager.createCharacter({
        modelId: dynamicModelId,
        setAsActive: true,
      });

      console.log(`✅ 动态角色加载成功: ${characterInfo.name}`);
    } catch (error) {
      console.error('❌ 动态角色加载失败:', error);
      throw error;
    }
  }

  /**
   * 加载高斯点云场景（使用配置文件中的参数）
   * @param options 加载选项
   * @param options.onScenesProgress 每个场景加载进度回调
   * @param options.onFirstSceneProgress 第一个场景加载进度回调
   */
  private async loadGaussianSplats(options?: {
    onScenesProgress?: (sceneUrl: string, progress: number) => void;
    onFirstSceneProgress?: (sceneUrl: string, progress: number) => void;
  }): Promise<void> {
    try {
      // 从配置管理器获取高斯泼溅配置
      const splatConfig = this.configManager.getGaussianSplattingConfig();
      if (!splatConfig) return Promise.resolve();

      const spawnPos = this.characterSpawnTransform.position!;
      const startPoint = new THREE.Vector3(spawnPos.x, spawnPos.y, spawnPos.z);

      const splatSceneConfig: { id: string; config: SplatConfig } = {
        id: 'main-scene',
        config: {
          ...splatConfig,
          startPoint,
          onFirstSceneProgress: options?.onFirstSceneProgress,
          onScenesProgress: options?.onScenesProgress,
        },
      };

      console.log(`🌟 开始加载高斯点云场景: ${splatSceneConfig.id}`);
      console.log(`📐 位置: [${splatConfig.transform.position?.join(', ')}]`);
      console.log(`🔄 旋转: [${splatConfig.transform.rotation?.join(', ')}]`);
      console.log(`📏 缩放: [${splatConfig.transform.scale?.join(', ')}]`);
      await this.gaussianSplattingManager.loadSplatScene(splatSceneConfig.id, splatSceneConfig.config);
      console.log(`✅ 高斯点云场景加载成功: ${splatSceneConfig.id}`);
      console.log('✨ 高斯点云加载完成');
    } catch (error) {
      console.error('❌ 高斯点云加载失败:', error);
      // 高斯点云加载失败不应该影响其他功能
    }
  }
  // 添加交互区域
  private addInteractionZone(options: InteractionZone[]): void {
    this.isInitInteractionZone = true;
    options.forEach((item) => {
      const geometry = new THREE.BoxGeometry(...item.geometry);
      const material = new THREE.MeshBasicMaterial({
        color: 0x00ffff,
        transparent: true,
        opacity: 0.0, // 完全透明
        visible: false, // 不可见
      });
      const zone = new THREE.Mesh(geometry, material);
      zone.position.set(...(item.geometryPos as [number, number, number]));
      this.interactionZone.push(zone);
      const box = new THREE.Box3().setFromObject(zone);
      this.interactionBox.push(box);
      this.scene.add(zone);
      this.addModel(
        new THREE.Vector3(
          Number(item.geometryPos[0]) + item.modelPos[0],
          Number(item.geometryPos[1]) + item.modelPos[1],
          Number(item.geometryPos[2]) + item.modelPos[2],
        ),
        item.model,
        item.scale || [1, 1, 1],
        degreesToRadians(item.rotation || [0, 0, 0]),
      );
    });
  }
  // 添加模型
  private addModel(position: THREE.Vector3, name: string, scale: number[], rotationArr: number[]): void {
    const loader = new GLTFLoader();
    loader.setPath('./models/aigc/');
    // 先加载模型
    loader.load(
      name,
      (gltf) => {
        const gltfScene = gltf.scene || gltf.scenes[0];
        gltfScene.position.copy(position);
        gltfScene.rotation.y = rotationArr[1]; // 让模型面向玩家
        gltf.scene.scale.set(...(scale as [number, number, number]));
        this.modelScene!.push(gltfScene);
        // 添加到场景
        this.scene.add(gltfScene);
        // 创建聚光灯，只照射指定的glb模型
        const spotLight = new THREE.SpotLight(0xffffcc, 3);
        const lightPositionFront = new THREE.Vector3(
          position.x,
          position.y + 0.5, // 稍微提高光源位置
          position.z + (rotationArr[1] === 0 ? 1 : -1),
        );
        spotLight.position.copy(lightPositionFront);
        // 设置聚光灯目标为模型位置
        spotLight.target.position.copy(position);
        // 设置聚光灯参数
        spotLight.angle = Math.PI / 3; // 30度角，形成较窄的光锥
        spotLight.penumbra = 1; // 边缘柔和度
        spotLight.decay = 1; // 光线衰减
        spotLight.distance = 3; // 光照距离限制，只照射模型附近
        this.scene.add(spotLight);
        this.scene.add(spotLight.target);
        // 存储聚光灯引用
        this.modelSpotLight.push(spotLight);
      },
      undefined,
      (error) => {
        console.error('Error loading model:', error);
      },
    );
  }
  // 检测玩家是否在交互区域内
  private checkInteractionZone(playerPosition: THREE.Vector3): void {
    const config = this.configManager.getConfig();
    if (!this.interactionZone.length || !this.interactionBox?.length || !config) return;
    // 创建一个点来表示玩家位置
    const playerPoint = new THREE.Vector3(playerPosition.x, playerPosition.y, playerPosition.z);
    // 检查玩家是否在交互区域内
    let isInZone = false;
    let text = '';
    let query = '';
    let buttonText = '';
    this.interactionBox.forEach((box, index) => {
      if (box.containsPoint(playerPoint)) {
        text = config.interactionZones?.[index]?.dialog || '';
        query = config.interactionZones?.[index]?.query || '';
        buttonText = config.interactionZones?.[index]?.buttonText || '';
        isInZone = true;
      }
    });
    if (this.interactionRef) {
      this.interactionRef.initIeration(isInZone, text, query, buttonText);
    }
  }

  /**
   * 设置弹簧臂碰撞对象
   * 使用 Rapier 物理世界进行碰撞检测（与角色使用相同的碰撞体）
   */
  private setupSpringArmCollision(): void {
    if (!this.characterManager) {
      console.warn('⚠️ 角色管理器未初始化，跳过弹簧臂碰撞设置');
      return;
    }

    const activeCharacter = this.characterManager.getActiveCharacter();
    if (!activeCharacter) {
      console.warn('⚠️ 没有活跃角色，跳过弹簧臂碰撞设置');
      return;
    }

    // 获取 Rapier 物理世界
    const rapierWorld = this.physicsWorldManager.getWorld();
    console.log('🔍 检查 Rapier 物理世界:', rapierWorld ? '已初始化' : '未初始化');

    if (rapierWorld) {
      // 设置弹簧臂使用 Rapier 物理世界
      this.characterManager.setSpringArmRapierWorld(rapierWorld);
      console.log('✅ 弹簧臂已连接到 Rapier 物理世界（使用与角色相同的碰撞体）');

      // 设置角色碰撞体（用于排除自身碰撞）
      const characterCollider = this.physicsWorldManager.getCharacterCollider();
      console.log('🔍 检查角色碰撞体:', characterCollider ? '已创建' : '未创建');
      if (characterCollider) {
        this.characterManager.setSpringArmCharacterCollider(characterCollider);
        console.log('✅ 弹簧臂已设置排除角色碰撞体');
      }
    } else {
      console.warn('⚠️ Rapier 物理世界未初始化，弹簧臂将使用 THREE.js 碰撞检测');
      // 备用方案：使用 THREE.js 碰撞检测
      this.setupSpringArmCollisionFallback();
    }
  }

  /**
   * 备用方案：使用 THREE.js 碰撞检测
   */
  private setupSpringArmCollisionFallback(): void {
    if (!this.characterManager) return;

    const collisionObjects: THREE.Object3D[] = [];

    // 从碰撞管理器获取碰撞网格
    if (this.collisionManager) {
      const collisionMeshes = this.collisionManager.getCollisionMeshes();
      console.log(`🔍 碰撞管理器网格数量: ${collisionMeshes?.length ?? 0}`);
      if (collisionMeshes && collisionMeshes.length > 0) {
        collisionObjects.push(...collisionMeshes);
        console.log(`🎯 添加碰撞管理器网格: ${collisionMeshes.length} 个`);
      }
    }

    // 从物理世界管理器获取地形网格
    const terrainMesh = this.physicsWorldManager.getTerrainMesh();
    if (terrainMesh) {
      collisionObjects.push(terrainMesh);
      console.log('🎯 添加地形网格');
    }

    // 遍历场景收集所有 Mesh
    this.scene.traverse((object) => {
      if (object.userData.isCharacter || object.userData.isHelper) return;
      if (object instanceof THREE.Mesh && object.geometry) {
        if (!collisionObjects.includes(object)) {
          collisionObjects.push(object);
        }
      }
    });

    if (collisionObjects.length > 0) {
      this.characterManager.setSpringArmCollisionObjects(collisionObjects);
      console.log(`✅ 弹簧臂碰撞对象设置完成（THREE.js）: ${collisionObjects.length} 个`);
    }
  }

  /**
   * 手动添加弹簧臂碰撞对象
   */
  public addSpringArmCollisionObject(object: THREE.Object3D): void {
    if (this.characterManager) {
      this.characterManager.addSpringArmCollisionObject(object);
    }
  }

  /**
   * 移除弹簧臂碰撞对象
   */
  public removeSpringArmCollisionObject(object: THREE.Object3D): void {
    if (this.characterManager) {
      this.characterManager.removeSpringArmCollisionObject(object);
    }
  }

  /**
   * 启用/禁用弹簧臂
   */
  public setSpringArmEnabled(enabled: boolean): void {
    if (this.characterManager) {
      this.characterManager.setSpringArmEnabled(enabled);
    }
  }

  /**
   * 获取弹簧臂是否启用
   */
  public isSpringArmEnabled(): boolean {
    return this.characterManager?.isSpringArmEnabled() ?? false;
  }
}
