import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import RAPIER from '@dimforge/rapier3d-compat';
import { CapsuleManager, CameraParams } from './capsule-manager';
import { SpringArmManager, SpringArmConfig } from './spring-arm-manager';

/**
 * 摄像机跟随模式
 */
export enum CameraFollowMode {
  ThirdPerson = 'third-person', // 第三人称视角
  Orbit = 'orbit', // 轨道控制视角
}

/**
 * 角色摄像机管理器
 * 负责管理角色的摄像机跟随、旋转、距离调整等逻辑
 * 集成弹簧臂功能，支持碰撞检测和自动收缩
 */
export class CharacterCameraManager {
  // 摄像机引用
  private camera: THREE.Camera;
  private orbitControl: OrbitControls;

  // 弹簧臂管理器
  private springArmManager: SpringArmManager;
  private springArmEnabled = true;

  // 摄像机参数
  private cameraTarget = new THREE.Vector3();
  private cameraYaw = 0;
  private cameraRotationSpeed = 0.003;
  private cameraDistance = 3.0;
  private targetCameraDistance = 3.0;
  private cameraDistanceTransitionSpeed = 2.0;
  private forwardCameraDistance = 4.0;
  private backwardCameraDistance = 8.0;
  private cameraHeight = 2.8;
  private cameraLookAtOffset = 2.0;

  // 旋转控制参数
  private keyboardCameraRotationSpeed = 2.0;
  private currentCameraRotationSpeed = 0;
  private cameraRotationAcceleration = 8.0;
  private cameraRotationDeceleration = 6.0;
  private cameraRotationDirection = 0;

  // 触摸旋转参数
  private touchRotationVelocity = 0;
  private touchRotationDeceleration = 5.0;
  private lastTouchDeltaTime = 0;

  // 移动端检测
  private isMobile = false;

  // 临时向量（避免频繁创建）
  private tempDirection = new THREE.Vector3();
  private tempOrigin = new THREE.Vector3();

  constructor(camera: THREE.Camera, orbitControl: OrbitControls, capsuleManager: CapsuleManager, isMobile = false) {
    this.camera = camera;
    this.orbitControl = orbitControl;
    this.isMobile = isMobile;

    // 从胶囊体管理器获取摄像头参数
    const cameraParams = capsuleManager.getCameraParams();
    this.initializeCameraParams(cameraParams);

    // 初始化弹簧臂管理器
    this.springArmManager = new SpringArmManager({
      targetArmLength: this.cameraDistance,
      minArmLength: 0.5,
      probeRadius: 0.3,
      enableCollision: true,
      enableCameraLag: false, // 摄像机滞后由原有逻辑处理
      cameraLagSpeed: 10.0,
      collisionRecoverySpeed: 3.0,
      collisionShrinkSpeed: 15.0,
    });

    console.log('🎯 SpringArmManager 已集成到 CharacterCameraManager');
  }

  /**
   * 初始化摄像头参数
   */
  private initializeCameraParams(cameraParams: CameraParams): void {
    this.cameraHeight = cameraParams.height;
    this.cameraDistance = cameraParams.distance;
    this.targetCameraDistance = cameraParams.distance;
    this.forwardCameraDistance = cameraParams.forwardDistance;
    this.backwardCameraDistance = cameraParams.backwardDistance;
    this.cameraLookAtOffset = cameraParams.lookAtOffset;

    console.log('📷 CharacterCameraManager 初始化:', {
      cameraHeight: this.cameraHeight,
      cameraDistance: this.cameraDistance,
      forwardDistance: this.forwardCameraDistance,
      backwardDistance: this.backwardCameraDistance,
      lookAtOffset: this.cameraLookAtOffset,
    });
  }

  /**
   * 更新摄像机旋转速度
   */
  public updateCameraRotationSpeed(speed: number): void {
    this.cameraRotationSpeed = speed;
  }

  /**
   * 获取摄像机偏航角
   */
  public getCameraYaw(): number {
    return this.cameraYaw;
  }

  /**
   * 设置摄像机偏航角
   */
  public setCameraYaw(yaw: number): void {
    this.cameraYaw = yaw;
  }

  /**
   * 更新摄像机旋转
   */
  public updateCameraRotation(
    delta: number,
    touchDelta: { x: number; y: number } | undefined,
    keysPressed: Record<string, boolean>,
    isOrbitControlActive: boolean,
  ): void {
    // 处理触摸旋转
    this.processTouchRotation(delta, touchDelta, isOrbitControlActive);

    // 处理键盘旋转
    this.processKeyboardRotation(delta, keysPressed, isOrbitControlActive);
  }

  /**
   * 处理触摸旋转和减速动画
   */
  private processTouchRotation(
    delta: number,
    touchDelta: { x: number; y: number } | undefined,
    shouldIgnore: boolean,
  ): void {
    const currentTime = performance.now();
    const timeSinceLastTouch = currentTime - this.lastTouchDeltaTime;
    const hasRecentTouchInput = touchDelta && (Math.abs(touchDelta.x) > 0 || Math.abs(touchDelta.y) > 0);

    if (hasRecentTouchInput && !shouldIgnore) {
      // 有触摸输入时，计算速度并更新时间
      this.touchRotationVelocity = (touchDelta.x * this.cameraRotationSpeed) / delta;
      this.lastTouchDeltaTime = currentTime;
      // 应用触摸旋转
      this.cameraYaw -= touchDelta.x * this.cameraRotationSpeed;
    } else if (timeSinceLastTouch < 1000 && Math.abs(this.touchRotationVelocity) > 0.1 && !this.isMobile) {
      // 触摸结束后的减速动画（1秒内有效）
      const decelerationAmount = this.touchRotationDeceleration * delta;
      const velocityDirection = Math.sign(this.touchRotationVelocity);

      // 减少速度
      this.touchRotationVelocity -= velocityDirection * decelerationAmount;

      // 检查是否需要停止（速度方向改变表示已减速到0）
      if (Math.sign(this.touchRotationVelocity) !== velocityDirection || Math.abs(this.touchRotationVelocity) < 0.1) {
        this.touchRotationVelocity = 0;
      } else {
        // 应用减速旋转
        this.cameraYaw -= this.touchRotationVelocity * delta;
      }
    } else {
      // 重置触摸旋转速度
      this.touchRotationVelocity = 0;
    }
  }

  /**
   * 处理键盘旋转（A/D键和Q/E键）
   */
  private processKeyboardRotation(
    delta: number,
    keysPressed: Record<string, boolean>,
    isOrbitControlActive: boolean,
  ): void {
    const A = 'keya';
    const D = 'keyd';
    const Q = 'keyq';
    const E = 'keye';
    const S = 'keys';

    if (isOrbitControlActive) {
      // OrbitControls 激活时，只处理双手模式下的Q/E键
      this.processQERotation(delta, keysPressed, Q, E);
      return;
    }

    // OrbitControls 未激活时：A/D 键用于摄像机旋转
    const isRotating = keysPressed[A] || keysPressed[D];
    this.processRotation(delta, isRotating, keysPressed[A], keysPressed[D], keysPressed[S], false);
  }

  /**
   * 处理Q/E键旋转（双手模式下）
   */
  private processQERotation(delta: number, keysPressed: Record<string, boolean>, Q: string, E: string): void {
    const isQPressed = keysPressed[Q] === true;
    const isEPressed = keysPressed[E] === true;
    const isQERotating = isQPressed || isEPressed;
    this.processRotation(delta, isQERotating, isQPressed, isEPressed, false, true);
  }

  /**
   * 通用旋转处理逻辑
   */
  private processRotation(
    delta: number,
    isRotating: boolean,
    leftKey: boolean,
    rightKey: boolean,
    backKey: boolean,
    isOrbitMode: boolean,
  ): void {
    if (isRotating) {
      // 确定旋转方向
      let newDirection = 0;
      if (leftKey && !rightKey) {
        newDirection = backKey ? -1 : 1; // S+A 反转为向右
      } else if (rightKey && !leftKey) {
        newDirection = backKey ? 1 : -1; // S+D 反转为向左
      }

      // 如果方向改变，需要重新加速
      if (newDirection !== this.cameraRotationDirection) {
        this.currentCameraRotationSpeed = 0;
        this.cameraRotationDirection = newDirection;
      }

      // 加速到目标速度
      if (this.currentCameraRotationSpeed < this.keyboardCameraRotationSpeed) {
        this.currentCameraRotationSpeed += this.cameraRotationAcceleration * delta;
        this.currentCameraRotationSpeed = Math.min(this.currentCameraRotationSpeed, this.keyboardCameraRotationSpeed);
      }

      // 应用旋转
      this.cameraYaw += this.currentCameraRotationSpeed * delta * this.cameraRotationDirection;
    } else {
      // 没有旋转输入时，减速到0
      if (this.currentCameraRotationSpeed > 0) {
        this.currentCameraRotationSpeed -= this.cameraRotationDeceleration * delta;
        this.currentCameraRotationSpeed = Math.max(0, this.currentCameraRotationSpeed);

        // 继续应用减速旋转
        if (this.currentCameraRotationSpeed > 0) {
          this.cameraYaw += this.currentCameraRotationSpeed * delta * this.cameraRotationDirection;
        } else {
          this.cameraRotationDirection = 0;
        }
      }
    }
  }

  /**
   * 调整目标摄像机距离（根据前进/后退输入）
   */
  public adjustTargetCameraDistance(forwardInput: number): void {
    // 根据前进/后退输入调整目标距离
    if (forwardInput > 0) {
      // 向前移动时，摄像机拉近
      this.targetCameraDistance = this.forwardCameraDistance;
    } else if (forwardInput < 0) {
      // 向后移动时，摄像机拉远
      this.targetCameraDistance = this.backwardCameraDistance;
    }
  }

  /**
   * 保存当前摄像机的高度和距离
   */
  public saveCameraPosition(characterPosition: THREE.Vector3): void {
    const offset = new THREE.Vector3();
    offset.subVectors(this.camera.position, characterPosition);

    // 保存水平距离和高度
    this.cameraHeight = offset.y;
    this.cameraDistance = Math.sqrt(offset.x * offset.x + offset.z * offset.z);
    this.targetCameraDistance = this.cameraDistance; // 同步目标距离
  }

  /**
   * 处理摄像机跟随逻辑
   */
  public handleCameraFollowing(
    characterPosition: THREE.Vector3,
    actualMove: { x: number; y: number; z: number },
    _hasInput: boolean,
    isOrbitControlActive: boolean,
    delta?: number,
  ): void {
    if (!isOrbitControlActive) {
      // 第三人称摄像机模式
      this.updateCameraTarget(characterPosition, delta);
    } else {
      // OrbitControls 激活时，摄像机跟随角色移动
      this.camera.position.x += actualMove.x;
      this.camera.position.y += actualMove.y;
      this.camera.position.z += actualMove.z;
      this.cameraTarget.set(characterPosition.x, characterPosition.y + this.cameraLookAtOffset, characterPosition.z);
      this.orbitControl.target = this.cameraTarget;

      // OrbitControls 模式下也进行弹簧臂碰撞检测
      this.applySpringArmCollision(characterPosition, delta);
    }
  }

  /**
   * 应用弹簧臂碰撞检测（在 OrbitControls 模式下使用）
   * 检测当前摄像机位置是否有碰撞，如果有则调整位置
   */
  private applySpringArmCollision(characterPosition: THREE.Vector3, delta = 0.016): void {
    if (!this.springArmEnabled) return;

    // 弹簧臂起点：角色注视点位置
    this.tempOrigin.set(characterPosition.x, characterPosition.y + this.cameraLookAtOffset, characterPosition.z);

    // 弹簧臂方向：从注视点指向当前摄像机位置
    this.tempDirection.copy(this.camera.position).sub(this.tempOrigin).normalize();

    // 当前摄像机到注视点的距离
    const currentDistance = this.tempOrigin.distanceTo(this.camera.position);
    this.springArmManager.setTargetArmLength(currentDistance);

    // 使用弹簧臂计算碰撞后的位置
    const collisionAdjustedPosition = this.springArmManager.update(this.tempOrigin, this.tempDirection, delta);

    // 如果发生了碰撞（位置被调整），更新摄像机位置
    const adjustedDistance = this.tempOrigin.distanceTo(collisionAdjustedPosition);
    if (adjustedDistance < currentDistance - 0.01) {
      this.camera.position.copy(collisionAdjustedPosition);
      this.orbitControl.update();
    }
  }

  /**
   * 更新摄像机目标（第三人称视角）
   * 集成弹簧臂碰撞检测
   */
  private updateCameraTarget(characterPosition: THREE.Vector3, delta = 0.016): void {
    // 调试日志
    console.log('📸 updateCameraTarget 被调用, springArmEnabled:', this.springArmEnabled);

    // 平滑过渡摄像机距离
    const distanceDiff = this.targetCameraDistance - this.cameraDistance;
    if (Math.abs(distanceDiff) > 0.01) {
      this.cameraDistance += distanceDiff * this.cameraDistanceTransitionSpeed * delta;
    } else {
      this.cameraDistance = this.targetCameraDistance;
    }

    // 计算理想的摄像机位置（无碰撞时）
    const idealCameraOffset = new THREE.Vector3(
      -Math.sin(this.cameraYaw) * this.cameraDistance,
      this.cameraHeight,
      -Math.cos(this.cameraYaw) * this.cameraDistance,
    );
    const idealCameraPosition = characterPosition.clone().add(idealCameraOffset);

    // 弹簧臂起点：角色注视点位置（头部）
    this.tempOrigin.set(characterPosition.x, characterPosition.y + this.cameraLookAtOffset, characterPosition.z);

    // 弹簧臂方向：从注视点指向理想摄像机位置
    this.tempDirection.copy(idealCameraPosition).sub(this.tempOrigin).normalize();

    // 计算弹簧臂目标长度（从注视点到理想摄像机位置的距离）
    const targetArmLength = this.tempOrigin.distanceTo(idealCameraPosition);
    this.springArmManager.setTargetArmLength(targetArmLength);

    let finalCameraPosition: THREE.Vector3;

    if (this.springArmEnabled) {
      // 使用弹簧臂计算摄像机位置（带碰撞检测）
      finalCameraPosition = this.springArmManager.update(this.tempOrigin, this.tempDirection, delta);
    } else {
      // 不使用弹簧臂，直接使用理想位置
      finalCameraPosition = idealCameraPosition;
    }

    // 设置摄像机位置
    this.camera.position.copy(finalCameraPosition);

    // 摄像机注视角色位置
    this.cameraTarget.set(characterPosition.x, characterPosition.y + this.cameraLookAtOffset, characterPosition.z);

    this.orbitControl.target = this.cameraTarget;
    this.orbitControl.update();
  }

  /**
   * 调整摄像机距离以支持更大角度向上看（OrbitControls模式）
   */
  public adjustCameraDistance(): void {
    if (!this.orbitControl) return;

    // 获取当前摄像机的极角（垂直角度）
    const currentDistance = this.orbitControl.getDistance();

    // 计算基于极角的目标距离
    const polarAngle = this.orbitControl.getPolarAngle();
    const { maxPolarAngle } = this.orbitControl;

    // 当接近最大极角时，增加最小距离
    if (polarAngle > maxPolarAngle * 0.8) {
      const targetDistance = currentDistance * 1.2;

      // 平滑调整OrbitControls的距离限制
      const direction = new THREE.Vector3();
      direction.subVectors(this.camera.position, this.orbitControl.target).normalize();

      // 更新摄像机位置
      this.camera.position.copy(this.orbitControl.target).add(direction.multiplyScalar(targetDistance));

      // 调整距离限制
      if (this.orbitControl.minDistance) {
        this.orbitControl.minDistance = Math.min(targetDistance, this.orbitControl.minDistance || 1);
      }
      if (this.orbitControl.maxDistance) {
        this.orbitControl.maxDistance = targetDistance;
      } else {
        this.orbitControl.maxDistance = targetDistance;
      }

      this.orbitControl.update();
    } else {
      // 恢复到正常距离
      if (currentDistance > this.cameraDistance * 1.1) {
        const newDistance = currentDistance * 0.95;
        const direction = new THREE.Vector3();
        direction.subVectors(this.camera.position, this.orbitControl.target).normalize();

        // 更新摄像机位置
        this.camera.position.copy(this.orbitControl.target).add(direction.multiplyScalar(newDistance));
        this.orbitControl.update();
      }
    }
  }

  /**
   * 计算移动速度因子（基于摄像机旋转速度和屏幕方向）
   */
  public calculateMovementSpeedFactor(hasJoystickInput: boolean): number {
    // 检查是否为移动端触摸输入
    const isMobileTouch = hasJoystickInput && window.innerWidth <= 768;

    if (!isMobileTouch) {
      return 1.0; // PC端或非触摸输入，不调整速度
    }

    // 检测屏幕方向
    const isPortrait = window.innerHeight > window.innerWidth;

    // 根据屏幕方向设置基础速度因子
    let baseSpeedFactor = 1.0;
    if (isPortrait) {
      baseSpeedFactor = 1.5; // 竖屏时速度提高50%
    }

    // 使用线性插值算法调整基于摄像机旋转速度的因子
    const minThreshold = 0.003;
    const maxThreshold = 0.02;
    const minSpeedFactor = 0.5;
    const maxSpeedFactor = 1.0;

    const clampedSpeed = Math.max(minThreshold, Math.min(maxThreshold, this.cameraRotationSpeed));
    const normalizedSpeed = (clampedSpeed - minThreshold) / (maxThreshold - minThreshold);
    const rotationSpeedFactor = maxSpeedFactor - normalizedSpeed * (maxSpeedFactor - minSpeedFactor);

    return baseSpeedFactor * rotationSpeedFactor;
  }

  /**
   * 重置摄像机状态
   */
  public reset(): void {
    this.cameraYaw = 0;
    this.currentCameraRotationSpeed = 0;
    this.cameraRotationDirection = 0;
    this.touchRotationVelocity = 0;
    this.targetCameraDistance = this.cameraDistance;
    this.springArmManager.reset();
  }

  /**
   * 获取摄像机参数（用于调试）
   */
  public getCameraInfo(): {
    yaw: number;
    distance: number;
    height: number;
    targetDistance: number;
    springArm: {
      currentArmLength: number;
      targetArmLength: number;
      isColliding: boolean;
    };
  } {
    const springArmInfo = this.springArmManager.getDebugInfo();
    return {
      yaw: this.cameraYaw,
      distance: this.cameraDistance,
      height: this.cameraHeight,
      targetDistance: this.targetCameraDistance,
      springArm: {
        currentArmLength: springArmInfo.currentArmLength,
        targetArmLength: springArmInfo.targetArmLength,
        isColliding: springArmInfo.isColliding,
      },
    };
  }

  // ============================================
  // 弹簧臂相关方法
  // ============================================

  /**
   * 获取弹簧臂管理器
   */
  public getSpringArmManager(): SpringArmManager {
    return this.springArmManager;
  }

  /**
   * 设置弹簧臂碰撞检测对象
   */
  public setSpringArmCollisionObjects(objects: THREE.Object3D[]): void {
    this.springArmManager.setCollisionObjects(objects);
    console.log(`🎯 弹簧臂碰撞对象已设置: ${objects.length} 个`);
    // 打印碰撞对象的详细信息
    objects.forEach((obj, index) => {
      console.log(`  [${index}] ${obj.name || 'unnamed'} - type: ${obj.type}`);
    });
  }

  /**
   * 添加弹簧臂碰撞检测对象
   */
  public addSpringArmCollisionObject(object: THREE.Object3D): void {
    this.springArmManager.addCollisionObject(object);
  }

  /**
   * 移除弹簧臂碰撞检测对象
   */
  public removeSpringArmCollisionObject(object: THREE.Object3D): void {
    this.springArmManager.removeCollisionObject(object);
  }

  /**
   * 启用/禁用弹簧臂
   */
  public setSpringArmEnabled(enabled: boolean): void {
    this.springArmEnabled = enabled;
    console.log(`🎯 弹簧臂 ${enabled ? '已启用' : '已禁用'}`);
  }

  /**
   * 获取弹簧臂是否启用
   */
  public isSpringArmEnabled(): boolean {
    return this.springArmEnabled;
  }

  /**
   * 启用/禁用弹簧臂碰撞检测
   */
  public setSpringArmCollisionEnabled(enabled: boolean): void {
    this.springArmManager.setCollisionEnabled(enabled);
  }

  /**
   * 设置弹簧臂探测半径
   */
  public setSpringArmProbeRadius(radius: number): void {
    this.springArmManager.setProbeRadius(radius);
  }

  /**
   * 设置弹簧臂碰撞恢复速度
   */
  public setSpringArmRecoverySpeed(speed: number): void {
    this.springArmManager.setCollisionRecoverySpeed(speed);
  }

  /**
   * 设置弹簧臂碰撞收缩速度
   */
  public setSpringArmShrinkSpeed(speed: number): void {
    this.springArmManager.setCollisionShrinkSpeed(speed);
  }

  /**
   * 更新弹簧臂配置
   */
  public updateSpringArmConfig(config: Partial<SpringArmConfig>): void {
    this.springArmManager.updateConfig(config);
  }

  /**
   * 启用/禁用弹簧臂调试模式
   */
  public setSpringArmDebugEnabled(enabled: boolean): void {
    this.springArmManager.setDebugEnabled(enabled);
  }

  /**
   * 设置 Rapier 物理世界（用于弹簧臂碰撞检测）
   * 这样弹簧臂可以使用与角色相同的碰撞体
   */
  public setSpringArmRapierWorld(world: RAPIER.World | null): void {
    this.springArmManager.setRapierWorld(world);
  }

  /**
   * 设置角色碰撞体（用于弹簧臂排除自身碰撞）
   */
  public setSpringArmCharacterCollider(collider: RAPIER.Collider | null): void {
    this.springArmManager.setCharacterCollider(collider);
  }
}
