import * as THREE from 'three';
import { GaussianSplatLoadStrategy } from './gaussian-splat-load-strategy';
import { SplatConfig } from '../../../../types';
import { GaussianComponent } from '../components/gaussian-component';

/**
 * 单场景加载策略
 * 只创建一个viewer，加载一个scene，使用config.transform作为场景变换
 */
export class SingleSceneStrategy extends GaussianSplatLoadStrategy {
  // private singleSceneConfig: SingleSceneConfig | null = null;

  constructor(scene: THREE.Scene, config: SplatConfig) {
    super(scene, config);
  }

  /**
   * 加载场景
   */
  async load(): Promise<void> {
    try {
      // 1. 加载配置文件
      // await this.loadSingleSceneConfig();

      // if (!this.singleSceneConfig) {
      //   throw new Error('Failed to load single scene config');
      // }

      // 2. 创建viewer组件
      this.createViewer();

      if (!this.viewer) {
        throw new Error('Failed to create viewer');
      }

      // 3. 添加场景（使用config.transform作为场景变换）
      const scene = await this.viewer.addScene(this.config.singleSceneConfigPath!, {
        position: this.config.transform.position,
        rotation: this.config.transform.rotation,
        scale: this.config.transform.scale,
        showLoadingUI: this.config.showLoadingUI,
        onProgress: (progress: number) => {
          // console.log(`场景加载进度: ${progress.toFixed(1)}%`);
          this.config.onFirstSceneProgress?.(this.config.singleSceneConfigPath!, progress);
          this.config.onScenesProgress?.(this.config.singleSceneConfigPath!, progress);
        },
      });
      this.viewer = scene;

      console.log(`SingleSceneStrategy: 场景加载完成`);
    } catch (error) {
      console.error('SingleSceneStrategy: 加载失败', error);
      this.dispose();
      throw error;
    }
  }

  /**
   * 卸载场景
   */
  dispose(): void {
    console.log('SingleSceneStrategy: 开始卸载');

    if (this.viewer) {
      this.viewer.dispose();
      this.viewer = null;
    }

    // this.singleSceneConfig = null;

    console.log('SingleSceneStrategy: 卸载完成');
  }

  /**
   * 更新策略（单场景策略不需要动态更新）
   */
  update(): void {
    // 单场景策略不需要每帧更新
  }

  /**
   * 创建viewer组件（根据gaussianComponentType）
   */
  private createViewer(): void {
    this.viewer = GaussianComponent.create(this.config.gaussianComponentType, this.config, this.scene);
  }
}
