import type * as THREE from 'three';
import type { GaussianSplats3DComponent, SparkComponent } from '@/infranstructure/viewers/scene-viewer/components';

/**
 * 单场景配置接口
 */
export interface SingleSceneConfig {
  /** 场景文件URL */
  url: string;
  transform: {
    position: [number, number, number];
    rotation: number[];
    scale: [number, number, number];
  };
}

/**
 * 区域模块配置接口
 */
export interface RegionModule {
  /** 模块唯一标识 */
  id: string;
  /** 模块名称 */
  name: string;
  /** 场景文件URL */
  url: string;
  /** 摩顿配置文件URL */
  mortonConfig: string;
  /** 模块中心点 */
  transform: {
    /** 模块位置 [x, y, z] */
    position: [number, number, number];
    /** 模块旋转 [x, y, z] (弧度) */
    rotation: [number, number, number];
    /** 模块缩放 [x, y, z] */
    scale: [number, number, number];
  };
  /** 模块变换信息 */
  gsInfo?: {
    /** 模块位置 [x, y, z] */
    position: [number, number, number];
    /** 模块旋转 [x, y, z] (弧度) */
    rotation: [number, number, number];
    /** 模块缩放 [x, y, z] */
    scale: [number, number, number];
  };
  /** 模块边界（用于检测用户是否进入该区域） */
  bounds: {
    /** 模块长度（X轴） */
    x: number;
    /** 模块高度（Y轴） */
    y: number;
    /** 模块宽度（Z轴） */
    z: number;
  };
  /** 是否为默认模块 */
  isDefault?: boolean;
}

/**
 * 区域替换配置接口
 */
export interface RegionReplaceConfig {
  /** 配置名称 */
  baseUrl?: string;
  fileType?: string;
  morton?: boolean;
  /** 区域模块列表 */
  modules: RegionModule[];
  /** 切换配置 */
  switchConfig?: {
    /** 预加载距离（米） */
    preloadDistance?: number;
    /** 卸载距离（米） */
    unloadDistance?: number;
    /** 切换延迟（毫秒） */
    switchDelay?: number;
  };
}

export type InteractionSceneConfig = any;

export interface InteractionZone {
  geometry: number[];
  geometryPos: number[];
  model: string;
  modelPos: number[];
  scale?: number[];
  rotation?: number[];
  dialog?: string;
  query?: string;
  buttonText?: string;
}
export enum GaussianComponentType {
  Spark = 'spark',
  GaussianSplats3D = 'gaussian-splats-3d',
}

export interface GaussianComponentClass {
  [GaussianComponentType.Spark]: SparkComponent;
  [GaussianComponentType.GaussianSplats3D]: GaussianSplats3DComponent;
}
export interface Collision {
  /** 模型文件URL */
  url: string;
  /** 变换信息 */
  transform: {
    position: [number, number, number];
    rotation: [number, number, number];
    scale: [number, number, number];
  };
  opacity?: number;
}
