/**
 * 项目配置接口
 */
export interface ProjectConfig {
  /** 项目名称 */
  name: string;
  /** 渲染器缩放 */
  rendererScale: number;
  /** 是否启用调试器 */
  debugger: boolean;
  /** 米制缩放 */
  meterScale: number;
  /** 高斯泼溅配置 */
  gaussianSplatting: SplatConfig;
  /** 网格模型配置 */
  collision: Collision;

  interactive: {
    /** 模型文件URL */
    url: string;
    /** 变换信息 */
    transform: {
      position: [number, number, number];
      rotation: [number, number, number];
      scale: [number, number, number];
    };
  };
  /** 地形配置 */
  terrain?: {
    /** 高度图URL */
    url: string;
    /** 变换信息 */
    transform: {
      locationCM: [number, number, number];
      rotation: [number, number, number];
      scale: [number, number, number];
    };
    /** 分辨率信息 */
    resolution: {
      totalVertices: [number, number];
      componentVertices: [number, number];
      componentSections: [number, number];
    };
  };
  /** 初始化配置 */
  initial: {
    /** 角色初始化 */
    player: {
      position: Vector3D;
      rotation: Vector3D;
    };
    /** 摄像机初始化 */
    camera: {
      // 摄像机位置设置已删除，将根据角色位置自动计算
    };
  };
  interaction?: InteractionZone;
  interactionZones?: InteractionZone[];
}

export interface Vector3D {
  x: number;
  y: number;
  z: number;
}
