import { AbortablePromise, AbortedPromiseError } from './abortable-promise';

export const fetchWithProgress = function (path, onProgress, saveChunks = true, headers) {
  /**
     * 在这个 3D 泼溅（GaussianSplats3D）项目中，AbortController 主要用于：
        1. 控制资源加载：允许在加载大型 3D 资源时，如果用户切换视图或取消操作，能够立即中止正在进行的网络请求。
        2. 防止资源浪费：当不再需要某个资源时，可以中止其下载过程，避免不必要的网络流量和内存使用。
        3. 提升用户体验：通过及时中止不再需要的操作，使应用响应更加迅速。
     */
  const abortController = new AbortController();
  const { signal } = abortController;
  let aborted = false;
  const abortHandler = (reason) => {
    try{
        console.log('abort', reason);
        abortController.abort(reason);
        aborted = true;
    } catch (error) {
      console.warn('abort error', error);
    }
  };

  let onProgressCalledAtComplete = false;
  const localOnProgress = (percent, percentLabel, chunk, fileSize) => {
    if (onProgress && !onProgressCalledAtComplete) {
      onProgress(percent, percentLabel, chunk, fileSize);
      if (percent === 100) {
        onProgressCalledAtComplete = true;
      }
    }
  };

  return new AbortablePromise((resolve, reject) => {
    const fetchOptions: {
        signal: AbortSignal;
        headers?: Record<string, string>;
    } = { signal };
    if (headers) fetchOptions.headers = headers;
    fetch(path, fetchOptions)
      .then(async (data) => {
        // 如果已经中断，直接返回，不再处理
        if (aborted) {
          return;
        }

        // Handle error conditions where data is still returned
        if (!data.ok) {
          const errorText = await data.text();
          reject(new Error(`Fetch failed: ${data.status} ${data.statusText} ${errorText}`));
          return;
        }

        const reader = data.body?.getReader();
        let bytesDownloaded = 0;
        const _fileSize = data.headers.get('Content-Length');
        const fileSize = _fileSize ? parseInt(_fileSize) : undefined;

        const chunks: Uint8Array<ArrayBuffer>[] = [];

        while (!aborted) {
          try {
            const { value: chunk, done } = await reader?.read() || {};
            if (done) {
              localOnProgress(100, '100%', chunk, fileSize);
              if (saveChunks) {
                const buffer = new Blob(chunks).arrayBuffer();
                resolve(buffer);
              } else {
                resolve();
              }
              break;
            }
            bytesDownloaded += chunk?.length || 0;
            let percent;
            let percentLabel;
            if (fileSize !== undefined) {
              percent = (bytesDownloaded / fileSize) * 100;
              percentLabel = `${percent.toFixed(2)}%`;
            }
            if (saveChunks) {
              chunks.push(chunk!);
            }
            localOnProgress(percent, percentLabel, chunk, fileSize);
          } catch (error) {
            reject(error);
            return;
          }
        }
      })
      .catch((error) => {
        reject(new AbortedPromiseError(error));
      });
  }, abortHandler);

};
