import * as THREE from 'three';
import RAPIER from '@dimforge/rapier3d-compat';

/**
 * 弹簧臂碰撞检测结果
 */
export interface SpringArmCollisionResult {
  hasCollision: boolean;
  hitDistance: number;
  hitPoint: THREE.Vector3 | null;
  hitNormal: THREE.Vector3 | null;
}

/**
 * 弹簧臂配置参数
 */
export interface SpringArmConfig {
  /** 目标臂长（无碰撞时的理想距离） */
  targetArmLength: number;
  /** 最小臂长 */
  minArmLength: number;
  /** 碰撞探测半径（球形探测） */
  probeRadius: number;
  /** 碰撞通道（用于射线检测的图层） */
  collisionChannel?: number;
  /** 是否启用碰撞检测 */
  enableCollision: boolean;
  /** 是否启用摄像机滞后（平滑跟随） */
  enableCameraLag: boolean;
  /** 摄像机滞后速度 */
  cameraLagSpeed: number;
  /** 是否启用摄像机旋转滞后 */
  enableCameraRotationLag: boolean;
  /** 摄像机旋转滞后速度 */
  cameraRotationLagSpeed: number;
  /** 碰撞恢复速度（从碰撞状态恢复到目标距离的速度） */
  collisionRecoverySpeed: number;
  /** 碰撞收缩速度（检测到碰撞时收缩的速度） */
  collisionShrinkSpeed: number;
}

/**
 * 弹簧臂管理器
 * 模拟 UE 中 SpringArm 组件的核心功能：
 * 1. 碰撞检测与自动收缩（使用 Rapier 物理引擎）
 * 2. 平滑恢复到目标距离
 * 3. 摄像机位置/旋转滞后
 */
export class SpringArmManager {
  // 配置参数
  private config: SpringArmConfig;

  // 当前状态
  private currentArmLength: number;
  private targetPosition = new THREE.Vector3();
  private currentPosition = new THREE.Vector3();
  private currentRotation = new THREE.Quaternion();

  // Rapier 物理世界引用
  private rapierWorld: RAPIER.World | null = null;
  // 角色碰撞体（用于排除自身碰撞）
  private characterCollider: RAPIER.Collider | null = null;

  // 备用：THREE.js 碰撞检测
  private raycaster = new THREE.Raycaster();
  private collisionObjects: THREE.Object3D[] = [];

  // 临时向量（避免频繁创建）
  private tempVector = new THREE.Vector3();
  private tempDirection = new THREE.Vector3();

  // 调试
  private debugEnabled = false;
  private lastDebugTime = 0;

  constructor(config?: Partial<SpringArmConfig>) {
    // 默认配置
    this.config = {
      targetArmLength: 5.0,
      minArmLength: 0.5,
      probeRadius: 0.2,
      collisionChannel: 0,
      enableCollision: true,
      enableCameraLag: true,
      cameraLagSpeed: 10.0,
      enableCameraRotationLag: false,
      cameraRotationLagSpeed: 10.0,
      collisionRecoverySpeed: 3.0,
      collisionShrinkSpeed: 15.0,
      ...config,
    };

    this.currentArmLength = this.config.targetArmLength;
  }

  /**
   * 设置 Rapier 物理世界（用于碰撞检测）
   */
  public setRapierWorld(world: RAPIER.World | null): void {
    this.rapierWorld = world;
    if (world) {
      console.log('🎯 SpringArm: 已连接到 Rapier 物理世界');
      console.log('🎯 SpringArm: 碰撞检测已启用:', this.config.enableCollision);
    } else {
      console.warn('⚠️ SpringArm: Rapier 物理世界设置为 null');
    }
  }

  /**
   * 设置角色碰撞体（用于排除自身碰撞）
   */
  public setCharacterCollider(collider: RAPIER.Collider | null): void {
    this.characterCollider = collider;
  }

  /**
   * 设置碰撞检测对象列表（THREE.js 备用方案）
   */
  public setCollisionObjects(objects: THREE.Object3D[]): void {
    this.collisionObjects = objects;
    if (this.debugEnabled) {
      console.log(`🎯 SpringArm 碰撞对象设置: ${objects.length} 个`);
    }
  }

  /**
   * 添加碰撞检测对象
   */
  public addCollisionObject(object: THREE.Object3D): void {
    if (!this.collisionObjects.includes(object)) {
      this.collisionObjects.push(object);
    }
  }

  /**
   * 移除碰撞检测对象
   */
  public removeCollisionObject(object: THREE.Object3D): void {
    const index = this.collisionObjects.indexOf(object);
    if (index !== -1) {
      this.collisionObjects.splice(index, 1);
    }
  }

  /**
   * 更新弹簧臂
   * @param origin 弹簧臂起点（角色位置）
   * @param direction 弹簧臂方向（从角色指向摄像机的方向）
   * @param delta 帧时间
   * @returns 计算后的摄像机位置
   */
  public update(origin: THREE.Vector3, direction: THREE.Vector3, delta: number): THREE.Vector3 {
    // 调试：确认 update 被调用
    // const now = Date.now();
    // if (now - this.lastDebugTime > 1000) {
    //   this.lastDebugTime = now;
    //   console.log('🔄 SpringArm.update 被调用:', {
    //     origin: `(${origin.x.toFixed(2)}, ${origin.y.toFixed(2)}, ${origin.z.toFixed(2)})`,
    //     direction: `(${direction.x.toFixed(2)}, ${direction.y.toFixed(2)}, ${direction.z.toFixed(2)})`,
    //     enableCollision: this.config.enableCollision,
    //     hasRapierWorld: !!this.rapierWorld,
    //     targetArmLength: this.config.targetArmLength.toFixed(2),
    //   });
    // }

    // 1. 碰撞检测
    let desiredArmLength = this.config.targetArmLength;

    if (this.config.enableCollision) {
      const collisionResult = this.performCollisionCheck(origin, direction);

      if (collisionResult.hasCollision) {
        // 碰撞时，目标距离为碰撞点距离减去探测半径
        desiredArmLength = Math.max(this.config.minArmLength, collisionResult.hitDistance - this.config.probeRadius);

        // console.log('🎯 碰撞后调整臂长:', {
        //   hitDistance: collisionResult.hitDistance.toFixed(2),
        //   probeRadius: this.config.probeRadius.toFixed(2),
        //   desiredArmLength: desiredArmLength.toFixed(2),
        //   currentArmLength: this.currentArmLength.toFixed(2),
        //   targetArmLength: this.config.targetArmLength.toFixed(2),
        // });
      }
    }

    // 2. 平滑过渡臂长
    // const previousArmLength = this.currentArmLength;
    this.currentArmLength = this.smoothArmLength(this.currentArmLength, desiredArmLength, delta);

    // 如果臂长发生变化，打印日志
    // if (Math.abs(previousArmLength - this.currentArmLength) > 0.01) {
    //   console.log('📏 臂长变化:', {
    //     previous: previousArmLength.toFixed(3),
    //     current: this.currentArmLength.toFixed(3),
    //     desired: desiredArmLength.toFixed(3),
    //   });
    // }

    // 3. 计算目标位置
    this.targetPosition.copy(origin).addScaledVector(direction, this.currentArmLength);

    // 4. 应用摄像机滞后
    if (this.config.enableCameraLag) {
      this.currentPosition.lerp(this.targetPosition, Math.min(1.0, this.config.cameraLagSpeed * delta));
    } else {
      this.currentPosition.copy(this.targetPosition);
    }

    return this.currentPosition.clone();
  }

  /**
   * 执行碰撞检测
   * 优先使用 Rapier 物理引擎，如果不可用则使用 THREE.js Raycaster
   */
  private performCollisionCheck(origin: THREE.Vector3, direction: THREE.Vector3): SpringArmCollisionResult {
    // 优先使用 Rapier 射线检测
    if (this.rapierWorld) {
      const result = this.performRapierRaycast(origin, direction);
      return result;
    }

    // 备用：使用 THREE.js 射线检测
    if (this.collisionObjects.length > 0) {
      return this.performThreeRaycast(origin, direction);
    }

    // 没有可用的碰撞检测方法
    console.warn(
      '⚠️ SpringArm: 没有可用的碰撞检测方法 (rapierWorld:',
      !!this.rapierWorld,
      ', collisionObjects:',
      this.collisionObjects.length,
      ')',
    );
    return {
      hasCollision: false,
      hitDistance: this.config.targetArmLength,
      hitPoint: null,
      hitNormal: null,
    };
  }

  /**
   * 使用 Rapier 物理引擎进行射线检测
   */
  private performRapierRaycast(origin: THREE.Vector3, direction: THREE.Vector3): SpringArmCollisionResult {
    const result: SpringArmCollisionResult = {
      hasCollision: false,
      hitDistance: this.config.targetArmLength,
      hitPoint: null,
      hitNormal: null,
    };

    try {
      // 严格检查 rapierWorld 和 castRay 方法是否可用
      if (!this.rapierWorld || typeof this.rapierWorld.castRay !== 'function') {
        return result;
      }

      // 创建 Rapier 射线
      const ray = new RAPIER.Ray(
        { x: origin.x, y: origin.y, z: origin.z },
        { x: direction.x, y: direction.y, z: direction.z },
      );

      // 执行射线检测
      const maxDistance = this.config.targetArmLength + this.config.probeRadius;

      // 使用 castRay 进行检测 - 返回 { collider, timeOfImpact } 或 null
      const hit = this.rapierWorld.castRay(
        ray,
        maxDistance,
        true, // 实体检测
      );

      // 每秒打印一次射线检测结果
      // const now = Date.now();
      // const shouldLog = now - this.lastDebugTime > 500;
      //
      // if (shouldLog) {
      //   this.lastDebugTime = now;
      //   if (hit) {
      //     // 注意：属性名是 timeOfImpact 而不是 toi
      //     const toi = hit.timeOfImpact ?? hit.toi;
      //     console.log('🔍 Rapier射线检测结果:', {
      //       origin: `(${origin.x.toFixed(2)}, ${origin.y.toFixed(2)}, ${origin.z.toFixed(2)})`,
      //       direction: `(${direction.x.toFixed(2)}, ${direction.y.toFixed(2)}, ${direction.z.toFixed(2)})`,
      //       maxDistance: maxDistance.toFixed(2),
      //       timeOfImpact: toi,
      //       colliderHandle: hit.collider?.handle,
      //       characterColliderHandle: this.characterCollider ? this.characterCollider.handle : 'null',
      //     });
      //   } else {
      //     console.log('🔍 Rapier射线检测结果: 无碰撞', {
      //       origin: `(${origin.x.toFixed(2)}, ${origin.y.toFixed(2)}, ${origin.z.toFixed(2)})`,
      //       direction: `(${direction.x.toFixed(2)}, ${direction.y.toFixed(2)}, ${direction.z.toFixed(2)})`,
      //       maxDistance: maxDistance.toFixed(2),
      //     });
      //   }
      // }

      if (hit && hit.collider) {
        // 注意：Rapier 使用 timeOfImpact 而不是 toi
        const hitDistance = hit.timeOfImpact ?? hit.toi;

        if (typeof hitDistance !== 'number') {
          console.warn('⚠️ hitDistance 不是数字:', hitDistance, hit);
          return result;
        }

        const hitCollider = hit.collider;

        // 检查是否命中了角色自身的碰撞体
        if (this.characterCollider && hitCollider.handle === this.characterCollider.handle) {
          return result;
        }

        if (hitDistance < this.config.targetArmLength + this.config.probeRadius) {
          result.hasCollision = true;
          result.hitDistance = hitDistance;

          // 计算碰撞点
          result.hitPoint = new THREE.Vector3(
            origin.x + direction.x * hitDistance,
            origin.y + direction.y * hitDistance,
            origin.z + direction.z * hitDistance,
          );

          // 获取碰撞法线
          const hitWithNormal = this.rapierWorld!.castRayAndGetNormal(ray, maxDistance, true);
          if (hitWithNormal && hitWithNormal.normal) {
            result.hitNormal = new THREE.Vector3(
              hitWithNormal.normal.x,
              hitWithNormal.normal.y,
              hitWithNormal.normal.z,
            );
          }

          // 碰撞日志
          // console.log('📷 摄像头碰撞检测成功:', {
          //   hitDistance: hitDistance.toFixed(3),
          //   hitPoint: `(${result.hitPoint.x.toFixed(2)}, ${result.hitPoint.y.toFixed(2)}, ${result.hitPoint.z.toFixed(2)})`,
          //   colliderHandle: hitCollider.handle,
          // });
        }
      }

      return result;
    } catch (error) {
      // Rapier 物理世界可能尚未完全初始化，静默返回默认结果
      return result;
    }
  }

  /**
   * 使用 THREE.js Raycaster 进行射线检测（备用方案）
   */
  private performThreeRaycast(origin: THREE.Vector3, direction: THREE.Vector3): SpringArmCollisionResult {
    const result: SpringArmCollisionResult = {
      hasCollision: false,
      hitDistance: this.config.targetArmLength,
      hitPoint: null,
      hitNormal: null,
    };

    // 设置射线
    this.raycaster.set(origin, direction);
    this.raycaster.far = this.config.targetArmLength + this.config.probeRadius;
    this.raycaster.near = 0;

    // 执行射线检测
    const intersects = this.raycaster.intersectObjects(this.collisionObjects, true);

    if (intersects.length > 0) {
      const closestHit = intersects[0];

      // 检查是否在有效范围内
      if (closestHit.distance < this.config.targetArmLength + this.config.probeRadius) {
        result.hasCollision = true;
        result.hitDistance = closestHit.distance;
        result.hitPoint = closestHit.point.clone();
        result.hitNormal = closestHit.face?.normal.clone() || null;
      }
    }

    // 球形探测（多方向检测，提高碰撞检测精度）
    if (this.config.probeRadius > 0 && !result.hasCollision) {
      const sphereCheckResult = this.performSphereProbe(origin, direction);
      if (sphereCheckResult.hasCollision) {
        return sphereCheckResult;
      }
    }

    return result;
  }

  /**
   * 球形探测（模拟 UE 的 Probe 功能）
   */
  private performSphereProbe(origin: THREE.Vector3, direction: THREE.Vector3): SpringArmCollisionResult {
    const result: SpringArmCollisionResult = {
      hasCollision: false,
      hitDistance: this.config.targetArmLength,
      hitPoint: null,
      hitNormal: null,
    };

    // 在目标位置周围进行多方向探测
    const probeDirections = [
      new THREE.Vector3(1, 0, 0),
      new THREE.Vector3(-1, 0, 0),
      new THREE.Vector3(0, 1, 0),
      new THREE.Vector3(0, -1, 0),
      new THREE.Vector3(0, 0, 1),
      new THREE.Vector3(0, 0, -1),
    ];

    // 计算当前目标位置
    const targetPos = this.tempVector.copy(origin).addScaledVector(direction, this.config.targetArmLength);

    let minDistance = this.config.targetArmLength;

    for (const probeDir of probeDirections) {
      this.raycaster.set(targetPos, probeDir);
      this.raycaster.far = this.config.probeRadius;
      this.raycaster.near = 0;

      const intersects = this.raycaster.intersectObjects(this.collisionObjects, true);

      if (intersects.length > 0) {
        const hit = intersects[0];
        // 计算需要收缩的距离
        const shrinkDistance = this.config.probeRadius - hit.distance;
        const newArmLength = this.config.targetArmLength - shrinkDistance;

        if (newArmLength < minDistance) {
          minDistance = newArmLength;
          result.hasCollision = true;
          result.hitDistance = newArmLength;
          result.hitPoint = hit.point.clone();
          result.hitNormal = hit.face?.normal.clone() || null;
        }
      }
    }

    return result;
  }

  /**
   * 平滑过渡臂长
   */
  private smoothArmLength(current: number, target: number, delta: number): number {
    if (Math.abs(current - target) < 0.001) {
      return target;
    }

    if (target < current) {
      // 收缩（碰撞时快速收缩）
      const shrinkAmount = this.config.collisionShrinkSpeed * delta;
      return Math.max(target, current - shrinkAmount);
    }
    // 恢复（平滑恢复到目标距离）
    const recoveryAmount = this.config.collisionRecoverySpeed * delta;
    return Math.min(target, current + recoveryAmount);
  }

  /**
   * 获取当前臂长
   */
  public getCurrentArmLength(): number {
    return this.currentArmLength;
  }

  /**
   * 获取目标臂长
   */
  public getTargetArmLength(): number {
    return this.config.targetArmLength;
  }

  /**
   * 设置目标臂长
   */
  public setTargetArmLength(length: number): void {
    this.config.targetArmLength = Math.max(this.config.minArmLength, length);
  }

  /**
   * 设置最小臂长
   */
  public setMinArmLength(length: number): void {
    this.config.minArmLength = Math.max(0, length);
  }

  /**
   * 设置探测半径
   */
  public setProbeRadius(radius: number): void {
    this.config.probeRadius = Math.max(0, radius);
  }

  /**
   * 启用/禁用碰撞检测
   */
  public setCollisionEnabled(enabled: boolean): void {
    this.config.enableCollision = enabled;
  }

  /**
   * 启用/禁用摄像机滞后
   */
  public setCameraLagEnabled(enabled: boolean): void {
    this.config.enableCameraLag = enabled;
  }

  /**
   * 设置摄像机滞后速度
   */
  public setCameraLagSpeed(speed: number): void {
    this.config.cameraLagSpeed = Math.max(0.1, speed);
  }

  /**
   * 设置碰撞恢复速度
   */
  public setCollisionRecoverySpeed(speed: number): void {
    this.config.collisionRecoverySpeed = Math.max(0.1, speed);
  }

  /**
   * 设置碰撞收缩速度
   */
  public setCollisionShrinkSpeed(speed: number): void {
    this.config.collisionShrinkSpeed = Math.max(0.1, speed);
  }

  /**
   * 启用/禁用调试模式
   */
  public setDebugEnabled(enabled: boolean): void {
    this.debugEnabled = enabled;
  }

  /**
   * 获取当前配置
   */
  public getConfig(): Readonly<SpringArmConfig> {
    return { ...this.config };
  }

  /**
   * 更新配置
   */
  public updateConfig(config: Partial<SpringArmConfig>): void {
    Object.assign(this.config, config);
  }

  /**
   * 重置弹簧臂状态
   */
  public reset(): void {
    this.currentArmLength = this.config.targetArmLength;
    this.currentPosition.set(0, 0, 0);
    this.targetPosition.set(0, 0, 0);
  }

  /**
   * 立即设置臂长（无平滑过渡）
   */
  public setArmLengthImmediate(length: number): void {
    this.currentArmLength = Math.max(this.config.minArmLength, length);
  }

  /**
   * 获取调试信息
   */
  public getDebugInfo(): {
    currentArmLength: number;
    targetArmLength: number;
    isColliding: boolean;
    currentPosition: THREE.Vector3;
    useRapier: boolean;
  } {
    return {
      currentArmLength: this.currentArmLength,
      targetArmLength: this.config.targetArmLength,
      isColliding: this.currentArmLength < this.config.targetArmLength,
      currentPosition: this.currentPosition.clone(),
      useRapier: this.rapierWorld !== null,
    };
  }
}
