import * as THREE from 'three';

/**
 * 路径节点
 */
export interface PathNode {
  position: THREE.Vector3;
  g: number; // 从起点到当前节点的实际代价
  h: number; // 从当前节点到目标的估计代价
  f: number; // f = g + h
  parent: PathNode | null;
}

/**
 * 简单的A*寻路系统
 * 使用网格化的导航网格进行寻路
 */
export class PathFinding {
  private gridSize = 0.5; // 网格大小（米）
  private obstacles: Set<string> = new Set(); // 障碍物位置的哈希集合
  private navigationBounds: THREE.Box3; // 可导航区域的边界

  constructor(bounds: THREE.Box3) {
    this.navigationBounds = bounds;
  }

  /**
   * 添加障碍物
   */
  public addObstacle(position: THREE.Vector3): void {
    const key = this.getGridKey(position);
    this.obstacles.add(key);
  }

  /**
   * 从网格移除障碍物
   */
  public removeObstacle(position: THREE.Vector3): void {
    const key = this.getGridKey(position);
    this.obstacles.delete(key);
  }

  /**
   * 清除所有障碍物
   */
  public clearObstacles(): void {
    this.obstacles.clear();
  }

  /**
   * 获取网格坐标的哈希键
   */
  private getGridKey(position: THREE.Vector3): string {
    const x = Math.floor(position.x / this.gridSize);
    const z = Math.floor(position.z / this.gridSize);
    return `${x},${z}`;
  }

  /**
   * 从网格键解析坐标
   */
  private parseGridKey(key: string): { x: number; z: number } {
    const [x, z] = key.split(',').map(Number);
    return { x, z };
  }

  /**
   * 获取网格中心位置
   */
  private getGridCenter(gridX: number, gridZ: number): THREE.Vector3 {
    return new THREE.Vector3(gridX * this.gridSize + this.gridSize / 2, 0, gridZ * this.gridSize + this.gridSize / 2);
  }

  /**
   * 检查位置是否可通行
   */
  private isWalkable(position: THREE.Vector3): boolean {
    // 检查是否在导航边界内
    if (!this.navigationBounds.containsPoint(position)) {
      return false;
    }

    // 检查是否是障碍物
    const key = this.getGridKey(position);
    return !this.obstacles.has(key);
  }

  /**
   * 获取相邻节点（8方向）
   */
  private getNeighbors(node: PathNode): PathNode[] {
    const neighbors: PathNode[] = [];
    const { x, z } = this.parseGridKey(this.getGridKey(node.position));

    // 8个方向：上下左右 + 4个对角线
    const directions = [
      { dx: 0, dz: 1, cost: 1 }, // 上
      { dx: 0, dz: -1, cost: 1 }, // 下
      { dx: 1, dz: 0, cost: 1 }, // 右
      { dx: -1, dz: 0, cost: 1 }, // 左
      { dx: 1, dz: 1, cost: 1.414 }, // 右上
      { dx: 1, dz: -1, cost: 1.414 }, // 右下
      { dx: -1, dz: 1, cost: 1.414 }, // 左上
      { dx: -1, dz: -1, cost: 1.414 }, // 左下
    ];

    for (const dir of directions) {
      const newX = x + dir.dx;
      const newZ = z + dir.dz;
      const newPosition = this.getGridCenter(newX, newZ);

      if (this.isWalkable(newPosition)) {
        neighbors.push({
          position: newPosition,
          g: 0,
          h: 0,
          f: 0,
          parent: node,
        });
      }
    }

    return neighbors;
  }

  /**
   * 计算两点之间的启发式距离（曼哈顿距离）
   */
  private heuristic(a: THREE.Vector3, b: THREE.Vector3): number {
    return Math.abs(a.x - b.x) + Math.abs(a.z - b.z);
  }

  /**
   * A*寻路算法
   * @param start 起点
   * @param goal 目标点
   * @returns 路径点数组，如果找不到路径则返回空数组
   */
  public findPath(start: THREE.Vector3, goal: THREE.Vector3): THREE.Vector3[] {
    // 起点和终点对齐到网格
    const startGridKey = this.getGridKey(start);
    const goalGridKey = this.getGridKey(goal);

    const startGridPos = this.parseGridKey(startGridKey);
    const goalGridPos = this.parseGridKey(goalGridKey);

    const startPosition = this.getGridCenter(startGridPos.x, startGridPos.z);
    const goalPosition = this.getGridCenter(goalGridPos.x, goalGridPos.z);

    // 检查起点和终点是否可通行
    if (!this.isWalkable(startPosition) || !this.isWalkable(goalPosition)) {
      console.warn('🚫 起点或终点不可通行');
      return [];
    }

    const openSet: PathNode[] = [];
    const closedSet = new Set<string>();

    // 初始化起点
    const startNode: PathNode = {
      position: startPosition,
      g: 0,
      h: this.heuristic(startPosition, goalPosition),
      f: 0,
      parent: null,
    };
    startNode.f = startNode.g + startNode.h;
    openSet.push(startNode);

    let iterations = 0;
    const maxIterations = 1000; // 防止无限循环

    while (openSet.length > 0 && iterations < maxIterations) {
      iterations++;

      // 找到f值最小的节点
      openSet.sort((a, b) => a.f - b.f);
      const current = openSet.shift()!;

      const currentKey = this.getGridKey(current.position);

      // 到达目标
      if (currentKey === goalGridKey) {
        return this.reconstructPath(current);
      }

      closedSet.add(currentKey);

      // 遍历相邻节点
      const neighbors = this.getNeighbors(current);
      for (const neighbor of neighbors) {
        const neighborKey = this.getGridKey(neighbor.position);

        if (closedSet.has(neighborKey)) {
          continue;
        }

        const tentativeG = current.g + current.position.distanceTo(neighbor.position);

        // 检查是否已在openSet中
        const existingNode = openSet.find((n) => this.getGridKey(n.position) === neighborKey);

        if (!existingNode) {
          // 新节点
          neighbor.g = tentativeG;
          neighbor.h = this.heuristic(neighbor.position, goalPosition);
          neighbor.f = neighbor.g + neighbor.h;
          neighbor.parent = current;
          openSet.push(neighbor);
        } else if (tentativeG < existingNode.g) {
          // 找到更好的路径
          existingNode.g = tentativeG;
          existingNode.f = existingNode.g + existingNode.h;
          existingNode.parent = current;
        }
      }
    }

    // 没找到路径
    console.warn('🚫 未找到路径');
    return [];
  }

  /**
   * 重构路径
   */
  private reconstructPath(endNode: PathNode): THREE.Vector3[] {
    const path: THREE.Vector3[] = [];
    let current: PathNode | null = endNode;

    while (current !== null) {
      path.unshift(current.position.clone());
      current = current.parent;
    }

    // 简化路径（移除不必要的中间点）
    return this.smoothPath(path);
  }

  /**
   * 平滑路径（移除共线的点）
   */
  private smoothPath(path: THREE.Vector3[]): THREE.Vector3[] {
    if (path.length <= 2) {
      return path;
    }

    const smoothed: THREE.Vector3[] = [path[0]];

    for (let i = 1; i < path.length - 1; i++) {
      const prev = path[i - 1];
      const current = path[i];
      const next = path[i + 1];

      // 检查是否共线
      const dir1 = new THREE.Vector3().subVectors(current, prev).normalize();
      const dir2 = new THREE.Vector3().subVectors(next, current).normalize();

      const dot = dir1.dot(dir2);

      // 如果不共线（角度差异较大），保留这个点
      if (dot < 0.99) {
        smoothed.push(current);
      }
    }

    smoothed.push(path[path.length - 1]);
    return smoothed;
  }

  /**
   * 设置网格大小
   */
  public setGridSize(size: number): void {
    this.gridSize = size;
    console.log(`📏 设置网格大小为: ${size}米`);
  }

  /**
   * 获取网格大小
   */
  public getGridSize(): number {
    return this.gridSize;
  }
}
