<template>
  <div ref="containerRef" class="three-container">
    <VirtualJoystick
      ref="virtualJoystickRef"
      :is-orbit-control-active="uiState.isOrbitControlActive"
      :is-orbit-control-manually-activated="uiState.isOrbitControlManuallyActivated"
      @joystick-move="onJoystickMove"
      @run-toggle="onRunToggle"
      @touch-delta="onTouchDelta"
      @camera-rotate="onCameraRotate"
      @camera-rotation-speed="onCameraRotationSpeed"
      @operation-mode-change="onOperationModeChange"
    />

    <!-- 跳跃按钮 (独立) -->
    <div class="jump-button-container">
      <div
        class="jump-button center-button"
        :class="{ active: uiState.isJumping }"
        @touchstart.prevent.stop="onJumpStart"
        @touchend.prevent.stop="onJumpEnd"
        @mousedown.prevent.stop="onJumpStart"
        @mouseup.prevent.stop="onJumpEnd"
        @click.prevent.stop
      >
        <svg viewBox="0 0 48 48" fill="currentColor">
          <!-- 跳跃小人图标 - 更动感的设计 -->
          <!-- 头部 -->
          <circle cx="24" cy="10" r="5" />
          <!-- 身体 (稍微倾斜) -->
          <ellipse cx="24" cy="20" rx="3" ry="8" transform="rotate(5 24 20)" />
          <!-- 左臂 (大幅向上摆动) -->
          <ellipse cx="18" cy="16" rx="1.5" ry="6" transform="rotate(-45 18 16)" />
          <!-- 右臂 (向后摆动) -->
          <ellipse cx="30" cy="18" rx="1.5" ry="6" transform="rotate(25 30 18)" />
          <!-- 左腿 (向前踢) -->
          <ellipse cx="21" cy="30" rx="2" ry="8" transform="rotate(-25 21 30)" />
          <!-- 右腿 (向后蹬) -->
          <ellipse cx="27" cy="32" rx="2" ry="8" transform="rotate(35 27 32)" />

          <!-- 跳跃轨迹弧线 -->
          <path
            d="M8 38 Q24 28 40 38"
            stroke="currentColor"
            stroke-width="2.5"
            fill="none"
            opacity="0.7"
            stroke-dasharray="3,2"
          />

          <!-- 地面冲击波 -->
          <ellipse cx="24" cy="42" rx="12" ry="2" opacity="0.4" />
          <ellipse cx="24" cy="43" rx="8" ry="1" opacity="0.3" />
        </svg>
      </div>
    </div>

    <!-- 右侧竖向按钮组 -->
    <div class="vertical-button-group">
      <!-- 选择模型按钮 -->
      <div
        class="model-selector-button vertical-button"
        @click.prevent.stop="toggleModelSelector"
        @touchstart.prevent.stop
        @touchend.prevent.stop="toggleModelSelector"
        @mousedown.prevent.stop
        @mouseup.prevent.stop
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <!-- 人物图标 -->
          <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
          <circle cx="12" cy="7" r="4"></circle>
        </svg>
      </div>

      <!-- 环绕按钮 -->
      <div
        class="orbit-button vertical-button"
        @touchstart.prevent.stop="onOrbitButtonStart"
        @touchend.prevent.stop="onOrbitButtonEnd"
        @mousedown.prevent.stop="onOrbitButtonStart"
        @mouseup.prevent.stop="onOrbitButtonEnd"
        @click.prevent.stop
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <!-- 圈形图标 -->
          <circle cx="12" cy="12" r="8" />
          <circle cx="12" cy="12" r="3" fill="currentColor" />
        </svg>
      </div>

      <!-- 全屏按钮 -->
      <div
        class="fullscreen-toggle vertical-button"
        :class="{ active: uiState.isFullscreen }"
        @click.prevent.stop="toggleFullscreen"
        @touchstart.prevent.stop
        @touchend.prevent.stop="toggleFullscreen"
        @mousedown.prevent.stop
        @mouseup.prevent.stop
      >
        <svg v-if="uiState.isFullscreen" viewBox="0 0 24 24" fill="none" stroke="currentColor"
             stroke-width="2">
          <!-- 退出全屏图标 -->
          <path
            d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3"
          ></path>
        </svg>
        <svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <!-- 进入全屏图标 -->
          <path
            d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"
          ></path>
        </svg>
      </div>
    </div>

    <!-- 模型选择卡片 -->
    <Transition name="modal">
      <div v-if="uiState.showModelSelector" class="model-selector-overlay"
           @click.prevent.stop="closeModelSelector">
        <div class="model-selector-card" @click.prevent.stop>
          <!-- 头部区域 -->
          <div class="model-selector-header">
            <div class="header-content">
              <div class="header-icon">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path>
                  <circle cx="9" cy="7" r="4"></circle>
                  <path d="M22 21v-2a4 4 0 0 0-3-3.87"></path>
                  <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
                </svg>
              </div>
              <div class="header-text">
                <h3>选择角色模型</h3>
              </div>
            </div>
            <button class="close-btn" @click.prevent.stop="closeModelSelector">
              ×
            </button>
          </div>

          <!-- 内容区域 -->
          <div class="model-selector-content">
            <div class="model-cards-container">
              <div
                v-for="(model, index) in availableModels"
                :key="model.id"
                class="model-card"
                :class="{
                  active: model.id === uiState.currentModelId,
                  selected: model.id === uiState.selectedModelId,
                }"
                :style="{ '--delay': index * 0.1 + 's' }"
                @click.prevent.stop="selectModelCard(model.id)"
                @touchstart.prevent.stop
                @touchend.prevent.stop="selectModelCard(model.id)"
                @mousedown.prevent.stop
                @mouseup.prevent.stop
              >
                <!-- 模型预览图 -->
                <div class="model-image-container">
                  <div class="image-wrapper">
                    <img :src="model.imagePath" :alt="model.name" class="model-image"
                         @error="onImageError" />
                    <div class="image-overlay"></div>
                  </div>

                  <!-- 选中状态 -->
                  <div v-if="model.id === uiState.selectedModelId" class="selected-badge">
                    <div class="badge-icon">
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" />
                      </svg>
                    </div>
                  </div>

                  <!-- 当前使用标识 -->
                  <div v-if="model.id === uiState.currentModelId" class="current-badge">
                    <div class="current-icon">
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <circle cx="12" cy="12" r="10" />
                        <path d="M12 6v6l4 2" stroke="white" stroke-width="2" fill="none" />
                      </svg>
                    </div>
                  </div>

                  <!-- 悬停效果 -->
                  <div class="hover-overlay">
                    <div class="play-icon">
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <polygon points="5,3 19,12 5,21"></polygon>
                      </svg>
                    </div>
                  </div>
                </div>

                <!-- 模型信息 -->
                <div class="model-info">
                  <div class="model-name">{{ model.name }}</div>
                  <div class="model-description">{{ model.describe }}</div>

                  <!-- 状态指示器 -->
                  <div class="model-status">
                    <div
                      class="status-dot"
                      :class="{
                        active: model.id === uiState.currentModelId,
                        selected: model.id === uiState.selectedModelId,
                      }"
                    ></div>
                    <span class="status-text">
                      {{
                        model.id === uiState.currentModelId
                          ? '当前使用'
                          : model.id === uiState.selectedModelId
                            ? '已选择'
                            : '点击选择'
                      }}
                    </span>
                  </div>
                </div>

                <!-- 装饰元素 -->
                <div class="card-decoration">
                  <div class="decoration-line"></div>
                </div>
              </div>
            </div>
          </div>

          <!-- 底部操作区 -->
          <div class="model-selector-footer">
            <div class="footer-info">
              <span class="model-count">{{ availableModels.length }} 个可用角色</span>
            </div>
            <button
              class="confirm-btn"
              @click.prevent.stop="confirmModelSelection"
              @touchstart.prevent.stop
              @touchend.prevent.stop="confirmModelSelection"
              @mousedown.prevent.stop
              @mouseup.prevent.stop
              :disabled="uiState.selectedModelId === uiState.currentModelId"
            >
              <span>{{ uiState.selectedModelId === uiState.currentModelId ? '已是当前模型' : '确认选择'
                }}</span>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="9,18 15,12 9,6"></polyline>
              </svg>
            </button>
          </div>
        </div>
      </div>
    </Transition>

    <!-- Toast 提示 -->
    <Transition name="toast">
      <div v-if="uiState.showToast" class="toast">
        {{ uiState.toastMessage }}
      </div>
    </Transition>

    <!-- Debug面板 -->
    <DebugPanel
      :debug-manager="debugManager"
      :npc-manager="npcManager"
      :camera-sensitivity="cameraSensitivity"
      @config-change="onDebugConfigChange"
      @log-debug-info="onLogDebugInfo"
      @reset-physics="onResetPhysics"
    />
    <!-- 交互对话框 -->
    <InteractionDialog ref="interactionRef" />
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, onUnmounted, inject } from 'vue';

import * as THREE from 'three';
import VirtualJoystick from './VirtualJoystick.vue';
import DebugPanel from './DebugPanel.vue';
import InteractionDialog from '../../components/InteractionDialog.vue';
import {
  SceneManager,
  OrbitControlManager,
  ToastManager,
  FullscreenManager,
  EventManager,
  DebugManager,
} from '@/infranstructure/viewers/scene-viewer';
import {
  DEFAULT_SCENE_CONFIG,
  LocalModelConfig,
  TARGET_CHARACTER_HEIGHT,
} from '@/infranstructure/viewers/scene-viewer/constant';
import { CharacterModelInfo, DialogType } from '@/types';


// 获取路由实例
const route = inject('route');

const containerRef = ref<HTMLDivElement>();
const virtualJoystickRef = ref<InstanceType<typeof VirtualJoystick>>();
const interactionRef = ref<DialogType>();

// 管理器实例
let sceneManager: SceneManager;
let orbitControlManager: OrbitControlManager;
let toastManager: ToastManager;
let fullscreenManager: FullscreenManager;
let eventManager: EventManager;
let debugManager: DebugManager;
let npcManager: any; // NPCManager实例
// 消息常量
const singleControlMessage = '单指控制视角';
const doubleControlMessage = '双指控制视角';

// 响应式状态
const uiState = ref({
  isOrbitControlActive: false,
  isOrbitControlManuallyActivated: false,
  isFullscreen: false,
  showToast: false,
  toastMessage: '',
  showModelSelector: false,
  currentModelId: LocalModelConfig.default,
  selectedModelId: LocalModelConfig.default, // 添加临时选择的模型ID
  isJumping: false, // 添加跳跃状态
});

// 当前操作模式状态
const currentOperationMode = ref<'auto' | 'single' | 'dual'>('dual'); // 默认双手模式

// 摄像机灵敏度状态
const cameraSensitivity = ref(0.003);

// 获取正确的资源路径
function getAssetPath(path: string): string {
  // 在开发环境中使用绝对路径，在生产环境中使用相对路径
  if (import.meta.env.DEV) {
    return path.startsWith('/') ? path : `/${path}`;
  } else {
    return path.startsWith('/') ? `.${path}` : path;
  }
}

// 可用的模型列表（使用 LocalModelConfig）
const availableModels = ref(
  LocalModelConfig.models.map((model) => ({
    ...model,
    imagePath: getAssetPath(model.imagePath),
  })),
);

// 同步管理器状态到 UI 状态
function syncUIState() {
  if (orbitControlManager) {
    uiState.value.isOrbitControlActive = orbitControlManager.isActive.value;
    uiState.value.isOrbitControlManuallyActivated = orbitControlManager.isManuallyActivated.value;
  }
  if (fullscreenManager) {
    uiState.value.isFullscreen = fullscreenManager.isFullscreen.value;
  }
  if (toastManager) {
    uiState.value.showToast = toastManager.showToast.value;
    uiState.value.toastMessage = toastManager.message.value;
  }
}

// 同步当前模型状态
function syncCurrentModelState() {
  if (sceneManager?.getCharacter()) {
    const currentModelId = sceneManager.getCharacter()?.currentModelId;
    const currentModel = availableModels.value.find((model) => model.id === currentModelId);
    if (currentModel) {
      uiState.value.currentModelId = currentModel.id;
      uiState.value.selectedModelId = currentModel.id;
      console.log(`🔄 同步当前模型状态: ${currentModel.name} (${currentModel.id})`);
    }
  }
}

// 添加动态角色到模型列表
function addDynamicCharacterToModelList(characterInfo: CharacterModelInfo) {
  // 从URL提取文件名作为模型ID
  const fileName = characterInfo.modelFilePath.split('/').pop() || 'dynamic_model.glb';
  const modelId = `dynamic_${characterInfo.name}`;

  // 检查是否已经存在
  const existingModel = availableModels.value.find((model) => model.id === modelId);
  if (existingModel) {
    console.log(`🔄 动态模型已存在: ${characterInfo.name}`);
    return;
  }

  // 创建新的模型配置
  const newModel: CharacterModelInfo = {
    id: modelId,
    name: characterInfo.name,
    describe: '动态加载的角色模型',
    modelFilePath: characterInfo.modelFilePath,
    imagePath:
      'data:image/svg+xml;base64,', // 动态角色的默认SVG图标
    transform: characterInfo.transform,
    anim: characterInfo.anim,
  };

  // 添加到列表开头（优先显示）
  availableModels.value.unshift(newModel);

  // 设置为当前选中的模型
  uiState.value.currentModelId = modelId;
  uiState.value.selectedModelId = modelId;

  console.log(`✅ 动态角色已添加到模型列表: ${characterInfo.name} (${modelId})`);
}

onMounted(() => {
  if (!containerRef.value) return;
  console.log(route.value.path);    // 当前路径
  console.log(route.value.query);   // 查询参数对象
  console.log(route.value.params);  // 路由参数对象
  console.log(route.value.name);    // 路由名称


  const sceneUrl = route.value.query.sceneUrl || '';
  console.log('sceneUrl====', sceneUrl);
  const avatarUrl = route.value.query.avatarUrl || '';
  const height = route.value.query.height || '';
  const aniListStr = route.value.query.aniList;
  const aniList = aniListStr ? JSON.parse(aniListStr) : [];
  const modelTextureStr = route.value.query.modelTexture;
  const modelTexture = modelTextureStr ? JSON.parse(modelTextureStr) : [];
  console.log('avatarUrl', avatarUrl, 'aniList', aniList, 'modelTexture', modelTexture, 'height', height);
  const modelAnimationConfig = {
    basePath: '',
    isFromQuery: true,
    animations: {
      Idle: { url: '', animationIdx: 0 },
      Walking: { url: '', animationIdx: 0 },
      Running: { url: '', animationIdx: 0 },
      Falling: { url: '', animationIdx: 0 },
      Jumping: { url: '', animationIdx: 0 },
    },
  };
  for (const ani of aniList) {
    switch (ani.name) {
      case 'idle':
        modelAnimationConfig.animations.Idle = {
          url: ani.url,
          animationIdx: ani.animationIdxs[0] || 0,
        };
        break;
      case 'running':
      case 'run':
      case '跑步':
        modelAnimationConfig.animations.Running = {
          url: ani.url,
          animationIdx: ani.animationIdxs[0] || 0,
        };
        break;
      case 'walking':
      case '走路':
        modelAnimationConfig.animations.Walking = {
          url: ani.url,
          animationIdx: ani.animationIdxs[0] || 0,
        };
        break;
      case 'Falling':
        modelAnimationConfig.animations.Falling = {
          url: ani.url,
          animationIdx: ani.animationIdxs[0] || 0,
        };
        break;
      case 'jump':
        modelAnimationConfig.animations.Jumping = {
          url: ani.url,
          animationIdx: ani.animationIdxs[0] || 0,
        };
        break;
      default:
        break;
    }
  }
  // 没有Falling动画，使用走路动画
  if (!modelAnimationConfig.animations.Falling.url) {
    modelAnimationConfig.animations.Falling = modelAnimationConfig.animations.Walking;
  }
  // 没有跑步动画，使用走路动画
  if (!modelAnimationConfig.animations.Running.url) {
    modelAnimationConfig.animations.Running = modelAnimationConfig.animations.Walking;
  }
  console.log('modelAnimationConfig:', modelAnimationConfig);
  const characterInfo: CharacterModelInfo = {
    id: 'test',
    name: 'demo',
    describe: '',
    imagePath: '',
    modelFilePath: avatarUrl,
    transform: {
      position: { x: 0, y: 0, z: 0 },
      rotation: { x: 0, y: 0, z: 0 },
    },
    modelTexture,
    anim: modelAnimationConfig,
    targetHeight: height ? Number(height) / 100 : TARGET_CHARACTER_HEIGHT,
  };
  console.log('characterInfo:', characterInfo);
  // 初始化管理器
  initManagers(typeof sceneUrl === 'string' ? sceneUrl : DEFAULT_SCENE_CONFIG, avatarUrl ? characterInfo : undefined);

  // 开始动画循环
  sceneManager.animate();
  sceneManager.animate();

  // 延迟同步当前模型状态（等待角色管理器初始化完成）
  setTimeout(() => {
    syncCurrentModelState();

    // 如果有动态角色信息，添加到可用模型列表中
    const dynamicCharacterInfo = sceneManager.getCharacterInfo();
    if (dynamicCharacterInfo) {
      addDynamicCharacterToModelList(dynamicCharacterInfo);
    }
  }, 1000);
});

onUnmounted(() => {
  cleanup();
});

function initManagers(configUrl: string, characterInfo?: CharacterModelInfo) {
  console.log('configUrl' ,configUrl)
  // 初始化事件管理器
  eventManager = new EventManager();

  // 初始化Toast管理器
  toastManager = new ToastManager(() => {
    // Toast状态变化时同步UI状态
    syncUIState();
  });

  // 初始化全屏管理器
  fullscreenManager = new FullscreenManager(() => {
    // 全屏状态变化时同步UI状态
    syncUIState();
  });

  // 初始化场景管理器（使用配置URL）
  sceneManager = new SceneManager(containerRef.value!, configUrl, characterInfo, interactionRef.value!);

  // 获取debug管理器
  debugManager = sceneManager.getDebugManager();

  // 获取NPC管理器
  npcManager = sceneManager.getNPCManager();

  // 🔥 新增：启用悬崖检测功能（默认配置）
  setTimeout(() => {
    // 等待角色管理器初始化完成后启用悬崖检测
    const characterManager = sceneManager.getCharacter();
    const physicsManager = sceneManager.getPhysicsWorldManager();

    if (characterManager && physicsManager) {
      // 启用悬崖检测，使用滑动模式
      const activeCharacter = characterManager.getActiveCharacter();
      if (activeCharacter) {
        activeCharacter.setCliffDetection(true, 'slide');
      }

      // 配置检测参数
      physicsManager.setCliffDetectionConfig({
        enabled: true,
        checkDistance: 1.2,        // 前瞻距离
        maxFallDistance: 3.0,      // 最大掉落高度
        safetyMargin: 0.3,         // 安全边距
      });

      console.log('✅ 悬崖检测功能已启用 (滑动模式)');
    }
  }, 1500); // 延迟启用，确保所有组件都已初始化

  // 获取OrbitControlManager（SceneManager内部已创建）
  orbitControlManager = sceneManager.getOrbitControlManager();

  // 设置状态变化回调函数
  orbitControlManager.setStateChangeCallback((isActive, _isManual) => {
    const message = isActive ? doubleControlMessage : singleControlMessage;
    toastManager?.show(message);
    // 同步 UI 状态
    syncUIState();
  });

  // 设置事件监听
  setupEventListeners();

  // 初始同步 UI 状态
  syncUIState();

  // 🔥 新增：应用默认操作模式（双手模式）
  setTimeout(() => {
    onOperationModeChange(currentOperationMode.value);
  }, 100); // 延迟确保所有管理器都已初始化
}

function setupEventListeners() {
  // 键盘事件
  eventManager.on('keydown', ({ key }: { key: string }) => {
    // 更新场景管理器的按键状态
    sceneManager.setKeysPressed(eventManager.keysPressed.value);

    if (key === 'keya' && virtualJoystickRef.value) {
      virtualJoystickRef.value.showEdgeArcFromKeyboard('left', false);
    }
    if (key === 'keyd' && virtualJoystickRef.value) {
      virtualJoystickRef.value.showEdgeArcFromKeyboard('right', false);
    }

    // 🔥 新增：快捷键控制悬崖检测
    if (key === 'keyc' && eventManager.keysPressed.value['shiftleft']) {
      // Shift + C 切换悬崖检测
      const characterManager = sceneManager.getCharacter();
      if (characterManager) {
        const currentStatus = characterManager.getCliffDetectionStatus();
        characterManager.setCliffDetection(!currentStatus.enabled, 'slide');
        toastManager?.show(`悬崖检测: ${!currentStatus.enabled ? '启用' : '禁用'}`);
      }
    }

    if (key === 'keyv' && eventManager.keysPressed.value['shiftleft']) {
      // Shift + V 切换悬崖检测可视化
      if (debugManager) {
        const currentConfig = debugManager.config;
        debugManager.setCliffDetectionVisualization(!currentConfig.showCliffDetection);
        toastManager?.show(`悬崖检测可视化: ${!currentConfig.showCliffDetection ? '启用' : '禁用'}`);
      }
    }
  });

  eventManager.on('keyup', ({ key }: { key: string }) => {
    // 更新场景管理器的按键状态
    sceneManager.setKeysPressed(eventManager.keysPressed.value);

    // 检查键盘激活OrbitControls
    orbitControlManager?.checkKeyboardActivation(eventManager.keysPressed.value);

    if ((key === 'keya' || key === 'keyd') && virtualJoystickRef.value) {
      virtualJoystickRef.value.startEdgeArcFadeOut();
    }

    // 检查自动停用（延迟检查，确保所有按键状态都已更新）- 仅在自动模式下生效
    if (currentOperationMode.value === 'auto') {
      setTimeout(() => {
        orbitControlManager?.checkAutoDeactivation(eventManager.hasAnyInput.bind(eventManager));
      }, 100);
    }
  });

  // 窗口大小变化
  eventManager.on('resize', () => {
    sceneManager.handleResize();
  });

  // 鼠标事件
  eventManager.on('mousedown', (event: MouseEvent) => {
    orbitControlManager?.handleMouseDown(event, eventManager.isInJoystickArea.bind(eventManager));
  });

  eventManager.on('mouseup', (event: MouseEvent) => {
    orbitControlManager?.handleMouseUp(event);

    // 检查自动停用 - 仅在自动模式下生效
    if (currentOperationMode.value === 'auto') {
      setTimeout(() => {
        orbitControlManager?.checkAutoDeactivation(eventManager.hasAnyInput.bind(eventManager));
      }, 100);
    }
  });

  // 触摸事件
  eventManager.on('touchstart', (event: TouchEvent) => {
    orbitControlManager?.handleTouchStart(event, eventManager.isInJoystickArea.bind(eventManager));
  });

  eventManager.on('touchmove', (event: TouchEvent) => {
    orbitControlManager?.handleTouchMove(event);
  });

  eventManager.on('touchend', (event: TouchEvent) => {
    orbitControlManager?.handleTouchEnd(event, eventManager.hasAnyInput.bind(eventManager));

    // 检查自动停用 - 仅在自动模式下生效
    if (currentOperationMode.value === 'auto') {
      setTimeout(() => {
        orbitControlManager?.checkAutoDeactivation(eventManager.hasAnyInput.bind(eventManager));
      }, 100);
    }
  });
}

// 事件处理方法
function onJoystickMove(data: { x: number; y: number; distance: number; edgeRatio?: number }) {
  eventManager.updateJoystickInput(data);
  // 确保edgeRatio存在，如果不存在则设为0
  const joystickData = {
    x: data.x,
    y: data.y,
    distance: data.distance,
    edgeRatio: data.edgeRatio || 0,
  };
  sceneManager.updateJoystick(joystickData);
}

function onTouchDelta(delta: { x: number; y: number }) {
  eventManager.updateTouchDelta(delta);
  sceneManager.updateTouchDelta(delta);
}

function onCameraRotate(rotation: number) {
  eventManager.updateCameraRotation(rotation);
}

function onCameraRotationSpeed(speed: number) {
  sceneManager.updateCameraRotationSpeed(speed);
  // 更新摄像机灵敏度显示
  cameraSensitivity.value = speed;
}

function onOperationModeChange(mode: 'auto' | 'single' | 'dual') {
  console.log(`操作模式切换为: ${mode}`);

  if (!orbitControlManager) return;

  // 更新当前操作模式
  currentOperationMode.value = mode;

  switch (mode) {
    case 'auto':
      // 自动模式：保持当前的自动切换逻辑
      console.log('切换到自动模式');
      break;
    case 'single':
      // 单手模式：强制关闭OrbitControls
      if (uiState.value.isOrbitControlActive) {
        orbitControlManager.deactivate();
      }
      console.log('切换到单手模式');
      toastManager?.show('已切换到单手操作模式');
      break;
    case 'dual':
      // 双手模式：强制开启OrbitControls
      if (!uiState.value.isOrbitControlActive) {
        orbitControlManager.activate(true); // 手动激活
      }
      console.log('切换到双手模式');
      toastManager?.show('已切换到双手操作模式');
      break;
  }

  syncUIState();
}

function onRunToggle(isRunning: boolean) {
  eventManager.toggleJoystickRun(isRunning);
  sceneManager.toggleRun(isRunning);
}

// 跳跃按钮事件处理
function onJumpStart() {
  console.log('🦘 跳跃按钮按下');
  uiState.value.isJumping = true;
  // 通知场景管理器开始跳跃
  if (sceneManager) {
    sceneManager.setJumpPressed(true);
    console.log('🦘 已通知场景管理器开始跳跃');
  }
}

function onJumpEnd() {
  console.log('🦘 跳跃按钮释放');
  uiState.value.isJumping = false;
  // 通知场景管理器结束跳跃
  if (sceneManager) {
    sceneManager.setJumpPressed(false);
    console.log('🦘 已通知场景管理器结束跳跃');
  }
}

// 圈形按钮事件处理
function onOrbitButtonStart() {
  console.log('⭕ 圈形按钮按下 - 开启自动环绕');
  if (orbitControlManager) {
    orbitControlManager.setAutoRotate(true);
  }
}

function onOrbitButtonEnd() {
  console.log('⭕ 圈形按钮释放 - 关闭自动环绕');
  if (orbitControlManager) {
    orbitControlManager.setAutoRotate(false);
  }
}

async function toggleFullscreen() {
  try {
    await fullscreenManager?.toggle();
  } catch (error) {
    toastManager?.show('全屏功能不可用');
  }
}

// 模型选择器相关方法
function toggleModelSelector() {
  uiState.value.showModelSelector = !uiState.value.showModelSelector;
  // 打开选择器时，将选择状态重置为当前使用的模型
  if (uiState.value.showModelSelector) {
    uiState.value.selectedModelId = uiState.value.currentModelId;
  }
}

function closeModelSelector() {
  uiState.value.showModelSelector = false;
}

// 点击卡片选择模型（不立即切换）
function selectModelCard(modelId: string) {
  uiState.value.selectedModelId = modelId;
  console.log(`选择了模型: ${modelId}`);
}

// 确认选择并切换模型
async function confirmModelSelection() {
  const selectedModelId = uiState.value.selectedModelId;

  if (selectedModelId === uiState.value.currentModelId) {
    closeModelSelector();
    return;
  }

  const selectedModel = availableModels.value.find((model) => model.id === selectedModelId);
  if (!selectedModel) {
    toastManager?.show('模型不存在');
    return;
  }

  try {
    toastManager?.show(`正在加载 ${selectedModel.name}...`);

    // 通过场景管理器切换模型（使用模型ID）
    await sceneManager.switchCharacterModel(selectedModelId);

    // 刷新debug可视化（如果开启了角色控制器可视化）
    const debugManager = sceneManager.getDebugManager();
    debugManager.refreshCharacterControllerVisualization();

    uiState.value.currentModelId = selectedModelId;
    toastManager?.show(`${selectedModel.name} 加载成功`);
    closeModelSelector();
  } catch (error) {
    console.error('模型切换失败:', error);
    toastManager?.show(`${selectedModel.name} 加载失败`);
  }
}

// 图片加载错误处理
function onImageError(event: Event) {
  const img = event.target as HTMLImageElement;
  console.warn('模型预览图片加载失败:', img.src);
  // 可以设置一个默认图片
  img.src =
    'data:image/svg+xml;base64,';
}

// Debug事件处理方法
function onDebugConfigChange(config: any) {
  if (debugManager) {
    // 处理特定的配置变化
    if (config.showColliders !== undefined) {
      debugManager.setColliderVisualization(config.showColliders);
    }

    if (config.showCharacterController !== undefined) {
      debugManager.setCharacterControllerVisualization(config.showCharacterController);
    }

    if (config.wireframeMode !== undefined) {
      debugManager.setWireframeMode(config.wireframeMode);
    }

    if (config.showTerrain !== undefined) {
      debugManager.setTerrainVisualization(config.showTerrain);
    }

    // 🔥 新增：悬崖检测可视化
    if (config.showCliffDetection !== undefined) {
      debugManager.setCliffDetectionVisualization(config.showCliffDetection);
    }

    // 更新配置
    Object.assign(debugManager.config, config);
  }

  // 🔥 新增：悬崖检测功能控制
  if (sceneManager?.getCharacter()) {
    const characterManager = sceneManager.getCharacter();

    // 悬崖检测启用/禁用
    if (config.cliffDetectionEnabled !== undefined) {
      characterManager.setCliffDetection(config.cliffDetectionEnabled, config.cliffBehaviorMode || 'slide');
      console.log(`🔧 悬崖检测: ${config.cliffDetectionEnabled ? '启用' : '禁用'}`);
    }

    // 悬崖检测行为模式
    if (config.cliffBehaviorMode !== undefined && config.cliffDetectionEnabled !== false) {
      characterManager.setCliffDetection(true, config.cliffBehaviorMode);
      console.log(`🔧 悬崖检测模式: ${config.cliffBehaviorMode}`);
    }
  }

  // 🔥 新增：物理世界悬崖检测配置
  if (sceneManager?.getPhysicsWorldManager()) {
    const physicsManager = sceneManager.getPhysicsWorldManager();

    if (config.cliffDetectionConfig) {
      physicsManager.setCliffDetectionConfig(config.cliffDetectionConfig);
      console.log('🔧 悬崖检测配置已更新:', config.cliffDetectionConfig);
    }
  }
}

function onLogDebugInfo() {
  if (debugManager) {
    debugManager.logDebugInfo();
  }
}

function onResetPhysics() {
  // 重置角色位置到原点
  const physicsManager = sceneManager?.getPhysicsWorldManager();
  if (physicsManager) {
    // 胶囊体中心位置应该在y=0.85，这样胶囊体底部就在地面上
    physicsManager.setCharacterPosition(new THREE.Vector3(0, 0.85, 0));
    toastManager?.show('物理世界已重置');
  }
}

function cleanup() {
  // 清理所有管理器
  if (eventManager) {
    eventManager.dispose();
  }

  if (orbitControlManager) {
    orbitControlManager.dispose();
  }

  if (toastManager) {
    toastManager.dispose();
  }

  if (fullscreenManager) {
    fullscreenManager.dispose();
  }

  if (sceneManager) {
    sceneManager.dispose();
  }
}
