/**
 * 胶囊体管理器
 * 用于根据角色高度计算和管理胶囊体的尺寸参数
 */

import { CHARACTER_HEIGHT_PRESETS, CAPSULE_RADIUS_RATIO, CAMERA_CONFIG } from './constant/character';

/**
 * 胶囊体参数接口
 */
export interface CapsuleParams {
  radius: number; // 胶囊体半径
  height: number; // 胶囊体高度（不包括两端的半球）
  bottomOffset: number; // 胶囊体底部到中心的偏移（用于模型位置对齐）
}

/**
 * 摄像头参数接口
 */
export interface CameraParams {
  height: number; // 摄像头高度（相对于角色位置）
  distance: number; // 摄像头距离（水平距离）
  forwardDistance: number; // 向前移动时的摄像头距离
  backwardDistance: number; // 向后移动时的摄像头距离
  lookAtOffset: number; // 摄像头看向位置的Y轴偏移
}

/**
 * 胶囊体管理器类
 * 负责计算和管理角色的胶囊体物理参数
 */
export class CapsuleManager {
  /**
   * 静态方法：根据高度创建管理器实例
   * @param targetHeight 目标高度
   * @param useRecommended 是否使用推荐参数
   */
  public static fromHeight(targetHeight: number, useRecommended = false): CapsuleManager {
    return new CapsuleManager(targetHeight, useRecommended);
  }

  /**
   * 静态方法：根据预设创建管理器实例
   * @param preset 预设类型
   * @param useRecommended 是否使用推荐参数
   */
  public static fromPreset(preset: keyof typeof CHARACTER_HEIGHT_PRESETS, useRecommended = false): CapsuleManager {
    return new CapsuleManager(CHARACTER_HEIGHT_PRESETS[preset], useRecommended);
  }

  /**
   * 静态方法：创建默认管理器（1.65m）
   */
  public static createDefault(): CapsuleManager {
    return new CapsuleManager(CHARACTER_HEIGHT_PRESETS.AVERAGE);
  }

  private targetHeight: number;
  private params: CapsuleParams;
  private cameraParams: CameraParams;

  /**
   * 构造函数
   * @param targetHeight 目标角色高度（米），默认1.65m
   * @param useRecommended 是否使用推荐参数（带微调），默认false
   */
  constructor(targetHeight: number = CHARACTER_HEIGHT_PRESETS.AVERAGE, useRecommended = false) {
    this.targetHeight = targetHeight;
    this.params = useRecommended ? this.calculateRecommendedParams() : this.calculateParams();
    this.cameraParams = this.calculateCameraParams();
  }

  /**
   * 获取胶囊体参数
   */
  public getParams(): CapsuleParams {
    return { ...this.params };
  }

  /**
   * 获取胶囊体半径
   */
  public getRadius(): number {
    return this.params.radius;
  }

  /**
   * 获取胶囊体高度（圆柱部分）
   */
  public getHeight(): number {
    return this.params.height;
  }

  /**
   * 获取底部偏移
   */
  public getBottomOffset(): number {
    return this.params.bottomOffset;
  }

  /**
   * 获取目标角色高度
   */
  public getTargetHeight(): number {
    return this.targetHeight;
  }

  /**
   * 获取胶囊体总高度
   */
  public getTotalHeight(): number {
    return this.params.height + 2 * this.params.radius;
  }

  /**
   * 获取摄像头参数
   */
  public getCameraParams(): CameraParams {
    return { ...this.cameraParams };
  }

  /**
   * 获取摄像头高度
   */
  public getCameraHeight(): number {
    return this.cameraParams.height;
  }

  /**
   * 获取摄像头距离
   */
  public getCameraDistance(): number {
    return this.cameraParams.distance;
  }

  /**
   * 获取向前移动时的摄像头距离
   */
  public getCameraForwardDistance(): number {
    return this.cameraParams.forwardDistance;
  }

  /**
   * 获取向后移动时的摄像头距离
   */
  public getCameraBackwardDistance(): number {
    return this.cameraParams.backwardDistance;
  }

  /**
   * 获取摄像头看向位置的偏移
   */
  public getCameraLookAtOffset(): number {
    return this.cameraParams.lookAtOffset;
  }

  /**
   * 更新目标高度并重新计算参数
   * @param newHeight 新的目标高度
   * @param useRecommended 是否使用推荐参数
   */
  public updateHeight(newHeight: number, useRecommended = false): void {
    this.targetHeight = newHeight;
    this.params = useRecommended ? this.calculateRecommendedParams() : this.calculateParams();
    this.cameraParams = this.calculateCameraParams();
  }

  /**
   * 输出参数信息（用于调试）
   */
  public toString(): string {
    return `CapsuleManager(
  角色高度: ${this.targetHeight}m
  胶囊体: 半径=${this.params.radius}m, 圆柱高度=${this.params.height}m, 总高度=${this.getTotalHeight()}m
  摄像头: 高度=${this.cameraParams.height}m, 距离=${this.cameraParams.distance}m, 前进距离=${this.cameraParams.forwardDistance}m, 后退距离=${this.cameraParams.backwardDistance}m
)`;
  }

  /**
   * 计算摄像头参数
   *
   * 根据角色高度自动计算合适的摄像头位置和距离
   * 使用非线性缩放确保不同高度的角色都能获得良好的视角
   *
   * 设计原理:
   * - 高度: 线性缩放，保持视角高度与角色成比例
   * - 距离: 非线性缩放(指数1.3)，高个子角色摄像头更远
   * - 视线偏移: 线性缩放
   */
  private calculateCameraParams(): CameraParams {
    // 计算高度缩放比例
    const heightRatio = this.targetHeight / CAMERA_CONFIG.BASE_HEIGHT;

    // 距离采用非线性缩放: distance = baseDistance * (heightRatio ^ scaleFactor)
    // 这样高个子角色的摄像头会按指数增长，距离更远
    const distanceRatio = Math.pow(heightRatio, CAMERA_CONFIG.DISTANCE_SCALE_FACTOR);

    return {
      // 高度线性缩放
      height: Number((CAMERA_CONFIG.BASE_CAMERA_HEIGHT * heightRatio).toFixed(2)),

      // 距离非线性缩放
      distance: Number((CAMERA_CONFIG.BASE_CAMERA_DISTANCE * distanceRatio).toFixed(2)),
      forwardDistance: Number((CAMERA_CONFIG.BASE_FORWARD_DISTANCE * distanceRatio).toFixed(2)),
      backwardDistance: Number((CAMERA_CONFIG.BASE_BACKWARD_DISTANCE * distanceRatio).toFixed(2)),

      // 视线偏移线性缩放
      lookAtOffset: Number((CAMERA_CONFIG.BASE_LOOK_AT_OFFSET * heightRatio).toFixed(2)),
    };
  }

  /**
   * 根据角色目标高度计算胶囊体参数
   *
   * 设计原理:
   * - 胶囊体总高度 = 胶囊体圆柱高度 + 2 * 半径
   * - 胶囊体总高度应该与角色高度一致
   * - 胶囊体半径约为角色高度的 0.21（经验值，确保合理的体型比例）
   *
   * @returns 胶囊体参数
   */
  private calculateParams(): CapsuleParams {
    // 胶囊体总高度等于角色高度
    const capsuleTotalHeight = this.targetHeight;

    // 胶囊体半径约为角色高度的21%（符合人体比例）
    const radius = this.targetHeight * CAPSULE_RADIUS_RATIO;

    // 胶囊体圆柱部分高度 = 总高度 - 2 * 半径
    const height = capsuleTotalHeight - 2 * radius;

    // 底部偏移 = 圆柱高度的一半 + 半径（从中心到底部的距离）
    const bottomOffset = height / 2 + radius;

    return {
      radius: Number(radius.toFixed(2)),
      height: Number(height.toFixed(2)),
      bottomOffset: Number(bottomOffset.toFixed(2)),
    };
  }

  /**
   * 计算推荐的胶囊体参数（带调整）
   *
   * 这个方法提供了一些基于实践经验的微调
   *
   * @returns 胶囊体参数
   */
  private calculateRecommendedParams(): CapsuleParams {
    const baseParams = this.calculateParams();

    // 对不同高度的角色应用经验性调整
    if (this.targetHeight > 2.0) {
      // 较高的角色稍微增加半径
      baseParams.radius *= 1.1;
    } else if (this.targetHeight < 1.5) {
      // 较矮的角色稍微减少半径
      baseParams.radius *= 0.9;
    }

    return {
      radius: Number(baseParams.radius.toFixed(2)),
      height: Number(baseParams.height.toFixed(2)),
      bottomOffset: Number(baseParams.bottomOffset.toFixed(2)),
    };
  }
}

// ============================================
// 向后兼容的导出函数（保持与旧代码兼容）
// ============================================

/**
 * 根据角色目标高度计算胶囊体参数
 * @deprecated 建议使用 CapsuleManager 类
 */
export function calculateCapsuleParams(targetHeight = 1.65): CapsuleParams {
  const manager = new CapsuleManager(targetHeight);
  return manager.getParams();
}

/**
 * 根据角色高度获取推荐的胶囊体参数（带调整）
 * @deprecated 建议使用 CapsuleManager 类
 */
export function getRecommendedCapsuleParams(targetHeight = 1.65): CapsuleParams {
  const manager = new CapsuleManager(targetHeight, true);
  return manager.getParams();
}

/**
 * 获取默认胶囊体参数（基于1.65m身高）
 * @deprecated 建议使用 CapsuleManager.createDefault()
 */
export function getDefaultCapsuleParams(): CapsuleParams {
  return CapsuleManager.createDefault().getParams();
}
