import * as THREE from 'three';
import { GaussianComponentClass, GaussianComponentType, SplatConfig } from '../../../../types';
import { SparkComponent } from './spark-component';
import { GaussianSplats3DComponent } from './gaussian-splats-3d-component';
import { getRotationMatrix } from '../../../../utils';
import { GaussianAbstractComponent } from './gaussian-abstract-component';

export class GaussianComponent {
  static type: GaussianComponentType;
  static config: SplatConfig;
  static component: any;
  static create<T extends GaussianComponentType>(
    type: T,
    config: SplatConfig,
    globalScene: THREE.Scene,
  ): GaussianComponentClass[T] {
    this.type = type;
    this.config = config;
    const viewerOptions = this.getViewerOptions();

    switch (this.config.gaussianComponentType) {
      case GaussianComponentType.Spark:
        console.log('创建 SparkComponent');
        this.component = new SparkComponent(viewerOptions, globalScene);
        break;

      case GaussianComponentType.GaussianSplats3D:
        console.log('创建 GaussianSplats3DComponent');
        this.component = new GaussianSplats3DComponent(viewerOptions, globalScene);
        break;

      default:
        throw new Error(`Unknown gaussian component type: ${this.config.gaussianComponentType}`);
    }
    return this.component;
  }

  static getViewerOptions() {
    let options = {};
    switch (this.config.gaussianComponentType) {
      case GaussianComponentType.Spark:
        options = {
          ...this.config.sparkOption,
        };
        break;

      case GaussianComponentType.GaussianSplats3D:
        options = {
          ...this.config.gaussianSplats3DOption,
        };
        break;
      default:
        throw new Error(`Unknown gaussian component type: ${this.config.gaussianComponentType}`);
        break;
    }
    if (this.config?.transform?.rotation) {
      this.config.transform.rotation = getRotationMatrix(this.config.transform.rotation)!;
    }
    return options;
  }
}
