import * as THREE from 'three';
import { GaussianSplatLoadStrategy } from './gaussian-splat-load-strategy';
import { SingleSceneStrategy } from './single-scene-strategy';
import { RegionReplaceStrategy } from './region-replace-strategy';
import { SplatConfig } from '../../../../types';
import { PhysicsWorldManager } from '../physics-world-manager';

/**
 * 策略类型枚举
 */
export enum GaussianSplatStrategyType {
  SingleScene = 'single-scene',
  RegionReplace = 'region-replace',
}

/**
 * 高斯泼溅策略管理器
 * 负责创建和管理不同的加载策略
 */
export class GaussianSplatStrategyManager {
  private scene: THREE.Scene;
  private currentStrategy: GaussianSplatLoadStrategy | null = null;
  private strategyType: GaussianSplatStrategyType | null = null;
  private physicsWorldManager: PhysicsWorldManager | null = null;

  constructor(scene: THREE.Scene, physicsWorldManager?: PhysicsWorldManager) {
    this.scene = scene;
    this.physicsWorldManager = physicsWorldManager || null;
  }

  /**
   * 根据配置自动创建策略
   */
  createStrategy(config: SplatConfig): GaussianSplatLoadStrategy {
    // 如果已有策略，先卸载
    if (this.currentStrategy) {
      this.currentStrategy.dispose();
      this.currentStrategy = null;
    }
    // 根据配置判断使用哪种策略
    if (config.singleSceneConfigPath) {
      console.log('使用 SingleSceneStrategy');
      this.strategyType = GaussianSplatStrategyType.SingleScene;
      this.currentStrategy = new SingleSceneStrategy(this.scene, config);
      return this.currentStrategy;
    }
    if (config.regionReplaceConfigPath) {
      console.log('使用 RegionReplaceStrategy');
      this.strategyType = GaussianSplatStrategyType.RegionReplace;
      // 传递 PhysicsWorldManager 给 RegionReplaceStrategy
      this.currentStrategy = new RegionReplaceStrategy(this.scene, config, this.physicsWorldManager || undefined);
      return this.currentStrategy;
    }
    throw new Error('No valid strategy config found. Please provide singleSceneConfigPath or regionReplaceConfigPath');
  }

  setEnablePreloadNearest(enable: boolean): void {
    if (this.currentStrategy instanceof RegionReplaceStrategy) {
      this.currentStrategy.setEnablePreloadNearest(enable);
    }
  }

  /**
   * 更新当前策略
   */
  update(): void {
    if (this.currentStrategy) {
      this.currentStrategy.update();
    }
  }

  /**
   * 获取当前策略
   */
  getCurrentStrategy(): GaussianSplatLoadStrategy | null {
    return this.currentStrategy;
  }

  /**
   * 获取当前策略类型
   */
  getStrategyType(): GaussianSplatStrategyType | null {
    return this.strategyType;
  }

  /**
   * 获取viewer实例
   */
  getViewer(): any {
    return this.currentStrategy?.getViewer();
  }

  /**
   * 设置角色位置（用于RegionReplaceStrategy）
   */
  setCharacterPosition(position: THREE.Vector3): void {
    if (this.currentStrategy instanceof RegionReplaceStrategy) {
      this.currentStrategy.setCharacterPosition(position);
    }
  }

  /**
   * 清理资源
   */
  dispose(): void {
    if (this.currentStrategy) {
      this.currentStrategy.dispose();
      this.currentStrategy = null;
    }
    this.strategyType = null;
  }
}
