import { AbortablePromise } from '@/utils/abortable-promise';
import { fetchWithProgress } from '@/utils/fetch-with-progress';

/**
 * 文件下载状态
 */
export enum FileLoadStatus {
  IDLE = 'idle', // 空闲
  DOWNLOADING = 'downloading', // 下载中
  COMPLETED = 'completed', // 已完成
  ABORTED = 'aborted', // 已中断
  ERROR = 'error', // 错误
}

/**
 * 文件下载任务
 */
interface FileLoadTask {
  url: string; // 文件 URL
  status: FileLoadStatus; // 下载状态
  progress: number; // 下载进度 (0-100)
  data: ArrayBuffer | null; // 下载的数据
  error: Error | null; // 错误信息
  downloadPromise: AbortablePromise | null; // 中断控制器
  startTime: number; // 开始时间
  endTime: number | null; // 结束时间
  waitingCallbacks: Array<{
    // 等待的回调函数
    resolve: (data: ArrayBuffer) => void;
    reject: (error: Error) => void;
  }>;
}

/**
 * 下载进度回调
 */
export type ProgressCallback = (progress: number, loaded: number, total: number) => void;

/**
 * 下载选项
 */
export interface FileLoadOptions {
  priority?: number; // 优先级（数字越大优先级越高）
  onProgress?: ProgressCallback; // 进度回调
  timeout?: number; // 超时时间（毫秒）
  retryCount?: number; // 重试次数
  cacheEnabled?: boolean; // 是否启用缓存
}

/**
 * 文件加载管理器
 * 支持预下载、中断下载、请求队列管理和缓存
 */
export class FileLoaderManager {
  private tasks: Map<string, FileLoadTask> = new Map(); // 下载任务映射
  private cache: Map<string, ArrayBuffer> = new Map(); // 文件缓存
  private maxConcurrent: number; // 最大并发下载数
  private currentDownloading = 0; // 当前下载数
  private queue: Array<{ url: string; options: FileLoadOptions }> = []; // 下载队列

  /**
   * 构造函数
   * @param maxConcurrent 最大并发下载数，默认为 6
   */
  constructor(maxConcurrent = 6) {
    this.maxConcurrent = maxConcurrent;
  }

  /**
   * 设置最大并发下载数
   * @param maxConcurrent 最大并发数
   */
  setMaxConcurrent(maxConcurrent: number): void {
    if (maxConcurrent < 1) {
      maxConcurrent = 1;
    }

    const oldValue = this.maxConcurrent;
    this.maxConcurrent = maxConcurrent;

    // 如果增加了并发数，尝试处理队列中的任务
    if (maxConcurrent > oldValue) {
      this.processQueue();
    }
  }

  /**
   * 获取最大并发下载数
   */
  getMaxConcurrent(): number {
    return this.maxConcurrent;
  }

  /**
   * 获取当前正在下载的文件数
   */
  getCurrentDownloading(): number {
    return this.currentDownloading;
  }

  /**
   * 批量取消下载
   * @param urls 要取消的文件 URL 数组
   */
  abortBatch(urls: string[]): void {
    urls.forEach((url) => this.abort(url));
  }

  /**
   * 预加载文件
   * @param url 文件 URL
   * @param options 下载选项
   * @returns Promise<ArrayBuffer>
   */
  async load(url: string, options: FileLoadOptions = {}): Promise<ArrayBuffer | void> {
    // 检查缓存
    if (options.cacheEnabled === true && this.cache.has(url)) {
      console.log(`📦 从缓存加载文件: ${url}`);
      return this.cache.get(url)!;
    }

    // 检查是否已有任务
    const existingTask = this.tasks.get(url);

    if (existingTask) {
      // 如果任务已完成，直接返回数据
      if (existingTask.status === FileLoadStatus.COMPLETED && existingTask.data) {
        console.log(`✅ 文件已下载完成: ${url}`);
        return existingTask.data;
      }

      // 如果任务正在下载，等待下载完成
      if (existingTask.status === FileLoadStatus.DOWNLOADING) {
        console.log(`✅ 文件正在下载: ${url}`);
        return new Promise<ArrayBuffer>((resolve, reject) => {
          existingTask.waitingCallbacks.push({ resolve, reject });
        });
      }

      // 如果任务已中断或出错
      if (existingTask.status === FileLoadStatus.ABORTED || existingTask.status === FileLoadStatus.ERROR) {
        this.tasks.delete(url);
      }
    }

    // 创建新任务
    return this.startDownload(url, options);
  }

  /**
   * 中断文件下载
   * @param url 文件 URL
   * @returns 是否成功中断
   */
  abort(url: string): boolean {
    const task = this.tasks.get(url);
    if (!task) {
      console.warn(`⚠️  未找到下载任务: ${url}`);
      return false;
    }

    if (task.status !== FileLoadStatus.DOWNLOADING) {
      console.warn(`⚠️  任务不在下载中: ${url} (状态: ${task.status})`);
      return false;
    }

    // 中断下载
    task.downloadPromise?.abort(`abort ${url}`);
    task.status = FileLoadStatus.ABORTED;
    task.endTime = Date.now();

    // 通知所有等待的回调
    const error = new Error(`下载已中断: ${url}`);
    task.waitingCallbacks.forEach((cb) => cb.reject(error));
    task.waitingCallbacks = [];

    this.tasks.delete(url);

    // 处理队列中的下一个任务
    this.processQueue();

    return true;
  }

  /**
   * 中断所有下载
   */
  abortAll(): void {
    this.tasks.forEach((task, url) => {
      if (task.status === FileLoadStatus.DOWNLOADING) {
        this.abort(url);
      }
    });

    // 清空队列
    this.queue = [];
  }

  /**
   * 获取文件下载状态
   * @param url 文件 URL
   * @returns 下载状态
   */
  getStatus(url: string): FileLoadStatus | null {
    return this.tasks.get(url)?.status || null;
  }

  /**
   * 获取文件下载进度
   * @param url 文件 URL
   * @returns 下载进度 (0-100)
   */
  getProgress(url: string): number {
    return this.tasks.get(url)?.progress || 0;
  }

  /**
   * 检查文件是否已缓存
   * @param url 文件 URL
   * @returns 是否已缓存
   */
  isCached(url: string): boolean {
    return this.cache.has(url);
  }

  /**
   * 从缓存中获取文件
   * @param url 文件 URL
   * @returns 文件数据，如果不存在则返回 null
   */
  getFromCache(url: string): ArrayBuffer | null {
    return this.cache.get(url) || null;
  }

  /**
   * 清除指定文件的缓存
   * @param url 文件 URL
   */
  clearCache(url: string): void {
    this.cache.delete(url);
  }

  /**
   * 清除所有缓存
   */
  clearAllCache(): void {
    const { size } = this.cache;
    this.cache.clear();
  }

  /**
   * 获取缓存大小（字节）
   */
  getCacheSize(): number {
    let size = 0;
    this.cache.forEach((data) => {
      size += data.byteLength;
    });
    return size;
  }

  /**
   * 获取缓存统计信息
   */
  getCacheStats(): {
    count: number;
    size: number;
    sizeInMB: number;
  } {
    const size = this.getCacheSize();
    return {
      count: this.cache.size,
      size,
      sizeInMB: size / 1024 / 1024,
    };
  }

  /**
   * 获取所有任务的状态
   */
  getAllTasksStatus(): Array<{
    url: string;
    status: FileLoadStatus;
    progress: number;
  }> {
    const result: Array<{ url: string; status: FileLoadStatus; progress: number }> = [];

    this.tasks.forEach((task, url) => {
      result.push({
        url,
        status: task.status,
        progress: task.progress,
      });
    });

    return result;
  }

  /**
   * 获取调试信息
   */
  getDebugInfo(): {
    currentDownloading: number;
    maxConcurrent: number;
    queueLength: number;
    tasksCount: number;
    cacheStats: ReturnType<FileLoaderManager['getCacheStats']>;
  } {
    return {
      currentDownloading: this.currentDownloading,
      maxConcurrent: this.maxConcurrent,
      queueLength: this.queue.length,
      tasksCount: this.tasks.size,
      cacheStats: this.getCacheStats(),
    };
  }

  /**
   * 清理已完成或已中断的任务
   */
  cleanup(): void {
    const toDelete: string[] = [];

    this.tasks.forEach((task, url) => {
      if (
        task.status === FileLoadStatus.COMPLETED ||
        task.status === FileLoadStatus.ABORTED ||
        task.status === FileLoadStatus.ERROR
      ) {
        toDelete.push(url);
      }
    });

    toDelete.forEach((url) => this.tasks.delete(url));
  }

  /**
   * 销毁管理器
   */
  dispose(): void {
    this.abortAll();
    this.clearAllCache();
    this.tasks.clear();
    this.queue = [];
  }

  /**
   * 开始下载文件
   */
  private async startDownload(url: string, options: FileLoadOptions): Promise<ArrayBuffer> {
    // 检查并发限制
    if (this.currentDownloading >= this.maxConcurrent) {
      return new Promise<ArrayBuffer>((resolve, reject) => {
        this.queue.push({ url, options });
        // 按优先级排序队列
        this.queue.sort((a, b) => (b.options.priority || 0) - (a.options.priority || 0));

        // 创建任务并添加回调
        const task = this.createTask(url);
        task.waitingCallbacks.push({ resolve, reject });
      });
    }

    // 创建下载任务
    const task = this.createTask(url);
    this.tasks.set(url, task);
    this.currentDownloading += 1;

    return new Promise<ArrayBuffer>(async (resolve, reject) => {
      task.waitingCallbacks.push({ resolve, reject });
      let timeoutId: number | null = null;
      try {
        // 设置超时
        const timeout = options.timeout || 60000;
        timeoutId = setTimeout(() => {
          task.downloadPromise?.abort(`timeout ${url}`);
          const error = new Error(`下载超时: ${url}`);
          this.handleDownloadError(task, error);
        }, timeout);

        // 发起请求
        const downloadPromise = fetchWithProgress(
          url,
          (percent, percentLabel, chunk, fileSize) => {
            // 更新任务进度
            task.progress = percent || 0;

            // 调用用户提供的进度回调
            if (options.onProgress) {
              const loaded = fileSize ? (fileSize * (percent || 0)) / 100 : 0;
              options.onProgress(percent || 0, loaded, fileSize || 0);
            }
          },
          false,
          {},
        );
        task.downloadPromise = downloadPromise;

        // 等待下载完成
        const result = await downloadPromise.promise;

        clearTimeout(timeoutId);

        // 下载成功
        task.status = FileLoadStatus.COMPLETED;
        task.data = result;
        task.endTime = Date.now();

        // 通知所有等待的回调
        task.waitingCallbacks.forEach((cb) => cb.resolve(task.data!));
        task.waitingCallbacks = [];

        this.tasks.delete(url);
        console.log(`✅ 文件下载完成: ${url} 耗时: ${Date.now() - task.startTime}ms)`);

        // 处理队列中的下一个任务
        this.processQueue();
      } catch (error) {
        timeoutId && clearTimeout(timeoutId);

        if (error instanceof Error) {
          // 检查是否是中断错误
          if (error.name === 'AbortError' || error.constructor.name === 'AbortedPromiseError') {
            task.status = FileLoadStatus.ABORTED;
            task.endTime = Date.now();

            // 通知所有等待的回调（中断错误）
            const abortError = new Error(`下载已中断: ${url}`);
            abortError.name = 'AbortError';
            task.waitingCallbacks.forEach((cb) => cb.reject(abortError));
            task.waitingCallbacks = [];

            this.tasks.delete(url);
          } else {
            this.handleDownloadError(task, error);
          }
        } else {
          this.handleDownloadError(task, new Error(String(error)));
        }

        console.warn(`❌ 下载失败: ${url}`, error);

        // 处理队列中的下一个任务
        this.processQueue();
      }
    });
  }

  /**
   * 创建下载任务
   */
  private createTask(url: string): FileLoadTask {
    return {
      url,
      status: FileLoadStatus.DOWNLOADING,
      progress: 0,
      data: null,
      error: null,
      downloadPromise: null,
      startTime: Date.now(),
      endTime: null,
      waitingCallbacks: [],
    };
  }

  /**
   * 处理下载错误
   */
  private handleDownloadError(task: FileLoadTask, error: Error): void {
    task.status = FileLoadStatus.ERROR;
    task.error = error;
    task.endTime = Date.now();

    // 通知所有等待的回调
    task.waitingCallbacks.forEach((cb) => cb.reject(error));
    task.waitingCallbacks = [];
    this.tasks.delete(task.url);

    // 处理队列中的下一个任务
    this.processQueue();
  }

  /**
   * 处理队列中的下一个任务
   */
  private processQueue(): void {
    this.currentDownloading -= 1;

    // 尝试启动队列中的任务，直到达到并发限制
    while (this.queue.length > 0 && this.currentDownloading < this.maxConcurrent) {
      const next = this.queue.shift();
      if (next) {
        this.startDownload(next.url, next.options);
      }
    }
  }
}

// 导出单例实例（默认并发数为 6）
export const fileLoaderManager = new FileLoaderManager(6);

/**
 * 创建自定义配置的文件加载管理器
 * @param maxConcurrent 最大并发下载数
 * @returns FileLoaderManager 实例
 */
export function createFileLoaderManager(maxConcurrent: number): FileLoaderManager {
  return new FileLoaderManager(maxConcurrent);
}
