/**
 * 动画状态机
 * 用于管理角色动画状态的转换逻辑
 */

// 动画状态枚举
export enum AnimationState {
  IDLE = 'Idle',
  WALKING = 'Walking', // 行走状态（速度较慢）
  RUNNING = 'Running',
  FALLING = 'Falling',
  JUMPING = 'Jumping', // 启用跳跃状态
  // 可以扩展更多状态
  // ATTACKING = 'Attacking',
}

// 转移条件接口
export interface TransitionCondition {
  name: string;
  check: (context: AnimationContext) => boolean;
  priority?: number; // 优先级，数字越大优先级越高
}

// 动画上下文 - 包含所有用于判断状态转移的信息
export interface AnimationContext {
  // 物理状态
  isGrounded: boolean;
  isJumping: boolean;

  // 输入状态
  hasMovementInput: boolean;
  forwardInput: number;
  strafeInput: number;
  jumpPressed: boolean;

  // 当前状态信息
  currentState: AnimationState;
  stateTime: number; // 当前状态持续时间

  // 速度信息
  currentVelocity?: number; // 当前移动速度

  // 其他可扩展的状态
  [key: string]: any;
}

// 状态转移定义
export interface StateTransition {
  from: AnimationState;
  to: AnimationState;
  condition: TransitionCondition;
}

// 状态定义
export interface StateDefinition {
  name: AnimationState;
  onEnter?: (context: AnimationContext) => void;
  onExit?: (context: AnimationContext) => void;
  onUpdate?: (context: AnimationContext, deltaTime: number) => void;
}

