export class AnimationStateMachine {
  private currentState: AnimationState = AnimationState.IDLE;
  private states: Map<AnimationState, StateDefinition> = new Map();
  private transitions: StateTransition[] = [];
  private stateStartTime = 0;
  private context: AnimationContext;

  // 状态变化回调
  private onStateChangeCallback?: (from: AnimationState, to: AnimationState) => void;

  constructor() {
    this.context = this.createDefaultContext();
    this.initializeStatesFromConfig();
    this.initializeTransitionsFromConfig();
  }

  /**
   * 添加状态定义
   */
  addState(state: StateDefinition): void {
    this.states.set(state.name, state);
  }

  /**
   * 添加状态转移
   */
  addTransition(transition: StateTransition): void {
    this.transitions.push(transition);
    // 按优先级排序
    this.transitions.sort((a, b) => (b.condition.priority || 0) - (a.condition.priority || 0));
  }

  /**
   * 更新上下文
   */
  updateContext(newContext: Partial<AnimationContext>): void {
    this.context = { ...this.context, ...newContext };
    this.context.currentState = this.currentState;
    this.context.stateTime = performance.now() - this.stateStartTime;
  }

  /**
   * 更新状态机
   */
  update(deltaTime: number): AnimationState {
    // 更新当前状态
    const currentStateDefinition = this.states.get(this.currentState);
    if (currentStateDefinition?.onUpdate) {
      currentStateDefinition.onUpdate(this.context, deltaTime);
    }

    // 检查状态转移
    for (const transition of this.transitions) {
      if (transition.from === this.currentState) {
        if (transition.condition.check(this.context)) {
          this.transitionTo(transition.to);
          break; // 找到第一个满足条件的转移就执行
        }
      }
    }

    return this.currentState;
  }

  /**
   * 强制转移到指定状态
   */
  transitionTo(newState: AnimationState): void {
    if (newState === this.currentState) {
      return; // 相同状态不需要转移
    }

    const oldState = this.currentState;

    // 执行当前状态的退出逻辑
    const currentStateDefinition = this.states.get(this.currentState);
    if (currentStateDefinition?.onExit) {
      currentStateDefinition.onExit(this.context);
    }

    // 切换状态
    this.currentState = newState;
    this.stateStartTime = performance.now();

    // 执行新状态的进入逻辑
    const newStateDefinition = this.states.get(newState);
    if (newStateDefinition?.onEnter) {
      newStateDefinition.onEnter(this.context);
    }

    // 触发状态变化回调
    if (this.onStateChangeCallback) {
      this.onStateChangeCallback(oldState, newState);
    }

    // console.log(`🔄 状态转移: ${oldState} -> ${newState}`);
  }

  /**
   * 获取当前状态
   */
  getCurrentState(): AnimationState {
    return this.currentState;
  }

  /**
   * 获取当前状态持续时间
   */
  getStateTime(): number {
    return performance.now() - this.stateStartTime;
  }

  /**
   * 设置状态变化回调
   */
  onStateChange(callback: (from: AnimationState, to: AnimationState) => void): void {
    this.onStateChangeCallback = callback;
  }

  /**
   * 获取所有可能的转移
   */
  getAvailableTransitions(): StateTransition[] {
    return this.transitions.filter((t) => t.from === this.currentState);
  }

  /**
   * 调试信息
   */
  getDebugInfo(): any {
    return {
      currentState: this.currentState,
      stateTime: this.getStateTime(),
      context: this.context,
      availableTransitions: this.getAvailableTransitions().map((t) => ({
        to: t.to,
        condition: t.condition.name,
        canTransition: t.condition.check(this.context),
      })),
    };
  }

  /**
   * 创建默认上下文
   */
  private createDefaultContext(): AnimationContext {
    return {
      isGrounded: true,
      isJumping: false,
      hasMovementInput: false,
      forwardInput: 0,
      strafeInput: 0,
      jumpPressed: false,
      currentState: AnimationState.IDLE,
      stateTime: 0,
    };
  }
  /**
   * 从配置初始化状态转换规则
   */
  private initializeTransitionsFromConfig(): void {
    DEFAULT_TRANSITIONS.forEach((transition) => {
      this.addTransition(transition);
    });
  }

  /**
   * 从配置初始化状态定义
   */
  private initializeStatesFromConfig(): void {
    DEFAULT_STATES.forEach((state) => {
      this.addState(state);
    });
  }
}
