import * as THREE from 'three';
import { GaussianSplatLoadStrategy } from './gaussian-splat-load-strategy';
import { SplatConfig, RegionReplaceConfig, RegionModule } from '../../../../types';
import { PhysicsWorldManager } from '../physics-world-manager';
import { GaussianComponent } from '../components/gaussian-component';
import { GaussianAbstractComponent } from '../components';
import { LoaderStatus } from '../components/gaussian-abstract-component';
import { fileLoaderManager } from '../../../managers/file-loader-manager';

const MORTON_FILE_TYPE = '_config.json';

/**
 * 区域模块信息
 */
interface ModuleInfo {
  module: RegionModule;
  viewer: GaussianAbstractComponent<unknown> | null; // 存储该区域的 viewer
  sceneId: string | null;
  isLoaded: boolean;
}

/**
 * 区域替换加载策略
 * 根据用户位置动态加载/卸载场景
 * 用户进入区域时加载该区域的场景，存储在 viewers 中
 * 用户离开区域时卸载该区域的场景
 * 自动预加载距离最近的4个模块
 */

export class RegionReplaceStrategy extends GaussianSplatLoadStrategy {
  private regionConfig: RegionReplaceConfig | null = null;
  private viewers: Map<string, GaussianAbstractComponent<unknown>> = new Map(); // 存储每个区域的 viewer
  private moduleInfos: Map<string, ModuleInfo> = new Map(); // 模块信息映射
  private currentModuleIds: Set<string> = new Set(); // 当前用户所在的区域ID集合
  private characterPosition: THREE.Vector3 = new THREE.Vector3();
  private lastCheckTime = 0;
  private checkInterval = 300; // 检查间隔（毫秒）
  private physicsWorldManager: PhysicsWorldManager | null = null;

  private isLoading = false;
  private airWallIds: string[] = []; // 存储空气墙的碰撞体ID

  private physicsWorldBoxTag = 'region_replace-airwall';
  private enablePreloadNearest = false; // 标记是否已加载第一个场景

  // 预加载管理

  private prepareToPreloadedModuleIds: Set<string> = new Set(); // 当前预加载的模块ID集合
  private preloadedModuleIds: Set<string> = new Set(); // 已完成加载
  private preloadingPromises: Map<string, Promise<ArrayBuffer | void>> = new Map(); // 正在下载的 Promise 缓存

  constructor(scene: THREE.Scene, config: SplatConfig, physicsWorldManager?: PhysicsWorldManager) {
    super(scene, config);
    this.physicsWorldManager = physicsWorldManager || null;
  }

  // setPhysicsWorldManager(physicsWorldManager: PhysicsWorldManager): void {
  //   this.physicsWorldManager = physicsWorldManager;
  // }

  setEnablePreloadNearest(enable: boolean): void {
    this.enablePreloadNearest = enable;
  }

  /**
   * 加载场景（创建所有区域的碰撞体）
   */
  async load(): Promise<void> {
    try {
      // 1. 加载配置文件
      await this.loadRegionReplaceConfig();

      if (!this.regionConfig?.modules.length) {
        throw new Error('No modules defined in config');
      }
      // 2. 初始化模块信息
      this.initializeModuleInfos();
    } catch (error) {
      console.error('RegionReplaceStrategy: 加载失败', error);
      this.dispose();
      throw error;
    }
  }

  /**
   * 卸载场景
   */
  dispose(): void {
    // 移除所有空气墙
    this.removeAirWalls();

    // 卸载所有已加载的 viewers
    this.viewers.forEach((viewer, moduleId) => {
      console.log(`🗑️ 卸载区域场景: ${moduleId}`);
      viewer.dispose();
    });
    this.viewers.clear();

    // 清理模块信息

    this.moduleInfos.clear();
    this.currentModuleIds.clear();
    this.preloadingPromises.clear();
    this.regionConfig = null;
  }

  /**
   * 更新策略（检查角色位置，必要时加载/卸载区域）
   */
  update(): void {
    if (!this.regionConfig || !this.physicsWorldManager) return;

    // 限制检查频率
    const now = Date.now();
    if (now - this.lastCheckTime < this.checkInterval) {
      return;
    }
    this.lastCheckTime = now;

    // 使用传统的位置检测
    this.checkRegionsWithPosition();
  }

  /**
   * 设置角色位置（供外部调用）
   */
  setCharacterPosition(position: THREE.Vector3): void {
    this.characterPosition.copy(position);
  }

  /**
   * 获取当前所在的模块ID列表
   */
  getCurrentModuleIds(): string[] {
    return Array.from(this.currentModuleIds);
  }

  /**
   * 获取已加载的场景数量
   */
  getLoadedSceneCount(): number {
    return this.viewers.size;
  }

  /**
   * 获取所有模块列表
   */
  getModules(): RegionModule[] {
    return this.regionConfig?.modules || [];
  }

  /**
   * 加载区域替换配置文件
   */
  private async loadRegionReplaceConfig(): Promise<void> {
    if (!this.config.regionReplaceConfigPath) {
      throw new Error('regionReplaceConfigPath is required for RegionReplaceStrategy');
    }

    try {
      const response = await fetch(this.config.regionReplaceConfigPath);
      if (!response.ok) {
        throw new Error(`Failed to load config: ${response.statusText}`);
      }
      this.regionConfig = await response.json();
      const { baseUrl } = this.regionConfig!;
      this.regionConfig?.modules.forEach((module) => {
        module.url = baseUrl + module.name + (`.${this.regionConfig?.fileType}` || '.splat');
        if (this.regionConfig?.morton) {
          module.mortonConfig = baseUrl + module.name + MORTON_FILE_TYPE;
        }
      });
    } catch (error) {
      console.error('加载区域替换配置失败:', error);
      throw error;
    }
  }

  /**
   * 创建viewer组件（根据gaussianComponentType）
   */
  private createViewer() {
    return GaussianComponent.create(this.config.gaussianComponentType, this.config, this.scene);
  }

  /**
   * 初始化所有模块信息
   */
  private initializeModuleInfos(): void {
    if (!this.regionConfig) return;

    for (const module of this.regionConfig.modules) {
      this.moduleInfos.set(module.name, {
        module,
        viewer: null,
        sceneId: null,
        isLoaded: false,
      });
    }
  }

  /**
   * 使用简单距离计算检查所有区域
   * 检测用户进入/离开哪些区域，并加载/卸载对应的场景
   * 规则：
   * 1. 如果用户在多个区域内，只加载距离最近的那个场景
   * 2. 保持至少有一个场景存在，不能全部清空
   * 3. 自动预加载距离最近的4个模块
   */
  private async checkRegionsWithPosition(): Promise<void> {
    if (!this.physicsWorldManager || this.isLoading || !this.config) return;

    // if (this.isLoading) return;
    this.isLoading = true;

    let characterPosition = this.physicsWorldManager.getCharacterPosition();

    if (characterPosition.x === 0 && characterPosition.y === 0 && characterPosition.z === 0 && this.config.startPoint) {
      characterPosition = this.config.startPoint;
    }
    const regionsWithDistance: Array<{ moduleId: string; distance: number; module: RegionModule }> = [];

    // 检查用户在哪些区域内，并计算距离
    this.moduleInfos.forEach((info, moduleId) => {
      const isInRegion = this.isPositionInModule(characterPosition, info.module);

      if (isInRegion) {
        // 计算用户到区域中心的距离
        const distance = this.getDistanceToModuleCenter(characterPosition, info.module);
        regionsWithDistance.push({
          moduleId,
          distance,
          module: info.module,
        });
      }
    });

    // 如果用户在多个区域内，按距离排序，只保留最近的那个
    let targetModuleId: string | null = null;
    let targetModule: RegionModule | null = null;

    if (regionsWithDistance.length > 0) {
      // 按距离排序（从近到远）
      regionsWithDistance.sort((a, b) => a.distance - b.distance);

      // 只加载最近的那个区域
      targetModuleId = regionsWithDistance[0].moduleId;
      targetModule = regionsWithDistance[0].module;
    }

    // 计算所有模块到用户的距离，找出最近的4个模块（用于预加载）
    let nearestModules: Array<{ moduleId: string; module: RegionModule; distance: number }> = [];

    if (targetModule) {
      const allModulesWithDistance: Array<{ moduleId: string; module: RegionModule; distance: number }> = [];

      // 计算所有模块到用户的距离
      this.moduleInfos.forEach((info, moduleId) => {
        const distance = this.getDistanceToModuleCenter(characterPosition, info.module);
        allModulesWithDistance.push({
          moduleId,
          module: info.module,
          distance,
        });
      });

      // 按距离排序，取最近的4个
      nearestModules = allModulesWithDistance.sort((a, b) => a.distance - b.distance).slice(0, 5);
    }

    // 处理场景加载/卸载
    if (targetModuleId && targetModule) {
      // 如果目标区域未加载，则加载它
      if (!this.currentModuleIds.has(targetModuleId)) {
        const info = this.moduleInfos.get(targetModuleId);
        if (info && !info.isLoaded) {
          await this.onEnterModule(targetModuleId, targetModule);
          !this.preloadedModuleIds.has(targetModuleId) && this.preloadedModuleIds.add(targetModuleId);
        }
      }

      // 卸载其他已加载的区域（除了目标区域）
      this.currentModuleIds.forEach((moduleId) => {
        if (moduleId !== targetModuleId) {
          console.log(`🚶 离开区域: ${moduleId}`);
          this.onLeaveModule(moduleId);
        }
      });

      // 更新当前所在区域集合（只包含目标区域）
      this.currentModuleIds.clear();
      this.currentModuleIds.add(targetModuleId);
      // 预加载最近的模块（排除当前目标模块）
      this.enablePreloadNearest && this.preloadNearestModules(nearestModules, targetModuleId);
    }

    this.isLoading = false;
  }

  /**
   * 计算模块的边界尺寸（考虑缩放）
   */
  private getModuleBounds(module: RegionModule, scale = 1) {
    const { scale: moduleScale } = module.transform;
    const { x: width, y: depth, z: height } = module.bounds;

    return {
      halfWidth: ((width * moduleScale[0]) / 2) * scale,
      halfHeight: ((height * moduleScale[1]) / 2) * scale,
      halfDepth: ((depth * moduleScale[2]) / 2) * scale,
      width: width * moduleScale[0] * scale,
      height: height * moduleScale[1] * scale,
      depth: depth * moduleScale[2] * scale,
    };
  }

  /**
   * 获取模块中心位置（Vector3格式）
   */
  private getModuleCenter(module: RegionModule): THREE.Vector3 {
    const { position } = module.transform;
    return new THREE.Vector3(position[0], position[1], position[2]);
  }

  /**
   * 检查位置是否在指定模块内
   */
  private isPositionInModule(position: THREE.Vector3, module: RegionModule): boolean {
    const { position: modulePos } = module.transform;
    const { halfWidth, halfHeight, halfDepth } = this.getModuleBounds(module);

    // 计算边界框
    const minX = modulePos[0] - halfWidth;
    const maxX = modulePos[0] + halfWidth;
    const minY = modulePos[1] - halfHeight;
    const maxY = modulePos[1] + halfHeight;
    const minZ = modulePos[2] - halfDepth;
    const maxZ = modulePos[2] + halfDepth;

    // 检查位置是否在边界内
    return (
      position.x >= minX &&
      position.x <= maxX &&
      position.y >= minY &&
      position.y <= maxY &&
      position.z >= minZ &&
      position.z <= maxZ
    );
  }

  /**
   * 计算用户位置到模块中心的距离
   */
  private getDistanceToModuleCenter(position: THREE.Vector3, module: RegionModule): number {
    return position.distanceTo(this.getModuleCenter(module));
  }

  /**
   * 进入模块事件处理
   */
  private async onEnterModule(moduleId: string, module: RegionModule): Promise<void> {
    return new Promise(async (resolve) => {
      const info = this.moduleInfos.get(moduleId);
      if (!info || info.isLoaded) return;

      try {
        // 如果当前有已加载的场景，为其创建空气墙
        if (this.viewers.size > 0) {
          this.createAirWallsForCurrentScenes();
        }

        // 如果是第一个场景，预加载文件并报告进度
        const isFirstScene = this.currentModuleIds.size === 0;

        // 创建该区域的 viewer
        const viewer = this.createViewer();
        const sceneOption: { mortonConfig?: string; mortonCenter?: THREE.Vector3 } = {};
        if (this.currentModuleIds.size <= 0 && this.regionConfig?.morton) {
          sceneOption.mortonConfig = module.mortonConfig;
          sceneOption.mortonCenter = this.config.startPoint;
        }

        // 加载场景
        await viewer.addScene(module.url, {
          ...sceneOption,
          position: module?.gsInfo?.position || [0, 0, 0],
          rotation: module?.gsInfo?.rotation || [1, 0, 0, 0],
          scale: module?.gsInfo?.scale || [1, 1, 1],
          renderOrder: this.config.renderOrder,
          sphericalHarmonicsDegree: this.config.sphericalHarmonicsDegree,
          showLoadingUI: this.config.showLoadingUI,
          onProgress: (progress: number, loaderStatus: LoaderStatus) => {
            if (isFirstScene) {
              this.config.onFirstSceneProgress?.(module.url, progress);
            }
            this.config.onScenesProgress?.(module.url, progress);
            if (loaderStatus === LoaderStatus.Done) {
              // 场景加载完成，移除空气墙
              this.removeAirWalls();
              setTimeout(() => {
                resolve();
              }, 400);
            }
          },
        });

        // 存储 viewer
        this.viewers.set(moduleId, viewer);

        // 更新模块信息
        info.viewer = viewer;
        info.sceneId = module.id;
        info.isLoaded = true;

        console.log(`✅ 区域场景加载完成: ${module.name} (${moduleId})`);
      } catch (error) {
        console.error(`❌ 加载区域场景失败: ${module.name}`, error);
        // 加载失败也要移除空气墙
        this.removeAirWalls();
      }
    });
  }

  /**
   * 创建单面空气墙
   */
  private createSingleWall(
    moduleId: string,
    direction: 'north' | 'south' | 'east' | 'west',
    size: THREE.Vector3,
    position: THREE.Vector3,
  ): void {
    const wallId = `${this.physicsWorldBoxTag}_${moduleId}_${direction}`;
    this.physicsWorldManager?.createBox(wallId, size, position, true);
    this.airWallIds.push(wallId);
  }

  /**
   * 为当前已加载的场景创建空气墙
   */
  private createAirWallsForCurrentScenes(): void {
    if (!this.physicsWorldManager) return;

    // 先清除旧的空气墙
    this.removeAirWalls();

    // 空气墙参数
    const wallThickness = 0.1; // 厚度0.1米
    const wallHeight = 50; // 高度50米
    const wallScale = 1.5; // 墙体缩放系数

    // 为每个已加载的场景创建空气墙
    this.currentModuleIds.forEach((moduleId) => {
      const info = this.moduleInfos.get(moduleId);
      if (!info?.isLoaded) return;

      const { module } = info;
      const { position: modulePos } = module.transform;
      const { halfWidth, halfDepth, width, depth } = this.getModuleBounds(module, wallScale);
      const wallY = modulePos[1]; // 空气墙的Y坐标（底部对齐地面）

      // 创建四面空气墙的配置
      const walls = [
        {
          direction: 'north' as const,
          size: new THREE.Vector3(width + wallThickness * 2, wallHeight, wallThickness),
          position: new THREE.Vector3(modulePos[0], wallY, modulePos[2] + halfDepth + wallThickness / 2),
        },
        {
          direction: 'south' as const,
          size: new THREE.Vector3(width + wallThickness * 2, wallHeight, wallThickness),
          position: new THREE.Vector3(modulePos[0], wallY, modulePos[2] - halfDepth - wallThickness / 2),
        },
        {
          direction: 'east' as const,
          size: new THREE.Vector3(wallThickness, wallHeight, depth),
          position: new THREE.Vector3(modulePos[0] + halfWidth + wallThickness / 2, wallY, modulePos[2]),
        },
        {
          direction: 'west' as const,
          size: new THREE.Vector3(wallThickness, wallHeight, depth),
          position: new THREE.Vector3(modulePos[0] - halfWidth - wallThickness / 2, wallY, modulePos[2]),
        },
      ];

      // 批量创建墙体
      walls.forEach(({ direction, size, position }) => {
        this.createSingleWall(moduleId, direction, size, position);
      });
    });
  }

  /**
   * 移除所有空气墙
   */
  private removeAirWalls(): void {
    if (this.airWallIds.length === 0) return;

    // 移除物理碰撞体
    if (this.physicsWorldManager) {
      this.airWallIds.forEach((wallId) => {
        this.physicsWorldManager!.removeRigidBody(wallId);
      });
    }
    this.airWallIds = [];
  }

  /**
   * 离开模块事件处理
   */
  private onLeaveModule(moduleId: string): void {
    const info = this.moduleInfos.get(moduleId);
    if (!info?.isLoaded) return;

    // 从 viewers 中获取该区域的 viewer
    const viewer = this.viewers.get(moduleId);
    if (viewer) {
      console.log(`🗑️ 卸载区域场景: ${info.module.name} (${moduleId})`);
      this.scene.remove(viewer.viewer as unknown as THREE.Object3D);
      viewer.dispose();
      this.viewers.delete(moduleId);
    }

    // 更新模块信息
    info.viewer = null;
    info.sceneId = null;
    info.isLoaded = false;
  }

  /**
   * 预加载最近的模块
   * @param nearestModules 最近的模块列表
   * @param excludeModuleId 要排除的模块ID（当前目标模块）
   */
  private async preloadNearestModules(
    nearestModules: Array<{ moduleId: string; module: RegionModule; distance: number }>,
    excludeModuleId: string | null,
  ): Promise<void> {
    // 过滤掉当前目标模块和已完成预加载的模块
    const modulesToPreload = nearestModules
      .filter((item) => item.moduleId !== excludeModuleId && !this.preloadedModuleIds.has(item.moduleId))
      .sort((a, b) => a.distance - b.distance); // 按距离从近到远排序

    // 获取新的预加载模块ID集合
    const newPreloadIds = new Set(modulesToPreload.map((item) => item.moduleId));

    // 找出需要取消的模块（在旧集合中但不在新集合中，且未完成下载）
    const modulesToCancel = Array.from(this.prepareToPreloadedModuleIds).filter(
      (id) => !newPreloadIds.has(id) && !this.preloadedModuleIds.has(id),
    );

    // 取消不再需要的下载
    if (modulesToCancel.length > 0) {
      const urlsToCancel = modulesToCancel
        .map((id) => this.moduleInfos.get(id)?.module.url)
        .filter((url): url is string => !!url);

      if (urlsToCancel.length > 0) {
        console.log(`🛑 取消预加载: ${modulesToCancel.join(', ')}`);
        fileLoaderManager.abortBatch(urlsToCancel);

        // 清理被取消模块的 Promise 缓存
        modulesToCancel.forEach((id) => {
          this.preloadingPromises.delete(id);
        });
      }
    }

    // 更新预加载模块集合
    this.prepareToPreloadedModuleIds = newPreloadIds;

    // 开始预加载新模块
    if (modulesToPreload.length > 0) {
      // 异步预加载，不阻塞主流程
      modulesToPreload.forEach((item, index) => {
        const { moduleId, module } = item;

        // 检查是否已经有正在进行的下载
        if (this.preloadingPromises.has(moduleId)) {
          return;
        }

        // 创建下载 Promise 并缓存
        const downloadPromise = fileLoaderManager
          .load(module.url, {
            priority: index,
            timeout: 120000,
          })
          .then(() => {
            // 下载成功，标记为已完成
            this.preloadedModuleIds.add(moduleId);
            console.log(`已完成预加载: ${Array.from(this.preloadedModuleIds).join(', ')}`);
          })
          .catch((error) => {
            // 下载失败，记录错误
            console.warn(`❌ 预加载失败: ${moduleId}`, error);
          })
          .finally(() => {
            // 无论成功或失败，都清理 Promise 缓存
            this.preloadingPromises.delete(moduleId);
          });

        // 缓存 Promise
        this.preloadingPromises.set(moduleId, downloadPromise);
      });
    }
  }
}
